#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0200  // PGA = ±4.096V
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115(int i2c_handle, uint8_t reg_addr)
{
    char buf[2];
    int16_t value;

    // Write the register address to be read
    if (i2cWriteI2CBlockData(i2c_handle, reg_addr, NULL, 0) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Read two bytes from the I2C device
    if (i2cReadI2CBlockData(i2c_handle, reg_addr, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value, taking into account byte order
    value = (int16_t)((buf[0] << 8) | buf[1]);

    return value;
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115(int i2c_handle, uint8_t reg_addr, uint16_t value)
{
    char buf[3];
    buf[0] = reg_addr;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (i2cWriteI2CBlockData(i2c_handle, reg_addr, buf + 1, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (write_ads1115(i2c_handle, ADS1115_REG_CONFIG, ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) != 0) {
        fprintf(stderr, "Error configuring ADS1115.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Read the conversion result
        int16_t raw_value = read_ads1115(i2c_handle, ADS1115_REG_CONVERT);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading conversion result.\n");
            break; // Exit loop on error
        }

        // Convert raw value to current in amperes
        float current = (float)raw_value * 40.0 / 32768.0; // 40mV/A sensitivity

        // Print the current value
        printf("Current: %.4f A\n", current);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

