    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC3; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    config[2] = 0x83; // Disable comparator, disable comparator high, disable comparator low

