#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdint.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define FAN_GPIO 18
#define DEFAULT_SENSITIVITY 0.1 // 100 mV/A
#define DEFAULT_THRESHOLD 5.0 // 5.0 A
#define DEFAULT_LOG_FILE "current_log.txt"
#define MAX_RETRIES 3

// Global variables (minimize usage)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *fan_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static float sensitivity = DEFAULT_SENSITIVITY;
static float threshold = DEFAULT_THRESHOLD;
static char *log_file_path = DEFAULT_LOG_FILE;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_adc(int fd, int channel);
float adc_to_current(int adc_value, float sensitivity);
void control_fan(float current, float threshold);
void log_data(float current);
void signal_handler(int sig);
int gpio_init(int pin, const char *chip_name);
void gpio_set_direction(int pin, const char *direction);
void gpio_set_value(int pin, int value);
void gpio_release(int pin);
void cleanup();

// SPI Initialization
int spi_init(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_buf[1] = {mode};
    if (ioctl(fd, SPI_IOC_WR_MODE, mode_buf) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_buf[1] = {bits_per_word};
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, bits_buf) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_buf = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_buf) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read ADC Value
int read_adc(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3008 single-ended read command
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) == -1) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// ADC to Current Conversion
float adc_to_current(int adc_value, float sensitivity) {
    float voltage = (float)adc_value / 1023.0 * 3.3;
    float current = voltage / sensitivity;
    return current;
}

// Fan Control
void control_fan(float current, float threshold) {
    if (current > threshold) {
        gpio_set_value(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpio_set_value(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Logging
void log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// GPIO Initialization
int gpio_init(int pin, const char *chip_name) {
    int chip_fd = open(chip_name, O_RDWR);
    if (chip_fd < 0) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Error opening GPIO chip");
        close(chip_fd);
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        close(chip_fd);
        return -1;
    }

    return chip;
}

// GPIO Set Direction
void gpio_set_direction(int pin, const char *direction) {
    int ret = gpiod_line_request_output(line, direction, 0);
    if (ret < 0) {
        perror("Error setting GPIO direction");
    }
}

// GPIO Set Value
void gpio_set_value(int pin, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
    }
}

// GPIO Release
void gpio_release(int pin) {
    if (fan_line) {
        gpiod_line_release(fan_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(0);
}

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Cleanup
void cleanup() {
    gpio_set_value(FAN_GPIO, 0); // Turn fan OFF
    gpio_release(FAN_GPIO);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:t:l:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            case 'l':
                log_file_path = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold] [-l log_file]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_chip = gpio_init(FAN_GPIO, "gpiochip4");
    if (!gpio_chip) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fan_line = gpiod_chip_get_line(gpio_chip, FAN_GPIO);
    if (!fan_line) {
        fprintf(stderr, "Failed to get GPIO line for fan control\n");
        gpio_release(FAN_GPIO);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpio_set_direction(FAN_GPIO, "out");

    // Initialize log file
    log_file = fopen(log_file_path, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpio_release(FAN_GPIO);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        float current = adc_to_current(adc_value, sensitivity);
        control_fan(current, threshold);
        log_data(current);

        sleep(1);
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

