#define ADS1115_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define CO_LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for ADS1115 configuration
typedef struct {
    uint8_t config;
} ads1115_config_t;

// Function prototypes
int initialize_i2c();
int read_ads1115(int handle, int16_t *adc_value);
float convert_to_ppm(int16_t adc_value);
int log_ppm_value(float ppm_value);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read from ADS1115
int read_ads1115(int handle, int16_t *adc_value) {
    ads1115_config_t config = {0x83}; // Single-ended A0, 4.096V, 128 SPS, Disable comparator
    char buf[3];
    int result;

    result = i2cWriteDevice(handle, (char *)&config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for conversion

    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *adc_value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Convert ADC value to PPM (logarithmic curve)
float convert_to_ppm(int16_t adc_value) {
    // Example logarithmic curve (adjust as needed based on sensor datasheet)
    // This is a placeholder; replace with your actual calibration data
    float ppm = 100.0 * powf((float)adc_value / 32767.0, 2.0); // Example: 0-100 PPM for 0-32767 ADC value
    return ppm;
}

