int log_ppm_value(float ppm_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(CO_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CO_LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, %.2f PPM\n", timestamp, ppm_value);
    fclose(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    int16_t adc_value;
    float ppm_value;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("CO Sensor Data Logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        if (read_ads1115(i2c_handle, &adc_value) == 0) {
            // Convert to PPM
            ppm_value = convert_to_ppm(adc_value);

            // Log PPM value
            if (log_ppm_value(ppm_value) != 0) {
                fprintf(stderr, "Error logging PPM value\n");
            }

            printf("CO Concentration: %.2f PPM\n", ppm_value);
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

