#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define I2C bus and addresses
#define I2C_BUS 1
#define SENSOR1_ADDR 0x48
#define SENSOR2_ADDR 0x49

// Define register address for ADC data
#define ADC_REG 0x00

// Define sampling interval (in milliseconds)
#define SAMPLE_INTERVAL 100

// Define error value for dB
#define ERROR_DB -999.0

// Global variables for I2C handles
int i2c_handle1 = -1;
int i2c_handle2 = -1;

// Function prototypes
int read_sensor_data(int i2c_handle, int sensor_address, int *raw_data);
float calculate_dB(int raw_data);
void log_data(float db1, float db2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int raw_data;
    float db;
} sensor_data_t;

// Function to read sensor data from I2C
int read_sensor_data(int i2c_handle, int sensor_address, int *raw_data) {
    char buf[2];
    int result;

    // Read 2 bytes from the specified register
    result = i2cReadI2CBlockData(i2c_handle, ADC_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit signed integer
    *raw_data = (int16_t)((buf[0] << 8) | buf[1]);

    return 0; // Indicate success
}

// Function to convert raw data to dB
float calculate_dB(int raw_data) {
    // Convert raw data to voltage (assuming 16-bit ADC, 2.5V reference)
    float voltage = (float)raw_data / 65535.0 * 2.5;

    // Convert voltage to pressure (Pa) using microphone sensitivity
    float pressure = voltage * 10e-6; // -38 dBV/Pa

    // Convert pressure to dB SPL (SPL = dB relative to 20 µPa)
    float db_spl = 20 * log10(pressure / 20e-6);

    return db_spl;
}

// Function to log data to file
void log_data(float db1, float db2) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open file in append mode
    fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    // Write data to file
    fprintf(fp, "%s, Sensor 1: %.2f dB, Sensor 2: %.2f dB\n", timestamp, db1, db2);

    // Close file
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    int raw_data1, raw_data2;
    float db1, db2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read data from both sensors
        if (read_sensor_data(i2c_handle1, SENSOR1_ADDR, &raw_data1) != 0) {
            db1 = ERROR_DB;
        } else {
            db1 = calculate_dB(raw_data1);
        }

        if (read_sensor_data(i2c_handle2, SENSOR2_ADDR, &raw_data2) != 0) {
            db2 = ERROR_DB;
        } else {
            db2 = calculate_dB(raw_data2);
        }

        // Log the data
        log_data(db1, db2);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    return 0;
}

