#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define MIC1_SPI_CE 8
#define MIC2_SPI_CE 9
#define LED_PIN 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 0.7

// Define sampling window
#define SAMPLING_WINDOW_MS 100
#define NUM_SAMPLES (SAMPLING_WINDOW_MS * 1000) / 1000 // 100 samples per channel

// Global variables
int spi_handle1, spi_handle2;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold ADC channel data
typedef struct {
    int channel;
    int adc_value;
} adc_channel_t;

// Function prototypes
int initialize_spi(int ce_pin);
int read_adc_channel(int spi_handle, int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(FILE *fp, double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Function to initialize SPI
int initialize_spi(int ce_pin) {
    int handle = spiOpen(ce_pin, SPI_SPEED, 0); // CE0 or CE1, 1MHz, Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read ADC channel
int read_adc_channel(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate RMS
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to log data to CSV file
void log_data(FILE *fp, double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn off LED initially

    // Initialize SPI channels
    spi_handle1 = initialize_spi(MIC1_SPI_CE);
    spi_handle2 = initialize_spi(MIC2_SPI_CE);

    if (spi_handle1 < 0 || spi_handle2 < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle1);
        spiClose(spi_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];

    // Main loop
    while (!terminate) {
        // Sample audio data
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = read_adc_channel(spi_handle1, 0); // Channel 0
            mic2_samples[i] = read_adc_channel(spi_handle2, 0); // Channel 0
            gpioDelay(1); // 1 ms delay
        }

        // Calculate RMS values
        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Log data
        log_data(log_file, mic1_rms, mic2_rms);

        // Check for threshold exceedance
        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_PIN, 1); // Turn on LED
            gpioDelay(500);       // Wait 500 ms
            gpioWrite(LED_PIN, 0); // Turn off LED
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup
    spiClose(spi_handle1);
    spiClose(spi_handle2);
    fclose(log_file);
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

