#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define WARNING_LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int16_t read_ads1115_channel_a0();
float convert_to_current(int16_t raw_value);
void add_to_circular_buffer(CircularBuffer *cb, float value);
float calculate_average_current(CircularBuffer *cb);
void control_warning_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read a single-ended channel A0 from the ADS1115
int16_t read_ads1115_channel_a0() {
    // Configuration register value: Single-shot mode, A0, +/-4.096V, 128 SPS
    uint8_t config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x83; // Single-shot, A0, 4.096V, 128 SPS
    config[2] = 0x83; // 128 SPS

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register (2 bytes)
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Function to convert the raw ADC value to current in Amperes
float convert_to_current(int16_t raw_value) {
    // Assuming a 5V supply and a 4.096V range
    float voltage = (float)raw_value / 32767.0 * 4.096;
    // Assuming a 0.5V offset for 0A
    float current = (voltage - 0.5) * 100.0; // 0-100A range
    return current;
}

// Function to add a new value to the circular buffer
void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the average current from the circular buffer
float calculate_average_current(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to control the warning LED based on the average current
void control_warning_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(WARNING_LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(WARNING_LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(WARNING_LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for the warning LED
    gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT);
    gpioWrite(WARNING_LED_GPIO, 0); // Ensure LED is off initially

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer current_buffer;
    init_circular_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t raw_value = read_ads1115_channel_a0();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(raw_value);

        // Add to circular buffer
        add_to_circular_buffer(&current_buffer, current);

        // Calculate average current
        float average_current = calculate_average_current(&current_buffer);

        // Control warning LED
        control_warning_led(average_current);

        // Print current and average current (for debugging)
        printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);

        // Sample at 10Hz
        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

