#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the TCS34725 sensor
int initialize_sensor() {
    int result;

    // Enable the sensor
    result = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x01 | 0x02); // Power on and enable ADC
    if (result < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(3); // Wait 3 ms

    // Set integration time
    result = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xFF); // 2.4 ms
    if (result < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }

    // Set gain
    result = i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01); // 4x gain
    if (result < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read color data from the sensor
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int result;
    char buffer[8];

    // Read 8 bytes from registers 0x14 to 0x1B
    result = i2cReadI2CBlockData(i2c_handle, 0x14, buffer, 8);
    if (result < 0) {
        fprintf(stderr, "Error reading color data: %s\n", strerror(errno));
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Log data to CSV file
int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file);

    return 0;
}

int main() {
    uint16_t clear, red, green, blue;
    int retry_count;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    int id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if ((id & 0x0F) != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Clear\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        retry_count = 0;
        while (retry_count < 3) {
            if (read_sensor_data(&clear, &red, &green, &blue) == 0) {
                log_data(clear, red, green, blue);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying... (%d/3)\n", retry_count + 1);
                retry_count++;
                gpioDelay(100); // Wait 100 ms before retrying
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "Critical I2C read failure, exiting...\n");
            break; // Exit main loop on critical failure
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

