#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_MOTOR_SHUTDOWN 17
#define OVERCURRENT_THRESHOLD 10.0
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 1023.0
#define VREF 3.3
#define CURRENT_SENSITIVITY 0.1
#define CURRENT_OFFSET 0.05
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *motor_shutdown_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
int log_current(float current);
int motor_shutdown(int state);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd;
    uint8_t mode = 0;
    uint8_t bits = 8;
    uint32_t speed = 1000000; // 1 MHz

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read ADC value from MCP3008
int spi_read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / ADC_RESOLUTION) * VREF;
}

// Convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - CURRENT_OFFSET) / CURRENT_SENSITIVITY;
}

// Log current reading to file
int log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "timestamp,current_in_Amperes\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file);
    return 0;
}

// Motor shutdown control
int motor_shutdown(int state) {
    if (motor_shutdown_line == NULL) {
        fprintf(stderr, "Motor shutdown line not initialized.\n");
        return -1;
    }

    if (gpiod_line_set_value(motor_shutdown_line, state) < 0) {
        perror("Error setting motor shutdown line value");
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (motor_shutdown_line != NULL) {
        gpiod_line_release(motor_shutdown_line);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return 1;
    }

    motor_shutdown_line = gpiod_chip_get_line(gpio_chip, GPIO_MOTOR_SHUTDOWN);
    if (!motor_shutdown_line) {
        perror("Error getting motor shutdown line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(motor_shutdown_line, "motor_shutdown", 0) < 0) {
        perror("Error requesting motor shutdown line as output");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpiod_line_release(motor_shutdown_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = spi_read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        if (log_current(current) < 0) {
            fprintf(stderr, "Error logging current.\n");
        }

        printf("Current: %.2f A\n", current);

        if (current > OVERCURRENT_THRESHOLD) {
            fprintf(stderr, "Overcurrent detected! Shutting down motor.\n");
            if (motor_shutdown(0) < 0) {
                fprintf(stderr, "Error shutting down motor.\n");
            }
            sleep(1);
            if (motor_shutdown(1) < 0) {
                fprintf(stderr, "Error restarting motor.\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

