#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90817_ADDR 0x40
#define PRESSURE_REG 0x00
#define PRESSURE_SCALE 500.0
#define PRESSURE_OFFSET 0.0
#define LOG_FILE "pressure_log.csv"
#define READ_DELAY_SEC 1

int i2c_handle;
FILE *log_file;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read pressure from the sensor
int read_pressure(int i2c_handle, int *raw_pressure) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading pressure: %d\n", result);
        return -1; // Indicate failure
    }

    *raw_pressure = (buf[0] << 8) | buf[1];
    return 0; // Indicate success
}

// Function to convert raw pressure to kPa
float convert_to_kPa(int raw_pressure) {
    return (float)raw_pressure / 65535.0 * PRESSURE_SCALE;
}

// Function to log data to a file
int log_data(const char *timestamp, float pressure_kPa) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int raw_pressure;
    float pressure_kPa;
    char *timestamp;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        // Read pressure
        if (read_pressure(i2c_handle, &raw_pressure) == 0) {
            // Convert to kPa
            pressure_kPa = convert_to_kPa(raw_pressure);

            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log data
            if (log_data(timestamp, pressure_kPa) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(READ_DELAY_SEC * 1000000); // Delay in microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

