#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Constants
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_ads1115();
int read_adc(int16_t *adc_value);
float convert_to_pressure(int16_t adc_value);
float convert_to_temperature(int16_t adc_value);
void control_led(float pressure);
void signal_handler(int signal);

// Structure for ADS1115 configuration
typedef struct {
    uint8_t config;
} ads1115_config_t;

// Structure for ADS1115 data
typedef struct {
    int16_t adc_value;
} ads1115_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (config_ads1115() != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        int16_t adc_value;
        float pressure, temperature;

        // Read ADC value
        if (read_adc(&adc_value) != 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Retry
        }

        // Convert ADC value to pressure and temperature
        pressure = convert_to_pressure(adc_value);
        temperature = convert_to_temperature(adc_value);

        // Display pressure and temperature
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Control LED based on pressure
        control_led(pressure);

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure ADS1115
int config_ads1115() {
    ads1115_config_t config = {
        .config = 0x4003 // Single-shot mode, AIN0, +/-6.144V, 128 SPS
    };

    int result = i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG, config.config);
    if (result < 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register: %d\n", result);
        return 1;
    }
    return 0;
}

// Read ADC value with retry
int read_adc(int16_t *adc_value) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, ADS1115_REG_CONVERT);
        if (result >= 0) {
            *adc_value = (int16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read ADC value (attempt %d): %d\n", retries + 1, result);
            retries++;
            time_sleep(0.01); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read ADC value after %d retries\n", RETRY_COUNT);
    return 1; // Failure
}

// Convert ADC value to pressure
float convert_to_pressure(int16_t adc_value) {
    // Assuming 0V = 0 kPa and 5V = 400 kPa
    float voltage = (adc_value / 32767.0) * 5.0; // Assuming 16-bit ADC
    return voltage * (400.0 / 5.0);
}

// Convert ADC value to temperature
float convert_to_temperature(int16_t adc_value) {
    // Assuming 0V = 0°C and 1V = 100°C
    float voltage = (adc_value / 32767.0) * 5.0; // Assuming 16-bit ADC
    return voltage * (100.0 / 1.0);
}

// Control LED based on pressure
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn on LED
    } else {
        gpioWrite(GPIO_LED, 0); // Turn off LED
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

