// Define GPIO pins
#define SPI_CLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_CS 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 command for single-ended channel 0
#define MCP3008_START 0x01
#define MCP3008_CONFIG 0x80
#define MCP3008_DUMMY 0x00

// Define methane concentration range
#define ADC_MIN 0
#define ADC_MAX 1023
#define METHANE_MIN 0.0
#define METHANE_MAX 5000.0

// Define leak alarm threshold
#define LEAK_THRESHOLD 1000.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_methane_reading(float ppm);
void check_leak_alarm(float ppm);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI command
    tx_buffer[0] = MCP3008_START;
    tx_buffer[1] = MCP3008_CONFIG | (channel << 4);
    tx_buffer[2] = MCP3008_DUMMY;

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to methane concentration (PPM)
float adc_to_ppm(int adc_value) {
    float ppm = METHANE_MIN + (float)(adc_value - ADC_MIN) * (METHANE_MAX - METHANE_MIN) / (ADC_MAX - ADC_MIN);
    return ppm;
}

// Function to log methane reading to file
void log_methane_reading(float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime_r(&rawtime, timestamp);

    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time.\n");
        return;
    }

    if (fopen(log_file, "a") == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }

    fprintf(fopen(log_file, "a"), "%s,%.2f\n", timestamp, ppm);
    fclose(fopen(log_file, "a"));

    printf("%s,%.2f\n", timestamp, ppm);
}

// Function to check for leak alarm
void check_leak_alarm(float ppm) {
    if (ppm > LEAK_THRESHOLD) {
        fprintf(stderr, "LEAK DETECTED! Methane concentration: %.2f PPM\n", ppm);
    }
}

