        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("methane_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in 1 second.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to methane concentration
        float ppm = adc_to_ppm(adc_value);

        // Log methane reading
        log_methane_reading(ppm);

        // Check for leak alarm
        check_leak_alarm(ppm);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close SPI handle and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

