    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to methane concentration (PPM)
float adc_to_ppm(int adc_value) {
    float ppm = METHANE_MIN + (float)(adc_value - ADC_MIN) * (METHANE_MAX - METHANE_MIN) / (ADC_MAX - ADC_MIN);
    return ppm;
}

// Function to log methane reading to file
void log_methane_reading(float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime_r(&rawtime, timestamp);

    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time.\n");
        return;
    }

    if (fopen(log_file, "a") == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }

    fprintf(fopen(log_file, "a"), "%s,%.2f\n", timestamp, ppm);
    fclose(fopen(log_file, "a"));

    printf("%s,%.2f\n", timestamp, ppm);
}

// Function to check for leak alarm
void check_leak_alarm(float ppm) {
    if (ppm > LEAK_THRESHOLD) {
        fprintf(stderr, "LEAK DETECTED! Methane concentration: %.2f PPM\n", ppm);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("methane_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in 1 second.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to methane concentration
        float ppm = adc_to_ppm(adc_value);

        // Log methane reading
        log_methane_reading(ppm);

        // Check for leak alarm
        check_leak_alarm(ppm);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close SPI handle and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

