#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define FULL_SCALE_VOLTAGE 4.096 // 4.096V for +/-4.096V range
#define OFFSET_VOLTAGE 0.5       // 0.5V offset
#define SENSITIVITY_VOLTAGE 0.1  // 0.1 V/kPa
#define PRESSURE_RANGE 100.0    // 0-100 kPa
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for ADS1115 configuration
typedef struct {
    int config;
} ads1115_config_t;

// Function prototypes
int initialize_i2c();
int initialize_ads1115();
int read_adc(int *raw_value);
float convert_to_voltage(int raw_value);
float convert_to_pressure(float voltage);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize ADS1115 for single-ended AIN0, 4.096V range, continuous conversion
int initialize_ads1115() {
    ads1115_config_t config = {
        .config = 0x4083 // Single-ended AIN0, 4.096V, Continuous, 128 SPS, Disable comparator
    };

    int result = i2cWriteByteData(i2c_handle, CONFIG_REG, config.config);
    if (result < 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read raw ADC value from ADS1115
int read_adc(int *raw_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read ADC value: %d\n", result);
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw ADC value to voltage
float convert_to_voltage(int raw_value) {
    return ((float)raw_value / 32767.0) * FULL_SCALE_VOLTAGE;
}

// Convert voltage to pressure using linear transfer function
float convert_to_pressure(float voltage) {
    return (voltage - OFFSET_VOLTAGE) / SENSITIVITY_VOLTAGE;
}

// Log pressure reading to file with ISO 8601 timestamp
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize ADS1115
    if (initialize_ads1115() != 0) {
        fprintf(stderr, "ADS1115 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    int raw_value;
    float voltage, pressure;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_adc(&raw_value) == 0) {
            // Convert to voltage
            voltage = convert_to_voltage(raw_value);

            // Convert to pressure
            pressure = convert_to_pressure(voltage);

            // Validate pressure range
            if (pressure >= 0.0 && pressure <= PRESSURE_RANGE) {
                // Log pressure
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Failed to log pressure.\n");
                }
            } else {
                fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

