#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0 // CE0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0 // Humidity ADC channel
#define VREF 5.0 // Reference voltage
#define RH_MAX 100.0 // Maximum relative humidity
#define T_MAX 125.0 // Maximum temperature in Celsius
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with your email address
#define EMAIL_SUBJECT "Humidity Alert"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int initialize();
int read_adc(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(float thermistor_voltage);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from the MCP3208 ADC
int read_adc(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3208 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate relative humidity from ADC value
float calculate_humidity(int adc_value) {
    float vout = ((float)adc_value / 1023.0) * VREF;
    float rh = (vout - 0.824) / 0.0315;
    if (rh < 0.0) rh = 0.0;
    if (rh > RH_MAX) rh = RH_MAX;
    return rh;
}

// Function to calculate temperature from thermistor voltage
float calculate_temperature(float thermistor_voltage) {
    // Simplified Beta equation (requires calibration for accurate results)
    // This is a placeholder; proper calibration is crucial for accurate temperature readings.
    float beta = 3950.0; // Beta parameter
    float r0 = 10.0; // Resistance at 25°C
    float temperature = beta / (log10(thermistor_voltage / (VREF / r0)) - 1.0) - 25.0;
    return temperature;
}

// Function to log data to a file
void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send an email alert
void send_email_alert(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: %s\nFrom: %(user)s\nTo: %(recipient)s\n\nHumidity: %.2f%%, Temperature: %.2f°C, Alert: Humidity exceeded 80%%\" | ssmtp -t -a %(user)s %(recipient)s", getenv("USER"), EMAIL_RECIPIENT, humidity, 0.0); // Placeholder temperature
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Failed to send email\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    fprintf(stdout, "Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_adc(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        float humidity = calculate_humidity(adc_value);
        float thermistor_voltage = ((float)adc_value / 1023.0) * VREF; // Assuming ADC is connected to the thermistor
        float temperature = calculate_temperature(thermistor_voltage);

        log_data(humidity, temperature);

        if (humidity > 80.0) {
            send_email_alert(humidity);
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        sleep(5);
    }

    cleanup();
    fprintf(stdout, "Humidity monitoring stopped.\n");
    return 0;
}

