#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8 // GPIO8 (CE0)
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "temperature_log.csv"
#define SLEEP_SECONDS 1

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_celsius(float voltage);
int log_data(float temperature);
void cleanup(void);
void signal_handler(int sig);

// SPI Initialization
int spi_init(void) {
    int fd;
    unsigned int mode = SPI_MODE;
    unsigned int bits = SPI_BITS_PER_WORD;
    unsigned int speed = SPI_SPEED;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3208
int read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;

    // MCP3208 command to read channel 0 (single-ended)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) == -1) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1;
    }

    // Extract ADC value from the response
    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 4095.0) * 3.3;
}

// Convert voltage to Celsius
float voltage_to_celsius(float voltage) {
    return (voltage - 0.5) / 0.01;
}

// Log data to CSV file
int log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "timestamp,temperature_celsius\n"); // Write header
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

// Signal handler
void signal_handler(int sig) {
    printf("Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main(void) {
    int adc_value;
    float voltage, temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return 1;
    }

    // Get CS line
    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting CS line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Request CS line as output
    if (gpiod_line_request_output(cs_line, "temperature_sensor", 0) < 0) {
        perror("Error requesting CS line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d seconds.\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Convert ADC value to voltage
        voltage = adc_to_voltage(adc_value);

        // Convert voltage to Celsius
        temperature = voltage_to_celsius(voltage);

        // Log data
        if (log_data(temperature) == -1) {
            fprintf(stderr, "Error logging data. Retrying in %d seconds.\n", SLEEP_SECONDS);
        }

        printf("Temperature: %.2f °C\n", temperature);

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

