#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8          // GPIO8 (CE0)
#define ADC_VREF 3.3       // ADC reference voltage
#define ADXL335_SENSITIVITY 0.3 // 300 mV/g
#define IMPACT_THRESHOLD 2.0 // Impact detection threshold in g
#define SAMPLE_RATE 100     // 100 Hz
#define NUM_SAMPLES 1000   // Number of samples to store

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} AccelData;

// Function prototypes
int initialize();
int read_adc(int channel);
AccelData process_acceleration(int x, int y, int z);
float calculate_magnitude(AccelData data);
void log_data(AccelData data, float magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Ensure CS is initially high

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Process raw ADC values to g-force units
AccelData process_acceleration(int x, int y, int z) {
    AccelData data;
    data.x = (float)x * ADXL335_SENSITIVITY / 1000.0; // Convert to g
    data.y = (float)y * ADXL335_SENSITIVITY / 1000.0; // Convert to g
    data.z = (float)z * ADXL335_SENSITIVITY / 1000.0; // Convert to g
    return data;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(AccelData data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Log data to file
void log_data(AccelData data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.3f\n", timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    AccelData accel_data[NUM_SAMPLES];
    float magnitude[NUM_SAMPLES];
    int sample_index = 0;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        int x = read_adc(0);
        int y = read_adc(1);
        int z = read_adc(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            break; // Exit loop on error
        }

        accel_data[sample_index] = process_acceleration(x, y, z);
        magnitude[sample_index] = calculate_magnitude(accel_data[sample_index]);

        log_data(accel_data[sample_index], magnitude[sample_index]);

        sample_index = (sample_index + 1) % NUM_SAMPLES; // Circular buffer

        gpioDelay(10); // 10 ms delay for 100 Hz sampling
    }

    cleanup();
    printf("Program terminated.\n");
    return 0;
}

