// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1172_init();
int read_si1172_data(int *ir, int *red);
int log_data(int hr, int spo2, int error_flag);
void signal_handler(int signal);

// Function to write a byte to a specific register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return 1;
    }
    return 0;
}

// Function to read a byte from a specific register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return 1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to initialize the Si1172 sensor
int si1172_init() {
    uint8_t part_id, rev_id, seq_id, hw_id;

    // Check Part ID
    if (read_register(i2c_handle, SI1172_REG_PART_ID, &part_id) != 0) {
        return 1;
    }
    if (part_id != 0x78) {
        fprintf(stderr, "Error: Incorrect Part ID: 0x%02X\n", part_id);
        return 1;
    }

    // Check Revision ID
    if (read_register(i2c_handle, SI1172_REG_REV_ID, &rev_id) != 0) {
        return 1;
    }
    if (rev_id != 0x01) {
        fprintf(stderr, "Error: Incorrect Revision ID: 0x%02X\n", rev_id);
        return 1;
    }

    // Check Sequence ID
    if (read_register(i2c_handle, SI1172_REG_SEQ_ID, &seq_id) != 0) {
        return 1;
    }
    if (seq_id != 0x00) {
        fprintf(stderr, "Error: Incorrect Sequence ID: 0x%02X\n", seq_id);
        return 1;
    }

    // Check HW ID
    if (read_register(i2c_handle, SI1172_REG_HW_ID, &hw_id) != 0) {
        return 1;
    }
    if (hw_id != 0x00) {
        fprintf(stderr, "Error: Incorrect HW ID: 0x%02X\n", hw_id);
        return 1;
    }

    // Reset the device
    if (write_register(i2c_handle, SI1172_REG_RESET, 0x01) != 0) {
        return 1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure measurement rate (adjust as needed)
    if (write_register(i2c_handle, SI1172_REG_MEAS_RATE, 0x0A) != 0) {
        return 1;
    }

    // Configure LED drive current (adjust as needed)
    if (write_register(i2c_handle, SI1172_REG_LED_DRIVE, 0x3F) != 0) {
        return 1;
    }

    // Configure FIFO configuration (adjust as needed)
    if (write_register(i2c_handle, SI1172_REG_FIFO_CONFIG, 0x01) != 0) {
        return 1;
    }

    return 0;
}

// Function to read data from the Si1172 sensor
int read_si1172_data(int *ir, int *red) {
    uint8_t data[4];

    // Trigger measurement (write to command register)
    if (write_register(i2c_handle, SI1172_REG_COMMAND, 0x01) != 0) {
        return 1;
    }

    gpioDelay(1); // Wait for measurement to complete

    // Read FIFO data (4 bytes: 2 IR, 2 RED)
    if (i2cReadI2CBlockData(i2c_handle, SI1172_REG_FIFO_DATA, (char *)data, 4) != 4) {
        fprintf(stderr, "Error reading FIFO data\n");
        return 1;
    }

    *ir = (data[0] << 8) | data[1];
    *red = (data[2] << 8) | data[3];

    return 0;
}

// Function to log data to a CSV file
int log_data(int hr, int spo2, int error_flag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, hr, spo2, error_flag);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int ir, red, hr, spo2, error_flag;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1172 sensor
    if (si1172_init() != 0) {
        fprintf(stderr, "Si1172 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(log_file, "Timestamp,HR,SpO2,ErrorFlag\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read data from the sensor
        if (read_si1172_data(&ir, &red) == 0) {
            // Log the data
            hr = ir; // Placeholder: Replace with actual HR/SpO2 calculation
            spo2 = red; // Placeholder: Replace with actual HR/SpO2 calculation
            error_flag = 0;
            log_data(hr, spo2, error_flag);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            hr = -1; // Indicate error
            spo2 = -1;
            error_flag = 1;
            log_data(hr, spo2, error_flag);
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

