#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel connected to microphone
#define SAMPLE_RATE 16000
#define NUM_SAMPLES 1024
#define GAIN_DEFAULT 1.0
#define MIN_GAIN 0.1
#define MAX_GAIN 10.0

// Global variables
int spi_handle;
int running = 1;
double gain = GAIN_DEFAULT;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    int sample_rate;
    int num_samples;
    double min_gain;
    double max_gain;
} Config;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
double process_audio(int16_t *audio_data, int num_samples);
void output_audio(double processed_audio);
void cleanup();
void signal_handler(int signal);
void parse_arguments(int argc, char *argv[]);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Process audio data (simple averaging)
double process_audio(int16_t *audio_data, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += audio_data[i];
    }
    return sum / num_samples;
}

// Output audio data to CSV format
void output_audio(double processed_audio) {
    printf("%f\n", processed_audio);
}

// Cleanup resources
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

// Parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "g:")) != -1) {
        switch (opt) {
            case 'g':
                gain = atof(optarg);
                if (gain < MIN_GAIN || gain > MAX_GAIN) {
                    fprintf(stderr, "Gain out of range (%f). Using default gain.\n", gain);
                    gain = GAIN_DEFAULT;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-g gain]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    parse_arguments(argc, argv);

    if (initialize()) {
        return 1;
    }

    int16_t audio_data[NUM_SAMPLES];
    int16_t mic1_data[NUM_SAMPLES];
    int16_t mic2_data[NUM_SAMPLES];

    // Read microphone data
    for (int i = 0; i < NUM_SAMPLES; i++) {
        int adc_value1 = read_mcp3008(MCP3008_CHANNEL);
        int adc_value2 = read_mcp3008(MCP3008_CHANNEL);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading ADC values. Exiting.\n");
            cleanup();
            return 1;
        }

        // Convert ADC value to 16-bit signed integer (assuming 10-bit ADC)
        mic1_data[i] = (int16_t)(adc_value1 - 512); // Center the values around 0
        mic2_data[i] = (int16_t)(adc_value2 - 512);

        // Apply gain
        mic1_data[i] = (int16_t)(mic1_data[i] * gain);
        mic2_data[i] = (int16_t)(mic2_data[i] * gain);
    }

    // Noise cancellation
    double processed_audio = process_audio(mic1_data, NUM_SAMPLES);

    // Output audio
    output_audio(processed_audio);

    cleanup();
    return 0;
}

