#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define DEFAULT_AMBIENT_TEMP 25.0
#define MAX_RETRIES 3
#define ADC_MAX_VALUE 1023

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float read_temperature();
float read_voltage(int raw_adc, float temperature);
int detect_flame(float voltage, float temperature);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void control_buzzer(int flame_detected);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int retries = 0;
    int adc_value = -1;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Dummy byte

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d). Retrying...\n", retries + 1);
            log_data(-1, -1.0, -1.0, -1.0, -1); // Log SPI error
            retries++;
            gpioDelay(1000); // Wait before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries. Aborting.\n", MAX_RETRIES);
    log_data(-1, -1.0, -1.0, -1.0, -1); // Log SPI error
    return -1; // Indicate failure
}

// Function to read temperature from file
float read_temperature() {
    FILE *fp;
    char line[256];
    float temperature = DEFAULT_AMBIENT_TEMP;

    fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file. Using default temperature.\n");
        return DEFAULT_AMBIENT_TEMP;
    }

    if (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%f", &temperature) != 1) {
            fprintf(stderr, "Error parsing temperature from file. Using default temperature.\n");
            temperature = DEFAULT_AMBIENT_TEMP;
        }
    }

    fclose(fp);
    return temperature;
}

// Function to read voltage from raw ADC value and temperature
float read_voltage(int raw_adc, float temperature) {
    return (float)raw_adc * 3.3 / ADC_MAX_VALUE;
}

// Function to detect flame based on voltage and temperature
int detect_flame(float voltage, float temperature) {
    float compensated_voltage = voltage + (temperature - 25.0) * 0.001;
    return (compensated_voltage > 1.0) ? 1 : 0;
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.3f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

// Function to control the buzzer
void control_buzzer(int flame_detected) {
    gpioWrite(BUZZER_GPIO, flame_detected);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    return 0;
}

// Cleanup function
void cleanup() {
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    while (!terminate) {
        int raw_adc = read_mcp3008(0);
        float temperature = read_temperature();
        float voltage = read_voltage(raw_adc, temperature);
        int flame_detected = detect_flame(voltage, temperature);

        log_data(raw_adc, voltage, -1.0, temperature, flame_detected);
        control_buzzer(flame_detected);

        gpioDelay(500000); // 500ms
    }

    cleanup();
    return 0;
}

