#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Water level thresholds (percentage)
#define HIGH_THRESHOLD 75.0
#define LOW_THRESHOLD 70.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void control_led(float water_level);
void log_water_level(float water_level);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int ce_pin;
    int mosi_pin;
    int miso_pin;
    int sclk_pin;
    int baud_rate;
} spi_config_t;

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x08 | (channel << 4); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the LED
void control_led(float water_level) {
    if (water_level > HIGH_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED ON
    } else if (water_level < LOW_THRESHOLD) {
        gpioWrite(LED_PIN, 0); // Turn LED OFF
    }
}

// Function to log water level to JSON file
void log_water_level(float water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char json_string[200];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"water_level\": %.2f}", timestamp, water_level);

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", json_string);
