        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,FlowRate (LPM)\n");
    }
    rewind(log_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to flow rate
        float flow_rate = adc_to_flow(adc_value);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(timestamp, flow_rate) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for 100 milliseconds
        gpioDelay(100); // pigpio's delay function
    }

    // Close SPI channel and log file
    spiClose(spi_handle);
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

