#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    int moisture_threshold;
    int logging_frequency;
    char recipient_email[100];
    char msmtp_config_file[100];
} Config;

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file = NULL;
static Config config;

// Function prototypes
int read_config(const char *filename, Config *config);
int initialize_spi(int channel);
int read_adc(int channel);
float calibrate_moisture(int raw_value, int min_raw, int max_raw);
int log_data(float moisture_percentage);
int send_email_alert(float moisture_percentage);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "spi_channel") == 0) {
            config->spi_channel = atoi(value);
        } else if (strcmp(key, "adc_channel") == 0) {
            config->adc_channel = atoi(value);
        } else if (strcmp(key, "min_raw") == 0) {
            config->min_raw = atoi(value);
        } else if (strcmp(key, "max_raw") == 0) {
            config->max_raw = atoi(value);
        } else if (strcmp(key, "moisture_threshold") == 0) {
            config->moisture_threshold = atoi(value);
        } else if (strcmp(key, "logging_frequency") == 0) {
            config->logging_frequency = atoi(value);
        } else if (strcmp(key, "recipient_email") == 0) {
            strncpy(config->recipient_email, value, sizeof(config->recipient_email) - 1);
            config->recipient_email[sizeof(config->recipient_email) - 1] = '\0';
        } else if (strcmp(key, "msmtplib_config_file") == 0) {
            strncpy(config->msmtplib_config_file, value, sizeof(config->msmtplib_config_file) - 1);
            config->msmtplib_config_file[sizeof(config->msmtplib_config_file) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize SPI
int initialize_spi(int channel) {
    spi_handle = spiOpen(channel, 500000, 0); // SPI channel, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read ADC value
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calibrate moisture percentage
float calibrate_moisture(int raw_value, int min_raw, int max_raw) {
    float moisture = 0.0;
    if (min_raw == max_raw) {
        moisture = 0.0; // Avoid division by zero
    } else {
        moisture = 100.0 * (raw_value - min_raw) / (max_raw - min_raw);
    }
    return moisture;
}

// Function to log data to file
int log_data(float moisture_percentage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to send email alert
int send_email_alert(float moisture_percentage) {
    char command[200];
    snprintf(command, sizeof(command), "msmtp -f %s -c \"Subject: Plant Alert!\\n\\nMoisture level: %.2f%%\" %s", config.recipient_email, config.msmtp_config_file, config.recipient_email);

    int status = popen(command, "r");
    if (status == NULL) {
        fprintf(stderr, "Error sending email: %s\n", strerror(errno));
        return -1;
    }

    int exit_status = pclose(status);
    if (exit_status != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", exit_status);
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Default configuration values
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_raw = 300;
    config.max_raw = 700;
    config.moisture_threshold = 30;
    config.logging_frequency = 60;
    strcpy(config.recipient_email, "recipient@example.com");
    strcpy(config.msmtp_config_file, "msmtp.conf");

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "s:a:m:M:t:l:r:")) != -1) {
        switch (opt) {
            case 's':
                config.spi_channel = atoi(optarg);
                break;
            case 'a':
                config.adc_channel = atoi(optarg);
                break;
            case 'm':
                config.min_raw = atoi(optarg);
                break;
            case 'M':
                config.max_raw = atoi(optarg);
                break;
            case 't':
                config.moisture_threshold = atoi(optarg);
                break;
            case 'l':
                strcpy(config.recipient_email, optarg);
                break;
            case 'r':
                strcpy(config.msmtp_config_file, optarg);
                break;
