    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Sampling every %d seconds.\n", sample_interval);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (log_data(moisture_percentage, adc_value) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
            printf("Moisture: %.2f%%, ADC: %d\n", moisture_percentage, adc_value);
        }

        gpioDelay(sample_interval * 1000000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

