#define SPI_SCLK 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define pressure range (kPa)
#define MIN_PRESSURE 0.1
#define MAX_PRESSURE 1.5

// Define voltage range (V)
#define MIN_VOLTAGE 0.5
#define MAX_VOLTAGE 4.5

// Define ADC range (10-bit)
#define ADC_MAX 1023

// Global variable for SPI handle
int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_pressure(float pressure);
void signal_handler(int signal);

