typedef struct {
    int spi_ce;
    int spi_mosi;
    int spi_miso;
    int spi_sclk;
    int spi_channel;
    int spi_baud;
    float min_pressure;
    float max_pressure;
    float min_voltage;
    float max_voltage;
    int adc_max;
} config_t;

// Configuration data
config_t config = {
    SPI_CE, SPI_MOSI, SPI_MISO, SPI_SCLK, SPI_CHANNEL, SPI_BAUD, MIN_PRESSURE, MAX_PRESSURE, MIN_VOLTAGE, MAX_VOLTAGE, ADC_MAX
};

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // Construct SPI message
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

