        if (pressure < 0) {
            fprintf(stderr, "Error: Failed to convert voltage to pressure\n");
            continue; // Skip to the next iteration
        }

        // Log pressure
        log_pressure(pressure);

        // Wait for 1 second
        gpioDelay(1000); // 1000 ms = 1 second
    }

    // The following lines will never be reached due to the infinite loop
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

