#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0" // SPI device file
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNELS 4
#define VREF 3.3 // Reference voltage
#define SAMPLE_INTERVAL_SEC 1

// GPIO pins for chip select (CE0, CE1, CE2, CE3)
const int gpio_pins[] = {8, 7, 12, 13};
const int num_sensors = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables
int spi_fd = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int channel);
float adc_to_voltage(int adc_value);
int log_data(float voltages[], int num_sensors);
void cleanup(int signal);
int gpio_init(int gpio_pin);
void gpio_set_direction(int gpio_pin, const char *direction);
void gpio_set_value(int gpio_pin, int value);
void gpio_set_edge(int gpio_pin, const char *edge);
void gpio_set_callback(int gpio_pin, void (*callback)(int));

// SPI Initialization
int spi_init(const char *device) {
    spi_fd = open(device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Read ADC
int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to Voltage Conversion
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Data Logging
int log_data(float voltages[], int num_sensors) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen("environmental_data.csv", "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        return -1;
    }

    fprintf(fp, "%s", timestamp);
    for (int i = 0; i < num_sensors; i++) {
        fprintf(fp, ",%.3f", voltages[i]);
    }
    fprintf(fp, "\n");

    fclose(fp);
    return 0;
}

// GPIO Initialization
int gpio_init(int gpio_pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(line, "adc_sensor", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// GPIO Set Direction
void gpio_set_direction(int gpio_pin, const char *direction) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), gpio_pin);
    if (!line) {
        perror("Error getting GPIO line for direction setting");
        return;
    }

    ret = gpiod_line_request_output(line, direction, 0);
    if (ret < 0) {
        perror("Error setting GPIO direction");
    }
}

// GPIO Set Value
void gpio_set_value(int gpio_pin, int value) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), gpio_pin);
    if (!line) {
        perror("Error getting GPIO line for value setting");
        return;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
    }
}

// GPIO Set Edge
void gpio_set_edge(int gpio_pin, const char *edge) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), gpio_pin);
    if (!line) {
        perror("Error getting GPIO line for edge setting");
        return;
    }

    ret = gpiod_line_request_event(line, edge, 0);
    if (ret < 0) {
        perror("Error setting GPIO edge");
    }
}

// GPIO Set Callback
void gpio_set_callback(int gpio_pin, void (*callback)(int)) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), gpio_pin);
    if (!line) {
        perror("Error getting GPIO line for callback");
        return;
    }

    ret = gpiod_line_request_callback(line, callback);
    if (ret < 0) {
        perror("Error setting GPIO callback");
    }
}

// Signal Handler
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    terminate = 1;

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close CSV file
    if (fp != NULL) {
        fclose(fp);
    }

    // Release GPIO lines
    for (int i = 0; i < num_sensors; i++) {
        struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
        if (chip) {
            struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_pins[i]);
            if (line) {
                gpiod_line_release(line);
            }
            gpiod_chip_close(chip);
        }
    }

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize SPI
    if (spi_init(SPI_DEVICE) != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO pins
    for (int i = 0; i < num_sensors; i++) {
        if (gpio_init(gpio_pins[i]) != 0) {
            fprintf(stderr, "GPIO initialization failed for pin %d. Exiting.\n", gpio_pins[i]);
            cleanup(0);
            return 1;
        }
        gpio_set_direction(gpio_pins[i], "out");
        gpio_set_value(gpio_pins[i], 0); // Set initial value to LOW
    }

    // Set up interrupt on GPIO pins (example: falling edge)
    for (int i = 0; i < num_sensors; i++) {
        gpio_set_edge(gpio_pins[i], "falling");
        gpio_set_callback(gpio_pins[i], (void (*)(int))[]() {
            // Interrupt handler - reset GPIO pins to LOW
            for (int j = 0; j < num_sensors; j++) {
                gpio_set_value(gpio_pins[j], 0);
            }
        });
    }

    // Main loop
    float voltages[MCP3008_CHANNELS];
    while (!terminate) {
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            int adc_value = spi_read_adc(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC channel %d. Retrying.\n", i);
                sleep(1); // Wait before retrying
                continue;
            }
            voltages[i] = adc_to_voltage(adc_value);
        }

        if (log_data(voltages, MCP3008_CHANNELS) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    return 0;
}

