#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define PART_ID_REG 0xFF
#define MODE_CONFIG_REG 0x06
#define SPO2_CONFIG_REG 0x08
#define LED1_PA_REG 0x09
#define LED2_PA_REG 0x0A
#define FIFO_DATA_REG 0x07
#define SAMPLE_RATE 100 // Hz
#define PULSE_WIDTH 411 // us
#define ADC_RANGE 4096
#define SPO2_THRESHOLD 95.0
#define HR_THRESHOLD 100.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102();
int read_max30102_data(uint8_t *red_data, uint8_t *ir_data);
float calculate_spo2(const uint8_t *red_data, const uint8_t *ir_data);
float calculate_heart_rate(const uint8_t *ir_data);
void log_data(float spo2, float heart_rate);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    uint8_t mode_config;
    uint8_t spo2_config;
    uint8_t led1_pa;
    uint8_t led2_pa;
} sensor_config_t;

// Function to write a byte to a specific register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a specific register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to initialize the MAX30102 sensor
int init_max30102() {
    sensor_config_t config = {
        .mode_config = 0x40, // Reset
        .spo2_config = 0x27, // 100Hz, 411us pulse width, 4096 ADC range
        .led1_pa = 0x24,
        .led2_pa = 0x24
    };

    // Reset the sensor
    if (write_register(i2c_handle, MODE_CONFIG_REG, config.mode_config) != 0) {
        fprintf(stderr, "Failed to reset MAX30102\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure SpO2 mode
    if (write_register(i2c_handle, MODE_CONFIG_REG, config.mode_config) != 0) {
        fprintf(stderr, "Failed to configure SpO2 mode\n");
        return -1;
    }

    // Configure FIFO
    if (write_register(i2c_handle, SPO2_CONFIG_REG, config.spo2_config) != 0) {
        fprintf(stderr, "Failed to configure FIFO\n");
        return -1;
    }

    // Configure LED amplitudes
    if (write_register(i2c_handle, LED1_PA_REG, config.led1_pa) != 0) {
        fprintf(stderr, "Failed to configure LED1 amplitude\n");
        return -1;
    }
    if (write_register(i2c_handle, LED2_PA_REG, config.led2_pa) != 0) {
        fprintf(stderr, "Failed to configure LED2 amplitude\n");
        return -1;
    }

    return 0;
}

// Function to read data from the MAX30102 sensor
int read_max30102_data(uint8_t *red_data, uint8_t *ir_data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading FIFO data: %d\n", result);
        return -1;
    }

    memcpy(red_data, buffer, 3);
    memcpy(ir_data, buffer + 3, 3);

    return 0;
}

// Function to calculate SpO2 using the ratio-of-ratios method
float calculate_spo2(const uint8_t *red_data, const uint8_t *ir_data) {
    // Simple ratio-of-ratios implementation (replace with more accurate method)
    uint16_t red_value = (red_data[0] << 8) | red_data[1];
    uint16_t ir_value = (ir_data[0] << 8) | ir_data[1];

    float ratio = (float)ir_value / (float)red_value;
    // Implement a more sophisticated SpO2 calculation here
    // This is a placeholder; refer to MAX30102 datasheet for details
    float spo2 = 100.0 - (ratio - 1.0) * 100.0; // Example calculation
    if (spo2 < 0.0) spo2 = 0.0;
    if (spo2 > 100.0) spo2 = 100.0;

    return spo2;
}

// Function to calculate heart rate using peak detection
float calculate_heart_rate(const uint8_t *ir_data) {
    // Simple peak detection implementation
    int peaks = 0;
    for (int i = 1; i < 6; i++) {
        if (ir_data[i] > ir_data[i - 1]) {
            peaks++;
        }
    }

    // Estimate heart rate based on the number of peaks
    float heart_rate = (float)peaks * SAMPLE_RATE; // Beats per second

    return heart_rate;
}

// Function to log data to a file
void log_data(float spo2, float heart_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, SpO2: %.2f%%, Heart Rate: %.2f BPM\n", timestamp, spo2, heart_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    uint8_t part_id;
    if (read_register(i2c_handle, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Sensor not found or error reading Part ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x15) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x15)\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_max30102() != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t red_data[3];
    uint8_t ir_data[3];
    float spo2, heart_rate;

    // Main loop
    while (!terminate) {
        // Read data from the sensor
        if (read_max30102_data(red_data, ir_data) == 0) {
            // Calculate SpO2 and heart rate
            spo2 = calculate_spo2(red_data, ir_data);
            heart_rate = calculate_heart_rate(ir_data);

            // Log the data
            log_data(spo2, heart_rate);

            // Check for critical values and log them
            if (spo2 < SPO2_THRESHOLD || heart_rate > HR_THRESHOLD) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

                fprintf(log_file, "%s, ALERT: SpO2: %.2f%%, Heart Rate: %.2f BPM\n", timestamp, spo2, heart_rate);
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000 / SAMPLE_RATE); // Delay to achieve desired sample rate
    }

    // Clean up resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

