        fprintf(stderr, "Failed to reset MAX30102\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure SpO2 mode
    if (write_register(i2c_handle, MODE_CONFIG_REG, config.mode_config) != 0) {
        fprintf(stderr, "Failed to configure SpO2 mode\n");
        return -1;
    }

    // Configure FIFO
    if (write_register(i2c_handle, SPO2_CONFIG_REG, config.spo2_config) != 0) {
        fprintf(stderr, "Failed to configure FIFO\n");
        return -1;
    }

    // Configure LED amplitudes
    if (write_register(i2c_handle, LED1_PA_REG, config.led1_pa) != 0) {
        fprintf(stderr, "Failed to configure LED1 amplitude\n");
        return -1;
    }
    if (write_register(i2c_handle, LED2_PA_REG, config.led2_pa) != 0) {
        fprintf(stderr, "Failed to configure LED2 amplitude\n");
        return -1;
    }

    return 0;
}

// Function to read data from the MAX30102 sensor
int read_max30102_data(uint8_t *red_data, uint8_t *ir_data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading FIFO data: %d\n", result);
        return -1;
    }

    memcpy(red_data, buffer, 3);
    memcpy(ir_data, buffer + 3, 3);

    return 0;
}

// Function to calculate SpO2 using the ratio-of-ratios method
float calculate_spo2(const uint8_t *red_data, const uint8_t *ir_data) {
    // Simple ratio-of-ratios implementation (replace with more accurate method)
    uint16_t red_value = (red_data[0] << 8) | red_data[1];
    uint16_t ir_value = (ir_data[0] << 8) | ir_data[1];

    float ratio = (float)ir_value / (float)red_value;
    // Implement a more sophisticated SpO2 calculation here
    // This is a placeholder; refer to MAX30102 datasheet for details
    float spo2 = 100.0 - (ratio - 1.0) * 100.0; // Example calculation
    if (spo2 < 0.0) spo2 = 0.0;
    if (spo2 > 100.0) spo2 = 100.0;

    return spo2;
}

// Function to calculate heart rate using peak detection
float calculate_heart_rate(const uint8_t *ir_data) {
    // Simple peak detection implementation
    int peaks = 0;
    for (int i = 1; i < 6; i++) {
        if (ir_data[i] > ir_data[i - 1]) {
            peaks++;
        }
    }

    // Estimate heart rate based on the number of peaks
    float heart_rate = (float)peaks * SAMPLE_RATE; // Beats per second

    return heart_rate;
}

