            spo2 = calculate_spo2(red_data, ir_data);
            heart_rate = calculate_heart_rate(ir_data);

            // Log the data
            log_data(spo2, heart_rate);

            // Check for critical values and log them
            if (spo2 < SPO2_THRESHOLD || heart_rate > HR_THRESHOLD) {
                time_t rawtime;
                struct tm *timeinfo;
