#define VREF 3.3
#define LOG_FILE "analog_log.csv"
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_voltage(int adc_value);
void log_data(int channel, float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for SPI configuration (optional)
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }
    rewind(log_file);

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];
    int count, retries = 3;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x08 | (channel << 4); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    while (retries > 0) {
        count = spiXfer(spi_handle, tx_buf, rx_buf, 3);
        if (count == 3) {
            // Extract ADC value
            int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", 4 - retries, count);
            retries--;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after multiple retries\n");
    return -1; // Indicate failure
}

// Function to calculate voltage from ADC value
float calculate_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to log data to CSV file
void log_data(int channel, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Starting data acquisition...\n");

    while (!terminate) {
        for (int channel = 0; channel < 3; channel++) {
            int adc_value = read_mcp3008(channel);
            if (adc_value >= 0) {
                float voltage = calculate_voltage(adc_value);
                log_data(channel, voltage);
                printf("Channel %d: Voltage = %.3f V\n", channel, voltage);
            } else {
                fprintf(stderr, "Failed to read channel %d\n", channel);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_MS); // Wait before next sample
    }

    cleanup();
    return 0;
}

