#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <gpiod.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define RELAY_GPIO 17
#define REED_GPIO 27
#define NUM_SAMPLES 10
#define SAMPLE_DELAY_MS 50
#define POLL_DELAY_MS 200
#define LOCK_DURATION_S 3
#define THRESHOLD_PERCENT 0.8

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;
static double baseline_sum = 0.0;
static int baseline_count = 0;
static double threshold = 0.0;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int init_i2c(void);
int read_ads1115(int16_t *adc_value);
double calibrate_threshold(void);
int control_relay(int state);
int read_reed_sensor(void);
void log_event(const char *message);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize GPIO lines
int init_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Error getting relay GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    reed_line = gpiod_chip_get_line(gpio_chip, REED_GPIO);
    if (!reed_line) {
        perror("Error getting reed GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_control", 0) < 0) {
        perror("Error requesting relay line as output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        gpiod_line_release(reed_line);
        return -1;
    }

    if (gpiod_line_request_input(reed_line, "reed_sensor", 1) < 0) {
        perror("Error requesting reed line as input");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        gpiod_line_release(reed_line);
        return -1;
    }

    return 0;
}

// Function to initialize I2C communication
int init_i2c(void) {
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
