#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE_0 "/dev/spidev0.0"
#define SPI_DEVICE_1 "/dev/spidev0.1"
#define SPI_DEVICE_2 "/dev/spidev0.2"
#define CS_PIN_0 8
#define CS_PIN_1 7
#define CS_PIN_2 25
#define CS_LINE_COUNT 3
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "soil_moisture_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
static int spi_fd_0 = -1;
static int spi_fd_1 = -1;
static int spi_fd_2 = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[CS_PIN_0, CS_PIN_1, CS_PIN_2];
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int spi_fd, int channel);
int log_data(FILE *fp, time_t timestamp, int sensor1, int sensor2, int sensor3);
void cleanup();
void signal_handler(int sig);

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Read ADC
int spi_read_adc(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].cs_change = 0; // Keep CS low

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Log Data to File
int log_data(FILE *fp, time_t timestamp, int sensor1, int sensor2, int sensor3) {
    if (fprintf(fp, "%ld,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    return 0;
}

// Cleanup Resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close SPI devices
    if (spi_fd_0 != -1) {
        close(spi_fd_0);
    }
    if (spi_fd_1 != -1) {
        close(spi_fd_1);
    }
    if (spi_fd_2 != -1) {
        close(spi_fd_2);
    }

    // Release GPIO lines
    for (int i = 0; i < CS_PIN_0; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Signal Handler
void signal_handler(int sig) {
    printf("Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI devices
    spi_fd_0 = spi_init(SPI_DEVICE_0);
    if (spi_fd_0 < 0) {
        fprintf(stderr, "Failed to initialize SPI device 0. Exiting.\n");
        return 1;
    }
    spi_fd_1 = spi_init(SPI_DEVICE_1);
    if (spi_fd_1 < 0) {
        fprintf(stderr, "Failed to initialize SPI device 1. Exiting.\n");
        cleanup();
        return 1;
    }
    spi_fd_2 = spi_init(SPI_DEVICE_2);
    if (spi_fd_2 < 0) {
        fprintf(stderr, "Failed to initialize SPI device 2. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Check if the file is new and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(log_file);

    // Get chip list
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    // Get CS lines
    lines[CS_PIN_0] = gpiod_chip_get_line(chip, CS_PIN_0);
    lines[CS_PIN_1] = gpiod_chip_get_line(chip, CS_PIN_1);
    lines[CS_PIN_2] = gpiod_chip_get_line(chip, CS_PIN_2);

    if (!lines[CS_PIN_0] || !lines[CS_PIN_1] || !lines[CS_PIN_2]) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    // Request CS lines as outputs
    for (int i = 0; i < CS_PIN_0; i++) {
        if (gpiod_line_request_output(lines[i], "soil_moisture", 0) < 0) {
            perror("Error requesting GPIO line as output");
            cleanup();
            return 1;
        }
    }

    // Main loop
    while (!terminate) {
        time_t timestamp = time(NULL);
        int sensor1_value = -1, sensor2_value = -1, sensor3_value = -1;

        // Read sensor 1 from chip 0
        int adc_value_0 = spi_read_adc(spi_fd_0, 0);
        if (adc_value_0 >= 0) {
            sensor1_value = adc_value_0;
        }

        // Read sensor 2 from chip 1
        int adc_value_1 = spi_read_adc(spi_fd_1, 0);
        if (adc_value_1 >= 0) {
            sensor2_value = adc_value_1;
        }

        // Read sensor 3 from chip 2
        int adc_value_2 = spi_read_adc(spi_fd_2, 0);
        if (adc_value_2 >= 0) {
            sensor3_value = adc_value_2;
        }

        // Log the data
        if (log_data(log_file, timestamp, sensor1_value, sensor2_value, sensor3_value) < 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

