#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3

// Global variables
static volatile int running = 1;
static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;
static int spi_handle;
static FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_moisture(int adc_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    for (int i = 0; i < MAX_RETRIES; ++i) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "SPI transfer failed (attempt %d): %d", i + 1, spiXfer(spi_handle, tx_buffer, rx_buffer, 3));
            log_message(error_message);
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    log_message("Error: Failed to read MCP3008 after multiple retries.");
    return -1; // Indicate failure
}

// Function to map ADC value to moisture percentage
float map_adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_message("Error: Invalid ADC value.");
        return -1.0;
    }

    float moisture = 100.0 - ((float)(adc_value - 200) / (float)(800 - 200)) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[50];
    snprintf(message, sizeof(message), "Pump set to %s", state ? "ON" : "OFF");
    log_message(message);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
    control_pump(0); // Turn off pump
    cleanup();
    exit(0);
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        log_message("Error: pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off on startup

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_message("Error: SPI open failed");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        log_message("Error: Failed to open log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (initialize()) {
        return 1;
    }

    log_message("System initialized.");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture = map_adc_to_moisture(adc_value);
            if (moisture >= 0.0) {
                char message[100];
                snprintf(message, sizeof(message), "Moisture: %.2f%%", moisture);
                log_message(message);

                if (moisture < threshold) {
                    log_message("Moisture below threshold, activating pump.");
                    control_pump(1);
                    gpioDelay(duration * 1000); // Convert seconds to milliseconds
                    control_pump(0);
                    log_message("Pump deactivated.");
                }
            } else {
                log_message("Error: Invalid moisture value.");
            }
        } else {
            log_message("Error: Failed to read moisture sensor.");
        }

        gpioDelay(sleep_interval * 1000); // Convert seconds to milliseconds
    }

    cleanup();
    return 0;
}

