#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SAMPLE_RATE_MS 10
#define EMA_ALPHA 0.2
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int sample_rate_ms;
    float ema_alpha;
    char *log_file;
} Config;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float calculate_ema(float new_value, float current_ema);
int detect_peak(float raw_value, float ema);
int log_event(float raw_value);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate EMA
float calculate_ema(float new_value, float current_ema) {
    return current_ema * (1 - EMA_ALPHA) + new_value * EMA_ALPHA;
}

// Detect peak
int detect_peak(float raw_value, float ema) {
    float threshold = ema * 1.2; // 20% margin
    if (raw_value > threshold) {
        return 1;
    }
    return 0;
}

// Log event
int log_event(float raw_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Raw: %.0f, Peak Detected\n", timestamp, raw_value);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .sample_rate_ms = SAMPLE_RATE_MS,
        .ema_alpha = EMA_ALPHA,
        .log_file = LOG_FILE
    };

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    float ema = 0.0;
    int peak_detected = 0;

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int raw_value = read_mcp3008(0);
        if (raw_value >= 0) {
            ema = calculate_ema((float)raw_value, ema);
            if (detect_peak((float)raw_value, ema)) {
                peak_detected = 1;
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        if (peak_detected) {
            if (log_event((float)raw_value)) {
                fprintf(stderr, "Failed to log event\n");
            }
            peak_detected = 0;
        }

        gpioDelay(config.sample_rate_ms * 1000); // pigpioDelay takes microseconds
    }

    cleanup();
    return 0;
}

