#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define PCF8591_CONTROL_BYTE 0x40 // Single-ended AIN0, analog disabled
#define SAMPLE_DELAY_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int init_i2c(void);
int read_pcf8591(int *sample);
void cleanup(void);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize GPIO
int init_gpio(void) {
    int ret;
    struct gpiod_line_request_config config;

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, 4); // GPIO4
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Configure GPIO line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "pcf8591";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(gpio_line, &config, 0); // Initial value is low
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize I2C
int init_i2c(void) {
    int ret;
    int fd;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    ret = i2c_SLAVE(fd, PCF8591_ADDR, 0);
    if (ret < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    i2c_fd = fd;
    return 0;
}

// Read from PCF8591
int read_pcf8591(int *sample) {
    int ret;
    unsigned char buf[2];

    // Send control byte
    buf[0] = PCF8591_CONTROL_BYTE;
    ret = write(i2c_fd, buf, 1);
    if (ret < 0) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Read 2 bytes (dummy read + actual read)
    ret = read(i2c_fd, buf, 2);
    if (ret < 0) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Discard dummy byte
    *sample = (int)buf[1];

    return 0;
}

// Cleanup resources
void cleanup(void) {
    int ret;

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    int sample;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("PCF8591 ADC reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_pcf8591(&sample) == 0) {
            printf("%d\n", sample);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        usleep(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("PCF8591 ADC reader stopped.\n");
    return 0;
}

