#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_SHUTDOWN 27
#define SAMPLE_RATE_HZ 1
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0
#define VCC 3.3
#define ZERO_FIELD_VOLTAGE 2.5
#define SENSITIVITY 0.0014 // 1.4 mV/Gauss

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_pigpio();
int16_t read_ads1115(int handle, int channel);
float convert_to_voltage(int16_t raw_value);
float calculate_magnetic_field(float voltage);
void update_buffer(float value);
float calculate_rolling_average();
void shutdown_system();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set GPIO mode");
        return -1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0); // Ensure it starts LOW
    return 0;
}

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to read from ADS1115
int16_t read_ads1115(int handle, int channel) {
    uint8_t config[3];
    int16_t raw_value;

    // Configure the ADS1115 for single-ended input on the specified channel
    // and continuous conversion mode.
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0x83; // Single-ended AIN0, 4.096V range, continuous conversion
    config[2] = 0x83; // 128 SPS, Disable comparator

    if (i2cWriteDevice(handle, (char *)config, 3) != 0) {
        log_message(LOG_ERR, "Failed to write to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10 ms

    // Read the conversion result
    uint8_t data[2];
    if (i2cReadDevice(handle, (char *)data, 2) != 0) {
        log_message(LOG_ERR, "Failed to read from I2C device");
        return -1;
    }

    raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Function to convert raw ADC value to voltage
float convert_to_voltage(int16_t raw_value) {
    float voltage = (float)raw_value * VCC / 32768.0;
    return voltage;
}

// Function to calculate magnetic field strength in Gauss
float calculate_magnetic_field(float voltage) {
    float gauss = (voltage - ZERO_FIELD_VOLTAGE) / SENSITIVITY;
    return gauss;
}

// Function to update the circular buffer
void update_buffer(float value) {
    buffer[buffer_index] = value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to shutdown the system
void shutdown_system() {
    log_message(LOG_INFO, "Shutting down system due to high magnetic field");
    gpioWrite(GPIO_SHUTDOWN, 1); // Set GPIO HIGH
    log_message(LOG_INFO, "GPIO HIGH");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    terminate = 1;
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Initialize syslog
    openlog("magnetic_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_message(LOG_INFO, "Magnetic sensor monitoring started");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t raw_value = read_ads1115(i2c_handle, 0); // Channel 0
        if (raw_value == -1) {
            log_message(LOG_WARNING, "Failed to read ADC value, skipping sample");
            gpioDelay(1000000); // 1 second delay
            continue;
        }

        // Convert to voltage
        float voltage = convert_to_voltage(raw_value);

        // Validate voltage
        if (voltage < 0.0 || voltage > VCC) {
            log_message(LOG_WARNING, "Invalid voltage reading, skipping sample");
            gpioDelay(1000000); // 1 second delay
            continue;
        }

        // Calculate magnetic field strength
        float gauss = calculate_magnetic_field(voltage);

        // Update circular buffer
        update_buffer(gauss);

        // Calculate rolling average
        float rolling_average = calculate_rolling_average();

        // Check threshold
        if (rolling_average > THRESHOLD_GAUSS) {
            shutdown_system();
        }

        // Log data
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Voltage: %.3f V, Gauss: %.3f, Rolling Average: %.3f", voltage, gauss, rolling_average);
        log_message(LOG_INFO, log_buffer);

        // Delay for 1 Hz sampling
        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    log_message(LOG_INFO, "Cleaning up...");
    gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

