#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define READ_INTERVAL 60      // seconds
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int control_pump(int state);
int log_event(int moisture_level);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    int spi_xfer_result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (spi_xfer_result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", spi_xfer_result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

// Function to log events to a file
int log_event(int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, Moisture: %d\n", timestamp, moisture_level);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open log file
    log_file = fopen("watering_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Deactivate pump
    control_pump(0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    fprintf(stderr, "Watering system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int moisture_level = -1;
        int retries = 0;

        while (moisture_level == -1 && retries < MAX_RETRIES) {
            moisture_level = read_mcp3008(0);
            if (moisture_level == -1) {
                fprintf(stderr, "Error: Failed to read moisture level, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                sleep(1); // Wait before retrying
            } else {
                printf("Moisture level: %d\n", moisture_level);
            }
        }

        if (moisture_level != -1) {
            if (moisture_level < MOISTURE_THRESHOLD) {
                printf("Moisture level below threshold. Activating pump.\n");
                if (control_pump(1) == 0) {
                    printf("Pump activated. Watering for %d seconds.\n", WATERING_DURATION);
                    sleep(WATERING_DURATION);
                    printf("Pump deactivated.\n");
                    if (control_pump(0) != 0) {
                        fprintf(stderr, "Error: Failed to deactivate pump after watering.\n");
                    }
                } else {
                    fprintf(stderr, "Error: Failed to activate pump.\n");
                }
            }

            if (log_event(moisture_level) != 0) {
                fprintf(stderr, "Error: Failed to log event.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read moisture level after multiple retries.\n");
        }

        sleep(READ_INTERVAL);
    }

    cleanup();
    fprintf(stderr, "Watering system terminated.\n");
    return 0;
}

