#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RAIN_SENSOR_CHANNEL 0
#define ADC_FULL_SCALE 1023.0
#define INTENSITY_MIN 0.0
#define INTENSITY_MAX 10.0
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_intensity(int adc_value);
void log_data(float intensity, int adc_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value from response
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map ADC value to rainfall intensity
float map_adc_to_intensity(int adc_value) {
    float intensity = INTENSITY_MIN + (float)(adc_value - INTENSITY_MIN) * INTENSITY_MAX / (ADC_FULL_SCALE - INTENSITY_MIN);
    return intensity;
}

// Function to log data to stdout
void log_data(float intensity, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, ADC Value: %d, Intensity: %.2f\n", timestamp, adc_value, intensity);
}

int main() {
    int adc_value;
    float intensity;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in 1 second...\n");
            sleep(1);
            continue; // Retry the loop
        }

        // Map ADC value to intensity
        intensity = map_adc_to_intensity(adc_value);

        // Log data
        log_data(intensity, adc_value);

        // Wait for 1 second
        sleep(SAMPLE_INTERVAL);
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

