#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1000 // milliseconds
#define BLINK_FREQUENCY 10    // Hz

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int16_t *adc_value);
double calculate_gauss(int16_t adc_value);
void blink_led(int duration_ms);
void signal_handler(int signal);
void cleanup();

// Structure for ADS1115 configuration
typedef struct {
    uint8_t config_reg;
    uint16_t config_value;
} ads1115_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read ADC value from ADS1115
int read_adc(int16_t *adc_value) {
    ads1115_config_t config = {
        .config_reg = 0x01, // Configuration register address
        .config_value = 0x4003  // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    };

    if (i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, (char *)&config.config_value, 2) != 2) {
        fprintf(stderr, "Failed to write config register\n");
        return 1;
    }

    gpioDelay(10); // Wait for conversion (adjust as needed)

    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2) != 2) {
        fprintf(stderr, "Failed to read conversion register\n");
        return 1;
    }

    *adc_value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Calculate magnetic field strength in Gauss
double calculate_gauss(int16_t adc_value) {
    double voltage = (adc_value * 4.096) / 32768.0; // Convert ADC value to voltage
    double gauss = voltage / 0.001; // Convert voltage to Gauss
    return gauss;
}

// Blink LED for a specified duration
void blink_led(int duration_ms) {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(duration_ms / 2); // On for half the duration
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(duration_ms / 2); // Off for half the duration
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
        printf("Using threshold: %.2f Gauss\n", threshold);
    } else {
        printf("Using default threshold: %.2f Gauss\n", DEFAULT_THRESHOLD);
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    int16_t adc_value;
    double gauss;

    // Main loop
    while (!terminate) {
        if (read_adc(&adc_value) == 0) {
            gauss = calculate_gauss(adc_value);

            printf("Magnetic Field: %.2f Gauss\n", gauss);

            if (fabs(gauss) > threshold) {
                printf("Threshold exceeded! Blinking LED...\n");
                blink_led(BLINK_DURATION);
            }
        } else {
            fprintf(stderr, "ADC read failed, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

