#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <time.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MOISTURE_HYSTERESIS 5
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_monitor"
#define MQTT_TOPIC "soil_moisture"
#define PUMP_CONTROL_TOPIC "pump_control"

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_relay(int state);
void publish_moisture(float moisture);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signum);
int mqtt_connect_and_subscribe();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        syslog(LOG_ERR, "SPI transfer failed: %d", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Assuming ADC range is 0-1023, and moisture range is 0-100%
    // You may need to calibrate this based on your sensor and soil
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    syslog(LOG_INFO, "Relay set to %d", state);
}

// Function to publish moisture reading to MQTT
void publish_moisture(float moisture) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(ret));
    }
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Received MQTT message on topic %s: %s", message->topic, (char *)message->payload);

        if (strcmp(message->topic, PUMP_CONTROL_TOPIC) == 0) {
            if (strcmp((char *)message->payload, "ON") == 0) {
                control_relay(1); // Activate relay (pump)
            } else if (strcmp((char *)message->payload, "OFF") == 0) {
                control_relay(0); // Deactivate relay (pump)
            } else {
                syslog(LOG_ERR, "Invalid pump control command: %s", (char *)message->payload);
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received: %d. Terminating...", signum);
    terminate = 1;
}

// Function to connect to MQTT broker and subscribe to topics
int mqtt_connect_and_subscribe() {
    int ret;

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, message_callback);

    ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_subscribe(mosq, NULL, PUMP_CONTROL_TOPIC, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mosquitto_strerror(ret));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

int main() {
    openlog("soil_monitor", LOG_PID, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Ensure relay is off on startup

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Connect to MQTT broker
    if (mqtt_connect_and_subscribe() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            sleep(60);
            continue;
        }

        float moisture = calculate_moisture(adc_value);

        // Publish moisture reading
        publish_moisture(moisture);

        // Control relay based on moisture level
        if (moisture < MOISTURE_THRESHOLD_LOW) {
            control_relay(1); // Activate relay
        } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
            control_relay(0); // Deactivate relay
        }

        sleep(60);
    }

    // Cleanup
    control_relay(0); // Ensure relay is off
    spiClose(spi_handle);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

