#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100
#define LOG_FILE "vibration_log.txt"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// GPIO pins for motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
int map_adc_to_pwm(int adc_value);
void set_motor_pwm(int gpio, int duty_cycle);
void log_event(int noise_level, int duty_cycle1, int duty_cycle2);
void send_data(int noise_level, int duty_cycle1, int duty_cycle2);
void signal_handler(int signal);
int get_mac_address(char *mac_address);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1; // Initialize to an error value

    buffer[0] = 0x01; // Start bit
    buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to map ADC value to PWM duty cycle
int map_adc_to_pwm(int adc_value) {
    // Linear mapping: 0-1023 -> 0-100
    return (int)(((float)adc_value / 1023.0) * 100.0);
}

// Function to set motor PWM duty cycle
void set_motor_pwm(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to log events to file
void log_event(int noise_level, int duty_cycle1, int duty_cycle2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Noise Level: %d, Motor 1 Duty Cycle: %d, Motor 2 Duty Cycle: %d\n",
            timestamp, noise_level, duty_cycle1, duty_cycle2);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send data to the server
void send_data(int noise_level, int duty_cycle1, int duty_cycle2) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[256];
    char mac_address[18];

    // Get MAC address
    if (get_mac_address(mac_address) != 0) {
        fprintf(stderr, "Failed to get MAC address\n");
        return;
    }

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));

    // Server information
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("inet_pton failed");
        close(sockfd);
        return;
    }

    // Format the data to send
    snprintf(buffer, sizeof(buffer), "%s,%d,%d", mac_address, noise_level, duty_cycle1, duty_cycle2);

    // Send the data
    if (sendto(sockfd, (const char *)buffer, strlen(buffer), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
    }

    close(sockfd);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to get MAC address
int get_mac_address(char *mac_address) {
    int fd;
    unsigned char buffer[6];

    fd = open("/proc/net/dev/macaddr", O_RDONLY);
    if (fd < 0) {
        perror("Failed to open /proc/net/dev/macaddr");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read mac address");
        close(fd);
        return -1;
    }

    close(fd);

    snprintf(mac_address, 18, "%02x:%02x:%02x:%02x:%02x:%02x",
             buffer[0], buffer[1], buffer[2], buffer[3], buffer[4], buffer[5]);
    return 0;
}

int main() {
    int noise_level, duty_cycle1, duty_cycle2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if ((spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read noise level from MCP3008
        noise_level = read_mcp3008(MCP3008_CHANNEL);
        if (noise_level == -1) {
            fprintf(stderr, "Failed to read noise level, skipping iteration\n");
            gpioDelay(10); // Wait 10ms before next iteration
            continue;
        }

        // Map ADC value to PWM duty cycle
        duty_cycle1 = map_adc_to_pwm(noise_level);
        duty_cycle2 = map_adc_to_pwm(noise_level);

        // Set motor PWM duty cycles
        set_motor_pwm(MOTOR1_GPIO, duty_cycle1);
        set_motor_pwm(MOTOR2_GPIO, duty_cycle2);

        // Log event
        log_event(noise_level, duty_cycle1, duty_cycle2);

        // Send data to server
        send_data(noise_level, duty_cycle1, duty_cycle2);

        // Wait 10ms
        gpioDelay(10);
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    set_motor_pwm(MOTOR1_GPIO, 0);
    set_motor_pwm(MOTOR2_GPIO, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

