        close(sockfd);
        return;
    }

    // Format the data to send
    snprintf(buffer, sizeof(buffer), "%s,%d,%d", mac_address, noise_level, duty_cycle1, duty_cycle2);

    // Send the data
    if (sendto(sockfd, (const char *)buffer, strlen(buffer), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
    }

    close(sockfd);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to get MAC address
int get_mac_address(char *mac_address) {
    int fd;
    unsigned char buffer[6];

    fd = open("/proc/net/dev/macaddr", O_RDONLY);
    if (fd < 0) {
        perror("Failed to open /proc/net/dev/macaddr");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read mac address");
        close(fd);
        return -1;
    }

    close(fd);

    snprintf(mac_address, 18, "%02x:%02x:%02x:%02x:%02x:%02x",
             buffer[0], buffer[1], buffer[2], buffer[3], buffer[4], buffer[5]);
    return 0;
}

int main() {
    int noise_level, duty_cycle1, duty_cycle2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if ((spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read noise level from MCP3008
        noise_level = read_mcp3008(MCP3008_CHANNEL);
        if (noise_level == -1) {
            fprintf(stderr, "Failed to read noise level, skipping iteration\n");
            gpioDelay(10); // Wait 10ms before next iteration
            continue;
        }

        // Map ADC value to PWM duty cycle
        duty_cycle1 = map_adc_to_pwm(noise_level);
        duty_cycle2 = map_adc_to_pwm(noise_level);

        // Set motor PWM duty cycles
        set_motor_pwm(MOTOR1_GPIO, duty_cycle1);
        set_motor_pwm(MOTOR2_GPIO, duty_cycle2);

        // Log event
        log_event(noise_level, duty_cycle1, duty_cycle2);

        // Send data to server
        send_data(noise_level, duty_cycle1, duty_cycle2);

        // Wait 10ms
        gpioDelay(10);
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    set_motor_pwm(MOTOR1_GPIO, 0);
    set_motor_pwm(MOTOR2_GPIO, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

