int i2c_fd;
int socket_fd;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_db(int adc_value);
int read_bh1750();
void log_data(float sound_level, float light_level, int error_code);
void send_data(float sound_level, float light_level, int error_code);
void signal_handler(int signal);
int init_i2c();
int init_spi();
int init_socket();
int init_logging();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(error_log_file, "%s: Invalid MCP3008 channel: %d\n", __func__, channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(error_log_file, "%s: SPI transfer failed\n", __func__);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to dB (example formula, adjust as needed)
float adc_to_db(int adc_value) {
    // This is a placeholder.  You'll need to calibrate this based on your setup.
    // Assuming a linear relationship between ADC value and dB.
    // Example: 0 ADC = -60 dB, 1023 ADC = 0 dB
    float db = (float)adc_value / 1023.0 * 60.0;
    return db;
}

// Function to read from BH1750 sensor
int read_bh1750() {
    unsigned char buf[2];
    int lux = -1; // Initialize to an error value

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(error_log_file, "%s: I2C_SLAVE failed\n", __func__);
        return -1;
    }

    // Send command for continuous high-resolution mode 2
    if (i2cWriteByte(i2c_fd, BH1750_CONTINUOUS_HIGH_RES_MODE) != 0) {
        fprintf(error_log_file, "%s: Failed to write to BH1750\n", __func__);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(200); // Wait 200ms

    // Read two bytes of data
    if (i2cReadI2CBlockData(i2c_fd, 0x00, (char *)buf, 2) != 2) {
        fprintf(error_log_file, "%s: Failed to read from BH1750\n", __func__);
        return -1;
    }

    lux = (buf[0] << 8) | buf[1];

    return lux;
}

