void send_data(float sound_level, float light_level, int error_code) {
    struct sockaddr_in server_addr;
    char message[256];

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(error_log_file, "%s: Invalid server IP address\n", __func__);
        return;
    }

    snprintf(message, sizeof(message), "%s,%.2f,%.2f,%d", SERVER_IP, sound_level, light_level, error_code);

    if (sendto(socket_fd, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(error_log_file, "%s: Failed to send data to server\n", __func__);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(error_log_file, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

