int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(error_log_file, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize UDP socket
int init_socket() {
    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        fprintf(error_log_file, "Failed to create socket: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

