#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define MAX_RETRIES 3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void control_pump(float moisture_level);
void log_data(float moisture_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count, adc_value;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    for (int i = 0; i < MAX_RETRIES; i++) {
        count = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (count == 3) {
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", i + 1, count);
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d attempts. Returning -1.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(float moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        printf("Moisture level low (%.2f%%). Turning pump ON.\n", moisture_level);
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        printf("Moisture level OK (%.2f%%). Turning pump OFF.\n", moisture_level);
    }
}

// Function to log data to the console
void log_data(float moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Moisture: %.2f%%\n", timestamp, moisture_level);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Shutting down gracefully...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
