#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define PROXIMITY_THRESHOLD 20 // cm
#define DEBOUNCE_DELAY 1000 // ms
#define LOG_FILE "door_events.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_distance(int adc_value);
void control_relay(int state);
void log_event(const char *event);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to distance (cm)
float adc_to_distance(int adc_value) {
    // This is a simplified linear approximation.
    // A more accurate model would involve a lookup table or polynomial fitting.
    // The GP2Y0A21YK0F has a non-linear relationship between voltage and distance.
    // This approximation is for demonstration purposes only.
    float voltage = (3.3 * adc_value) / 1024.0; // Assuming 3.3V reference
    float distance = 27.0 / (voltage + 0.05); // Example approximation
    return distance;
}

// Function to control the relay (active-high)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    // Deactivate relay
    control_relay(0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Door sensor monitoring started. Press Ctrl+C to exit.\n");

    int relay_state = 0; // 0 = off, 1 = on
    int last_relay_state = 0;
    time_t last_trigger_time = 0;

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to distance
        float distance = adc_to_distance(adc_value);

        // Log distance reading
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Distance: %.2f cm", distance);
        log_event(log_message);

        // Check for proximity
        if (distance < PROXIMITY_THRESHOLD) {
            // Check for debounce
            time_t current_time = time(NULL);
            if (difftime(current_time, last_trigger_time) * 1000 >= DEBOUNCE_DELAY) {
                // Activate relay
                control_relay(1);
                relay_state = 1;

                // Log event
                log_event("Door opened");

                // Update last trigger time
                last_trigger_time = current_time;

                // Wait for a while before checking again
                gpioDelay(500); // Check every 500ms
            }
        } else {
            // Deactivate relay
            control_relay(0);
            relay_state = 0;
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

