        // Convert ADC value to distance
        float distance = adc_to_distance(adc_value);

        // Log distance reading
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Distance: %.2f cm", distance);
        log_event(log_message);

        // Check for proximity
        if (distance < PROXIMITY_THRESHOLD) {
            // Check for debounce
            time_t current_time = time(NULL);
            if (difftime(current_time, last_trigger_time) * 1000 >= DEBOUNCE_DELAY) {
                // Activate relay
                control_relay(1);
                relay_state = 1;

                // Log event
                log_event("Door opened");

                // Update last trigger time
                last_trigger_time = current_time;

                // Wait for a while before checking again
                gpioDelay(500); // Check every 500ms
            }
        } else {
            // Deactivate relay
            control_relay(0);
            relay_state = 0;
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

