// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define RETRY_COUNT 5
#define BACKOFF_DELAY 10 // milliseconds
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for SPI configuration (optional)
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value = -1; // Initialize to an invalid value
    int retry = 0;

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    while (retry < RETRY_COUNT) {
        int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (spi_result == 3) {
            // Extract ADC value
            adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            break; // Exit retry loop on success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", retry + 1, spi_result);
            retry++;
            gpioDelay(BACKOFF_DELAY * (1 << retry)); // Exponential backoff
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "Failed to read MCP3008 after %d attempts\n", RETRY_COUNT);
    }

    return adc_value;
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate an error
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to cleanup resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    fprintf(stdout, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture_percentage = convert_to_moisture_percentage(adc_value);
            if (moisture_percentage >= 0.0) {
                log_data(moisture_percentage);
                printf("Moisture: %.2f%%\n", moisture_percentage);
            } else {
                fprintf(stderr, "Error converting ADC value to moisture percentage\n");
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    fprintf(stdout, "Soil moisture monitoring stopped.\n");
    return 0;
}

