// Read distance from HC-SR04 sensor
int read_distance() {
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) {
        log_message("Timeout waiting for echo high");
        return -1; // Timeout
    }
    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) {
        log_message("Timeout waiting for echo low");
        return -1; // Timeout
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double time_taken = (double)diff / 1000000.0; // in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // in cm

    if (distance < 0 || distance > MAX_DISTANCE) {
        log_message("Invalid distance reading");
        return -1; // Invalid reading
    }

    return (int)distance;
}

// Read LDR value from MCP3008 ADC
int read_ldr() {
    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | MCP3008_CHANNEL) << 4;
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

