    }

    float normalized_distance = (float)(distance - min_distance) / (max_distance - min_distance);
    float frequency = MIN_FREQUENCY + normalized_distance * (MAX_FREQUENCY - MIN_FREQUENCY);

    return (int)frequency;
}

// Map LDR value to PWM duty cycle
