    float normalized_ldr = (float)(ldr_value - min_ldr_value) / (max_ldr_value - min_ldr_value);
    float duty_cycle = MIN_DUTY_CYCLE + normalized_ldr * (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE);

    return (int)duty_cycle;
