// Log messages to file
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file);
    }
}

int main() {
    // Initialize logging
    log_file = fopen("theremin.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_message("Starting Theremin application");

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_message("GPIO initialization failed");
        fclose(log_file);
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        log_message("SPI initialization failed");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Load configuration
    if (load_config() != 0) {
        log_message("Using default configuration");
    }

    // Calibrate sensor
    if (calibrate_sensor() != 0) {
        log_message("Calibration skipped");
    }

    // Main loop
    while (running) {
        // Read distance
        int distance = read_distance();
        if (distance == -1) {
            distance = last_distance; // Use last valid reading
        }

        // Map distance to frequency
        int frequency = map_distance_to_frequency(distance);

        // Read LDR value
        int ldr_value = read_ldr();
        if (ldr_value == -1) {
            ldr_value = last_ldr_value; // Use last valid reading
        }

        // Map LDR to duty cycle
        int duty_cycle = map_ldr_to_duty_cycle(ldr_value);

        // Map LDR to PWM ADC
        int pwm_adc = map_ldr_to_duty_cycle(ldr_value);

        // Set PWM duty cycle
        if (pwm_handle >= 0) {
            gpioPWM(PWM_PIN, duty_cycle);
        } else {
            pwm_handle = gpioSetPWMchannel(PWM_PIN, 0); // Use channel 0
            if (pwm_handle < 0) {
                log_message("Failed to set PWM channel");
            } else {
                gpioSetPWMfrequency(pwm_handle, PWM_FREQUENCY);
                gpioSetPWMrange(pwm_handle, PWM_RANGE);
            }
        }

        // Map LDR to PWM ADC
        if (spi_handle >= 0) {
            unsigned char buffer[3];
            buffer[0] = 0x01; // Start bit
            buffer[1] = (0x08 | MCP3008_CHANNEL) << 4;
            buffer[2] = pwm_adc;

            wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

            // The ADC value is already in the buffer[2]
            ldr_value = buffer[2];
        } else {
            spi_handle = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
            if (spi_handle == -1) {
                log_message("SPI setup failed for ADC");
            } else {
                pwm_handle = gpioSetPWMchannel(PWM_PIN, 0); // Use channel 0
                if (pwm_handle < 0) {
                    log_message("Failed to set PWM channel for ADC");
                } else {
                    gpioSetPWMfrequency(pwm_handle, PWM_FREQUENCY);
                    gpioSetPWMrange(pwm_handle, PWM_RANGE);
                }
            }
        }

        // Update last values
        last_distance = distance;
        last_ldr_value = ldr_value;
        last_pwm_duty_cycle = duty_cycle;
        last_pwm_adc = pwm_adc;

        // Log data
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Distance: %d cm, Frequency: %d Hz, LDR: %d, Duty Cycle: %d, PWM ADC: %d",
                 distance, frequency, ldr_value, duty_cycle, pwm_adc);
        log_message(log_buffer);

        gpioDelay(50); // Delay for 50ms
    }

    // Clean up
    log_message("Cleaning up...");
    if (pwm_handle >= 0) {
        gpioPWM(PWM_PIN, 0); // Stop PWM
        gpioSetPWMchannel(PWM_PIN, -1); // Disable PWM channel
    }
    if (spi_handle >= 0) {
        wiringPiSPIClose(SPI_CHANNEL);
    }
    gpioTerminate();
    fclose(log_file);

    return 0;
}

