#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIR 23
#define MOTOR1_PWM 12 // PWM channel

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIR 25
#define MOTOR2_PWM 13 // PWM channel

// MCP3008 SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define SPI_CE0 8

// Potentiometer channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Logarithmic mapping function
int map_log(int value, int min, int max) {
    if (value <= 0) return 0;
    if (value >= 1023) return max;
    return (int)(min + 255 * (1.0 - log10((float)value / 1023.0) / log10(2.0)));
}

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
void set_motor_speed(int motor, int speed);
void move_motor(int motor, int direction, int speed);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        gpioPWM(MOTOR1_PWM, speed);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_PWM, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor: %d\n", motor);
    }
}

// Function to move motor with acceleration/deceleration
void move_motor(int motor, int direction, int speed) {
    int current_speed = 0;
    int direction_gpio = (direction == 1) ? MOTOR1_DIR : MOTOR2_DIR;
    int enable_gpio = (motor == 1) ? MOTOR1_ENABLE : MOTOR2_ENABLE;

    // Acceleration phase
    for (int i = 0; i <= 255; i += 5) {
        set_motor_speed(motor, i);
        gpioWrite(direction_gpio, (i > 0) ? 1 : 0); // Set direction based on speed
        gpioWrite(enable_gpio, 1); // Enable motor
        gpioDelay(1000); // 1ms delay
    }

    // Constant speed phase
    for (int i = 0; i < 2; i++) {
        set_motor_speed(motor, speed);
        gpioWrite(direction_gpio, (speed > 0) ? 1 : 0); // Set direction based on speed
        gpioWrite(enable_gpio, 1); // Enable motor
        gpioDelay(2000); // 2 seconds
    }

    // Deceleration phase
    for (int i = 255; i >= 0; i -= 5) {
        set_motor_speed(motor, i);
        gpioWrite(direction_gpio, (i > 0) ? 1 : 0); // Set direction based on speed
        gpioWrite(enable_gpio, 1); // Enable motor
        gpioDelay(1000); // 1ms delay
    }

    // Disable motor
    gpioWrite(enable_gpio, 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Disable motors
    gpioWrite(MOTOR1_ENABLE, 0);
    gpioWrite(MOTOR2_ENABLE, 0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR1_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_PWM, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_PWM, 255);
    gpioSetPWMrange(MOTOR2_PWM, 255);

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(MOTOR1_PWM, 1000);
    gpioSetPWMfrequency(MOTOR2_PWM, 1000);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values. Retrying...\n");
            gpioDelay(100000); // 0.1 second delay
            continue;
        }

        // Map potentiometer values to speed factors
        int speed_factor1 = map_log(pot1_value, 0, 255);
        int speed_factor2 = map_log(pot2_value, 0, 255);

        // Move motors
        move_motor(1, 1, speed_factor1); // Motor 1 forward
        move_motor(2, 0, speed_factor2); // Motor 2 backward

        gpioDelay(5000000); // 5-second pause
    }

    // Cleanup (should not reach here if signal handler is used)
    gpioWrite(MOTOR1_ENABLE, 0);
    gpioWrite(MOTOR2_ENABLE, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

