// Define GPIO pins
#define LED_PIN 17
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// SPI channel
#define SPI_CHANNEL 0

// SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Global variables
int spi_handle;
int ambient_level;
int running = 1;

// Function prototypes
int read_mcp3008(int channel);
int calibrate_ambient_level(int *ambient_level);
void control_led(int state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    if (spiXfer(spi_handle, spi_data, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calibrate ambient level
int calibrate_ambient_level(int *ambient_level) {
    int sum = 0;
    int num_samples = 100; // Number of samples for calibration

    printf("Calibrating ambient level... Please keep the environment quiet.\n");
    for (int i = 0; i < num_samples; i++) {
        int raw_value = read_mcp3008(0);
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read raw value during calibration\n");
            return -1;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between samples
    }

    *ambient_level = sum / num_samples;
    printf("Calibration complete. Ambient level: %d\n", *ambient_level);
    return 0;
