#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE)
#define CS_PIN 8 // GPIO8

static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nSignal received, terminating...\n");
}

// Function to initialize the SPI device
int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to initialize the GPIO line
int gpio_init() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, CS_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request(line, "audio_sampler", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log the audio data to a file
int log_data(int adc_value) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
        perror("Error getting timestamp");
        fclose(fp);
        return -1;
    }

    long timestamp_ns = ts.tv_sec * 1000000000 + ts.tv_nsec;

    fprintf(fp, "%ld|%d\n", timestamp_ns, adc_value);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("Error flushing log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            usleep(10000); // 10ms delay
            continue;
        }

        if (log_data(adc_value) != 0) {
            fprintf(stderr, "Error logging data. \n");
        }

        usleep(SAMPLE_PERIOD_NS); // Sleep for the remaining time
    }

    // Cleanup
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd > 0) {
        close(spi_fd);
    }

    return 0;
}

