        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            usleep(10000); // 10ms delay
            continue;
        }

        if (log_data(adc_value) != 0) {
            fprintf(stderr, "Error logging data. \n");
        }

        usleep(SAMPLE_PERIOD_NS); // Sleep for the remaining time
    }

    // Cleanup
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd > 0) {
        close(spi_fd);
    }

