#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define ADXL335 sensitivity (300 mV/g)
#define ADXL335_SENSITIVITY 0.3

// Define zero-g bias voltage (1.5V)
#define ADXL335_ZERO_G 1.5

// Define Kalman filter parameters
#define Q_ANGLE 0.001 // Process noise covariance
#define R_MEASUREMENT 0.03 // Measurement noise covariance

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state variables
float x_angle = 0.0; // State
float P = 1.0;       // Error covariance

// Function prototypes
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
void kalman_filter(float measurement, float *x, float *P);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    if (spiXfer(spi_handle, spi_data, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * (3.3 / 1024.0);
}

// Function to convert voltage to acceleration (g)
float voltage_to_acceleration(float voltage) {
    return (voltage - ADXL335_ZERO_G) / ADXL335_SENSITIVITY;
}

// Kalman filter function
void kalman_filter(float measurement, float *x, float *P) {
    float y = measurement; // Measurement
    float z = *x;          // State
    float Q = Q_ANGLE;     // Process noise covariance
    float R = R_MEASUREMENT; // Measurement noise covariance

    // Prediction step
    float z_pred = z; // Predicted state
    float P_pred = *P + Q; // Predicted error covariance

    // Update step
    float K = P_pred / (P_pred + R); // Kalman gain
    *x = z_pred + K * (y - z_pred); // Updated state
    *P = (1 - K) * P_pred; // Updated error covariance
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_adc(0);
        int y_adc = read_adc(1);
        int z_adc = read_adc(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltages
        float x_voltage = adc_to_voltage(x_adc);
        float y_voltage = adc_to_voltage(y_adc);
        float z_voltage = adc_to_voltage(z_adc);

        // Convert voltages to acceleration
        float x_acceleration = voltage_to_acceleration(x_voltage);
        float y_acceleration = voltage_to_acceleration(y_voltage);
        float z_acceleration = voltage_to_acceleration(z_voltage);

        // Apply Kalman filter
        kalman_filter(x_acceleration, &x_angle, &P);
        kalman_filter(y_acceleration, &x_angle, &P);
        kalman_filter(z_acceleration, &x_angle, &P);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_angle, x_angle, x_angle);

        // Delay for 100 ms (10 Hz sampling rate)
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

