#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO lines for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the sampling interval (in milliseconds)
#define SAMPLING_INTERVAL 100

// Define the magnetic field range (in mT)
#define MIN_MG  -100.0
#define MAX_MG   100.0

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int gpio);
float calculate_magnetic_field(int sensor_value);
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT);
void signal_handler(int sig);
int initialize_gpio(void);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig)
{
    if (sig == SIGINT)
    {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read the sensor value from a GPIO line
int read_sensor(int gpio)
{
    int value = -1; // Initialize to an invalid value
    struct gpiod_line *line = NULL;

    if (gpio == SENSOR1_GPIO)
    {
        line = line1;
    } else if (gpio == SENSOR2_GPIO)
    {
        line = line2;
    } else if (gpio == SENSOR3_GPIO)
    {
        line = line3;
    } else
    {
        fprintf(stderr, "Error: Invalid GPIO line number: %d\n", gpio);
        return -1; // Indicate an error
    }

    value = gpiod_line_get_value(line);
    if (value < 0)
    {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", gpio, strerror(errno));
        return -1; // Indicate an error
    }

    return value;
}

// Function to calculate the magnetic field strength in millitesla
float calculate_magnetic_field(int sensor_value)
{
    float mT = (sensor_value * 3.3 - 1.65) / 0.025;
    return mT;
}

// Function to log the sensor data to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL)
    {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, sensor1_mT, sensor2_mT, sensor3_mT) < 0)
    {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Function to initialize the GPIO lines
int initialize_gpio(void)
{
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request lines for each sensor
    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1)
    {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR1_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2)
    {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR2_GPIO, strerror(errno));
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return -1;
    }

    line3 = gpiod_chip_get_line(chip, SENSOR3_GPIO);
    if (!line3)
    {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR3_GPIO, strerror(errno));
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request lines as inputs
    ret = gpiod_line_request_input(line1, "sensor1");
    if (ret < 0)
    {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", SENSOR1_GPIO, strerror(errno));
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return -1;
