#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>
#include <pigpio.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60 // seconds

static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static int reconnect_delay = 1; // Initial delay in seconds

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED on startup
    return 0;
}

// Function to parse JSON payload
int parse_json_payload(const char *payload, int *led_state) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            syslog(LOG_ERR, "JSON parse error: %s", error_ptr);
        }
        return -1;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (cJSON_IsBool(led_state_json)) {
        *led_state = led_state_json->valueint;
    } else {
        syslog(LOG_ERR, "Invalid type for 'led_state' in JSON");
        cJSON_Delete(json);
        return -1;
    }

    cJSON_Delete(json);
    return 0;
}

// Function to control the LED
void control_led(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
}

// Function to reconnect to MQTT broker
int reconnect_mqtt() {
    int rc;
    int retry_delay = reconnect_delay;

    while (retry_delay <= MAX_RECONNECT_DELAY) {
        syslog(LOG_INFO, "Attempting to reconnect to MQTT broker in %d seconds...", retry_delay);
        rc = mosquitto_reconnect(mosq, retry_delay);
        if (rc == MOSQ_ERR_SUCCESS) {
            syslog(LOG_INFO, "Reconnected to MQTT broker successfully.");
            return 0;
        } else {
            syslog(LOG_ERR, "Reconnection failed: %s. Retrying in %d seconds...", mosquitto_strerror(rc), retry_delay);
            sleep(retry_delay);
            retry_delay *= 2; // Exponential backoff
        }
    }

    syslog(LOG_ERR, "Failed to reconnect to MQTT broker after %d seconds. Giving up.", MAX_RECONNECT_DELAY);
    return -1;
}

int main(int argc, char *argv[]) {
    openlog("rpi_led_control", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting rpi_led_control...");

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance.");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_disconnect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, message_callback);
    mosquitto_subscribe_callback_set(mosq, subscribe_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        int led_state;
        int rc = mosquitto_loop(mosq, -1, 1); // -1 means blocking, 1 is the max number of messages to process

        if (rc == MOSQ_ERR_SUCCESS) {
            if (rc > 0) {
                // A message was received
                rc = mosquitto_message(mosq, NULL, NULL, &rc, NULL, NULL, NULL, NULL);
                if (rc == MOSQ_ERR_SUCCESS) {
                    if (parse_json_payload((char *)rc, &led_state) == 0) {
                        control_led(led_state);
                        syslog(LOG_INFO, "Received: led_state=%d, GPIO=%d, state=%d", led_state, GPIO_PIN, gpioRead(GPIO_PIN));
                    } else {
                        syslog(LOG_ERR, "Failed to parse JSON payload.");
                    }
                } else {
                    syslog(LOG_ERR, "Failed to receive message.");
                }
            }
        } else {
            // No message received or error occurred
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            }
        }

        sleep(1); // Check for messages every second
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

// Callback function for incoming MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        int led_state;
        if (parse_json_payload((char *)message->payload, &led_state) == 0) {
            control_led(led_state);
        } else {
            syslog(LOG_ERR, "Failed to parse JSON payload in message callback.");
        }
    } else {
        syslog(LOG_ERR, "Empty message received in message callback.");
    }
}

// Callback function for subscription events
void subscribe_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "Subscribed to topic: %s", MQTT_TOPIC);
    } else {
        syslog(LOG_ERR, "Failed to subscribe to topic: %s", MQTT_TOPIC);
    }
}

