#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sound sensor
int read_sound_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to trigger the alarm LED
void trigger_alarm_led(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED ON
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Turn LED OFF
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as input and output
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor(SOUND_SENSOR_PIN);
        if (sound_level == -1) {
            fprintf(stderr, "Error reading sound sensor, exiting.\n");
            break;
        }

        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            trigger_alarm_led(ALARM_LED_PIN, 1000); // Trigger alarm for 1 second
        }

        gpioDelay(100 * 1000); // Delay for 100ms
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

