    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name failed");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line failed");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for falling-edge event detection
    ret = gpiod_line_request(line, "vibration-monitor", GPIOD_LINE_REQUEST_EVENT, 0);
    if (ret < 0) {
        perror("gpiod_line_request failed");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen failed");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(stdout, "Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        // Wait for a falling-edge event
        ret = gpiod_line_event_wait(line, &event, DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
        if (ret < 0) {
            perror("gpiod_line_event_wait failed");
            break; // Exit loop on error
        }

        // Read the event status
        int event_value = gpiod_line_event_read(line);
        if (event_value < 0) {
            perror("gpiod_line_event_read failed");
            break; // Exit loop on error
        }

        // Log the event
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Vibration detected!");
        log_message(log_message_buffer);

        // Send shutdown command
        char send_message_buffer[256];
        snprintf(send_message_buffer, sizeof(send_message_buffer), "Vibration detected, initiating shutdown!");
        if (send_shutdown_command(send_message_buffer) != 0) {
            fprintf(stderr, "Failed to send shutdown command.\n");
        }

        // Shutdown the system
        system("sudo shutdown -h now");
        break; // Exit loop after shutdown is initiated
    }

    // Clean up resources
    fprintf(stdout, "Cleaning up resources...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stdout, "Exiting.\n");
    return 0;
}

