#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "environmental_log.txt"

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
int socket_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int init_spi();
int init_socket();
int read_bh1750();
int read_mcp3008(int channel);
void log_data(int light_level, int sound_level);
void send_data(int light_level, int sound_level);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

// Initialize I2C
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Initialize SPI
int init_spi() {
    int fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (fd < 0) {
        perror("Error initializing SPI");
        return -1;
    }
    return fd;
}

// Initialize socket
int init_socket() {
    struct sockaddr_in server_addr;
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("Error creating socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(socket_fd);
        return -1;
    }

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error connecting to server");
        close(socket_fd);
        return -1;
    }
    return socket_fd;
}

// Read light level from BH1750 sensor
int read_bh1750() {
    unsigned char buf[2];
    int lux = -1;

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address for BH1750");
        return -1;
    }

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-Resolution Mode
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    delay(180); // Wait for measurement (at least 180ms)

    // Read two bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Read sound level from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (write(spi_fd, buffer, 3) != 3) {
        perror("Error writing to SPI device");
        return -1;
    }

    delay(10); // Small delay after SPI transaction

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Log data to file
void log_data(int light_level, int sound_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Light: %d, Sound: %d\n", timestamp, light_level, sound_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Send data to server
void send_data(int light_level, int sound_level) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "Light: %d, Sound: %d\n", light_level, sound_level);

    if (send(socket_fd, buffer, strlen(buffer), 0) < 0) {
        perror("Error sending data to server");
    }
}

int main() {
    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd == -1) {
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi();
    if (spi_fd == -1) {
        close(i2c_fd);
        return 1;
    }

    // Initialize socket
    socket_fd = init_socket();
    if (socket_fd == -1) {
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        close(spi_fd);
        close(socket_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int light_level = read_bh1750();
        int sound_level = read_mcp3008(0);

        if (light_level != -1 && sound_level != -1) {
            log_data(light_level, sound_level);
            send_data(light_level, sound_level);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging and sending.\n");
        }

        delay(1000); // Wait 1 second
    }

    return 0;
}

