        perror("Error setting I2C slave address for BH1750");
        return -1;
    }

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-Resolution Mode
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    delay(180); // Wait for measurement (at least 180ms)

    // Read two bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Read sound level from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    if (write(spi_fd, buffer, 3) != 3) {
        perror("Error writing to SPI device");
        return -1;
    }

    delay(10); // Small delay after SPI transaction

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Log data to file
void log_data(int light_level, int sound_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Light: %d, Sound: %d\n", timestamp, light_level, sound_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Send data to server
void send_data(int light_level, int sound_level) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "Light: %d, Sound: %d\n", light_level, sound_level);

    if (send(socket_fd, buffer, strlen(buffer), 0) < 0) {
        perror("Error sending data to server");
    }
}

int main() {
    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd == -1) {
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi();
    if (spi_fd == -1) {
        close(i2c_fd);
        return 1;
    }

    // Initialize socket
    socket_fd = init_socket();
    if (socket_fd == -1) {
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        close(spi_fd);
        close(socket_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int light_level = read_bh1750();
        int sound_level = read_mcp3008(0);

        if (light_level != -1 && sound_level != -1) {
            log_data(light_level, sound_level);
            send_data(light_level, sound_level);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging and sending.\n");
        }

        delay(1000); // Wait 1 second
    }

    return 0;
}

