static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t keep_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int init_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) != 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_event event;
    if (gpiod_line_event_open(line, &event) != 0) {
        perror("Error opening GPIO line event");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO line value");
        return -1;
    }
    return value;
}

// Function to log the event
int log_event(int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        perror("Log file not opened");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, GPIO_LINE, state);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to handle flame detection
void handle_flame_detection(int state) {
    if (state == 1) {
        printf("Flame detected!\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        return 1;
    }

    // Main loop
    while (keep_running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        log_event(sensor_value);
        handle_flame_detection(sensor_value);

        struct timespec sleep_time;
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    if (line) {
        gpiod_line_close(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

