#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MCP4725_ADDR 0x62
#define VREF 3.3
#define LOG_FILE "temperature_log.txt"

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
int dac_to_voltage(int dac_value);
int log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature in Celsius
float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to convert DAC value to voltage
int dac_to_voltage(int dac_value) {
    return (int)((float)dac_value / 4095.0 * VREF * 1000.0); // Return voltage in mV
}

// Function to log data to file
int log_data(int adc_value, float temperature, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C channel
    i2c_handle = i2cOpen(1, MCP4725_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Convert temperature to DAC value
        int dac_value = (int)((temperature / 50.0) * 4095.0); // Map 0-50C to 0-4095
        if (dac_value < 0) dac_value = 0;
        if (dac_value > 4095) dac_value = 4095;

        // Convert DAC value to voltage
        float voltage = dac_to_voltage(dac_value);

        // Log data
        log_data(adc_value, temperature, voltage);

        // Print data to stdout
        printf("ADC: %d, Temperature: %.2f C, Voltage: %.2f mV\n", adc_value, temperature, voltage);

        // Wait 0.5 seconds
        gpioDelay(500000); // 500 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

