struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void cleanup_gpio();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", sig);

    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Release all GPIO lines
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Exit the program
    exit(0);
}

// Function to initialize the GPIO lines
int initialize_gpio() {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines for each relay
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    if (!relay1_line) {
        perror("Error getting GPIO line for relay 1");
        gpiod_chip_close(chip);
        return -1;
    }

    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    if (!relay2_line) {
        perror("Error getting GPIO line for relay 2");
        gpiod_line_release(relay1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    if (!relay3_line) {
        perror("Error getting GPIO line for relay 3");
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);
    if (!relay4_line) {
        perror("Error getting GPIO line for relay 4");
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request each line as an output
    if (gpiod_line_request_output(relay1_line, "relay1", 0) < 0) {
        perror("Error requesting relay 1 as output");
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(relay2_line, "relay2", 0) < 0) {
        perror("Error requesting relay 2 as output");
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(relay3_line, "relay3", 0) < 0) {
        perror("Error requesting relay 3 as output");
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(relay4_line, "relay4", 0) < 0) {
        perror("Error requesting relay 4 as output");
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to activate a relay (set GPIO line HIGH)
void activate_relay(int pin) {
    struct gpiod_line *line;

    switch (pin) {
        case RELAY1_PIN:
            line = relay1_line;
            break;
        case RELAY2_PIN:
            line = relay2_line;
            break;
        case RELAY3_PIN:
            line = relay3_line;
            break;
        case RELAY4_PIN:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay pin: %d\n", pin);
            return;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting relay value HIGH");
    }
}

// Function to deactivate a relay (set GPIO line LOW)
void deactivate_relay(int pin) {
    struct gpiod_line *line;

    switch (pin) {
        case RELAY1_PIN:
            line = relay1_line;
            break;
        case RELAY2_PIN:
            line = relay2_line;
            break;
