    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO lines
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Activate relay 1
        activate_relay(RELAY1_PIN);
        sleep(RELAY_DURATION);

        // Deactivate relay 1
        deactivate_relay(RELAY1_PIN);

        // Activate relay 2
        activate_relay(RELAY2_PIN);
        sleep(RELAY_DURATION);

        // Deactivate relay 2
        deactivate_relay(RELAY2_PIN);

        // Activate relay 3
        activate_relay(RELAY3_PIN);
        sleep(RELAY_DURATION);

        // Deactivate relay 3
        deactivate_relay(RELAY3_PIN);

        // Activate relay 4
        activate_relay(RELAY4_PIN);
        sleep(RELAY_DURATION);

        // Deactivate relay 4
        deactivate_relay(RELAY4_PIN);

        // Delay before repeating the sequence
        sleep(DELAY);
    }

    return 0;
}

