// Define GPIO pins
#define LED_PIN 16
#define SPI_CE0 8
#define SPI_CE1 7
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_CLK 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define ADC channel
