#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD 150
#define MOTOR_REVERSE 150
#define MOTOR_DURATION 3 // seconds
#define LOG_FILE "rain_log.txt"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// GPIO pins
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_handle;
FILE *log_file;
int socket_desc;

// Function prototypes
int read_rain_sensor();
int convert_adc_to_rain_level(int adc_value);
void control_motor(int direction, int speed);
void log_rain_data(int rain_level);
void send_rain_data(int rain_level);
void signal_handler(int signal);
int spi_transfer(int channel);

// Function to read rain sensor data from MCP3008
int read_rain_sensor() {
    unsigned char tx[3];
    unsigned char rx[3];
    int adc_value;

    // MCP3008 single-ended read command
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended, channel selection
    tx[2] = 0x00; // Don't care

    if (spi_transfer(0) != 0) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return -1; // Indicate error
    }

    // Parse the ADC value from the received data
    adc_value = ((rx[1] & 0x03) << 8) + rx[2];

    return adc_value;
}

// Function to convert ADC value to rain level
int convert_adc_to_rain_level(int adc_value) {
    // Map ADC value (0-1023) to rain level (0-10)
    // Higher voltage (dry) maps to lower rain level
    return 10 - (adc_value / 1023.0) * 10; // Ensure rain_level is within 0-10
}

// Function to control the motor
void control_motor(int direction, int speed) {
    if (direction == 1) { // Forward
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
    } else if (direction == 0) { // Reverse
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
    } else { // Stop
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 0);
    }

    gpioPWM(MOTOR_ENA, speed); // Set PWM duty cycle
}

// Function to log rain data to a file
void log_rain_data(int rain_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send rain data to a server
void send_rain_data(int rain_level) {
    char message[50];
    snprintf(message, sizeof(message), "Rain Level: %d", rain_level);

    if (send(socket_desc, message, strlen(message), 0) < 0) {
        perror("Send failed");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Stop the motor
    control_motor(0, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close the socket
    close(socket_desc);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// SPI transfer function
int spi_transfer(int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    int result;

    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | channel) << 4; // Single-ended, channel selection
    tx[2] = 0x00; // Don't care

    result = spiXfer(spi_handle, tx, rx, 3);

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    return 0;
}

int main() {
    int rain_level;
    int adc_value;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        perror("Could not create socket");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in server;
    server.sin_addr.s_addr = inet_addr(SERVER_IP);
    server.sin_family = AF_INET;
    server.sin_port = htons(SERVER_PORT);

    // Connect to remote server
    if (connect(socket_desc, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("Connect error");
        close(socket_desc);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initial window state: open
    control_motor(0, 0); // Stop the motor

    // Main loop
    while (program_running) {
        // Read rain sensor
        adc_value = read_rain_sensor();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading rain sensor, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        rain_level = convert_adc_to_rain_level(adc_value);

        // Log rain data
        log_rain_data(rain_level);

        // Send rain data to server
        send_rain_data(rain_level);

        // Control motor based on rain level
        if (rain_level >= RAIN_THRESHOLD) {
            printf("Rain level above threshold, closing window.\n");
            control_motor(1, MOTOR_FORWARD); // Close window
            sleep(MOTOR_DURATION);
            control_motor(0, 0); // Stop motor
        } else if (rain_level < RAIN_THRESHOLD) {
            printf("Rain level below threshold, opening window.\n");
            control_motor(0, 0); // Stop motor
            sleep(MOTOR_DURATION);
            control_motor(1, MOTOR_FORWARD); // Open window
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_motor(0, 0);
    spiClose(spi_handle);
    fclose(log_file);
    close(socket_desc);
    gpioTerminate();

    return 0;
}

