// Define GPIO pins
#define LED_PIN 16
#define ADC_PIN 26

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define LED on time in milliseconds
#define LED_ON_TIME 500

// Global variables
static volatile int running = 1;
static volatile unsigned long last_trigger_time = 0;

// Function prototypes
int initialize_gpio();
int read_adc();
void control_led(int state);
void log_detection();
void debounce();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int led_pin;
    int adc_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(ADC_PIN, PI_INPUT);

    return 0;
}

// Function to read ADC value via bit-banging
int read_adc() {
    int adc_value = 0;
    int i;

    // Set ADC pin as input
    gpioSetMode(ADC_PIN, PI_INPUT);

    // Read 10 bits of data
    for (i = 0; i < 10; i++) {
        // Wait for the pin to go high
        while (gpioRead(ADC_PIN) == 0) {
            // Wait for the pin to go high
        }

        // Measure the time the pin is high
        gpioDelay(1); // Small delay to measure pulse width

        // Calculate the value based on the pulse width
        adc_value |= (1 << (9 - i));
    }

    return adc_value;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log detection event with timestamp
void log_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("Clap detected at: %s\n", timestamp);
}

// Function to implement debounce
void debounce() {
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

