    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Clap detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int adc_value = read_adc();

        if (adc_value > 700) { // Threshold for clap detection
            unsigned long current_time = gpioTick();

            // Debounce logic
            if (current_time - last_trigger_time > DEBOUNCE_TIME * 1000) {
                log_detection();
                control_led(1); // Turn on LED
                gpioDelay(LED_ON_TIME * 1000); // LED on time
                control_led(0); // Turn off LED
                last_trigger_time = current_time;
            }
        }

        gpioDelay(1000); // Check every 1 ms
    }

    return 0;
}

