    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Function to check if the distance is below the threshold
int is_distance_below_threshold(float distance) {
    return (distance < DISTANCE_THRESHOLD) ? 1 : 0;
}

// Function to print a message to the console
void print_message(const char *message) {
    printf("%s\n", message);
}

