    int gpio_value;
    float voltage, distance;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export the GPIO pin
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    // Set the GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Monitoring distance on GPIO %d...\n", GPIO_PIN);

    while (keep_running) {
        // Read the GPIO value
        gpio_value = gpio_read_value(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d value\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        // Convert the reading to voltage
        voltage = voltage_from_reading(gpio_value);

        // Convert the voltage to distance
        distance = voltage_to_distance(voltage);

        // Log the distance
        if (log_distance(distance) < 0) {
            fprintf(stderr, "Failed to log distance\n");
        }

        // Check if the distance is below the threshold
        if (is_distance_below_threshold(distance)) {
            print_message("Feeder Activated");
        } else {
            print_message("Feeder Idle");
        }

        sleep(1); // Check every 1 second
    }

    // Unexport the GPIO pin
    if (gpio_unexport(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
    }

    return 0;
}

