}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (pump_line) {
        gpiod_line_set_value(pump_line, 0); // Turn off pump
        gpiod_line_release(pump_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed!\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed!\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed!\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set pump to OFF initially
    control_pump(0);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 60 seconds.\n");
            sleep(60);
            continue;
        }

        // Calculate moisture percentage
        float moisture = calculate_moisture(adc_value);
        if (moisture < 0.0) {
            fprintf(stderr, "Failed to calculate moisture. Retrying in 60 seconds.\n");
            sleep(60);
            continue;
        }

        // Control pump based on moisture threshold
        int pump_state = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
        if (control_pump(pump_state) < 0) {
            fprintf(stderr, "Failed to control pump. Retrying in 60 seconds.\n");
