#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SAMPLE_INTERVAL_MS 500
#define LOG_FILE "magnetic_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int spi_close(int fd);
int gpio_init(const char *chip_name, int line_num);
int gpio_set_direction(struct gpiod_line *line, const char *direction);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_get_value(struct gpiod_line *line);
int read_adc(int fd, int channel);
float calculate_voltage(int adc_value);
float calculate_magnetic_field(float voltage);
int log_data(float magnetic_field);
void signal_handler(int sig);

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed hz
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// SPI Close
int spi_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing SPI device");
        return -1;
    }
    return 0;
}

// GPIO Initialization
int gpio_init(const char *chip_name, int line_num) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, line_num);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return (int)(line);
}

// GPIO Set Direction
int gpio_set_direction(struct gpiod_line *line, const char *direction) {
    int ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        perror("Error setting GPIO direction");
        return -1;
    }
    return 0;
}

// GPIO Set Value
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO Get Value
int gpio_get_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Read ADC Value
int read_adc(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3008 Command: Start bit (1), Single-ended (1), Channel (3 bits), Don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error during ADC read\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate Voltage
float calculate_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * 3300.0;
}

// Calculate Magnetic Field
float calculate_magnetic_field(float voltage) {
    return (voltage - 1650.0) / 100.0;
}

// Log Data
int log_data(float magnetic_field) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, magnetic_field);

    fclose(fp);
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    int gpio_fd = gpio_init(GPIO_CHIP, GPIO_LINE);
    if (gpio_fd < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        spi_close(spi_fd);
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(gpio_fd, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO direction\n");
        spi_close(spi_fd);
        gpiod_line_release(gpio_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Drive CS low
        if (gpio_set_value(gpio_fd, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO value\n");
            terminate = 1; // Exit loop on error
            continue;
        }

        // Read ADC value
        int adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            terminate = 1; // Exit loop on error
            continue;
        }

        // Calculate voltage and magnetic field
        float voltage = calculate_voltage(adc_value);
        float magnetic_field = calculate_magnetic_field(voltage);

        // Log data
        if (log_data(magnetic_field) < 0) {
            fprintf(stderr, "Failed to log data\n");
            terminate = 1; // Exit loop on error
        }

        // Drive CS high
        if (gpio_set_value(gpio_fd, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO value\n");
            terminate = 1; // Exit loop on error
            continue;
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    fprintf(stderr, "Cleaning up resources...\n");
    spi_close(spi_fd);
    gpiod_line_release(gpio_fd);
    gpiod_chip_close(gpio_chip);

    fprintf(stderr, "Exiting.\n");
    return 0;
}

