#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3 // Reference voltage for MCP3008
#define SENSITIVITY 0.1 // 100 mV/A = 0.1 V/A
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    char *device;
    int mode;
    int bits_per_word;
    int speed;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t config);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int spi_fd, int channel);
float adc_to_current(int adc_value);
int log_current(float current);
void signal_handler(int signal);
void cleanup();

// SPI Initialization function
int spi_init(spi_config_t config) {
    int fd = open(config.device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = config.mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits = config.bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    int speed = config.speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer function
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MCP3008 Read function
int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) == -1) {
        fprintf(stderr, "Error reading MCP3008\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to Current Conversion function
float adc_to_current(int adc_value) {
    float current = (adc_value / 1023.0) * VREF / SENSITIVITY;
    return current;
}

// Logging function
int log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s,%.3f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // SPI Configuration
    spi_config_t spi_config = {
        .device = SPI_DEVICE,
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed = SPI_SPEED
    };

    // Initialize SPI
    spi_fd = spi_init(spi_config);
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log current value
        if (log_current(current) == -1) {
            fprintf(stderr, "Error logging current value\n");
        }

        // Print current value to console
        printf("Current: %.3f A\n", current);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

