#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static volatile sig_atomic_t keep_running = 1;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to read sensor value with debouncing
int read_sensor(struct gpiod_line *line)
{
    int value = -1; // Initialize to an invalid value
    for (int i = 0; i < 5; i++) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor value: %d\n", value);
            return -1; // Indicate an error
        }
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 2000000; // 2 milliseconds
        nanosleep(&ts, NULL);
    }

    // Return the majority value
    if (value == 0) {
        return 0; // Object present (active-low)
    } else {
        return 1; // No object
    }
}

// Function to log sensor state
void log_sensor_state(int sensor1_value, int sensor2_value)
{
    printf("Sensor 1: %s, Sensor 2: %s\n", sensor1_value ? "No Object" : "Object", sensor2_value ? "No Object" : "Object");
}

int main()
{
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", 0);
        return 1;
    }

    // Request GPIO lines
    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        fprintf(stderr, "Error getting GPIO line %d\n", SENSOR1_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO line %d\n", SENSOR2_PIN);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request input lines
    if (gpiod_line_request_input(line1, "sensor1") < 0) {
        fprintf(stderr, "Error requesting input line for sensor 1\n");
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line2, "sensor2") < 0) {
        fprintf(stderr, "Error requesting input line for sensor 2\n");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        int sensor1_value = read_sensor(line1);
        int sensor2_value = read_sensor(line2);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        log_sensor_state(sensor1_value, sensor2_value);

        // Check for both sensors detecting an object
        if (sensor1_value == 0 && sensor2_value == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        struct timespec ts;
        ts.tv_sec = 1; // 1 second
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    // Release resources
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

