// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
int log_data(double moisture_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended + channel select
    tx_buf[2] = 0x00; // Dummy byte

    // Retry loop for SPI transfer
    int retries = 3;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) == 3) {
            // Extract ADC value
            adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed. Retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "SPI transfer failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to calculate moisture level percentage
double calculate_moisture_level(int adc_value) {
    double moisture_level;

    if (adc_value < MIN_ADC) {
        moisture_level = 0.0;
    } else if (adc_value > MAX_ADC) {
        moisture_level = 100.0;
    } else {
        moisture_level = 100.0 - ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    }

    return moisture_level;
}

