#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DIR "/home/pi/security_cam/"
#define CAPTURE_COMMAND "libcamera-still -o /home/pi/security_cam/%Y%m%d_%H%M%S.jpg"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, exiting...");
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

int capture_image() {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execlp("libcamera-still", "libcamera-still", "-o", CAPTURE_DIR "%Y%m%d_%H%M%S.jpg", (char *)NULL);
        perror("execlp failed");
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        // Fork failed
        syslog(LOG_ERR, "Fork failed: %s", strerror(errno));
        return -1;
    } else {
        // Parent process
        int status;
