#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT)
#define PGM_HEADER "P5\n640 480\n255\n"

static int device_fd = -1;
static void *buffer = NULL;
static size_t buffer_size = 0;
static int frame_count = 0;
static int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    running = 0;
}

// Function to initialize the V4L2 device
int init_device(const char *device_name) {
    device_fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (device_fd < 0) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(device_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(device_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        close(device_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming\n");
        close(device_fd);
        return -1;
    }

    return 0;
}

// Function to set the image format
int set_format(int fd, int width, int height, int pixel_format) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = pixel_format;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    return 0;
}

// Function to initialize the buffer
int init_buffer(int fd, size_t *buffer_size) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Error: Not enough video buffers\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        return -1;
    }

    *buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to capture a frame and save it as a PGM file
int capture_frame(int fd, int width, int height) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    FILE *fp = fopen("image_0001.pgm", "wb");
    if (fp == NULL) {
        perror("Error opening PGM file");
        return -1;
    }

    fprintf(fp, "%s", PGM_HEADER);
    fwrite(buffer, 1, buffer_size, fp);

    fclose(fp);
    frame_count++;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to unmap the buffer
int unmap_buffer(int fd) {
    if (munmap(buffer, buffer_size) < 0) {
        perror("Error unmapping buffer");
        return -1;
    }
    buffer = NULL;
    return 0;
}

// Function to close the device
int close_device(int fd) {
    if (close(fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    const char *device_name = DEFAULT_DEVICE;
    if (argc > 1) {
        device_name = argv[1];
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_device(device_name) < 0) {
        return 1;
    }

    if (set_format(device_fd, IMAGE_WIDTH, IMAGE_HEIGHT, V4L2_PIX_FMT_GREY) < 0) {
        close_device(device_fd);
        return 1;
    }

    if (init_buffer(device_fd, &buffer_size) < 0) {
        close_device(device_fd);
        return 1;
    }

    if (start_streaming(device_fd) < 0) {
        unmap_buffer(device_fd);
        close_device(device_fd);
        return 1;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    while (running) {
        FD_ZERO(&fds);
        FD_SET(device_fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(device_fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            perror("Error in select");
            break;
        } else if (r == 0) {
            // Timeout occurred, continue capturing
            if (capture_frame(device_fd, IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
                break;
            }
        } else {
            // Data is available, capture frame
            if (capture_frame(device_fd, IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
                break;
            }
        }
    }

    if (stop_streaming(device_fd) < 0) {
        fprintf(stderr, "Error stopping streaming, but continuing cleanup.\n");
    }

    if (unmap_buffer(device_fd) < 0) {
        fprintf(stderr, "Error unmapping buffer, but continuing cleanup.\n");
    }

    if (close_device(device_fd) < 0) {
        fprintf(stderr, "Error closing device, but continuing cleanup.\n");
    }

    printf("Total frames captured: %d\n", frame_count);

    return 0;
}

