#include <sys/select.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/time.h>

// Constants
#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FRAME_RATE 30
#define NUM_BUFFERS 2
#define MMAP_OFFSET 0 // No offset for simplicity

// Global variables
static int fd = -1; // File descriptor for the device
static void *buffers[NUM_BUFFERS]; // Memory-mapped buffers
static int buffer_count = 0; // Number of allocated buffers
static FILE *log_file = NULL; // File pointer for the log file
static volatile sig_atomic_t terminate = 0; // Termination flag

// Structure to hold camera configuration
typedef struct {
    int fd;
    int width;
    int height;
    int frame_rate;
    int num_buffers;
} camera_config_t;

// Function prototypes
int init_camera(camera_config_t *config);
int capture_frame(camera_config_t *config, void **buffer, size_t *buffer_size);
int log_timestamp(FILE *fp, long long timestamp_us);
void signal_handler(int sig);
void cleanup(camera_config_t *config);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        printf("Caught SIGINT, exiting gracefully.\n");
    }
}

// Initialize the camera
int init_camera(camera_config_t *config) {
    config->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (config->fd == -1) {
        perror("Error opening device");
        return -1;
    }

    // Determine the number of available buffers
    struct v4l2_capability cap;
    if (ioctl(config->fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(config->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(config->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(config->fd);
        return -1;
    }

    // Set resolution
    struct v4l2_format fmt;
