#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 2) // YUYV is 2 bytes per pixel
#define BUFFER_COUNT 4
#define UDP_BUFFER_SIZE 65000
#define MAX_FRAME_INDEX 100 // Maximum frame index to prevent buffer overflow

// Structure to hold frame data and metadata
typedef struct {
    unsigned int frame_index;
    unsigned int fragment_index;
    unsigned int total_fragment_count;
    unsigned int payload_size;
    unsigned char *data;
} frame_metadata_t;

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int sockfd = -1; // Socket file descriptor
int videofd = -1; // Video device file descriptor
frame_metadata_t *frame_metadata = NULL;

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping...\n", signum);
}

// Function to initialize the video device
int init_video_device(int *videofd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    *videofd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (*videofd == -1) {
        perror("Error opening video device");
        return -1;
    }

    if (ioctl(*videofd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(*videofd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        close(*videofd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        close(*videofd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(*videofd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(*videofd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(*videofd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        close(*videofd);
        return -1;
    }

    frame_metadata = (frame_metadata_t *)malloc(BUFFER_COUNT * sizeof(frame_metadata_t));
    if (frame_metadata == NULL) {
        perror("Error allocating frame metadata");
        close(*videofd);
        return -1;
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(*videofd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            close(*videofd);
            free(frame_metadata);
            return -1;
        }

        if (ioctl(*videofd, VIDIOC_MMAP, &buf) == -1) {
            perror("Error mapping buffer");
            close(*videofd);
            free(frame_metadata);
            return -1;
        }

        frame_metadata[i].data = buf.buffer;
        frame_metadata[i].frame_index = 0; // Initialize frame index
        frame_metadata[i].total_fragment_count = 0; // Initialize total fragment count
    }

    return 0;
}

// Function to start streaming from the video device
int start_streaming(int videofd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    for (int i = 0; i < BUFFER_COUNT; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(videofd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    if (ioctl(videofd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame(int videofd, unsigned char **frame_data, size_t *frame_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(videofd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *frame_data = frame_metadata[buf.index].data;
    *frame_size = buf.bytesused;

    if (ioctl(videofd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to fragment the frame data into UDP datagrams
int fragment_frame(unsigned char *frame_data, size_t frame_size, int *fragment_count, unsigned char **datagrams, size_t *datagram_sizes) {
    size_t total_payload_size = frame_size;
    size_t remaining_payload_size = total_payload_size;
    size_t datagram_size = 0;
    size_t offset = 0;

    while (remaining_payload_size > 0 && *fragment_count < MAX_FRAME_INDEX) {
        datagram_size = 0;
        while (datagram_size < UDP_BUFFER_SIZE) {
            if (offset + datagram_size >= remaining_payload_size) {
                datagram_size = remaining_payload_size - offset;
            }

            datagrams[*fragment_count] = (unsigned char *)malloc(datagram_size);
            if (datagrams[*fragment_count] == NULL) {
                perror("Error allocating datagram");
                return -1;
            }

            memcpy(datagrams[*fragment_count], frame_data + offset, datagram_size);
            datagram_sizes[*fragment_count] = datagram_size;
            offset += datagram_size;
            datagram_size = UDP_BUFFER_SIZE; // Reset for next iteration
        }

        (*fragment_count)++;
    }

    return 0;
}

// Function to send the UDP datagrams
int send_udp_datagrams(int sockfd, unsigned char **datagrams, size_t *datagram_sizes, int fragment_count) {
    for (int i = 0; i < fragment_count; i++) {
        if (sendto(sockfd, datagrams[i], datagram_sizes[i], 0, NULL, datagram_sizes[i]) == -1) {
            perror("Error sending datagram");
            return -1;
        }
    }
    return 0;
}

// Function to clean up resources
void cleanup(int videofd, int sockfd) {
    if (videofd != -1) {
        for (int i = 0; i < BUFFER_COUNT; i++) {
            if (frame_metadata[i].data != NULL) {
                munmap(frame_metadata[i].data, frame_metadata[i].data[sizeof(unsigned char) * FRAME_SIZE]);
            }
        }
        close(videofd);
    }
    if (sockfd != -1) {
        close(sockfd);
    }
    if (frame_metadata != NULL) {
        free(frame_metadata);
    }
}

int main(int argc, char *argv[]) {
    int server_ip[10]; // Assuming IP address is a string and can be up to 10 characters
    int server_port;
    int videofd;
    unsigned char *frame_data;
    size_t frame_size;
    unsigned char **datagrams;
    size_t *datagram_sizes;
    int fragment_count = 0;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    strncpy(server_ip[0], argv[1], sizeof(server_ip[0]) - 1);
    server_ip[0][sizeof(server_ip[0]) - 1] = '\0'; // Ensure null termination
    server_port = atoi(argv[2]);

    // Initialize video device
    if (init_video_device(&videofd) == -1) {
        return 1;
    }

    // Start streaming
    if (start_streaming(videofd) == -1) {
        cleanup(videofd, -1);
        return 1;
    }

    // Create UDP socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("Error creating socket");
        cleanup(videofd, -1);
        return 1;
    }

    // Configure server address
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip[0], &server_addr.sin_addr) <= 0) {
        perror("Error converting IP address");
        cleanup(videofd, sockfd);
        return 1;
    }

    // Capture and fragment frames
    while (program_running) {
        if (capture_frame(videofd, &frame_data, &frame_size) == -1) {
            break;
        }

        datagrams = (unsigned char **)malloc(BUFFER_COUNT * sizeof(unsigned char *));
