#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2) // RGB24
#define JPEG_SIZE 1000000 // Adjust as needed, must be larger than IMAGE_SIZE
#define JPEG_FILE "image.jpg"

// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;
int fd = -1;
buffer_t *buffers = NULL;
int n_buffers = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

// Function to initialize the camera
int init_camera() {
    fd = open(DEVICE_NAME, O_RDWR); // Open the device in blocking mode
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    // Check device capabilities
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return -1;
    }

    // Request the desired format
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    // Request the number of buffers
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4; // Request 4 buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return -1;
    }

    // Mmap the buffers
    buffers = calloc(req.count, sizeof(buffer_t));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return -1;
    }

    n_buffers = req.count;

    for (int i = 0; i < n_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming() {
    for (int i = 0; i < n_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame() {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Check if a frame was received
    if (buf.bytesused == 0) {
        fprintf(stderr, "No frame received\n");
        return -1;
    }

    // Requeue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error requeuing buffer");
        return -1;
    }

    return 0;
}

// Function to save the JPEG image to a file
int save_jpeg(const void *data, size_t size) {
    FILE *fp = fopen(JPEG_FILE, "wb");
    if (!fp) {
        perror("Error opening file");
        return -1;
    }

    size_t bytes_written = fwrite(data, 1, size, fp);
    if (bytes_written != size) {
        fprintf(stderr, "Error writing to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to uninitialize the camera
int uninit_camera() {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);

        for (int i = 0; i < n_buffers; i++) {
            if (munmap(buffers[i].start, buffers[i].length) < 0) {
                perror("Error unmapping buffer");
                return -1;
            }
        }

        free(buffers);
        buffers = NULL;
        n_buffers = 0;

        close(fd);
        fd = -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    if (init_camera() < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    // Start streaming
    if (start_streaming() < 0) {
        fprintf(stderr, "Streaming failed\n");
        uninit_camera();
        return 1;
    }

    // Capture a frame
    if (capture_frame() < 0) {
        fprintf(stderr, "Frame capture failed\n");
        uninit_camera();
        return 1;
    }

    // Save the JPEG image
    if (save_jpeg(buffers[0].start, buffers[0].length) < 0) {
        fprintf(stderr, "JPEG save failed\n");
        uninit_camera();
        return 1;
    }

    // Uninitialize the camera
    if (uninit_camera() < 0) {
        fprintf(stderr, "Camera uninitialization failed\n");
        return 1;
    }

    printf("Image saved to %s\n", JPEG_FILE);

    return 0;
}

