        int tilt_up = read_button(TILT_UP);
        int tilt_down = read_button(TILT_DOWN);
        int pan_left = read_button(PAN_LEFT);
        int pan_right = read_button(PAN_RIGHT);

        // Update servo positions based on button presses
        if (tilt_up && tilt_duty > SERVO_MIN) {
            tilt_duty -= 5;
        } else if (tilt_down && tilt_duty < SERVO_MAX) {
            tilt_duty += 5;
        } else if (pan_left && pan_duty > SERVO_MIN) {
            pan_duty -= 5;
        } else if (pan_right && pan_duty < SERVO_MAX) {
            pan_duty += 5;
        }

        // Set servo positions
        if (set_servo_position(PAN_SERVO, pan_duty) != 0) {
            fprintf(stderr, "Error setting pan servo position\n");
        }
        if (set_servo_position(TILT_SERVO, tilt_duty) != 0) {
            fprintf(stderr, "Error setting tilt servo position\n");
        }

        // Delay
        gpioDelay(50000); // 50 ms
    }

    return 0;
}

