#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <math.h>
#include <jpeglib.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <sys/wait.h>

// Configuration
#define VIDEO_DEVICE "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75
#define CAPTURE_INTERVAL_SEC 1
#define MAX_JPEG_SIZE 1048576 // 1MB

// Global variables (minimize usage)
static volatile sig_atomic_t keep_running = 1;
static int camera_fd = -1;
static unsigned char *buffer = NULL;
static int buffer_size = 0;
static int current_frame = 0;
static int last_frame = 0;
static int frame_ready = 0;
static int jpeg_size = 0;

// Structure to hold JPEG parameters
struct my_jerror_mgr {
  struct jpeg_error_mgr pub;
  jmp_buf setjmp_buffer;
};

typedef struct my_jerror_mgr * my_jerror_ptr;

// Function prototypes
int init_camera();
int capture_frame(unsigned char *frame_buffer);
int apply_box_blur(unsigned char *input, unsigned char *output, int width, int height, int radius);
int save_jpeg(unsigned char *rgb_frame, int width, int height, int quality);
void signal_handler(int sig);
void cleanup();
void log_message(int priority, const char *message);
int select_timeout(int fd, struct timeval tv);

// Helper function to calculate Gaussian kernel
int gaussian_kernel(int radius) {
    int kernel_size = 2 * radius + 1;
    int kernel[(kernel_size * kernel_size)];
    for (int i = 0; i < kernel_size; i++) {
        for (int j = 0; j < kernel_size; j++) {
            kernel[i * kernel_size + j] = 1; // Simple kernel for now
        }
    }
    return kernel_size;
}

// Helper function to apply Gaussian blur (simplified for demonstration)
unsigned char apply_gaussian_blur(unsigned char *input, unsigned char *output, int width, int height, int radius) {
    // This is a placeholder.  A real implementation would use the Gaussian kernel.
    // For simplicity, we'll just average the pixels.
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            unsigned char sum = 0;
            int count = 0;
            for (int i = -radius; i <= radius; i++) {
                for (int j = -radius; j <= radius; j++) {
                    int nx = x + j;
                    int ny = y + i;
                    if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        sum += input[ny * width + nx];
                        count++;
                    }
                }
            }
            output[y * width + x] = (unsigned char)(sum / count);
        }
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        log_message(LOG_INFO, "Received SIGINT, exiting...");
        keep_running = 0;
    }
}

// Cleanup function
void cleanup() {
    log_message(LOG_INFO, "Cleaning up resources...");

    if (buffer != NULL) {
        if (buffer_size > 0) {
            munmap(buffer, buffer_size);
        }
        free(buffer);
    }

    if (camera_fd != -1) {
        close(camera_fd);
    }

    log_message(LOG_INFO, "Cleanup complete.");
}

// Log message to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Initialize camera
int init_camera() {
    camera_fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (camera_fd < 0) {
        perror("Error opening camera");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(camera_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        close(camera_fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(camera_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(camera_fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer for simplicity
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(camera_fd);
        return -1;
    }

    buffer = mmap(NULL, req.count * (fmt.fmt.pix.width * fmt.fmt.pix.height * 2), PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(camera_fd);
        return -1;
    }

    buffer_size = req.count * (fmt.fmt.pix.width * fmt.fmt.pix.height * 2);

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera_fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        munmap(buffer, buffer_size);
        close(camera_fd);
        return -1;
    }

    if (ioctl(camera_fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buffer_size);
        close(camera_fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera_fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buffer_size);
        close(camera_fd);
        return -1;
    }

    frame_ready = 0;
    last_frame = 0;
    current_frame = 0;

    return 0;
}

// Capture frame
int capture_frame(unsigned char *frame_buffer) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(camera_fd, &fds);

    tv.tv_sec = CAPTURE_INTERVAL_SEC;
    tv.tv_usec = 0;

    r = select(camera_fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select()");
        return -1;
    } else if (r == 0) {
        log_message(LOG_WARNING, "Timeout waiting for frame");
        return -1;
    } else {
        if (FD_ISSET(camera_fd, &fds)) {
            if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("Error dequeuing buffer");
                return -1;
            }

            if (ioctl(camera_fd, VIDIOC_QBUF, &buf) < 0) {
                perror("Error queuing buffer");
                return -1;
            }

            memcpy(frame_buffer, buffer, buffer_size);
            frame_ready = 1;
            last_frame = current_frame;
            current_frame++;
        }
    }
    return 0;
}

// Apply box blur (simplified, edge clamping)
int apply_box_blur(unsigned char *input, unsigned char *output, int width, int height, int radius) {
    int kernel_size = 2 * radius + 1;
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            unsigned char sum = 0;
            int count = 0;
            for (int i = -radius; i <= radius; i++) {
                for (int j = -radius; j <= radius; j++) {
                    int nx = x + j;
                    int ny = y + i;
                    if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        sum += input[ny * width + nx];
                        count++;
                    }
                }
            }
            output[y * width + x] = (unsigned char)(sum / count);
        }
    }
    return 0;
}

// Save JPEG
int save_jpeg(unsigned char *rgb_frame, int width, int height, int quality) {
    struct my_jerror_mgr jerr;
    my_jerror_ptr my_error = &jerr;

    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr2;
    cinfo.err = jpeg_std_error(&jerr2);
    my_jerror_ptr my_error2 = &jerr;

    jpeg_create_compress(&cinfo);

    unsigned char *outbuffer = NULL;
    unsigned long outsize = 0;

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3; // RGB
    cinfo.in_color_space = JCS_RGB;

    jpeg_mem_dest(&cinfo, &outbuffer, &outsize);

    cinfo.out_color_space = JCS_RGB; // Output RGB
    cinfo.input_components = 1; // Input YUYV
    cinfo.in_color_space = JCS_YUYV;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    JSAMPARRAY image = &row_pointer[0];

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb_frame[cinfo.next_scanline * width * 3];
        jpeg_write_scanlines(&cinfo, image, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    FILE *outfile = fopen("capture.jpg", "wb");
    fwrite(outbuffer, 1, outsize, outfile);
    fclose(outfile);

    jpeg_size = outsize;
    log_message(LOG_INFO, "JPEG saved: %d bytes", jpeg_size);

    return 0;
}

// Select timeout function
int select_timeout(int fd, struct timeval tv) {
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    return select(fd + 1, &fds, NULL, NULL, &tv);
}

int main() {
    openlog("bookworm", LOG_PID, LOG_USER);
    log_message(LOG_INFO, "Starting Bookworm...");

    signal(SIGINT, signal_handler);

    if (init_camera() < 0) {
        log_message(LOG_ERR, "Camera initialization failed");
        cleanup();
        return 1;
    }

    unsigned char *rgb_frame = NULL;
    unsigned char *blurred_frame = NULL;
    int rgb_width = FRAME_WIDTH;
    int rgb_height = FRAME_HEIGHT;
    int blurred_width = FRAME_WIDTH;
    int blurred_height = FRAME_HEIGHT;

    while (keep_running) {
        if (capture_frame(buffer) == 0) {
            if (frame_ready && (current_frame - last_frame) == 1) {
                // Allocate memory for RGB and blurred frames
                blurred_frame = (unsigned char *)malloc(rgb_width * rgb_height * 3);
                rgb_frame = (unsigned char *)malloc(rgb_width * rgb_height * 3);
                if (!blurred_frame || !rgb_frame) {
                    log_message(LOG_ERR, "Memory allocation failed");
                    cleanup();
                    break;
                }

                // Convert YUYV to RGB (simplified conversion)
                for (int y = 0; y < FRAME_HEIGHT; y++) {
                    for (int x = 0; x < FRAME_WIDTH; x++) {
                        unsigned char y1 = buffer[y * FRAME_WIDTH * 2 + x * 2];
                        unsigned char y2 = buffer[y * FRAME_WIDTH * 2 + (x + 1) * 2];
                        unsigned char u = (y1 + y2) / 2;
                        unsigned char v = buffer[y * FRAME_WIDTH * 2 + x * 2 + 1];

                        unsigned char r = y1 + 1.402 * (v - 128);
                        unsigned char g = y1 - 0.344 * (v - 128) - 0.714 * (u - 128);
                        unsigned char b = y1 + 1.772 * (v - 128);

                        // Clamp RGB values
                        if (r < 0) r = 0;
                        if (r > 255) r = 255;
                        if (g < 0) g = 0;
                        if (g > 255) g = 255;
                        if (b < 0) b = 0;
                        if (b > 255) b = 255;

                        rgb_frame[y * rgb_width * 3 + x * 3] = r;
                        rgb_frame[y * rgb_width * 3 + x * 3 + 1] = g;
                        rgb_frame[y * rgb_width * 3 + x * 3 + 2] = b;
                    }
                }

                // Apply box blur
                apply_box_blur(rgb_frame, blurred_frame, rgb_width, rgb_height, BLUR_RADIUS);

                // Save JPEG
                save_jpeg(blurred_frame, rgb_width, rgb_height, JPEG_QUALITY);

                // Free allocated memory
                free(rgb_frame);
                free(blurred_frame);
            }
        }

        if (frame_ready && (current_frame - last_frame) > 1) {
            log_message(LOG_WARNING, "Frame ready but not processed within interval");
        }

        // Check JPEG size
        if (jpeg_size > MAX_JPEG_SIZE) {
            log_message(LOG_WARNING, "JPEG size exceeds limit, discarding frame");
            jpeg_size = 0; // Reset size to avoid repeated warnings
        }
    }

    cleanup();
    closelog();
    return 0;
}

