    data->buf.memory = V4L2_MEMORY_MMAP;
    data->buf.index = 0;
    data->buf.length = 0;
    data->autofocus_supported = 0;

    return 0;
}

// Function to open the camera device
int open_camera(camera_data_t *data) {
    data->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (data->fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (ioctl(data->fd, VIDIOC_QUERYCAP, &data->cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(data->fd);
        data->fd = -1;
        return -1;
    }

    if (!(data->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(data->fd);
        data->fd = -1;
        return -1;
    }

    if (!(data->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(data->fd);
        data->fd = -1;
        return -1;
    }

    return 0;
}

