// Function to check autofocus support
int check_autofocus_support(camera_data_t *data) {
    struct v4l2_control ctrl;
    ctrl.type = V4L2_CID_FOCUS_AUTO;
    ctrl.index = 0;
    ctrl.value = 1; // Assume 1 for supported

    if (ioctl(data->fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        fprintf(stderr, "Error querying autofocus control: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(data->fd, VIDIOC_GETCAP, &ctrl) < 0) {
        fprintf(stderr, "Error getting autofocus capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (ctrl.value >= 0) {
        data->autofocus_supported = 1;
    } else {
        data->autofocus_supported = 0;
    }

    return 0;
}

