    printf("  Bus Info: %s\n", data->cap.bus_info);
    printf("  Version: %d.%d\n", data->cap.cap.version & 0xFF, (data->cap.cap.version >> 8) & 0xFF);
    printf("  Capabilities: 0x%x\n", data->cap.capabilities);
}

// Function to print supported resolutions
void print_supported_resolutions(camera_data_t *data) {
    printf("\nSupported Resolutions:\n");
    printf("  Width x Height x BitsPerPixel\n");
    for (int i = 0; data->frame_sizes[i] != 0; i++) {
        if (data->frame_sizes[i] > 0 && data->frame_sizes[i] <= MAX_RES_WIDTH && i < 32) {
            printf("  %d x %d x %d\n", data->frame_sizes[i], data->frame_sizes[i], 8); // Assuming 8 bits per pixel
        }
    }
}

// Function to print supported frame rates
void print_supported_frame_rates(camera_data_t *data) {
    printf("\nSupported Frame Rates:\n");
    printf("  %d Hz\n", data->frame_intervals[0]);
    for (int i = 0; data->frame_intervals[i] != 0; i++) {
        if (data->frame_intervals[i] > 0 && i < 32) {
            printf("  %d Hz\n", data->frame_intervals[i]);
        }
    }
}

// Function to print autofocus support
void print_autofocus_support(camera_data_t *data) {
    printf("\nAutofocus Support:\n");
    if (data->autofocus_supported) {
        printf("  Supported\n");
    } else {
        printf("  Not Supported\n");
    }
}

int main() {
    camera_data_t camera_data;

    if (init_camera_data(&camera_data) != 0) {
        fprintf(stderr, "Failed to initialize camera data.\n");
        return 1;
    }

    if (open_camera(&camera_data) != 0) {
        fprintf(stderr, "Failed to open camera device.\n");
        return 1;
    }

    if (enumerate_frame_sizes(&camera_data) != 0) {
        fprintf(stderr, "Failed to enumerate frame sizes.\n");
        close(camera_data.fd);
        return 1;
    }

    if (enumerate_frame_intervals(&camera_data) != 0) {
        fprintf(stderr, "Failed to enumerate frame intervals.\n");
        close(camera_data.fd);
        return 1;
    }

    if (check_autofocus_support(&camera_data) != 0) {
        fprintf(stderr, "Failed to check autofocus support.\n");
        close(camera_data.fd);
        return 1;
    }

    print_camera_capabilities(&camera_data);
    print_supported_resolutions(&camera_data);
    print_supported_frame_rates(&camera_data);
    print_autofocus_support(&camera_data);

    close(camera_data.fd);
    return 0;
}

