#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO 4
#define TILT_SERVO 5
#define UP_BUTTON 6
#define DOWN_BUTTON 7
#define LEFT_BUTTON 8
#define RIGHT_BUTTON 9

// Define button pull-up GPIO pins
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define center position for servos
#define CENTER_POSITION 1500

// Define increment/decrement value for servo position
#define STEP_SIZE 10

// Global variables for servo positions
int pan_position = CENTER_POSITION;
int tilt_position = CENTER_POSITION;

// Function prototypes
void initialize_gpio();
void set_servo_position(int pan, int tilt);
void handle_button_interrupt(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(PAN_SERVO, 0); // Stop PWM on pan servo
    gpioServo(TILT_SERVO, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit program
}

// Function to initialize GPIO pins
void initialize_gpio() {
    // Set servo pins as outputs
    gpioSetMode(PAN_SERVO, PI_OUTPUT);
    gpioSetMode(TILT_SERVO, PI_OUTPUT);

    // Set button pins as inputs with pull-up resistors
    gpioSetMode(UP_BUTTON, PI_INPUT);
    gpioSetMode(DOWN_BUTTON, PI_INPUT);
    gpioSetMode(LEFT_BUTTON, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set initial servo positions
    set_servo_position(pan_position, tilt_position);
}

// Function to set servo positions
void set_servo_position(int pan, int tilt) {
    gpioServo(PAN_SERVO, pan);
    gpioServo(TILT_SERVO, tilt);
}

// Function to handle button interrupts
void handle_button_interrupt(int gpio, int level, uint32_t tick, void *user_data) {
    static int up_pressed = 0;
    static int down_pressed = 0;
    static int left_pressed = 0;
    static int right_pressed = 0;

    if (gpio == UP_BUTTON_PIN) {
        if (level == 0) { // Button pressed (active-low)
            if (!up_pressed) {
                pan_position += STEP_SIZE;
                if (pan_position > 2000) pan_position = 1000;
                set_servo_position(pan_position, tilt_position);
                up_pressed = 1;
            }
        } else {
            up_pressed = 0;
        }
    } else if (gpio == DOWN_BUTTON_PIN) {
        if (level == 0) { // Button pressed (active-low)
            if (!down_pressed) {
                pan_position -= STEP_SIZE;
                if (pan_position < 1000) pan_position = 2000;
                set_servo_position(pan_position, tilt_position);
                down_pressed = 1;
            }
        } else {
            down_pressed = 0;
        }
    } else if (gpio == LEFT_BUTTON_PIN) {
        if (level == 0) { // Button pressed (active-low)
            if (!left_pressed) {
                tilt_position -= STEP_SIZE;
                if (tilt_position < 1000) tilt_position = 2000;
                set_servo_position(pan_position, tilt_position);
                left_pressed = 1;
            }
        } else {
            left_pressed = 0;
        }
    } else if (gpio == RIGHT_BUTTON_PIN) {
        if (level == 0) { // Button pressed (active-low)
            if (!right_pressed) {
                tilt_position += STEP_SIZE;
                if (tilt_position > 2000) tilt_position = 1000;
                set_servo_position(pan_position, tilt_position);
                right_pressed = 1;
            }
        } else {
            right_pressed = 0;
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Print startup message
    printf("Pan-Tilt Camera Control\n");
    printf("Pan Servo: GPIO %d, Tilt Servo: GPIO %d\n", PAN_SERVO, TILT_SERVO);
    printf("Center Position: 1500 us\n");
    printf("Button Assignments:\n");
    printf("  UP: GPIO %d\n", UP_BUTTON);
    printf("  DOWN: GPIO %d\n", DOWN_BUTTON);
    printf("  LEFT: GPIO %d\n", LEFT_BUTTON);
    printf("  RIGHT: GPIO %d\n", RIGHT_BUTTON);
    printf("Press Ctrl+C to exit.\n");

    // Initialize GPIO pins
    initialize_gpio();

    // Set up interrupt handlers for button presses
    gpioSetAlertFuncEx(UP_BUTTON_PIN, handle_button_interrupt, NULL);
    gpioSetAlertFuncEx(DOWN_BUTTON_PIN, handle_button_interrupt, NULL);
    gpioSetAlertFuncEx(LEFT_BUTTON_PIN, handle_button_interrupt, NULL);
    gpioSetAlertFuncEx(RIGHT_BUTTON_PIN, handle_button_interrupt, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        gpioDelay(50); // 50 ms delay
    }

    return 0;
}

