#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY 2000 // milliseconds
#define POLL_DELAY 100      // milliseconds

// Structure to hold the filename and timestamp
typedef struct {
    char filename[256];
    long timestamp;
} FileData;

// Global variables
static volatile int running = 1;
static int server_port = 0;
static char server_ip[64] = {0};

// Function prototypes
int init_gpio();
int read_sensor();
int capture_image(const char *filename);
int send_data(const char *filename, long timestamp, int motion_status, int gpio_pin);
void cleanup();
void signal_handler(int signal);
char* get_iso8601_timestamp_with_microseconds();

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // In a real application, you might want to process the response here.
    // For now, we just ignore it.
    return real_size;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to read the PIR sensor
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -q 85", filename);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing libcamera-still command\n");
        return -1;
    }
    if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Function to send data to the server
int send_data(const char *filename, long timestamp, int motion_status, int gpio_pin) {
    CURL *curl;
    CURLcode res;
    char json_payload[512];

    // Create JSON payload
    snprintf(json_payload, sizeof(json_payload), "{\"filename\": \"%s\", \"timestamp\": %ld, \"motion_status\": %d, \"gpio_pin\": %d}",
             filename, timestamp, motion_status, gpio_pin);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://localhost:8080/upload"); // Replace with server IP and port
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        // Set content type header
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        curl_slist_free_all(headers); // Free the header list
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Error initializing libcurl\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

// Function to get the current timestamp with microseconds
char* get_iso8601_timestamp_with_microseconds() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t t = ts.tv_sec;
    struct tm tm_info;
    localtime_r(&t, &tm_info);
    static char timestamp[64]; // Static to persist across calls
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ldZ", ts.tv_nsec / 1000); // Append microseconds and 'Z'
    return timestamp;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Function to cleanup resources
void cleanup() {
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    strncpy(server_ip, argv[1], sizeof(server_ip) - 1);
    server_ip[sizeof(server_ip) - 1] = '\0'; // Ensure null termination
    server_port = atoi(argv[2]);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
