#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 5000
#define DEBOUNCE_DELAY_MS 50
#define TIMEOUT_MS 2000

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYYMMDD_HHMMSS

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
    return timestamp;
}

// Function to generate filename
char* generate_filename() {
    char *filename = malloc(100 * sizeof(char));
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }
    snprintf(filename, 100, "%s/%s.jpg", IMAGE_DIR, get_timestamp());
    return filename;
}

// Function to capture image using libcamera-still
int capture_image(const char *filename) {
    char command[200];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout %d --nopreview", filename, TIMEOUT_MS);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute libcamera-still");
        return -1;
    }
    return WEXITSTATUS(status);
}

// Function to log events
void log_event(const char *message) {
    if (log_file == NULL) return;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

// Function to publish image to server
int publish_image(const char *filename) {
    int sockfd;
    struct sockaddr_in servaddr;
    char message[256];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("inet_pton failed");
        close(sockfd);
        return -1;
    }

    snprintf(message, sizeof(message), "Image: %s", filename);
    sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr));

    close(sockfd);
    return 0;
}

// Function to handle motion detection
void handle_motion() {
    char *filename = generate_filename();
    if (filename == NULL) {
        log_event("Failed to generate filename");
        return;
    }

    if (capture_image(filename) == 0) {
        log_event("Image captured successfully");
        if (publish_image(filename) != 0) {
            log_event("Failed to publish image");
        }
        free(filename);
    } else {
        log_event("Failed to capture image");
    }
    free(filename);
}

// Function to handle GPIO events
void handle_gpio_event(int gpio, int direction) {
    if (gpio == GPIO_PIN) {
        if (direction == GPIOD_LINE_DIRECTION_INPUT) {
            struct gpiod_line_event event;
            int ret;

            while (keep_running) {
                ret = gpiod_line_event(line, &event);
                if (ret < 0) {
                    perror("gpiod_line_event");
                    break;
                }

                if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    log_event("Motion detected");
                    handle_motion();
                    break; // Exit debounce loop after first rising edge
                }
                usleep(1000); // Check every 1ms
            }
        }
    }
}

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Received signal, exiting...");
        keep_running = 0;
    }
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    log_event("Starting motion detection...");

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }

    // Claim GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to claim GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Request GPIO line as input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (keep_running) {
        handle_gpio_event(GPIO_PIN, GPIOD_LINE_DIRECTION_INPUT);
        usleep(10000); // Check every 10ms
    }

    // Clean up
    log_event("Cleaning up...");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    log_event("Exiting...");
    return 0;
}

