#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define YUYV_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 2)
#define CROPPED_SIZE (CROP_WIDTH * CROP_HEIGHT * 2)
#define FILENAME "cropped.yuv"

static int fd = -1;
static void *buffer = NULL;
static size_t buffer_size = 0;
static int cropped_fd = -1;
static FILE *cropped_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (fd != -1) {
        if (munmap(buffer, buffer_size) != 0) {
            perror("munmap");
        }
        if (close(fd) != 0) {
            perror("close");
        }
    }
    if (cropped_file != NULL) {
        if (fclose(cropped_file) != 0) {
            perror("fclose");
        }
    }
    exit(EXIT_SUCCESS);
}

// Function to check if a device is a V4L2 camera
int is_v4l2_camera(const char *device) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return 0;
    }
    return (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE);
}

// Function to set the camera format
int set_camera_format(int fd, int width, int height, enum v4l2_pixelformat format, enum v4l2_field field) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = format;
    fmt.fmt.pix.field = field;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    return 0;
}

// Function to capture a single frame
int capture_frame(int fd, void **buffer, size_t *buffer_size) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "VIDIOC_REQBUFS returned too few buffers\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
