#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define initial pan and tilt angles
#define INITIAL_PAN_ANGLE 90
#define INITIAL_TILT_ANGLE 90

// Define angle increment/decrement
#define ANGLE_INCREMENT 5

// Define PWM pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variables for pan and tilt angles
int pan_angle = INITIAL_PAN_ANGLE;
int tilt_angle = INITIAL_TILT_ANGLE;

// Function prototypes
void set_pan_angle(int angle);
void set_tilt_angle(int angle);
void handle_arrow_key(int key);
void handle_sigint(int sig);
void cleanup();

// Function to set the pan servo angle
void set_pan_angle(int angle) {
    // Validate angle
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Pan angle out of range (0-180). Current angle: %d\n", angle);
        return;
    }

    // Calculate pulse width (microseconds)
    int pulse_width = (int)(500 + (angle * 2000.0 / 180.0));

    // Set PWM pulse width
    gpioPWM(PAN_GPIO, pulse_width);

    // Update pan_angle
    pan_angle = angle;
}

// Function to set the tilt servo angle
void set_tilt_angle(int angle) {
    // Validate angle
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Tilt angle out of range (0-180). Current angle: %d\n", angle);
        return;
    }

    // Calculate pulse width (microseconds)
    int pulse_width = (int)(500 + (angle * 2000.0 / 180.0));

    // Set PWM pulse width
    gpioPWM(TILT_GPIO, pulse_width);

    // Update tilt_angle
    tilt_angle = angle;
}

// Function to handle arrow key input
void handle_arrow_key(int key) {
    switch (key) {
        case 'w':
            set_tilt_angle(tilt_angle + ANGLE_INCREMENT);
            break;
        case 's':
            set_tilt_angle(tilt_angle - ANGLE_INCREMENT);
            break;
        case 'a':
            set_pan_angle(pan_angle - ANGLE_INCREMENT);
            break;
        case 'd':
            set_pan_angle(pan_angle + ANGLE_INCREMENT);
            break;
        default:
            fprintf(stderr, "Error: Invalid arrow key input.\n");
            break;
    }
}

// Signal handler for SIGINT (Ctrl+C)
void handle_sigint(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

// Cleanup function to terminate pigpio and set servos to neutral position
void cleanup() {
    // Set servos to neutral position (90 degrees)
    set_pan_angle(INITIAL_PAN_ANGLE);
    set_tilt_angle(INITIAL_TILT_ANGLE);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for PWM output
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(PAN_GPIO, 1000); // Range of 1000 for 0-1000 duty cycle
    gpioSetPWMrange(TILT_GPIO, 1000);

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Main loop
    int key;
    while (1) {
        // Read keyboard input
        key = getchar();

        // Handle arrow key input
        if (key == 'w') {
            handle_arrow_key('w');
        } else if (key == 's') {
            handle_arrow_key('s');
        } else if (key == 'a') {
            handle_arrow_key('a');
        } else if (key == 'd') {
            handle_arrow_key('d');
        } else if (key == 'q') {
            cleanup();
            return 0;
        } else {
            // Ignore other characters
        }

        // Delay to prevent excessive CPU usage
        usleep(100000); // 100 ms
    }

    return 0;
}

