// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temperature = -1.0f; // Default to -1.0 if error

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1.0f;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temperature = atoi(buffer) / 1000.0f;
    } else {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        temperature = -1.0f;
    }

    fclose(fp);
    return temperature;
}

// Function to read CPU usage from /proc/stat
float read_cpu_usage() {
    FILE *fp;
    char buffer[50];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    float usage = -1.0f; // Default to -1.0 if error

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open proc/stat file.\n");
        return -1.0f;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        if (sscanf(buffer, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                   &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) == 10) {
            unsigned long long prev_idle = idle + iowait;
            unsigned long long prev_non_idle = user + nice + system + irq + softirq + steal;
            unsigned long long prev_total = prev_idle + prev_non_idle;

            unsigned long long new_idle = idle;
            unsigned long long new_non_idle = user + nice + system + irq + softirq + steal;

            unsigned long long totald = new_idle + iowait - prev_idle - iowait;
            unsigned long long idled = new_idle - prev_idle;

            float usage = (float)(totald - idled) / (float)(prev_total - prev_idle);
            usage = 100.0f - usage;
        } else {
            fprintf(stderr, "Error: Could not parse CPU usage from file.\n");
        }
    } else {
        fprintf(stderr, "Error: Could not read CPU usage from file.\n");
    }

    fclose(fp);
    return usage;
}

// Function to initialize the OLED display
void oled_init() {
    oled_command(0xAE);  // Display off
    oled_command(0xD5);  // Set Display Clock Divide Ratio/Oscillator Frequency
    oled_command(0x80);  // --ratio
    oled_command(0xA8);  // Set Multiplex Ratio
    oled_command(0x3F);  // --ratio
    oled_command(0xD3);  // Set Display Offset
    oled_command(0x00);  // --offset
    oled_command(0x40);  // Set Display Start Line
    oled_command(0x8D);  // Charge Pump Setting
    oled_command(0x14);  // --enable
    oled_command(0x20);  // Set Memory Addressing Mode
    oled_command(0x00);  // --horizontal addressing mode
    oled_command(0xA1);  // Set Segment Re-map
    oled_command(0xC8);  // Set COM Output Scan Direction
    oled_command(0xDA);  // Set COM Pins hardware configuration
    oled_command(0x12);  // --configuration
    oled_command(0x81);  // Set Contrast Control
    oled_command(0xCF);  // --contrast
    oled_command(0xD9);  // Set Pre-charge Period
    oled_command(0xF1);  // --period
    oled_command(0xDB);  // Set VCOMH Deselect Level
    oled_command(0x40);  // --level
    oled_command(0xA4);  // Entire Display ON/OFF
    oled_command(0xA6);  // Set Normal Display
    oled_command(0xAF);  // Display on
}

// Function to clear the OLED display
void oled_clear() {
    for (int i = 0; i < OLED_WIDTH * (OLED_HEIGHT / 8); i++) {
        oled_data(0x00);
    }
}

// Function to send a command to the OLED display
void oled_command(unsigned char command) {
    char buf[2];
    buf[0] = 0x00; // Control byte: command
    buf[1] = command;
    i2cWriteDevice(i2c_handle, buf, 2);
}

// Function to send data to the OLED display
void oled_data(unsigned char data) {
    char buf[2];
    buf[0] = 0x40; // Control byte: data
    buf[1] = data;
    i2cWriteDevice(i2c_handle, buf, 2);
}

// Function to set the cursor position on the OLED display
void oled_set_cursor(int x, int y) {
    oled_command(0xB0 + y); // Set page address
    oled_command(0x00 + (x & 0x0F)); // Set lower column address
    oled_command(0x10 + ((x >> 4) & 0x0F)); // Set higher column address
}

// Function to write a string to the OLED display using the font
void oled_write_string(int x, int y, const char *str) {
    int i;
    for (i = 0; str[i] != '\0'; i++) {
        int char_index = str[i] - ' ';
        if (char_index < 0 || char_index >= 95) {
            char_index = 0; // Use space if character is out of range
        }
        for (int j = 0; j < 5; j++) {
            oled_set_cursor(x + j, y);
            oled_data(font[char_index][j]);
        }
        x += 6; // Move to the next character position
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the OLED display
    oled_init();

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature and usage
        float temperature = read_cpu_temp();
        float usage = read_cpu_usage();

        // Display the data on the OLED screen
        if (temperature == -1.0f) {
            fprintf(stderr, "Error reading temperature, displaying error message.\n");
            oled_clear();
            oled_write_string(0, 0, "Temp Err");
        } else {
            char temp_str[20];
            snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", temperature);
            oled_clear();
            oled_write_string(0, 0, temp_str);
        }

        if (usage == -1.0f) {
            fprintf(stderr, "Error reading usage, displaying error message.\n");
            oled_clear();
            oled_write_string(0, 16, "Usage Err");
        } else {
            char usage_str[20];
            snprintf(usage_str, sizeof(usage_str), "Usage: %.1f%%", usage);
            oled_clear();
            oled_write_string(0, 16, usage_str);
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's replacement for sleep
    }

    // Clear the display and close the I2C connection before exiting
    oled_clear();
    oled_command(0xAE); // Display off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

