    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        if (sscanf(buffer, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                   &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) == 10) {
            unsigned long long prev_idle = idle + iowait;
            unsigned long long prev_non_idle = user + nice + system + irq + softirq + steal;
            unsigned long long prev_total = prev_idle + prev_non_idle;

            unsigned long long new_idle = idle;
            unsigned long long new_non_idle = user + nice + system + irq + softirq + steal;

            unsigned long long totald = new_idle + iowait - prev_idle - iowait;
            unsigned long long idled = new_idle - prev_idle;

            float usage = (float)(totald - idled) / (float)(prev_total - prev_idle);
            usage = 100.0f - usage;
        } else {
            fprintf(stderr, "Error: Could not parse CPU usage from file.\n");
        }
    } else {
        fprintf(stderr, "Error: Could not read CPU usage from file.\n");
    }

    fclose(fp);
    return usage;
}

