        int char_index = str[i] - ' ';
        if (char_index < 0 || char_index >= 95) {
            char_index = 0; // Use space if character is out of range
        }
        for (int j = 0; j < 5; j++) {
            oled_set_cursor(x + j, y);
            oled_data(font[char_index][j]);
        }
        x += 6; // Move to the next character position
    }
}

// Signal handler for graceful shutdown
