        gpioDelay(500000); // Wait 500ms
    }

    // Cleanup
    lcd_clear();
    lcd_send_command(0x01); // Clear display
    gpioDelay(2000); // Wait 2ms
    lcd_send_command(0x08); // Display off
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
