#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows and columns
const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};

// Number of rows and columns
const int num_rows = 8;
const int num_cols = 8;

// Function prototypes
int initialize_gpio();
void scan_row(int row);
void wave_left_to_right();
void wave_right_to_left();
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Generate wave patterns
        wave_left_to_right();
        wave_right_to_left();
    }

    // Cleanup GPIO pins before exiting
    cleanup_gpio();

    return 0;
}

// Initialize pigpio and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set row pins as outputs
    for (int i = 0; i < num_rows; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set row pin %d as output\n", row_pins[i]);
            gpioTerminate();
            return 1;
        }
        gpioWrite(row_pins[i], 1); // Set row HIGH initially
    }

    // Set column pins as outputs
    for (int i = 0; i < num_cols; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set column pin %d as output\n", col_pins[i]);
            gpioTerminate();
            return 1;
        }
        gpioWrite(col_pins[i], 0); // Set column LOW initially
    }

    return 0;
}

// Scan a single row
void scan_row(int row) {
    gpioWrite(row_pins[row], 1); // Set row HIGH
    gpioDelay(800);              // Delay for 800 microseconds
    gpioWrite(row_pins[row], 0); // Set row LOW
}

// Wave pattern: Left to Right
void wave_left_to_right() {
    for (int i = 0; i < num_cols; i++) {
        scan_row(i);
    }
}

// Wave pattern: Right to Left
void wave_right_to_left() {
    for (int i = num_cols - 1; i >= 0; i--) {
        scan_row(i);
    }
}

// Cleanup GPIO pins
void cleanup_gpio() {
    printf("Cleaning up GPIO pins...\n");
    // Set all row pins LOW
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 0);
    }

    // Set all column pins HIGH
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1);
    }

    gpioTerminate();
    printf("GPIO cleanup complete.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    program_running = 0;
}

