#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for rows and columns
#define ROW1 2
#define ROW2 3
#define ROW3 4
#define ROW4 17
#define ROW5 27
#define ROW6 22
#define ROW7 10
#define ROW8 9

#define COL1 14
#define COL2 15
#define COL3 18
#define COL4 23
#define COL5 24
#define COL6 25
#define COL7 8
#define COL8 7

// Define chip names
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *row_lines[8];
struct gpiod_line *col_lines[8];

// Function prototypes
int init_gpio();
void cleanup_gpio();
void signal_handler(int sig);
void set_row(int row);
void set_col(int col);
void clear_matrix();
void delay_ms(int milliseconds);

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int init_gpio()
{
    int i;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return -1;
    }

    // Get row lines
    for (i = 0; i < 8; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, ROW1 + i);
        if (!row_lines[i]) {
            fprintf(stderr, "Error getting row line %d\n", ROW1 + i);
            gpiod_chip_close(chip);
            return -1;
        }
    }

    // Get column lines
    for (i = 0; i < 8; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, COL1 + i);
        if (!col_lines[i]) {
            fprintf(stderr, "Error getting column line %d\n", COL1 + i);
            gpiod_chip_close(chip);
            return -1;
        }
    }

    // Request row lines as outputs
    for (i = 0; i < 8; i++) {
        if (gpiod_line_request_output(row_lines[i], "row", 0) < 0) {
            fprintf(stderr, "Error requesting row line %d as output\n", ROW1 + i);
            cleanup_gpio();
            return -1;
        }
    }

    // Request column lines as outputs
    for (i = 0; i < 8; i++) {
        if (gpiod_line_request_output(col_lines[i], "col", 0) < 0) {
            fprintf(stderr, "Error requesting column line %d as output\n", COL1 + i);
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio()
{
    int i;

    // Release column lines
    for (i = 0; i < 8; i++) {
        gpiod_line_release(col_lines[i]);
    }

    // Release row lines
    for (i = 0; i < 8; i++) {
        gpiod_line_release(row_lines[i]);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);
}

// Set a row anode HIGH
void set_row(int row)
{
    if (row >= 0 && row < 8) {
        if (gpiod_line_set_value(row_lines[row], 1) < 0) {
            fprintf(stderr, "Error setting row %d HIGH\n", row);
        }
    }
}

// Set a column cathode LOW
void set_col(int col)
{
    if (col >= 0 && col < 8) {
        if (gpiod_line_set_value(col_lines[col], 0) < 0) {
            fprintf(stderr, "Error setting column %d LOW\n", col);
        }
    }
}

// Clear the matrix by setting all row anodes LOW and all column cathodes HIGH
void clear_matrix()
{
    int i;
    for (i = 0; i < 8; i++) {
        set_row(i);
    }
    for (i = 0; i < 8; i++) {
        set_col(i);
    }
}

// Delay for a specified number of milliseconds
void delay_ms(int milliseconds)
{
    struct timespec ts;
    ts.tv_sec = milliseconds / 1000;
    ts.tv_nsec = (milliseconds % 1000) * 1000000;
    nanosleep(&ts, NULL);
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("8x8 LED matrix animation started. Press Ctrl+C to exit.\n");

    // Main loop: scan columns and light them sequentially
    while (1) {
        for (int col = 0; col < 8; col++) {
            clear_matrix();
            set_col(col);
            delay_ms(150);
        }
    }

    return 0;
}

