        if (!col_lines[i]) {
            fprintf(stderr, "Error getting column line %d\n", COL1 + i);
            gpiod_chip_close(chip);
            return -1;
        }
    }

    // Request row lines as outputs
    for (i = 0; i < 8; i++) {
        if (gpiod_line_request_output(row_lines[i], "row", 0) < 0) {
            fprintf(stderr, "Error requesting row line %d as output\n", ROW1 + i);
            cleanup_gpio();
            return -1;
        }
    }

    // Request column lines as outputs
    for (i = 0; i < 8; i++) {
        if (gpiod_line_request_output(col_lines[i], "col", 0) < 0) {
            fprintf(stderr, "Error requesting column line %d as output\n", COL1 + i);
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio()
{
    int i;

    // Release column lines
    for (i = 0; i < 8; i++) {
        gpiod_line_release(col_lines[i]);
    }

    // Release row lines
    for (i = 0; i < 8; i++) {
        gpiod_line_release(row_lines[i]);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);
}

// Set a row anode HIGH
void set_row(int row)
{
    if (row >= 0 && row < 8) {
        if (gpiod_line_set_value(row_lines[row], 1) < 0) {
            fprintf(stderr, "Error setting row %d HIGH\n", row);
        }
    }
}

// Set a column cathode LOW
void set_col(int col)
{
    if (col >= 0 && col < 8) {
        if (gpiod_line_set_value(col_lines[col], 0) < 0) {
            fprintf(stderr, "Error setting column %d LOW\n", col);
        }
    }
}

// Clear the matrix by setting all row anodes LOW and all column cathodes HIGH
void clear_matrix()
{
    int i;
    for (i = 0; i < 8; i++) {
        set_row(i);
    }
    for (i = 0; i < 8; i++) {
        set_col(i);
    }
}

// Delay for a specified number of milliseconds
void delay_ms(int milliseconds)
{
    struct timespec ts;
    ts.tv_sec = milliseconds / 1000;
    ts.tv_nsec = (milliseconds % 1000) * 1000000;
    nanosleep(&ts, NULL);
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("8x8 LED matrix animation started. Press Ctrl+C to exit.\n");

    // Main loop: scan columns and light them sequentially
    while (1) {
        for (int col = 0; col < 8; col++) {
            clear_matrix();
            set_col(col);
            delay_ms(150);
        }
    }

    return 0;
}

