#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_i2c();
int read_distance(int i2c_handle);
int log_data(FILE *fp, int distance);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    char *log_file_name;
} config_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
int read_distance(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    // Convert big-endian to little-endian
    int16_t distance = (buf[1] << 8) | buf[0];
    return distance;
}

// Function to log data to a file
int log_data(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    fflush(log_file);

    // Main loop
    while (1) {
        int distance = read_distance(i2c_handle);
        if (distance != -1) {
            if (log_data(log_file, distance) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, logging -1\n");
            fprintf(log_file, "Timestamp,-1\n");
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

