#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define PART_ID_VALUE 0x45
#define MEASURE_RATE_REG 0x18
#define MEASURE_RATE_VALUE 0x77 // Example value, adjust as needed

int i2c_handle;
FILE *log_file;

// Function to read a register from the Si1145
int read_register(int handle, unsigned char reg, unsigned char *value) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)value, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to write a register to the Si1145
int write_register(int handle, unsigned char reg, unsigned char value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the Si1145 sensor
int initialize_sensor(int handle) {
    // Verify PART ID
    unsigned char part_id;
    if (read_register(handle, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART ID\n");
        return -1;
    }
    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_VALUE);
        return -1;
    }

    // Set measurement rate
    if (write_register(handle, MEASURE_RATE_REG, MEASURE_RATE_VALUE) != 0) {
        fprintf(stderr, "Failed to set measurement rate\n");
        return -1;
    }

    // Clear any stale IRQ
    if (write_register(handle, 0x07, 0x00) != 0) {
        fprintf(stderr, "Failed to clear IRQ\n");
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data
int read_sensor_data(int handle, unsigned short *proximity, unsigned short *ambient_light) {
    unsigned char data[4];

    if (i2cReadI2CBlockData(handle, 0x22, (char *)data, 4) != 4) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *proximity = (data[0] << 8) | data[1];
    *ambient_light = (data[2] << 8) | data[3];

    return 0;
}

// Function to log data to a file
int log_data(FILE *file, time_t timestamp, unsigned short proximity, unsigned short ambient_light) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(file, "%s, %u, %u\n", timestamp_str, proximity, ambient_light);
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    unsigned short proximity, ambient_light;
    time_t current_time;

    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &proximity, &ambient_light) == 0) {
            // Get current timestamp
            current_time = time(NULL);

            // Log data
            log_data(log_file, current_time, proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait 500ms
        gpioDelay(500000); // pigpio uses microseconds
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

