#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>
#include <errno.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL_MS 100
#define BLINK_DURATION_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t keep_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
int log_event(const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
        return -1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
        free(timestamp);
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        free(timestamp);
        return -1;
    }
}

// Function to initialize the GPIO lines
int initialize_gpio() {
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            perror("Failed to open GPIO chip");
            return -1;
        }
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Failed to get sensor GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "proximity_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(sensor_line, &config, 0);
    if (ret < 0) {
        perror("Failed to request sensor GPIO line as input");
        gpiod_line_release(led_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "proximity_sensor_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(led_line, &config, 0);
    if (ret < 0) {
        perror("Failed to request LED GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to blink the LED
void blink_led() {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "proximity_sensor_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        perror("Failed to request LED GPIO line for output during blink");
        return;
    }

    int ret = gpiod_line_set_value(led_line, 1); // Turn LED on
    if (ret < 0) {
        perror("Failed to set LED GPIO line value to 1");
        gpiod_line_release(led_line);
        return;
    }
    usleep(BLINK_DURATION_MS * 1000); // Keep LED on for BLINK_DURATION_MS ms

    ret = gpiod_line_set_value(led_line, 0); // Turn LED off
    if (ret < 0) {
        perror("Failed to set LED GPIO line value to 0");
        gpiod_line_release(led_line);
        return;
    }
    usleep(BLINK_DURATION_MS * 1000); // Keep LED off for BLINK_DURATION_MS ms

    gpiod_line_release(led_line);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup_gpio();
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "proximity_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Failed to get sensor GPIO line");
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }

    int ret = gpiod_line_request(sensor_line, &config, 0);
    if (ret < 0) {
        perror("Failed to request sensor GPIO line as input");
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }

    fprintf(stderr, "Proximity sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        int value = gpiod_line_get_value(sensor_line);
        if (value < 0) {
            perror("Failed to get sensor GPIO line value");
            break;
        }

        if (value == 0) { // Object detected (LOW signal)
            if (log_event("Object detected") == 0) {
                fprintf(stderr, "Object detected, logged to file.\n");
            } else {
                fprintf(stderr, "Failed to log object detection event.\n");
            }
            blink_led();
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every POLL_INTERVAL_MS ms
    }

    // Cleanup resources before exiting
    cleanup_gpio();
    fclose(log_file);

    fprintf(stderr, "Proximity sensor program finished.\n");
    return 0;
}

