#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define TIMEOUT_US 30000  // 30ms timeout
#define MIN_DISTANCE 2.0  // Minimum distance in cm
#define MAX_DISTANCE 400.0 // Maximum distance in cm
#define REMINDER_THRESHOLD 15.0 // Distance threshold for watering reminder

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance();
void log_data(double distance);
void signal_handler(int signal);
void cleanup();

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin events
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that the rising edge was received
    } else if (level == 0 && echo_received) {
        echo_end_tick = tick;
    } else if (level == 0 && !echo_received) {
        timeout_flag = 1; // Timeout occurred
    }
}

// Function to calculate distance in centimeters
double calculate_distance() {
    if (echo_received) {
        uint32_t pulse_width = echo_end_tick - echo_start_tick;
        if (pulse_width > TIMEOUT_US) {
            timeout_flag = 1;
            return -1.0; // Timeout
        }
        double distance = (double)pulse_width * 34300.0 / 2000000.0; // cm
        return distance;
    } else {
        return -1.0; // Sensor not received
    }
}

// Function to log data to a file
void log_data(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-up/down resistor on ECHO pin (optional, depends on your voltage divider)
    // gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Or PI_PUD_UP if needed

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance sensor running. Press Ctrl+C to exit.\n");

    while (1) {
        trigger_sensor();
        gpioDelay(50); // Wait for echo

        double distance = calculate_distance();

        if (distance > 0 && distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
            log_data(distance);
            if (distance < REMINDER_THRESHOLD) {
                printf("Time to water the plant!\n");
            }
        } else if (distance < 0) {
            log_data(-1.0); // Log timeout
            printf("Timeout occurred.\n");
        } else {
            log_data(-2.0); // Log sensor not received
            printf("Sensor not received.\n");
        }

        gpioDelay(60); // Poll every 60 seconds
    }

    return 0;
}

