#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// APDS9960 Registers
#define APDS9960_ID 0x92
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90

// Configuration Values
#define ENABLE_VALUE 0x03
#define ATIME_VALUE 0xDB
#define WTIME_VALUE 0xF6
#define PPULSE_VALUE 0x87
#define CONTROL_VALUE 0x03
#define CONFIG2_VALUE 0x01

// Proximity Threshold
#define PROXIMITY_THRESHOLD 200

// I2C Bus and Address
#define I2C_BUS 1
#define APDS9960_ADDRESS 0x39

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity);
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize Sensor
int initialize_sensor() {
    int result;

    // Verify Sensor ID
    result = i2cWriteByteData(i2c_handle, APDS9960_ID, 0x00); // Dummy write to read ID
    if (result < 0) {
        fprintf(stderr, "Error writing to sensor ID register: %d\n", result);
        return -1;
    }
    uint8_t sensor_id;
    result = i2cReadI2CBlockData(i2c_handle, APDS9960_ID, (char*)&sensor_id, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", result);
        return -1;
    }
    if (sensor_id != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Configure Registers
    result = i2cWriteByteData(i2c_handle, APDS9960_ENABLE, ENABLE_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", result);
        return -1;
    }

    result = i2cWriteByteData(i2c_handle, APDS9960_ATIME, ATIME_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error writing to ATIME register: %d\n", result);
        return -1;
    }

    result = i2cWriteByteData(i2c_handle, APDS9960_WTIME, WTIME_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error writing to WTIME register: %d\n", result);
        return -1;
    }

    result = i2cWriteByteData(i2c_handle, APDS9960_PPULSE, PPULSE_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error writing to PPULSE register: %d\n", result);
        return -1;
    }

    result = i2cWriteByteData(i2c_handle, APDS9960_CONTROL, CONTROL_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %d\n", result);
        return -1;
    }

    result = i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, CONFIG2_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read Sensor Data
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0x96, (char*)red, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading red data: %d\n", result);
        return -1;
    }

    result = i2cReadI2CBlockData(i2c_handle, 0x98, (char*)green, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading green data: %d\n", result);
        return -1;
    }

    result = i2cReadI2CBlockData(i2c_handle, 0x9A, (char*)blue, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", result);
