#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x5A
#define PART_ID_REG 0x00
#define MEAS_RATE0_REG 0x08
#define COMMAND_REG 0x47
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    int fd;
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    int proximity_value;
    int bpm;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return 1;
    }

    // Verify Part ID
    int part_id = i2c_read_reg(fd, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID, exiting.\n");
        close(fd);
        return 1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X, expected 0x82\n", part_id);
        close(fd);
        return 1;
    }

    // Configure and start measurement
    if (i2c_write_reg(fd, MEAS_RATE0_REG, 0x0A) < 0) {
        fprintf(stderr, "Error configuring measurement rate.\n");
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, COMMAND_REG, 0x01) < 0) {
        fprintf(stderr, "Error starting measurement.\n");
        close(fd);
        return 1;
    }

    // Open CSV file
    fp = fopen("heartrate.csv", "a");
    if (fp == NULL) {
        perror("Error opening heartrate.csv");
        close(fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read proximity data
        int ps_data0 = i2c_read_reg(fd, PS_DATA0_REG);
        int ps_data1 = i2c_read_reg(fd, PS_DATA1_REG);

        if (ps_data0 < 0 || ps_data1 < 0) {
            fprintf(stderr, "Error reading proximity data, skipping sample.\n");
            usleep(100000); // 100ms
            continue;
        }

        // Combine the two bytes into a 16-bit value
        proximity_value = (ps_data1 << 8) | ps_data0;

        // Placeholder BPM calculation
        bpm = proximity_value / 10; // Example calculation

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log data to CSV file
        fprintf(fp, "%s,%d\n", timestamp, bpm);
        fflush(fp);

        usleep(100000); // 100ms delay
    }

    // Cleanup
    close(fd);
    fclose(fp);

    return 0;
}

