#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_PIN 17 // BCM numbering
#define DISTANCE_REG 0x14
#define INTERRUPT_REG 0x13
#define INTERRUPT_CLEAR_REG 0x0B
#define TIMEOUT_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int gpio_pin;
    int timeout_ms;
} sensor_config_t;

// Function to initialize the sensor
int init_sensor() {
    // Check if the sensor is present by reading a register
    char data[1];
    data[0] = 0x00; // SYSRANGE_START register
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to sensor (presence check)\n");
        return -1;
    }
    gpioDelay(10); // Small delay after write

    char check_data[1];
    if (i2cReadDevice(i2c_handle, check_data, 1) != 1) {
        fprintf(stderr, "Error reading from sensor (presence check)\n");
        return -1;
    }

    if (check_data[0] != 0x00) {
        fprintf(stderr, "Sensor not present or returned unexpected data\n");
        return -1;
    }

    // Configure GPIO pin as input with pull-up
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the distance from the sensor
int read_distance(uint16_t *distance) {
    char data[1];
    data[0] = 0x01; // SYSRANGE_START register
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error writing to sensor (range start)\n");
        return -1;
    }
    gpioDelay(10); // Small delay after write

    // Wait for interrupt
    int timeout_counter = 0;
    while (1) {
        char interrupt_status[1];
        if (i2cReadDevice(i2c_handle, interrupt_status, 1) != 1) {
            fprintf(stderr, "Error reading interrupt status\n");
            return -1;
        }

        if (interrupt_status[0] & 0x01) {
            break; // Interrupt occurred
        }

        gpioDelay(1); // Small delay
        timeout_counter++;
        if (timeout_counter > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for interrupt\n");
            return -1;
        }
    }

    // Read the distance data
    char distance_data[2];
    if (i2cReadDevice(i2c_handle, distance_data, 2) != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    *distance = (distance_data[0] << 8) | distance_data[1];

    // Clear interrupt
    char clear_data[1];
    clear_data[0] = 0x01; // SYSTEM_INTERRUPT_CLEAR register
    if (i2cWriteDevice(i2c_handle, clear_data, 1) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }
    gpioDelay(10); // Small delay after clear

    return 0;
}

// Function to log the distance to a file
void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    uint16_t distance;
