int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from a register with retry mechanism
int read_register(int handle, int reg, uint8_t *data, int count) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(handle, reg, (char *)data, count);
        if (result >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, retry %d): %d\n", reg, retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
