// Structure to hold sensor data
typedef struct {
    int fd;
    int address;
} sensor_t;

// Global variables
sensor_t *sensors = NULL;
int num_sensors = 0;
int running = 1;

// Function prototypes
int i2c_open(int bus, int address);
int i2c_write(int fd, uint8_t *data, int len);
int i2c_read(int fd, uint8_t *data, int len);
int read_distance(int fd);
