int log_intrusion(int sensor_id, int average_distance);
void sample_sensor(sensor_t *sensor);
void signal_handler(int sig);

// I2C open function
int i2c_open(int bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
