#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define MODEL_ID_REG 0xC0
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

int i2c_handle;

// Function to read a single byte from the VL53L0X
int vl53l0x_read_byte(int handle, unsigned char reg, unsigned char *data) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading byte from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *data = (unsigned char)result;
    return 0;
}

// Function to write a single byte to the VL53L0X
int vl53l0x_write_byte(int handle, unsigned char reg, unsigned char data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing byte to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the model ID register
int vl53l0x_read_model_id(int handle, unsigned char *model_id) {
    if (vl53l0x_read_byte(handle, MODEL_ID_REG, model_id) != 0) {
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L0X sensor
int vl53l0x_init(int handle) {
    // Check if the sensor is present
    unsigned char model_id;
    if (vl53l0x_read_model_id(handle, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID. Check if sensor is present.\n");
        return -1;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Error: Incorrect model ID (0x%02X). Check sensor connection.\n", model_id);
        return -1;
    }

    // Start a single measurement
    if (vl53l0x_write_byte(handle, SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting single measurement.\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int vl53l0x_read_distance(int handle, unsigned short *distance) {
    unsigned char result;

    // Wait for the interrupt to be set (bit 0 of RESULT_INTERRUPT_STATUS)
    int timeout = 100; // Timeout in milliseconds
    while (timeout > 0) {
        if (vl53l0x_read_byte(handle, RESULT_INTERRUPT_STATUS, &result) != 0) {
            fprintf(stderr, "Error reading interrupt status.\n");
            return -1;
        }
        if (result & 0x01) {
            break; // Interrupt is set
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for interrupt.\n");
        return -1;
    }

    // Read the distance (2 bytes, little-endian)
    unsigned char low_byte, high_byte;
    if (vl53l0x_read_byte(handle, RESULT_RANGE_STATUS, &low_byte) != 0) {
        fprintf(stderr, "Error reading distance low byte.\n");
        return -1;
    }
    if (vl53l0x_read_byte(handle, RESULT_RANGE_STATUS + 1, &high_byte) != 0) {
        fprintf(stderr, "Error reading distance high byte.\n");
        return -1;
    }

    *distance = (unsigned short)((high_byte << 8) | low_byte);

    // Clear the interrupt
    if (vl53l0x_write_byte(handle, SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error clearing interrupt.\n");
        return -1;
    }

    return 0;
}

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L0X sensor
    if (vl53l0x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        unsigned short distance;
        if (vl53l0x_read_distance(i2c_handle, &distance) == 0) {
            char timestamp[20];
            get_timestamp(timestamp);
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

