#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Si1182 I2C address
#define SI1182_ADDR 0x39

// Si1182 register addresses
#define SI1182_REG_STATUS 0x25
#define SI1182_REG_PROX_DATA_LSB 0x2A
#define SI1182_REG_PROX_DATA_MSB 0x2B

// Si1182 configuration register
#define SI1182_REG_CONFIG 0x18

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the Si1182 sensor
int initialize_sensor() {
    // Write 0x01 to the CONFIG register to enable proximity mode
    int result = i2cWriteByteData(i2c_handle, SI1182_REG_CONFIG, 0x01);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Check if data is ready by reading the STATUS register
        int status = i2cReadByteData(i2c_handle, SI1182_REG_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading status register: %d\n", status);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Check if the proximity data is ready (bit 0 of the status register is set)
        if (status & 0x01) {
            // Read the proximity data from the registers
            int prox_lsb = i2cReadByteData(i2c_handle, SI1182_REG_PROX_DATA_LSB);
            int prox_msb = i2cReadByteData(i2c_handle, SI1182_REG_PROX_DATA_MSB);

            if (prox_lsb < 0 || prox_msb < 0) {
                fprintf(stderr, "Error reading proximity data: prox_lsb=%d, prox_msb=%d\n", prox_lsb, prox_msb);
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }

            // Combine the two bytes to form the 16-bit proximity value
            int proximity_value = (prox_msb << 8) | prox_lsb;

            // Print the proximity value
            printf("Proximity: %d\n", proximity_value);
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
