        distance_raw = i2cReadWordData(i2c_fd, DISTANCE_REGISTER_OFFSET);

        if (distance_raw >= 0) {
            // Success, return the distance in millimetres
            return (int)(distance_raw * DISTANCE_FACTOR);
        } else {
            // Error occurred, print an error message and retry
            fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
