#include <unistd.h>
#include <errno.h>

// Define OPT3101 I2C address
#define OPT3101_ADDR 0x44

// Define OPT3101 register addresses (Example - Refer to OPT3101 datasheet)
#define OPT3101_REG_CH0_DISTANCE 0x00
#define OPT3101_REG_CH0_AMBIENT 0x02
#define OPT3101_REG_ERROR 0x04

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a register from OPT3101
int opt3101_read_register(int handle, uint8_t reg_addr) {
    int result = i2cReadByteData(handle, reg_addr);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1; // Indicate error
    }
    return result;
}

// Function to write a register to OPT3101
int opt3101_write_register(int handle, uint8_t reg_addr, uint8_t value) {
    int result = i2cWriteByteData(handle, reg_addr, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Function to initialize OPT3101
int opt3101_init(int handle) {
    // Example initialization sequence (Refer to OPT3101 datasheet)
    if (opt3101_write_register(handle, 0x01, 0x00) < 0) return -1; // Reset
    gpioDelay(10000); // 10ms delay
    if (opt3101_write_register(handle, 0x02, 0x01) < 0) return -1; // Enable channel 0
    gpioDelay(10000); // 10ms delay
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize OPT3101
    if (opt3101_init(i2c_handle) < 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance and ambient light data
        int distance = opt3101_read_register(i2c_handle, OPT3101_REG_CH0_DISTANCE);
        int ambient = opt3101_read_register(i2c_handle, OPT3101_REG_CH0_AMBIENT);
        int error_flag = opt3101_read_register(i2c_handle, OPT3101_REG_ERROR);

        // Check for errors
        if (distance < 0 || ambient < 0 || error_flag < 0) {
            fprintf(stderr, "Error reading sensor data. Check I2C connection.\n");
        } else {
            // Log data to console
            printf("Distance: %d, Ambient: %d, Error: %d\n", distance, ambient, error_flag);
        }

        gpioDelay(500000); // 500ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

