#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TIMEOUT_US 200000 // 200ms timeout in microseconds
#define MAX_DISTANCE_CM 400 // Maximum measurable distance in cm (4 meters)

// Global variables
static volatile int running = 1;
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
long pulse_width();
float distance_cm(long pulse_width);
void log_distance(float distance);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulse_width() {
    long start_tick, end_tick, diff;

    // Wait for rising edge
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - echo_start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout (rising edge).\n");
            return -1; // Indicate error
        }
    }
    echo_start_tick = gpioTick();

    // Wait for falling edge
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - echo_start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout (falling edge).\n");
            return -1; // Indicate error
        }
    }
    echo_end_tick = gpioTick();

    diff = echo_end_tick - echo_start_tick;
    return diff;
}

// Function to calculate distance in centimeters
float distance_cm(long pulse_width) {
    if (pulse_width <= 0 || pulse_width > 38000) {
        fprintf(stderr, "Error: Invalid pulse duration: %ld us\n", pulse_width);
        return -1.0; // Indicate error
    }
    return (pulse_width * 0.0343) / 2.0;
}

// Function to log the distance with a timestamp
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        long pulse_width_us = pulse_width();

        if (pulse_width_us > 0) {
            float distance_cm = distance_cm(pulse_width_us);
            if (distance_cm >= 0) {
                log_distance(distance_cm);
            }
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

