#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_PIN 17
#define RANGE_RESOLUTION 0.0486
#define THRESHOLD_DISTANCE 1.0
#define ALERT_DURATION 2

// Structure to hold UART configuration
typedef struct {
    int fd;
    struct termios tty;
} uart_config_t;

// Global variables
volatile sig_atomic_t program_running = 1;
uart_config_t uart_config;

// Function prototypes
int uart_init(uart_config_t *config);
int uart_read_data(uart_config_t *config, short *range_profile);
float calculate_distance(short range_bin);
int detect_intrusion(float distance);
int log_intrusion(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// UART initialization function
int uart_init(uart_config_t *config) {
    config->fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (config->fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    if (tcgetattr(config->fd, &config->tty) != 0) {
        perror("Error getting termios attributes");
        close(config->fd);
