#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define BUZZER_PIN 18

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor();
void activate_buzzer();
void deactivate_buzzer();
void log_state(int state);
void signal_handler(int signal);

// Function to read the sensor value
int read_sensor() {
    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor: %d\n", sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to activate the buzzer
void activate_buzzer() {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error activating buzzer\n");
    }
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error deactivating buzzer\n");
    }
}

// Function to log the state to a file
void log_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d\n", timestamp, state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Deactivate buzzer
    deactivate_buzzer();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("obstacle_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int previous_state = -1; // Initialize to an invalid state
    int current_state;

    // Main loop
    while (running) {
        current_state = read_sensor();

        if (current_state == -1) {
            // Error reading sensor, skip this iteration
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (current_state != previous_state) {
            if (current_state == 0) {
                activate_buzzer();
            } else {
                deactivate_buzzer();
            }
            log_state(current_state);
            previous_state = current_state;
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup (should not reach here if signal handler is used)
    deactivate_buzzer();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

