#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_REG_HIGH 0x31
#define DISTANCE_REG_LOW 0x32
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_distance(int *distance);
float convert_to_cm(int raw_distance);
int log_distance(float distance);
int check_threshold(float distance);
int set_gpio_alert(int alert);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int gpio_pin;
    float distance_threshold;
} sensor_config_t;

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance data from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG_HIGH, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw distance to centimeters (example conversion)
float convert_to_cm(int raw_distance) {
    // This is a placeholder.  Replace with the actual conversion formula
    // from the ICU-20201 datasheet.
    return (float)raw_distance / 10.0; // Example: 1 unit = 10 cm
}

// Log distance data to a file
int log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

// Check if distance is below the threshold
int check_threshold(float distance) {
    return (distance < DISTANCE_THRESHOLD) ? 1 : 0;
}

// Set GPIO alert based on distance
int set_gpio_alert(int alert) {
    gpioWrite(GPIO_PIN, alert);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is low on exit
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance_raw;
    float distance_cm;

    // Main loop
    while (!terminate) {
        // Check for termination signal
        if (terminate) break;

        // Read distance
        if (read_distance(&distance_raw) == 0) {
            // Convert to centimeters
            distance_cm = convert_to_cm(distance_raw);

            // Log distance
            if (log_distance(distance_cm) != 0) {
                fprintf(stderr, "Error logging distance\n");
            }

            // Check threshold and set GPIO
            if (check_threshold(distance_cm)) {
                set_gpio_alert(1);
            } else {
                set_gpio_alert(0);
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

