#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define BLINK_FREQUENCY_MIN 1
#define BLINK_FREQUENCY_MAX 10
#define DISTANCE_MIN 50.0  // mm
#define DISTANCE_MAX 500.0 // mm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
void control_led(float distance);
void log_data(float distance, int blink_frequency);
void signal_handler(int signal);

// Structure to hold sensor data (optional)
typedef struct {
    float distance;
    int blink_frequency;
} sensor_data_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the CH201 sensor
int read_distance(float *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char buf[2];           // Buffer to store the received data
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Small delay after writing the command

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert the received data to distance (example conversion)
    int raw_distance = (buf[0] << 8) | buf[1];
    *distance = (float)raw_distance * 0.1; // Example scaling factor

    return 0;
}

// Control the LED based on the measured distance
void control_led(float distance) {
    int blink_frequency = 0;
    if (distance >= DISTANCE_MIN && distance <= DISTANCE_MAX) {
        // Linear mapping
        blink_frequency = (int)(((distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN)) * (BLINK_FREQUENCY_MAX - BLINK_FREQUENCY_MIN) + BLINK_FREQUENCY_MIN);
    } else if (distance < DISTANCE_MIN) {
        blink_frequency = BLINK_FREQUENCY_MAX;
    } else {
        blink_frequency = BLINK_FREQUENCY_MIN;
    }

    // Calculate half-cycle duration in microseconds
    int half_cycle_duration = 500000 / blink_frequency; // 0.5 ms per half-cycle

    // Toggle the LED state
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(half_cycle_duration);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(half_cycle_duration);
}

// Log the distance and blink frequency to stdout
void log_data(float distance, int blink_frequency) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Distance: %.2f mm, Blink Frequency: %d Hz\n", timestamp, distance, blink_frequency);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance;
    int blink_frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            control_led(distance);
            blink_frequency = (int)(((distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN)) * (BLINK_FREQUENCY_MAX - BLINK_FREQUENCY_MIN) + BLINK_FREQUENCY_MIN);
            log_data(distance, blink_frequency);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

