#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "proximity_log.txt"

// Structure to hold sensor data
typedef struct {
    int gpio;
    int sensor_id;
    int last_state;
} sensor_t;

// Global variables
FILE *log_file = NULL;
sensor_t sensors[2];

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
void log_event(int sensor_id, const char *event_type);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initializes the pigpio library and sets the GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    sensors[0].gpio = SENSOR_1_GPIO;
    sensors[0].sensor_id = 1;
    sensors[0].last_state = gpioRead(SENSOR_1_GPIO);

    sensors[1].gpio = SENSOR_2_GPIO;
    sensors[1].sensor_id = 2;
    sensors[1].last_state = gpioRead(SENSOR_2_GPIO);

    return 0;
}

// Reads the sensor value from the specified GPIO pin
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Logs the event to the log file with an ISO 8601 timestamp
void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
    fflush(log_file); // Ensure the data is written to the file immediately
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        for (int i = 0; i < 2; i++) {
            int current_state = read_sensor(sensors[i].gpio);

            if (current_state != sensors[i].last_state) {
                if (current_state == 0 && sensors[i].last_state == 1) {
                    log_event(sensors[i].sensor_id, "DETECTED");
                } else if (current_state == 1 && sensors[i].last_state == 0) {
                    log_event(sensors[i].sensor_id, "CLEARED");
                }
                sensors[i].last_state = current_state;
            }
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
        }
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

