#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT_MS 50

int i2c_fd = -1;
FILE *log_file = NULL;

// Helper function to read from I2C
int i2c_read_reg(int fd, unsigned char reg, unsigned char *value) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return 0;
}

// Helper function to write to I2C
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
int read_distance(int fd, int *distance_mm) {
    unsigned char status;
    unsigned char dist_high, dist_low;
    int retries = 3;

    while (retries > 0) {
        // Trigger measurement
        if (i2c_write_reg(fd, MEAS_TRIGGER, 0x01) == 0) {
            usleep(TIMEOUT_MS * 1000); // Wait for measurement to complete

            // Check if measurement is ready
            if (i2c_read_reg(fd, MEAS_STATUS, &status) == 0) {
                if (status & 0x01) { // Check bit 0 of MEAS_STATUS
                    // Read distance
                    if (i2c_read_reg(fd, DIST_HIGH, &dist_high) == 0) {
                        if (i2c_read_reg(fd, DIST_LOW, &dist_low) == 0) {
                            *distance_mm = ((dist_high << 8) | dist_low);
                            return 0; // Success
                        } else {
                            perror("Failed to read DIST_LOW");
                            retries--;
                            continue;
                        }
                    } else {
                        perror("Failed to read DIST_HIGH");
                        retries--;
                        continue;
                    }
                } else {
                    fprintf(stderr, "Measurement not ready (status = 0x%02X)\n", status);
                    retries--;
                    usleep(TIMEOUT_MS * 1000); // Wait before retrying
                    continue;
                }
            } else {
                perror("Failed to read MEAS_STATUS");
                retries--;
                usleep(TIMEOUT_MS * 1000); // Wait before retrying
                continue;
            }
        } else {
            perror("Failed to trigger measurement");
            retries--;
            usleep(TIMEOUT_MS * 1000); // Wait before retrying
            continue;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Function to log data to CSV file
int log_data(FILE *fp, int distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, distance_mm) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    int distance_mm;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        ret = read_distance(i2c_fd, &distance_mm);
        if (ret == 0) {
            if (log_data(log_file, distance_mm) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }
        usleep(500000); // 500 ms
    }

    return 0;
}

