#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_START_RANGING 0x0009
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0046
#define VL53L4CX_REG_DISTANCE_HIGH 0x0096
#define VL53L4CX_REG_DISTANCE_LOW 0x0097

// I2C bus number
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l4cx();
int read_distance(int *distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize VL53L4CX sensor
int init_vl53l4cx() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x7FFF, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Soft reset failed (status = %d)\n", status);
        return -1;
    }
    gpioDelay(10000); // 10 ms

    // Start ranging
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_START_RANGING, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to start ranging (status = %d)\n", status);
        return -1;
    }

    return 0;
}

// Read distance from VL53L4CX sensor
int read_distance(int *distance) {
    int status;
    uint8_t high_byte, low_byte;

    // Read distance data
    status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_DISTANCE_HIGH, (char *)&high_byte, 1);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read high byte (status = %d)\n", status);
        return -1;
    }

    status = i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_DISTANCE_LOW, (char *)&low_byte, 1);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read low byte (status = %d)\n", status);
        return -1;
    }

    *distance = (high_byte << 8) | low_byte;

    return 0;
}

int main() {
    int distance;
    struct timespec ts;
    char timestamp[30];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (status = %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (init_vl53l4cx() != 0) {
        fprintf(stderr, "Error: VL53L4CX initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Poll interrupt status
        int interrupt_status = i2cReadByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_STATUS);
        if (interrupt_status < 0) {
            fprintf(stderr, "Error: Failed to read interrupt status (status = %d)\n", interrupt_status);
            gpioDelay(500000); // 500 ms
            continue;
        }

        // Check if ranging is ready
        if (interrupt_status & 0x01) {
            // Read distance
            if (read_distance(&distance) == 0) {
                // Get timestamp
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    // Format timestamp
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

                    // Print distance with timestamp
                    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
                } else {
                    fprintf(stderr, "Error: Failed to get timestamp\n");
                }
            } else {
                fprintf(stderr, "Error: Failed to read distance\n");
            }
        }

        // Wait 500 ms
        gpioDelay(500000);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

