#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_buzzer(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x0001, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: Soft reset failed: %d\n", status);
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Set I2C slave address (optional, but good practice)
    status = i2cWriteByteData(i2c_handle, 0x0001, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: Setting I2C slave address failed: %d\n", status);
        return -1;
    }

    // Configure continuous ranging mode
    status = i2cWriteByteData(i2c_handle, 0x0007, 0x01); // SYSTEM__MODE_START
    if (status < 0) {
        fprintf(stderr, "Error: Setting SYSTEM__MODE_START failed: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, 0x0096, 0x00); // RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM
    if (status < 0) {
        fprintf(stderr, "Error: Setting RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM failed: %d\n", status);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    int status;
    int range;

    // Start a single measurement
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: Starting measurement failed: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // Wait for measurement to complete (adjust as needed)

    // Read distance
    range = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM);
    if (range < 0) {
        fprintf(stderr, "Error: Reading distance failed: %d\n", range);
        return -1;
    }

    *distance = range; // Store the distance
    return 0;
}

// Control the buzzer based on distance
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
    }
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }
        gpioDelay(500000); // 500 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();

    return 0;
}

