#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_PULSE_WIDTH 500   // us
#define MAX_PULSE_WIDTH 2500  // us
#define SERVO_MIN_ANGLE -90
#define SERVO_MAX_ANGLE 90

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float measure_distance();
int map_distance_to_angle(float distance);
void set_servo_angle(int angle);
void log_data(float distance, int angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, then divide by 2 for one-way distance

    return distance;
}

// Function to map distance to servo angle
int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return SERVO_MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return SERVO_MAX_ANGLE;
    } else {
        // Linear mapping
        return (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE);
    }
}

// Function to set servo angle
void set_servo_angle(int angle) {
    int pulse_width = MIN_PULSE_WIDTH + (int)((float)(angle - SERVO_MIN_ANGLE) / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log data to file
void log_data(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %d degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Parking-assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance > 0) {
            int angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Invalid distance reading, skipping servo update.\n");
        }

        gpioDelay(200); // Delay 200ms
    }

    // Cleanup
    set_servo_angle(0); // Stop the servo
    fclose(log_file);
    gpioTerminate();

    printf("Parking-assist system terminated.\n");

    return 0;
}

