#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <sys/types.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/mman.h>

// Configuration
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define MSG_QUEUE_KEY 1234
#define DISTANCE_THRESHOLD 100 // mm
#define MSG_QUEUE_NAME "/distance_queue"

// VL53L1X Registers
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRANGE_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0094
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Message Queue Structure
typedef struct {
    long mtype;        // Message type (must be > 0)
    int distance;      // Distance in millimeters
} message_t;

// Global Variables
int i2c_handle;
int msg_queue_id;
void *map;
int buzzer_state = 0; // 0: off, 1: on

// Function Prototypes
int init_vl53l1x();
int read_distance();
void activate_buzzer(int state);
void send_distance_message(int distance);
void signal_handler(int signal);
int init_message_queue();

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        syslog(LOG_ERR, "I2C write error: reg=0x%02X, value=0x%02X, error=%d", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        syslog(LOG_ERR, "I2C read error: reg=0x%02X, error=%d", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to read a 16-bit value from two VL53L1X registers
int read_16bit_value(int handle, uint8_t reg, uint16_t *value) {
    uint8_t msb, lsb;
    if (read_register(handle, reg, &msb) != 0 || read_register(handle, reg + 1, &lsb) != 0) {
        return -1;
    }
    *value = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    uint8_t model_id;

    // Check model ID
    if (read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        syslog(LOG_ERR, "Failed to read model ID");
        return -1;
    }

    if (model_id != 0xEA) {
        syslog(LOG_ERR, "Incorrect model ID: 0x%02X (expected 0xEA)", model_id);
        return -1;
    }

    // Software reset
    if (write_register(i2c_handle, 0x0000, 0x00) != 0) return -1;
    gpioDelay(100); // Wait for reset to complete
    if (write_register(i2c_handle, 0x0000, 0x01) != 0) return -1;
    gpioDelay(100);

    // Configure timing budget (50ms)
    // Refer to VL53L1X datasheet for detailed configuration
    if (write_register(i2c_handle, 0x0085, 0x00) != 0) return -1; // Set bit 0 to 0
    if (write_register(i2c_handle, 0x0086, 0x00) != 0) return -1; // Set bit 1 to 0
    if (write_register(i2c_handle, 0x0087, 0x00) != 0) return -1; // Set bit 2 to 0
    if (write_register(i2c_handle, 0x0088, 0x00) != 0) return -1; // Set bit 3 to 0
    if (write_register(i2c_handle, 0x0089, 0x00) != 0) return -1; // Set bit 4 to 0
    if (write_register(i2c_handle, 0x008A, 0x00) != 0) return -1; // Set bit 5 to 0
    if (write_register(i2c_handle, 0x008B, 0x00) != 0) return -1; // Set bit 6 to 0
    if (write_register(i2c_handle, 0x008C, 0x00) != 0) return -1; // Set bit 7 to 0
    if (write_register(i2c_handle, 0x008D, 0x00) != 0) return -1; // Set bit 8 to 0
    if (write_register(i2c_handle, 0x008E, 0x00) != 0) return -1; // Set bit 9 to 0
    if (write_register(i2c_handle, 0x008F, 0x00) != 0) return -1; // Set bit 10 to 0
    if (write_register(i2c_handle, 0x0090, 0x00) != 0) return -1; // Set bit 11 to 0
    if (write_register(i2c_handle, 0x0091, 0x00) != 0) return -1; // Set bit 12 to 0
    if (write_register(i2c_handle, 0x0092, 0x00) != 0) return -1; // Set bit 13 to 0
    if (write_register(i2c_handle, 0x0093, 0x00) != 0) return -1; // Set bit 14 to 0
    if (write_register(i2c_handle, 0x0094, 0x00) != 0) return -1; // Set bit 15 to 0

    // Start ranging
    if (write_register(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) return -1;

    return 0;
}

// Read the distance from the VL53L1X sensor
int read_distance() {
    uint16_t distance;
    if (read_16bit_value(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
        syslog(LOG_ERR, "Failed to read distance");
        return -1;
    }
    return (int)distance;
}

// Activate or deactivate the buzzer
void activate_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
    buzzer_state = state;
}

// Send the distance reading to the message queue
void send_distance_message(int distance) {
    message_t message;
    message.mtype = 1; // Message type (must be > 0)
    message.distance = distance;

    if (msgsnd(msg_queue_id, &message, sizeof(message_t) - sizeof(long), 0) == -1) {
        syslog(LOG_ERR, "msgsnd failed: %s", strerror(errno));
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (msg_queue_id >= 0) {
        if (msgctl(msg_queue_id, IPC_RMID, NULL) == -1) {
            syslog(LOG_ERR, "msgctl IPC_RMID failed: %s", strerror(errno));
        }
    }
    if (map != MAP_FAILED) {
        munmap(map, 4096);
    }
    gpioTerminate();
    closelog();
    exit(0);
}

// Initialize the message queue
int init_message_queue() {
    key_t key = MSG_QUEUE_KEY;
    if ((msg_queue_id = msgget(key, IPC_CREAT | 0666)) == -1) {
        syslog(LOG_ERR, "msgget failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize syslog
    openlog("distance_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize message queue
    if (init_message_queue() == -1) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Main loop
    while (1) {
        // Check data ready bit
        if (read_register(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, NULL) == 0) {
            // Read distance
            int distance = read_distance();
            if (distance >= 0) {
                // Send distance message
                send_distance_message(distance);

                // Activate buzzer if distance is below threshold
                if (distance < DISTANCE_THRESHOLD && buzzer_state == 0) {
                    activate_buzzer(1);
                } else if (distance >= DISTANCE_THRESHOLD && buzzer_state == 1) {
                    activate_buzzer(0);
                }
            }
        } else {
            syslog(LOG_WARNING, "Data not ready");
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    i2cClose(i2c_handle);
    if (msgctl(msg_queue_id, IPC_RMID, NULL) == -1) {
        syslog(LOG_ERR, "msgctl IPC_RMID failed: %s", strerror(errno));
    }
    gpioTerminate();
    closelog();

    return 0;
}

