    if (write_register(i2c_handle, 0x0091, 0x00) != 0) return -1; // Set bit 12 to 0
    if (write_register(i2c_handle, 0x0092, 0x00) != 0) return -1; // Set bit 13 to 0
    if (write_register(i2c_handle, 0x0093, 0x00) != 0) return -1; // Set bit 14 to 0
    if (write_register(i2c_handle, 0x0094, 0x00) != 0) return -1; // Set bit 15 to 0

    // Start ranging
    if (write_register(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) return -1;

    return 0;
}

// Read the distance from the VL53L1X sensor
int read_distance() {
    uint16_t distance;
    if (read_16bit_value(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
        syslog(LOG_ERR, "Failed to read distance");
        return -1;
    }
    return (int)distance;
}

// Activate or deactivate the buzzer
void activate_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
    buzzer_state = state;
}

// Send the distance reading to the message queue
void send_distance_message(int distance) {
    message_t message;
    message.mtype = 1; // Message type (must be > 0)
    message.distance = distance;

    if (msgsnd(msg_queue_id, &message, sizeof(message_t) - sizeof(long), 0) == -1) {
        syslog(LOG_ERR, "msgsnd failed: %s", strerror(errno));
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (msg_queue_id >= 0) {
        if (msgctl(msg_queue_id, IPC_RMID, NULL) == -1) {
            syslog(LOG_ERR, "msgctl IPC_RMID failed: %s", strerror(errno));
        }
    }
    if (map != MAP_FAILED) {
        munmap(map, 4096);
    }
    gpioTerminate();
    closelog();
    exit(0);
}

// Initialize the message queue
int init_message_queue() {
    key_t key = MSG_QUEUE_KEY;
    if ((msg_queue_id = msgget(key, IPC_CREAT | 0666)) == -1) {
        syslog(LOG_ERR, "msgget failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize syslog
    openlog("distance_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize message queue
    if (init_message_queue() == -1) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Main loop
    while (1) {
        // Check data ready bit
        if (read_register(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, NULL) == 0) {
            // Read distance
            int distance = read_distance();
            if (distance >= 0) {
                // Send distance message
                send_distance_message(distance);

                // Activate buzzer if distance is below threshold
                if (distance < DISTANCE_THRESHOLD && buzzer_state == 0) {
                    activate_buzzer(1);
                } else if (distance >= DISTANCE_THRESHOLD && buzzer_state == 1) {
                    activate_buzzer(0);
                }
            }
        } else {
            syslog(LOG_WARNING, "Data not ready");
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    i2cClose(i2c_handle);
    if (msgctl(msg_queue_id, IPC_RMID, NULL) == -1) {
        syslog(LOG_ERR, "msgctl IPC_RMID failed: %s", strerror(errno));
    }
    gpioTerminate();
    closelog();

    return 0;
}

