#include <string.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 30000       // microseconds
#define TIMEOUT_MS 60          // milliseconds
#define TRIGGER_PULSE_US 10    // microseconds

// Global variables
static volatile int pulse_start_tick = 0;
static volatile int pulse_end_tick = 0;
static volatile int valid_pulse = 0;
static volatile int timeout_flag = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width_us);
void log_distance(double distance);
void signal_handler(int signal);

// Callback function for ECHO pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (level == 1) // Rising edge
    {
        pulse_start_tick = tick;
        valid_pulse = 0; // Reset valid_pulse flag
        timeout_flag = 0; // Reset timeout flag
    }
    else if (level == 0) // Falling edge
    {
        pulse_end_tick = tick;
        valid_pulse = 1; // Set valid_pulse flag
        timeout_flag = 0; // Reset timeout flag
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor()
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width_us)
{
    return (pulse_width_us * SPEED_OF_SOUND) / 2.0;
}

// Function to log distance to stdout and file
void log_distance(double distance)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);

    if (log_file != NULL)
    {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Initialize TRIG pin to LOW
    gpioWrite(TRIG_PIN, 0);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        trigger_sensor();

        int pulse_width = pulse_end_tick - pulse_start_tick;
        timeout_flag = 1; // Set timeout flag

        if (valid_pulse)
        {
            if (pulse_width > 100 && pulse_width < TIMEOUT_US)
            {
                double distance = calculate_distance(pulse_width);
                log_distance(distance);
            }
            else
            {
                fprintf(stderr, "Warning: Invalid pulse width: %d us\n", pulse_width);
                if (log_file != NULL)
                {
                    fprintf(log_file, "Warning: Invalid pulse width: %d us\n", pulse_width);
                    fflush(log_file);
                }
            }
        }
        else
        {
            fprintf(stderr, "Warning: No valid pulse received.\n");
            if (log_file != NULL)
            {
                fprintf(log_file, "Warning: No valid pulse received.\n");
                fflush(log_file);
            }
        }

        gpioDelay(200); // Wait 200 ms
    }

    return 0;
}

