#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define VL53L1X_ADDR 0x29
#define GPIO_TRIGGER 24
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18
#define DISTANCE_THRESHOLD_FORWARD 100 // mm
#define DISTANCE_THRESHOLD_BACKWARD 300 // mm
#define I2C_BUS 1

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void motor_forward();
void motor_backward();
void motor_stop();
void signal_handler(int signal);

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = value;

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, (reg >> 8) & 0xFF, 1); // Write MSB of register address
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, (char *)value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    uint8_t model_id, revision_id;

    // Check sensor ID
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Soft reset
    if (vl53l1x_write_byte(i2c_handle, 0x0000, 0x00) != 0) {
        fprintf(stderr, "Error soft resetting VL53L1X\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms

    // Set timing budget (example value)
    if (vl53l1x_write_byte(i2c_handle, 0x002d, 0x00) != 0) {
        fprintf(stderr, "Error setting timing budget\n");
        return -1;
    }

    // Start continuous ranging
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting continuous ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int *distance) {
    uint8_t range_status;
    uint16_t range;

    // Wait for data ready
    while (1) {
        if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
            fprintf(stderr, "Error reading range status\n");
            return -1;
        }
        if (range_status & 0x01) {
            break; // Data ready
        }
