#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void motor_forward();
void motor_backward();
void motor_stop();
void signal_handler(int signal);

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = value;

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, (reg >> 8) & 0xFF, 1); // Write MSB of register address
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, (char *)value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

