#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define GPIO pins for LEDs
#define LED1 17
#define LED2 18
#define LED3 27
#define LED4 22

// Define I2C address for MPR121
#define MPR121_ADDR 0x5A

// Define register addresses
#define ELE0 0x00
#define ELE1 0x01
#define ELE2 0x02
#define ELE3 0x03
#define ELE4 0x04
#define ELE5 0x05
#define ELE6 0x06
#define ELE7 0x07
#define ELE8 0x08
#define ELE9 0x09
#define ELE10 0x0A
#define ELE11 0x0B
#define ELECONFIG0 0x5E
#define MHDR 0x2B
#define NHDR 0x2C
#define NCLR 0x2D
#define FDLR 0x2E
#define AUTOCONFIG 0x5A
#define TOUCHTH 0x5D
#define RELEASETH 0x5E
#define ELECONFIG1 0x5F

// Define LED patterns (4-bit)
#define LED_PATTERN_0 {1, 0, 0, 0}
#define LED_PATTERN_1 {0, 1, 0, 0}
#define LED_PATTERN_2 {0, 0, 1, 0}
#define LED_PATTERN_3 {0, 0, 0, 1}

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, unsigned char reg);
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void led_pattern(int pattern);
void log_event(int electrode);
void signal_handler(int signal);

// Structure to hold LED patterns
typedef struct {
    int led1;
    int led2;
    int led3;
    int led4;
} led_pattern_t;

led_pattern_t current_pattern = {0, 0, 0, 0};

// I2C read function
int i2c_read_reg(int fd, unsigned char reg) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Soft reset
    if (i2c_write_reg(fd, 0x80, 0x63) < 0) return -1;
    gpioDelay(100); // Wait for reset

    // Configure electrodes
    if (i2c_write_reg(fd, ELECONFIG0, 0x00) < 0) return -1;

    // Set baseline filtering
    if (i2c_write_reg(fd, MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg(fd, FDLR, 0x00) < 0) return -1;

    // Auto-configuration
    if (i2c_write_reg(fd, AUTOCONFIG, 0x0B) < 0) return -1;

    // Touch and release thresholds
    if (i2c_write_reg(fd, TOUCHTH, 0xC8) < 0) return -1;
    if (i2c_write_reg(fd, RELEASETH, 0x82) < 0) return -1;

    // Enable all electrodes
    if (i2c_write_reg(fd, ELECONFIG0, 0x0C) < 0) return -1;

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int fd) {
    unsigned char buf[2];
    buf[0] = ELE0;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (ELE0 select) failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return (buf[1] << 8) | buf[0];
}

// LED pattern function
void led_pattern(int pattern) {
    gpioWrite(LED1, (pattern >> 3) & 1);
    gpioWrite(LED2, (pattern >> 2) & 1);
    gpioWrite(LED3, (pattern >> 1) & 1);
    gpioWrite(LED4, pattern & 1);
}

// Log event function
void log_event(int electrode) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buf[64];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: Electrode %d touched\n", buf, electrode);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LED1, PI_OUTPUT);
    gpioSetMode(LED2, PI_OUTPUT);
    gpioSetMode(LED3, PI_OUTPUT);
    gpioSetMode(LED4, PI_OUTPUT);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status < 0) {
            fprintf(stderr, "Failed to read touch status\n");
        } else {
            for (int i = 0; i < 12; i++) {
                if (touch_status & (1 << i)) {
                    // Electrode i is touched
                    led_pattern(current_pattern);
                    log_event(i);
                    current_pattern = LED_PATTERN_0; // Update LED pattern
                    gpioDelay(50); // Debounce delay
                } else {
                    // Electrode i is not touched
                    led_pattern(current_pattern);
                    log_event(0); // Log no electrode touched
                    gpioDelay(50); // Debounce delay
                }
            }
        }
        gpioDelay(50); // Polling interval
    }

    // Cleanup
    gpioWrite(LED1, 0);
    gpioWrite(LED2, 0);
    gpioWrite(LED3, 0);
    gpioWrite(LED4, 0);
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

