    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status < 0) {
            fprintf(stderr, "Failed to read touch status\n");
        } else {
            for (int i = 0; i < 12; i++) {
                if (touch_status & (1 << i)) {
                    // Electrode i is touched
                    led_pattern(current_pattern);
                    log_event(i);
                    current_pattern = LED_PATTERN_0; // Update LED pattern
                    gpioDelay(50); // Debounce delay
                } else {
                    // Electrode i is not touched
                    led_pattern(current_pattern);
                    log_event(0); // Log no electrode touched
                    gpioDelay(50); // Debounce delay
                }
            }
        }
        gpioDelay(50); // Polling interval
    }

    // Cleanup
    gpioWrite(LED1, 0);
    gpioWrite(LED2, 0);
    gpioWrite(LED3, 0);
    gpioWrite(LED4, 0);
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

