    uint8_t debounce; // Debounce Configuration Register
    uint8_t afe_config; // AFE Configuration Register
    uint8_t baseline_filtering; // Baseline Filtering Register
} mpr121_config_t;

// Function to write a byte to an MPR121 register
int mpr121_write_register(int i2c_handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
