        return -1;
    }
    return 0;
}

// Function to read a byte from an MPR121 register
int mpr121_read_register(int i2c_handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the MPR121 sensor
int mpr121_init(int i2c_handle) {
    mpr121_config_t config;

    // Set touch and release thresholds for electrode 0
    if (mpr121_write_register(i2c_handle, 0x41, 0x0A) != 0) return -1; // Touch threshold
    if (mpr121_write_register(i2c_handle, 0x42, 0x05) != 0) return -1; // Release threshold

