#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 30000 // 30ms timeout
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    int ret = gpiod_line_request_output(trigger_line, "hc_sr04", 0); // Initial value 0
    if (ret < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        return -1;
    }

    ret = gpiod_line_request_input(echo_line, "hc_sr04");
    if (ret < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        return -1;
    }

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    int ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        perror("Error setting trigger low");
        return;
    }
    usleep(5); // 5 microseconds

    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        perror("Error setting trigger high");
        return;
    }
    usleep(10); // 10 microseconds

    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        perror("Error setting trigger low");
        return;
    }
}

// Function to measure the echo pulse width with timeout
int measure_pulse_width() {
    struct timespec start, end;
    int pulse_width = -1; // Initialize to -1 to indicate timeout

    // Wait for rising edge with timeout
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            perror("Error getting echo value");
            return -1; // Indicate error
        }
        if (value == 1) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            return -1; // Timeout
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    // Wait for falling edge with timeout
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            perror("Error getting echo value");
            return -1; // Indicate error
        }
        if (value == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            return -1; // Timeout
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000; // in microseconds
    return pulse_width;
}

// Function to calculate distance in centimeters
float calculate_distance(int pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_width * 0.0343) / 2.0;
}

// Function to log the distance to a file
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, distance) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        trigger_sensor();
        int pulse_width = measure_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance >= 0.0 && distance <= 400.0) {
            if (log_distance(distance) < 0) {
                fprintf(stderr, "Error logging distance.\n");
            }
        } else {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            if (log_file != NULL) {
                fprintf(log_file, "ERROR: Distance out of range: %.2f cm\n", distance);
                fflush(log_file);
            }
        }

        usleep(1000000); // 1 second delay
    }

    // Cleanup
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

