        long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            return -1; // Timeout
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000; // in microseconds
    return pulse_width;
}

// Function to calculate distance in centimeters
float calculate_distance(int pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_width * 0.0343) / 2.0;
}

// Function to log the distance to a file
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, distance) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        trigger_sensor();
        int pulse_width = measure_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance >= 0.0 && distance <= 400.0) {
            if (log_distance(distance) < 0) {
                fprintf(stderr, "Error logging distance.\n");
            }
        } else {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            if (log_file != NULL) {
                fprintf(log_file, "ERROR: Distance out of range: %.2f cm\n", distance);
                fflush(log_file);
            }
        }

        usleep(1000000); // 1 second delay
    }

    // Cleanup
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
