#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds

// Global variables
static volatile int pulse_start_tick = 0;
static volatile int pulse_end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(int pulse_width_us);
