// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        pulse_start_tick = tick;
        echo_received = 1; // Indicate that an echo has been received
    } else if (level == 0) {
        pulse_end_tick = tick;
    }
}

