    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR callback\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(100000); // Wait 100ms before next trigger

        // Calculate pulse width
        int pulse_width_us = pulse_end_tick - pulse_start_tick;
        if (pulse_width_us < 0) {
            pulse_width_us += 0xFFFFFFFF; // Handle tick wraparound
        }

        // Validate pulse width
        if (pulse_width_us > 0 && pulse_width_us < 25000) { // 25ms max
            double distance = calculate_distance(pulse_width_us);
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid pulse width: %d us\n", pulse_width_us);
        }

        echo_received = 0; // Reset echo received flag
        pulse_start_tick = 0;
        pulse_end_tick = 0;
    }

    return 0;
}

