// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// GPIO pin for XSHUT
#define VL53L1X_XSHUT_PIN 27

// I2C handle
int i2c_handle;

// Function prototypes
int init_vl53l1x();
int read_distance();
void log_data(int distance, int status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    closelog();
    exit(0);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        syslog(LOG_ERR, "Failed to read model ID: %d", model_id);
        return -1;
    }
    if (model_id != 0xEACC) {
        syslog(LOG_ERR, "Incorrect model ID: 0x%02X", model_id);
        return -1;
    }

    // Configure continuous mode
    if (i2cWriteByteData(i2c_handle, 0x0018, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0018");
        return -1;
    }

    // Configure no timeout
    if (i2cWriteByteData(i2c_handle, 0x0019, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0019");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0040");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    int status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);

    if (distance < 0 || status < 0) {
        syslog(LOG_ERR, "Failed to read distance or status");
        return -1;
    }

    return distance;
}

// Log data to syslog
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s, Distance: %d mm, Status: %d", timestamp, distance, status);
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(VL53L1X_XSHUT_PIN, PI_OUTPUT);
    gpioWrite(VL53L1X_XSHUT_PIN, 1); // Enable sensor

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (1) {
        int distance = read_distance();
        int status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);

        if (distance >= 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance, status: %d", status);
        }

        gpioDelay(100000); // 100 ms
    }

    // Cleanup (should not reach here due to signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return 0;
}

