#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000        // 30 ms timeout
#define MOVING_AVG_SIZE 5
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_SERVO_PULSEWIDTH 500
#define MAX_SERVO_PULSEWIDTH 2500
#define DEFAULT_SERVO_ANGLE 90.0

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;
double pulse_width = 0.0; // Shared variable for pulse width
volatile int pulse_width_valid = 0; // Flag to indicate valid pulse width

// Structure for moving average filter
typedef struct {
    double values[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverageFilter;

// Function prototypes
void signal_handler(int signal);
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(double pulse_width);
double apply_moving_average(double new_value);
double map_distance_to_angle(double distance);
int set_servo_angle(double angle);
int log_data(double distance, double angle);
void init_moving_average_filter(MovingAverageFilter *filter);
double update_moving_average_filter(MovingAverageFilter *filter, double new_value);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;
    static int timeout_flag = 0;

    if (level == 1) {
        start_tick = tick;
        timeout_flag = 0; // Reset timeout flag on rising edge
    } else if (level == 0) {
        end_tick = tick;
        timeout_flag = 0; // Reset timeout flag on falling edge

        if (start_tick != 0 && end_tick != 0) {
            pulse_width = (double)(end_tick - start_tick);
            pulse_width_valid = 1;
        }
    } else {
        // Ignore other levels (e.g., falling edge from trigger)
    }
}

// Function to calculate distance from pulse width
double calculate_distance(double pulse_width) {
    return (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0; // in cm
}

// Function to apply a 5-sample moving average filter
double apply_moving_average(double new_value) {
    static MovingAverageFilter filter;
    init_moving_average_filter(&filter);
    filter.values[filter.index] = new_value;
    filter.index = (filter.index + 1) % MOVING_AVG_SIZE;
    filter.count = (filter.count + 1) % MOVING_AVG_SIZE; // Increment count even if wrap-around

    double sum = 0.0;
    for (int i = 0; i < filter.count; i++) {
        sum += filter.values[i];
    }
    return sum / filter.count;
}

// Function to map distance to servo angle (logarithmic mapping)
double map_distance_to_angle(double distance) {
    double angle = 0.0;
    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        angle = 180.0 * log10((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) / log10(MAX_DISTANCE / MIN_DISTANCE);
    } else {
        angle = DEFAULT_SERVO_ANGLE; // Default to 90 degrees if out of range
    }
    return angle;
}

// Function to set the servo angle
int set_servo_angle(double angle) {
    int pulse_width_us = (int)(angle / 180.0 * (MAX_SERVO_PULSEWIDTH - MIN_SERVO_PULSEWIDTH) + MIN_SERVO_PULSEWIDTH);
    int result = gpioServo(SERVO_PIN, pulse_width_us);
    if (result != 0) {
        fprintf(stderr, "Error setting servo angle: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to log data to a CSV file
int log_data(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
        fflush(log_file); // Flush the buffer to ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Initialize the moving average filter
void init_moving_average_filter(MovingAverageFilter *filter) {
    filter->index = 0;
    filter->count = 0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        filter->values[i] = 0.0;
    }
}

// Update the moving average filter
double update_moving_average_filter(MovingAverageFilter *filter, double new_value) {
    filter->values[filter->index] = new_value;
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;
    filter->count = (filter->count + 1) % MOVING_AVG_SIZE; // Increment count even if wrap-around

    double sum = 0.0;
    for (int i = 0; i < filter->count; i++) {
        sum += filter->values[i];
    }
    return sum / filter->count;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize servo to 90 degrees
    set_servo_angle(DEFAULT_SERVO_ANGLE);

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (program_running) {
        trigger_sensor();
        gpioDelay(100); // Wait 100 ms before next trigger

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Apply moving average filter
        distance = apply_moving_average(distance);

        // Map distance to servo angle
        double angle = map_distance_to_angle(distance);

        // Set servo angle
        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Error setting servo angle, continuing...\n");
        }

        // Log data
        if (log_data(distance, angle) != 0) {
            fprintf(stderr, "Error logging data, continuing...\n");
        }

        // Check for invalid readings
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE || !pulse_width_valid) {
            fprintf(stderr, "Invalid reading, setting servo to 90 degrees and logging -1.0\n");
            set_servo_angle(DEFAULT_SERVO_ANGLE);
            log_data(-1.0, DEFAULT_SERVO_ANGLE);
        }

        pulse_width = 0.0; // Reset pulse width for next reading
        pulse_width_valid = 0; // Reset validity flag
    }

    // Stop servo and close log file
    set_servo_angle(DEFAULT_SERVO_ANGLE); // Set to a safe position
    fclose(log_file);
    gpioTerminate();

    return 0;
}

