#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define PROXIMITY_REG_HIGH 0x08
#define PROXIMITY_REG_LOW 0x09
#define LOG_FILE "proximity.log"

// Global variables
static int i2c_handle;
static int threshold = DEFAULT_THRESHOLD;
static volatile int running = 1;
static int interrupt_flag = 0;
static int interrupt_queue = 0; // Simulate a queue

// Function prototypes
int initialize_i2c(int address);
int read_proximity(int i2c_handle);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int proximity_value, const char *status);
void signal_handler(int signal);
void parse_arguments(int argc, char *argv[]);

// Function to initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return i2c_handle;
}

// Function to read proximity value from Si1102
int read_proximity(int i2c_handle) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, PROXIMITY_REG_HIGH, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
        return -1;
    }

    int proximity = (buf[0] << 8) | buf[1];
    return proximity;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge
        int proximity_value = read_proximity(i2c_handle);
        if (proximity_value < 0) {
            fprintf(stderr, "Error reading proximity in interrupt handler\n");
            return;
        }

        char status[10];
        if (proximity_value <= threshold) {
            strcpy(status, "SAFE");
        } else {
            strcpy(status, "ALERT");
        }

        log_data(proximity_value, status);
        interrupt_queue = proximity_value; // Simulate queueing
        interrupt_flag = 1; // Set flag to indicate interrupt occurred
    }
}

// Function to log data to file
void log_data(int proximity_value, const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %d, %s\n", timestamp, proximity_value, status);
    fclose(fp);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    interrupt_flag = 1; // Signal interrupt to exit loop
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                if (sscanf(optarg, "%x", &threshold) != 1) {
                    fprintf(stderr, "Invalid I2C address format. Using default 0x60\n");
                    threshold = DEFAULT_THRESHOLD;
                } else {
                    printf("Using I2C address: 0x%X\n", (unsigned int)threshold);
                }
                break;
            case 't':
                if (sscanf(optarg, "%d", &threshold) != 1) {
                    fprintf(stderr, "Invalid threshold format. Using default 1000\n");
                    threshold = DEFAULT_THRESHOLD;
                } else {
                    printf("Using threshold: %d\n", threshold);
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(DEFAULT_I2C_ADDRESS) < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure GPIO27 as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (interrupt_flag) {
            // Read and log data
            int proximity_value = read_proximity(i2c_handle);
            if (proximity_value >= 0) {
                char status[10];
                if (proximity_value <= threshold) {
                    strcpy(status, "SAFE");
                } else {
                    strcpy(status, "ALERT");
                }
                log_data(proximity_value, status);
            } else {
                fprintf(stderr, "Error reading proximity in main loop\n");
            }
            interrupt_flag = 0; // Reset flag
        }
        gpioDelay(100); // Delay to avoid busy-waiting
    }

    // Cleanup (should not reach here if signal handler works)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

