#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0    // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define PWM_FREQUENCY 1000    // Hz
#define PWM_RANGE 1000        // Range for PWM duty cycle (0-1000)
#define TIMEOUT_US 200         // Timeout for HC-SR04 in microseconds

// Global variables
static volatile int running = 1;
static int previous_frequency = 0; // Store the previous frequency

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float getDistance();
float mapDistanceToFrequency(float distance);
void setToneFrequency(int gpio, float frequency);
void signalHandler(int signal);

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioTrigger(TRIGGER_PIN, 10, 1); // 10 us trigger pulse
}

// Function to measure the pulse width on the echo pin
long pulseIn(int pin, int level, int timeout) {
    long width = 0;
    long start = gpioTick();
    long now;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        if (gpioTick() - start > timeout) {
            return 0; // Timeout
        }
    }

    start = gpioTick();
    // Wait for the pulse to end
    while (gpioRead(pin) == level) {
        now = gpioTick();
        if (now - start > timeout) {
            return 0; // Timeout
        }
        width++;
    }

    return width;
}

// Function to measure the distance using the HC-SR04 sensor
float getDistance() {
    triggerSensor();
    long pulse = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

    if (pulse == 0) {
        return -1.0; // Indicate timeout or error
    }

    // Calculate the distance in centimeters
    float time = (float)pulse / 1000000.0; // Convert pulse width to seconds
    float distance = (time * SPEED_OF_SOUND) / 2.0;

    return distance;
}

// Function to map the distance to a frequency using a logarithmic formula
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return previous_frequency; // Use the previous frequency if out of range
    }

    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    // Map distance to frequency using logarithmic formula
    float frequency = MIN_FREQUENCY + (float)(distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Function to set the tone frequency on the speaker pin using pigpio's hardware-timed PWM
void setToneFrequency(int gpio, float frequency) {
    // Calculate the PWM duty cycle (50% duty cycle)
    int dutyCycle = PWM_RANGE / 2;

    // Set the PWM frequency and duty cycle
    gpioSetPWMfrequency(gpio, (int)frequency);
    gpioPWM(gpio, dutyCycle);
}

// Signal handler for graceful shutdown
