volatile int echo_start_time = 0; // Store the start time of the echo pulse
volatile int echo_end_time = 0; // Store the end time of the echo pulse

// Function prototypes
void triggerSensor();
float getDistance();
int mapDistanceToFrequency(float distance);
void setBuzzerFrequency(int frequency);
