    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float getDistance() {
    echo_start_time = 0;
    echo_end_time = 0;

    // Wait for echo to start (with timeout)
    int timeout_count = 0;
    while (echo_start_time == 0 && timeout_count < TIMEOUT_THRESHOLD) {
        if (gpioRead(ECHO_PIN) == 1) {
            echo_start_time = gpioTick();
            break;
        }
        gpioDelay(1); // Check every microsecond
        timeout_count++;
    }

    if (echo_start_time == 0) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }

    // Wait for echo to end (with timeout)
    timeout_count = 0;
    while (echo_end_time == 0 && timeout_count < TIMEOUT_THRESHOLD) {
        if (gpioRead(ECHO_PIN) == 0) {
            echo_end_time = gpioTick();
            break;
        }
        gpioDelay(1); // Check every microsecond
        timeout_count++;
    }

    if (echo_end_time == 0) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }

    // Calculate pulse width in microseconds
    unsigned int pulse_width = echo_end_time - echo_start_time;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (pulse_width / 1000000.0) * 34300.0 / 2.0;

    return distance;
}

// Function to map distance to frequency
int mapDistanceToFrequency(float distance) {
    if (distance < 5.0) {
        return MIN_FREQ;
    } else if (distance > 50.0) {
        return MAX_FREQ;
    } else {
        return MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (distance - 5.0) / (50.0 - 5.0);
    }
}

