    printf("Caught signal %d, cleaning up...\n", signal);
    setBuzzerFrequency(0); // Stop the PWM output
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistors on the echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set PWM range for buzzer pin
    gpioSetPWMrange(BUZZER_PIN, 1000000); // 1 MHz range

    // Set PWM frequency (initial value)
    setBuzzerFrequency(500); // Start with a frequency of 500 Hz

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Main loop
    while (1) {
        float distance = getDistance();

        if (distance > 0) {
            // Update last valid distance
            last_valid_distance = distance;

            // Map distance to frequency
            int frequency = mapDistanceToFrequency(last_valid_distance);

            // Set buzzer frequency
            setBuzzerFrequency(frequency);

            // Print distance and frequency
            printf("Distance: %.2f cm, Frequency: %d Hz\n", last_valid_distance, frequency);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    return 0;
}

