#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000 // 50ms timeout

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // Wait 1ms

    signal(SIGINT, signal_handler);

    while (!terminate) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        // Measure the echo pulse width
        uint32_t start_tick = 0, end_tick = 0;
        int timeout = 0;

        // Wait for echo to go high
        while (gpioRead(ECHO_PIN) == 0 && !timeout) {
            start_tick = gpioTick();
            timeout = 1;
        }

        if (timeout) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            continue; // Skip to the next iteration
        }

        // Wait for echo to go low
        timeout = 0;
        while (gpioRead(ECHO_PIN) == 1 && !timeout) {
            end_tick = gpioTick();
            timeout = 1;
        }

        if (timeout) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            continue; // Skip to the next iteration
        }

        // Calculate the pulse width in microseconds
        uint32_t pulse_width = end_tick - start_tick;

        // Calculate distance in centimeters
        float distance = (float)pulse_width / 2.0 / 29.1;

        // Validate the distance
        if (distance < 2.0 || distance > 400.0) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);

            // Check if the distance is too close
            if (distance < 10.0) {
                printf("Too close!\n");
            }
        }
    }

    // Clean up and terminate
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

