#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define MEASURE_REG 0x01
#define RANGE_REG 0x02
#define DISTANCE_REG_LOW 0x0C
#define DISTANCE_REG_HIGH 0x0D

// Define sensor configuration values
#define MEASURE_MODE 0x01
#define RANGE_5MM 0x00

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
int log_distance(int distance);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int cs_pin;
    int measure_mode;
    int range;
} sensor_config_t;

// Function to initialize the sensor
int initialize_sensor() {
    int status;

    // Write measurement mode to register 0x01
    status = spiWrite(spi_handle, MEASURE_REG, MEASURE_MODE);
    if (status != 0) {
        fprintf(stderr, "Error writing to register 0x01: %d\n", status);
        return -1;
    }

    // Write range to register 0x02
    status = spiWrite(spi_handle, RANGE_REG, RANGE_5MM);
    if (status != 0) {
        fprintf(stderr, "Error writing to register 0x02: %d\n", status);
        return -1;
    }

    // Trigger measurement by writing 0x01 to register 0x00
    status = spiWrite(spi_handle, 0x00, 0x01);
    if (status != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read distance from the sensor
int read_distance(int *distance) {
    char tx_buf[1];
    char rx_buf[2];
    int status;

    // Read low byte of distance
    tx_buf[0] = DISTANCE_REG_LOW;
    status = spiXfer(spi_handle, tx_buf, rx_buf, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading low byte: %d\n", status);
        return -1;
    }
    *distance = rx_buf[0];

    // Read high byte of distance
    tx_buf[0] = DISTANCE_REG_HIGH;
    status = spiXfer(spi_handle, tx_buf, rx_buf, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading high byte: %d\n", status);
        return -1;
    }
    *distance = (*distance << 8) | rx_buf[0];

    return 0;
}

// Function to log distance to a file
int log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

