#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x60
#define ALS_REG_LOW 0x22
#define ALS_REG_HIGH 0x23
#define ALS_REG_COMMAND 0x30
#define ALS_MEAS_RATE 0x08
#define ALS_IT_100MS 0x00

// Global variables for signal handling
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t stop_flag = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    stop_flag = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the Si1175 sensor
int init_si1175(int fd) {
    uint8_t buf[2];

    // Reset the device (optional, but good practice)
    buf[0] = ALS_REG_COMMAND;
    buf[1] = 0x01; // Reset command
    if (write(fd, buf, 2) != 2) {
        perror("Failed to reset Si1175");
        return -1;
    }
    usleep(10000); // Wait for reset to complete

    // Configure ALS measurement rate and integration time
    buf[0] = ALS_REG_COMMAND;
    buf[1] = ALS_MEAS_RATE | 0x80; // Enable measurement rate
    if (write(fd, buf, 2) != 2) {
        perror("Failed to set ALS measurement rate");
        return -1;
    }

    buf[0] = ALS_REG_COMMAND;
    buf[1] = ALS_IT_100MS | 0x80; // Enable integration time
    if (write(fd, buf, 2) != 2) {
        perror("Failed to set ALS integration time");
        return -1;
    }

    return 0;
}

// Function to read the visible ambient light value from the Si1175
int read_als(int fd, uint16_t *als_value) {
    uint8_t buf[1];
    uint8_t data[2];

    // Read the low byte
    buf[0] = ALS_REG_LOW;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read low byte from I2C device");
        return -1;
    }
    uint16_t low_byte = (uint16_t)data[0];

    // Read the high byte
    buf[0] = ALS_REG_HIGH;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read high byte from I2C device");
        return -1;
    }
    uint16_t high_byte = (uint16_t)data[0];

    *als_value = (high_byte << 8) | low_byte;

    return 0;
}

// Function to log the timestamp and ALS value to a CSV file
int log_data(FILE *fp, uint16_t als_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (fprintf(fp, "%s,%u\n", timestamp, als_value) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    uint16_t als_value;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize the Si1175 sensor
    if (init_si1175(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize Si1175 sensor.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open the log file in append mode
    log_file = fopen("proximity_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    rewind(log_file);

    // Main loop
    while (!stop_flag) {
        // Read the visible ambient light value
        if (read_als(i2c_fd, &als_value) == 0) {
            // Log the data to the CSV file
            if (log_data(log_file, als_value) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read ALS value.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up resources before exiting
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

