#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_PS1_DATA0 0x18

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int si1120_init();
int si1120_read_als();
int si1120_read_proximity();
int si1120_read_part_id(uint8_t *part_id);
int si1120_write_register(uint8_t reg, uint8_t value);
void log_data(int als_value, int proximity_value);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int als_value;
    int proximity_value;
} sensor_data_t;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1120 sensor
    if (si1120_init() != 0) {
        fprintf(stderr, "Si1120 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        int als_value = si1120_read_als();
        int proximity_value = si1120_read_proximity();

        // Log data
        log_data(als_value, proximity_value);

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    return 0;
}

// Initialize Si1120 sensor
int si1120_init() {
    // Reset the sensor
    if (si1120_write_register(0x30, 0x01) != 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms

    // Verify Part ID
    uint8_t part_id;
    if (si1120_read_part_id(&part_id) != 0) {
        fprintf(stderr, "Failed to read Si1120 Part ID\n");
        return -1;
    }

    if (part_id != 0x41) {
        fprintf(stderr, "Incorrect Si1120 Part ID: 0x%02X (expected 0x41)\n", part_id);
        return -1;
    }

    // Add more initialization steps here if needed
    return 0;
}

// Read ALS data from Si1120
int si1120_read_als() {
    int retries = 3;
    int als_low, als_high;

    while (retries > 0) {
        als_low = i2cReadByteData(i2c_handle, SI1120_REG_ALS_VIS_DATA0);
        if (als_low >= 0) {
            als_high = i2cReadByteData(i2c_handle, SI1120_REG_ALS_VIS_DATA0 + 1);
            if (als_high >= 0) {
                return (als_high << 8) | als_low; // Combine high and low bytes
            } else {
                fprintf(stderr, "Failed to read ALS high byte, retrying...\n");
                gpioDelay(10000); // 10 ms delay
                retries--;
            }
        } else {
            fprintf(stderr, "Failed to read ALS low byte, retrying...\n");
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read ALS data after multiple retries\n");
    return -1; // Indicate failure
}

// Read proximity data from Si1120
int si1120_read_proximity() {
    int retries = 3;
    int proximity_low, proximity_high;

    while (retries > 0) {
        proximity_low = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0);
        if (proximity_low >= 0) {
            proximity_high = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0 + 1);
            if (proximity_high >= 0) {
                return (proximity_high << 8) | proximity_low; // Combine high and low bytes
            } else {
                fprintf(stderr, "Failed to read proximity high byte, retrying...\n");
                gpioDelay(10000); // 10 ms delay
                retries--;
            }
        } else {
            fprintf(stderr, "Failed to read proximity low byte, retrying...\n");
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read proximity data after multiple retries\n");
    return -1; // Indicate failure
}

// Read Part ID from Si1120
int si1120_read_part_id(uint8_t *part_id) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (result >= 0) {
            *part_id = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read Part ID, retrying...\n");
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read Part ID after multiple retries\n");
    return -1; // Indicate failure
}

// Write to Si1120 register
int si1120_write_register(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Failed to write to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Log data to file
void log_data(int als_value, int proximity_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %d, Proximity: %d\n", timestamp, als_value, proximity_value);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

