    int retries = 3;
    int als_low, als_high;

    while (retries > 0) {
        als_low = i2cReadByteData(i2c_handle, SI1120_REG_ALS_VIS_DATA0);
        if (als_low >= 0) {
            als_high = i2cReadByteData(i2c_handle, SI1120_REG_ALS_VIS_DATA0 + 1);
            if (als_high >= 0) {
                return (als_high << 8) | als_low; // Combine high and low bytes
            } else {
                fprintf(stderr, "Failed to read ALS high byte, retrying...\n");
                gpioDelay(10000); // 10 ms delay
                retries--;
            }
        } else {
            fprintf(stderr, "Failed to read ALS low byte, retrying...\n");
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read ALS data after multiple retries\n");
    return -1; // Indicate failure
}

// Read proximity data from Si1120
int si1120_read_proximity() {
    int retries = 3;
    int proximity_low, proximity_high;

    while (retries > 0) {
        proximity_low = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0);
        if (proximity_low >= 0) {
            proximity_high = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0 + 1);
            if (proximity_high >= 0) {
                return (proximity_high << 8) | proximity_low; // Combine high and low bytes
            } else {
                fprintf(stderr, "Failed to read proximity high byte, retrying...\n");
                gpioDelay(10000); // 10 ms delay
                retries--;
            }
        } else {
            fprintf(stderr, "Failed to read proximity low byte, retrying...\n");
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read proximity data after multiple retries\n");
    return -1; // Indicate failure
}

// Read Part ID from Si1120
int si1120_read_part_id(uint8_t *part_id) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (result >= 0) {
            *part_id = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read Part ID, retrying...\n");
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read Part ID after multiple retries\n");
    return -1; // Indicate failure
}

// Write to Si1120 register
int si1120_write_register(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Failed to write to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Log data to file
void log_data(int als_value, int proximity_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %d, Proximity: %d\n", timestamp, als_value, proximity_value);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

