#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define AMBIENT_REG 0x22
#define PROX_REG 0x24
#define LUX_SCALE 0.1

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two registers
int i2c_read_16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    *value = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to initialize the Si1182 sensor
int init_si1182(int fd) {
    uint8_t part_id;
    if (i2c_read_reg(fd, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Failed to read Part ID\n");
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    if (i2c_write_reg(fd, MEAS_RATE_REG, 0x07) != 0) {
        fprintf(stderr, "Failed to set measurement rate\n");
        return -1;
    }

    return 0;
}

// Function to read ambient light data
float read_ambient_light(int fd) {
    uint16_t raw_ambient;
    if (i2c_read_16(fd, AMBIENT_REG, &raw_ambient) != 0) {
        fprintf(stderr, "Failed to read ambient light data\n");
        return -1.0;
    }
    return (float)raw_ambient * LUX_SCALE;
}

// Function to read proximity data
uint16_t read_proximity(int fd) {
    uint16_t raw_proximity;
    if (i2c_read_16(fd, PROX_REG, &raw_proximity) != 0) {
        fprintf(stderr, "Failed to read proximity data\n");
        return 0;
    }
    return raw_proximity;
}

// Function to log data to a file
int log_data(FILE *fp, float lux, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03d", &tm);

    if (fprintf(fp, "%s,%.2f,%u\n", timestamp, lux, proximity) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_si1182(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize Si1182 sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        float lux = read_ambient_light(i2c_fd);
        uint16_t proximity = read_proximity(i2c_fd);

        if (lux >= 0.0 && proximity != 0) {
            if (log_data(log_file, lux, proximity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            printf("Lux: %.2f, Proximity: %u\n", lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100000); // 100 ms
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

