#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x60
#define PROXIMITY_REG 0x16
#define LOG_FILE "proximity_log.txt"

int i2c_handle;

// Function to write a byte to a specific register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a specific register
int read_register(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to initialize the Si1145 sensor
int initialize_sensor(int handle) {
    if (write_register(handle, 0x07, 0x03) != 0) return -1;
    if (write_register(handle, 0x06, 0x02) != 0) return -1;
    if (write_register(handle, 0x1A, 0x00) != 0) return -1;
    if (write_register(handle, 0x21, 0x0B) != 0) return -1;
    if (write_register(handle, 0x24, 0x00) != 0) return -1;
    if (write_register(handle, 0x22, 0x49) != 0) return -1;
    if (write_register(handle, 0x0C, 0x03) != 0) return -1;
    if (write_register(handle, 0x0F, 0x0F) != 0) return -1;
    if (write_register(handle, 0x11, 0x03) != 0) return -1;
    if (write_register(handle, 0x80, 0x03) != 0) return -1;

    return 0;
}

// Function to read proximity data from the sensor
int read_proximity(int handle) {
    int low_byte = read_register(handle, PROXIMITY_REG);
    int high_byte = read_register(handle, PROXIMITY_REG + 1);

    if (low_byte < 0 || high_byte < 0) {
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

// Function to log data to a file
void log_data(int proximity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %d\n", timestamp, proximity);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int proximity = read_proximity(i2c_handle);
        if (proximity >= 0) {
            log_data(proximity);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

