#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 20000        // Timeout for echo pulse in microseconds
#define MIN_DISTANCE 20.0       // Minimum measurable distance in cm
#define MAX_DISTANCE 200.0      // Maximum measurable distance in cm

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
float measureDistance();
void setServoAngle(float distance);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Cleaning up and exiting.\n");
        program_running = 0;
        gpioServo(SERVO_PIN, 0); // Stop the servo
        gpioTerminate();         // Terminate pigpio
        exit(0);
    }
}

// Function to measure distance using HC-SR04
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0; // Timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, then divide by 2 for one-way distance

    return distance;
}

// Function to set servo angle based on distance
void setServoAngle(float distance) {
    // Map distance to pulse width (us)
    float pulse_width;

    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        pulse_width = 1500.0 + (distance - MIN_DISTANCE) * (1500.0 - 500.0) / (MAX_DISTANCE - MIN_DISTANCE);
    } else {
        // Handle out-of-range distances (e.g., set to 0 or 180 degrees)
        if (distance < MIN_DISTANCE) {
            pulse_width = 2500.0; // 180 degrees
        } else {
            pulse_width = 500.0;  // 0 degrees
        }
    }

    // Set servo pulse width
    gpioServo(SERVO_PIN, (int)pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measureDistance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            setServoAngle(distance);
        } else {
            fprintf(stderr, "Error measuring distance.\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio

    return 0;
}

