#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define OPEN_PULSE 2000
#define CLOSE_PULSE 1000
#define DISTANCE_THRESHOLD_OPEN 200
#define DISTANCE_THRESHOLD_CLOSE 250
#define HISTORICAL_WINDOW 5
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void set_servo_pulse(int gpio, int pulse_width);
void open_gate(int gpio);
void close_gate(int gpio);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0010
#define VL53L1X_REG_INTERMEASUREMENT_PERIOD 0x008A
#define VL53L1X_REG_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to initialize the VL53L1X sensor
int vl53l1x_init(int i2c_handle) {
    // Example initialization sequence (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) { // Continuous mode
        fprintf(stderr, "Error: Could not set ranging mode.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_INTERMEASUREMENT_PERIOD, 0x10) < 0) { // 10ms inter-measurement period
        fprintf(stderr, "Error: Could not set inter-measurement period.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP, 0x01) < 0) { // Start ranging
        fprintf(stderr, "Error: Could not start ranging.\n");
        return -1;
    }

    // Verify model ID
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error: Could not read model ID.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    printf("VL53L1X sensor initialized successfully.\n");
    return 0;
}

// Function to read distance from the VL53L1X sensor
int vl53l1x_read_distance(int i2c_handle) {
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error: Could not read distance.\n");
        return -1;
    }
    return distance;
}

// Function to set the servo pulse width
void set_servo_pulse(int gpio, int pulse_width) {
    gpioServo(gpio, pulse_width);
}

// Function to open the gate
void open_gate(int gpio) {
    set_servo_pulse(gpio, OPEN_PULSE);
    log_event("Gate opened");
}

// Function to close the gate
void close_gate(int gpio) {
    set_servo_pulse(gpio, CLOSE_PULSE);
    log_event("Gate closed");
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int distance = -1; // Initialize to an invalid value
    int gate_open = 0; // Flag to track gate state
    while (!terminate) {
        distance = vl53l1x_read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error: Failed to read distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Hysteresis control
        if (distance < DISTANCE_THRESHOLD_OPEN && !gate_open) {
            open_gate(SERVO_PIN);
            gate_open = 1;
        } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_open) {
            close_gate(SERVO_PIN);
            gate_open = 0;
        }

        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    // Cleanup
    set_servo_pulse(SERVO_PIN, 0); // Stop the servo
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

