#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50 ms timeout

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int timeout_flag = 0;

// Function prototypes
void triggerSensor();
float getDistance();
int mapDistanceToAngle(float distance);
void setServoAngle(int angle);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float getDistance() {
    pulse_start = 0;
    pulse_end = 0;
    timeout_flag = 0;

    // Wait for the echo pin to go high (rising edge)
    int start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            timeout_flag = 1;
            return -1.0;
        }
    }
    start_time = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            timeout_flag = 1;
            return -1.0;
        }
    }
    end_time = gpioTick();

    if (timeout_flag) {
        return -1.0;
    }

    pulse_end = end_time;

    // Calculate the pulse duration in microseconds
    int pulse_duration = pulse_end - pulse_start;

    // Calculate the distance in centimeters
    float distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, then divide by 2 for one-way distance

    return distance;
}

// Function to map the distance to an angle for the servo
int mapDistanceToAngle(float distance) {
    if (distance < 20.0) {
        return 0;
    } else if (distance > 200.0) {
        return 180;
    } else {
        return (int)((distance - 20.0) / (200.0 - 20.0) * 180.0);
    }
}

// Function to set the servo angle
void setServoAngle(int angle) {
    // Map angle (0-180) to pulse width (500-2500 us)
    int pulse_width = 500 + (int)((float)angle / 180.0 * (2500.0 - 500.0));
    gpioServo(SERVO_PIN, pulse_width);
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Trigger the sensor
        triggerSensor();

        // Get the distance
        float distance = getDistance();

        // Map the distance to an angle
        int angle = mapDistanceToAngle(distance);

        // Set the servo angle
        setServoAngle(angle);

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);

        // Delay for 100 ms
        gpioDelay(100);
    }

    return 0;
}

