#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Si7005 I2C address
#define SI7005_ADDR 0x40

// Si7005 Registers
#define SI7005_TEMP_REG 0x00
#define SI7005_HUMID_REG 0x02
#define SI7005_CONFIG_REG 0x03

// Configuration value to select internal temperature sensor and disable heater
#define SI7005_CONFIG_VALUE 0x00

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the Si7005 sensor
int initialize_si7005() {
    // Write to the configuration register
    if (i2cWriteByteData(i2c_handle, SI7005_CONFIG_REG, SI7005_CONFIG_VALUE) != 0) {
        fprintf(stderr, "Error writing to configuration register!\n");
        return -1;
    }

    // Small delay after writing to the configuration register
    gpioDelay(10); // 10 ms delay

    return 0;
}

// Function to read temperature and humidity from the Si7005
int read_si7005(float *temperature, float *humidity) {
    unsigned char raw_temperature, raw_humidity;

    // Read temperature register
    if (i2cReadI2CBlockData(i2c_handle, SI7005_TEMP_REG, (char *)&raw_temperature, 1) != 1) {
        fprintf(stderr, "Error reading temperature register!\n");
        return -1;
    }

    // Read humidity register
    if (i2cReadI2CBlockData(i2c_handle, SI7005_HUMID_REG, (char *)&raw_humidity, 1) != 1) {
        fprintf(stderr, "Error reading humidity register!\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    *temperature = (175.72 * raw_temperature) / 65536.0 - 46.85;
    *humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed!\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the Si7005 sensor
    if (initialize_si7005() != 0) {
        fprintf(stderr, "Si7005 initialization failed!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (1) {
        // Read temperature and humidity
        if (read_si7005(&temperature, &humidity) == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data!\n");
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

