#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define TEMP_OUT_H 0x41
#define TEMP_OUT_L 0x42
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig)
{
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050()
{
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to stabilize

    // Configure accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range to ±250 deg/s
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    // Set sample rate divider to 7 for 125 Hz output
    if (i2cWriteByteData(i2c_handle, 0x19, 7) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    return 0;
}

// Function to read raw sensor data
int read_sensor_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *temp, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    char buf[14];
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) < 0) {
        fprintf(stderr, "Error: Could not read sensor data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *temp = (int16_t)((buf[6] << 8) | buf[7]);
    *gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, 0x75);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: MPU-6050 not found (WHO_AM_I = 0x%x)\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Print startup message
    printf("MPU-6050 data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    int16_t accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        if (read_sensor_data(&accel_x, &accel_y, &accel_z, &temp, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print sensor data
            printf("Accel: %6d %6d %6d  Temp: %6d  Gyro: %6d %6d %6d\n",
                   accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    printf("Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

