#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// I2C bus
#define I2C_BUS 1

// Measurement command for high repeatability
#define MEASURE_CMD 0xFD

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read temperature and humidity from SHT40
int read_sht40(float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0); // Command is a single byte
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10); // pigpio's delay function

    // Read 6 bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    // Extract raw temperature and humidity values
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    // CRC validation
    uint8_t temp_crc = data[2];
    uint8_t hum_crc = data[5];

    if (crc8(data, 2) != temp_crc) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    if (crc8(data + 3, 2) != hum_crc) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = -6.0 + 125.0 * (float)raw_humidity / 65535.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (read_sht40(&temperature, &humidity) == 0) {
            // Print temperature and humidity to console
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

