#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

int i2c_handle;
FILE *log_file = NULL;
FILE *error_log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float temperature;
    time_t timestamp;
} SensorData;

// Function prototypes
int initialize();
int read_temperature(float *temperature);
int log_temperature(float temperature);
int handle_error(const char *message);
void signal_handler(int signal);
void cleanup();

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler); // Register signal handler for Ctrl+C

    while (1) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            handle_error("Failed to read temperature.");
        }
        sleep(5);
    }

    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_temperature(float *temperature) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        handle_error("Failed to write measurement command.");
        return 1;
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 15ms for continuous mode)

    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        handle_error("Failed to read temperature data.");
        return 1;
    }

    // Convert raw data to temperature (Celsius)
    int raw_temperature = (buffer[0] << 8) | buffer[1];
    *temperature = -45.0 + (175.0 * raw_temperature / 65535.0);

    return 0;
}

int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int handle_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_file, "%s, %s\n", timestamp, message);
    fflush(error_log_file);
    fprintf(stderr, "%s, %s\n", timestamp, message); // Also print to stderr
    return 1;
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

