#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define LOG_FILE "sht40_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define MEASUREMENT_DELAY_MS 10

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SHT40 sensor
int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t data[6];
    int retries = RETRY_COUNT;
    int bytes_read;

    while (retries > 0) {
        // Send measurement command
        if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
            perror("Error: Could not set I2C slave address");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        uint8_t cmd[1] = {MEASURE_CMD};
        if (write(fd, cmd, 1) != 1) {
            perror("Error: Could not write to I2C device");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete
        usleep(MEASUREMENT_DELAY_MS * 1000);

        // Read 6 bytes of data
        bytes_read = read(fd, data, 6);
        if (bytes_read != 6) {
            perror("Error: Could not read from I2C device");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // CRC validation
        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "Error: CRC validation failed\n");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // Convert data to temperature and humidity
        int raw_temperature = (data[0] << 8) | data[1];
        int raw_humidity = (data[3] << 8) | data[4];

        *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
        *humidity = 100.0 * (float)raw_humidity / 65535.0;

        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to read SHT40 after multiple retries\n");
    return -1; // Failure
}

// Function to log data to a file
int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error: Could not open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

int main() {
    int fd;
    float temperature, humidity;

    // Register signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C device
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error: Could not open I2C device");
        return 1;
    }

    // Main loop
    while (!stop) {
        // Read sensor data
        if (read_sht40(fd, &temperature, &humidity) == 0) {
            // Log data
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device and log file
    close(fd);
    printf("Program terminated gracefully.\n");

    return 0;
}

