#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define TRIGGER_COMMAND 0x21 0x96
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define BACKOFF_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int trigger_measurement(int i2c_handle);
int read_sensor_data(int i2c_handle, uint8_t *data);
sensor_data_t convert_data(const uint8_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
int safe_i2c_write(int handle, const char *buf, int count);
int safe_i2c_read(int handle, char *buf, int count);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Safe I2C write with retry and exponential backoff
int safe_i2c_write(int handle, const char *buf, int count) {
    int retries = 0;
    int delay_ms = BACKOFF_DELAY_MS;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(handle, buf, count);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries++;
        }
    }
    fprintf(stderr, "I2C write failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Safe I2C read with retry and exponential backoff
int safe_i2c_read(int handle, char *buf, int count) {
    int retries = 0;
    int delay_ms = BACKOFF_DELAY_MS;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Trigger measurement
int trigger_measurement(int i2c_handle) {
    char buf[2] = {TRIGGER_COMMAND[0], TRIGGER_COMMAND[1]};
    return safe_i2c_write(i2c_handle, buf, 2);
}

// Read sensor data
int read_sensor_data(int i2c_handle, uint8_t *data) {
    char buf[2];
    if (safe_i2c_read(i2c_handle, buf, 2) != 0) {
        return -1; // I2C read failed
    }

    data[0] = buf[0];
    data[1] = buf[1];

    return 0;
}

// Convert raw data to physical units
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[2] << 8) | data[3];

    sensor_data.pressure_pa = (float)raw_pressure / 60.0;
    sensor_data.temperature_c = (float)raw_temperature / 200.0;

    return sensor_data;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->pressure_pa, data->temperature_c);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t sensor_data[6];
    sensor_data_t converted_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_handle) != 0) {
