#define TRIGGER_COMMAND 0x21 0x96
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define BACKOFF_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

