    uint8_t buf[2];
    int result;
    int retries = RETRY_COUNT;
    int delay_ms = RETRY_DELAY_MS;

    // Read temperature
    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, TEMP_CMD);
        if (result != 0) {
            fprintf(stderr, "Failed to write temperature command: %s\n", strerror(errno));
            gpioDelay(delay_ms);
