int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len, CRC_POLYNOMIAL);
    if (calculated_crc != crc) {
        log_error("CRC check failed.");
        return -1;
    }
    return 0;
}

