        gpioDelay(20); // Wait 20 ms

        // Read data
        uint8_t data[3];
        if (read_data(i2c_handle, data, 3) != 0) {
            log_error("Failed to read sensor data.");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Validate CRC
        if (validate_crc(data, 2, data[2]) != 0) {
            log_error("CRC check failed.");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Convert raw temperature
        uint16_t raw_temperature = (data[0] << 8) | data[1];
