#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define SCALE_PRESSURE 240.0
#define SCALE_TEMPERATURE 200.0
#define OFFSET_TEMPERATURE -45.0
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables for signal handling
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t stop_flag = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int fd, float *pressure, float *temperature) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, cmd, 2) != 2) {
            perror("Failed to write measurement command");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        usleep(10000); // Wait 10ms for measurement

        if (read(fd, data, 6) != 6) {
            perror("Failed to read data");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // CRC validation
        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC validation failed\n");
            return -1; // CRC error
        }

        // Conversion
        int16_t raw_pressure = (data[0] << 8) | data[1];
        int16_t raw_temperature = (data[3] << 8) | data[4];

        *pressure = (float)raw_pressure / SCALE_PRESSURE;
        *temperature = ((float)raw_temperature / SCALE_TEMPERATURE) + OFFSET_TEMPERATURE;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor after multiple retries\n");
    return -1; // Failed after retries
}

// Function to log data to a file
int log_data(const char *filename, float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, exiting...\n");
        stop_flag = 1;
    }
}

int main() {
    int fd;
    float pressure, temperature;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    printf("SDP800-500Pa sensor reader started. Press Ctrl+C to exit.\n");

    while (!stop_flag) {
        if (read_sdp800(fd, &pressure, &temperature) == 0) {
            if (log_data("airflow_data.txt", pressure, temperature) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup
    close(fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

