#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor readings
typedef struct {
    float temperature;
    float humidity;
    time_t timestamp;
} sensor_reading_t;

// Circular buffer
sensor_reading_t sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
void control_fan(float temperature);
void log_reading(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the sensor
int read_sensor_data(float *temperature, float *humidity) {
    uint8_t cmd[1];
    uint8_t data[2];
    int result;

    // Read temperature
    cmd[0] = 0xE3; // Hold master measurement command for temperature
    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms

    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    uint16_t raw_temp = (data[0] << 8) | data[1];
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    // Read humidity
    cmd[0] = 0xE5; // Hold master measurement command for humidity
    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms

    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    uint16_t raw_humidity = (data[0] << 8) | data[1];
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Function to log sensor readings to the circular buffer
void log_reading(float temperature, float humidity) {
    time(&sensor_buffer[buffer_index].timestamp);
    sensor_buffer[buffer_index].temperature = temperature;
    sensor_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("Timestamp,Temperature,Humidity\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t timestamp = sensor_buffer[i].timestamp;
        struct tm *timeinfo = localtime(&timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s,%.2f,%.2f\n", timestamp_str, sensor_buffer[i].temperature, sensor_buffer[i].humidity);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int retry;

    printf("Starting temperature monitoring...\n");

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sensor_data(&temperature, &humidity) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Sensor read failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(100); // Wait 100 ms before retrying
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries. Sensor may be absent.\n", RETRY_COUNT);
            // Optionally, you could add code here to attempt to re-initialize I2C or handle the sensor absence.
            // For this example, we'll just continue and potentially log the error.
        } else {
            control_fan(temperature);
            log_reading(temperature, humidity);
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    cleanup();
    return 0;
}

