// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    // Stop periodic measurement
    if (i2cWriteWordData(i2c_handle, STOP_PERIODIC_MEASUREMENT, 0) != 0) {
        fprintf(stderr, "Error stopping periodic measurement.\n");
    }
    // Close I2C handle
    i2cClose(i2c_handle);
    // Terminate pigpio
    gpioTerminate();
    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the SCD40 sensor
int initialize_scd40() {
    // Start periodic measurement
    if (i2cWriteWordData(i2c_handle, START_PERIODIC_MEASUREMENT, 0) != 0) {
        fprintf(stderr, "Error starting periodic measurement.\n");
        return -1;
    }
    gpioDelay(100000); // Wait 100ms
    return 0;
}

// Function to read data from the SCD40 sensor
int read_scd40_data(uint8_t *data) {
    if (i2cWriteWordData(i2c_handle, READ_MEASUREMENT, 0) != 0) {
        fprintf(stderr, "Error requesting measurement data.\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

