#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define GPIO_LED 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL 5 // seconds

// SCD40 Commands
#define START_PERIODIC_MEASUREMENT 0x21B1
#define GET_DATA_READY_STATUS 0xE4B8
#define READ_MEASUREMENT 0xEC05
#define STOP_PERIODIC_MEASUREMENT 0x3F86

// Data structure for sensor readings
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int start_periodic_measurement();
int get_data_ready_status(uint16_t *ready);
int read_measurement(uint8_t *data);
int validate_crc(uint8_t data[], int len);
int stop_periodic_measurement();
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
void print_buffer(circular_buffer_t *buffer);
void control_led(float co2);
void signal_handler(int signal);
void cleanup();

// Function to initialize the circular buffer
void init_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Function to initialize the program
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Initially turn off the LED

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    init_buffer(&buffer);

    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return 1;
    }
    return 0;
}

// Function to get data ready status
int get_data_ready_status(uint16_t *ready) {
    char buf[2];
    buf[0] = (GET_DATA_READY_STATUS >> 8) & 0xFF;
    buf[1] = GET_DATA_READY_STATUS & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to get data ready status command: %d\n", result);
        return 1;
    }

    result = i2cReadDevice(i2c_handle, (char*)ready, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading data ready status: %d\n", result);
        return 1;
    }

    *ready = (uint16_t)result;
    return 0;
}

// Function to read measurement data
int read_measurement(uint8_t *data) {
    char buf[2];
    buf[0] = (READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to read measurement command: %d\n", result);
        return 1;
    }

    result = i2cReadDevice(i2c_handle, (char*)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading measurement data: %d\n", result);
        return 1;
    }

    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }

    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC check failed!\n");
        return 1;
    }

    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error stopping periodic measurement: %d\n", result);
        return 1;
    }
    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer(circular_buffer_t *buffer) {
    printf("CO2 (ppm), Temperature (C), Humidity (%%)\n");
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%6.2f, %6.2f, %6.2f\n", buffer->data[index].co2, buffer->data[index].temperature, buffer->data[index].humidity);
    }
}

// Function to control the LED based on CO2 level
void control_led(float co2) {
    if (co2 > CO2_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn on LED
    } else {
        gpioWrite(GPIO_LED, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    stop_periodic_measurement();
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    uint16_t data_ready;
    uint8_t measurement_data[9];
    sensor_data_t sensor_data;
    int retry_count = 0;
    const int max_retries = 3;

    while (!terminate) {
        if (get_data_ready_status(&data_ready) == 0 && data_ready & 0x01) {
            if (read_measurement(measurement_data) == 0) {
                // Validate CRC for each word
                if (validate_crc(measurement_data, 2) && validate_crc(measurement_data + 2, 2) && validate_crc(measurement_data + 4, 2)) {
                    // Extract data
                    uint16_t co2_raw = (measurement_data[0] << 8) | measurement_data[1];
                    uint16_t temperature_raw = (measurement_data[2] << 8) | measurement_data[3];
                    uint16_t humidity_raw = (measurement_data[4] << 8) | measurement_data[5];

                    // Convert data (refer to SCD40 datasheet)
                    sensor_data.co2 = (float)co2_raw;
                    sensor_data.temperature = -45 + 175 * ((float)temperature_raw / 65535.0);
                    sensor_data.humidity = 100 * ((float)humidity_raw / 65535.0);

                    // Add data to the circular buffer
                    add_to_buffer(&buffer, sensor_data);

                    // Print the data
                    printf("CO2: %.2f ppm, Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.co2, sensor_data.temperature, sensor_data.humidity);

                    // Control the LED
                    control_led(sensor_data.co2);

                    retry_count = 0; // Reset retry count on success
                } else {
                    fprintf(stderr, "CRC validation failed, retrying...\n");
                    retry_count++;
                    if (retry_count > max_retries) {
                        fprintf(stderr, "Too many CRC failures, exiting.\n");
                        terminate = 1;
                        break;
                    }
                    continue; // Retry the measurement read
                }
            } else {
                fprintf(stderr, "Failed to read measurement, retrying...\n");
                retry_count++;
                if (retry_count > max_retries) {
                    fprintf(stderr, "Too many measurement read failures, exiting.\n");
                    terminate = 1;
                    break;
                }
                continue; // Retry the measurement read
            }
        } else {
            fprintf(stderr, "Data not ready, waiting...\n");
            gpioDelay(100); // Wait 100ms
        }
    }

    print_buffer(&buffer);
    cleanup();
    return 0;
}

