        gpioDelay(1);
    }

    if (edge_count >= TIMEOUT_US) {
        return 0; // Sensor absent
    }

    last_edge_time = gpioTick();

    // Measure high time
    while (gpioRead(GPIO_PIN) == 1 && edge_count < TIMEOUT_US) {
        edge_count++;
        gpioDelay(1);
    }

    if (edge_count >= TIMEOUT_US) {
        return 0; // Sensor absent
    }

    return 1; // Sensor present
}

