    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Check sensor presence
    if (!check_sensor_presence()) {
        fprintf(log_file, "%s, SENSOR MALFUNCTION: Sensor not detected\n", __TIME__);
        fflush(log_file);
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

