#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x24  // High Repeatability, Clock Stretching Disabled
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 1000
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t *data, int len);
SensorData convert_data(uint8_t *data);
SensorData apply_offset(SensorData data);
char* format_data(SensorData data);
int log_data(char *data);
void signal_handler(int signal);
void cleanup();

// CRC lookup table (for polynomial 0x31)
const uint8_t crc_table[256] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {MEASURE_CMD, 0x00};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }

    gpioDelay(20); // Wait for measurement (at least 15ms)

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to validate CRC
int validate_crc(uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        crc = (crc << 4) ^ crc_table[data[i] & 0x0F];
        crc = (crc << 4) ^ crc_table[(data[i] >> 4) & 0x0F];
    }
    crc = (crc << 4) ^ crc_table[data[len - 1] & 0x0F];
    crc = (crc << 4) ^ crc_table[(data[len - 1] >> 4) & 0x0F];

    if (crc != 0) {
        return -1; // CRC error
    }
    return 0; // CRC valid
}

// Function to convert raw data to temperature and humidity
SensorData convert_data(uint8_t *data) {
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    float temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    float humidity = 100.0 * (float)humidity_raw / 65535.0;

    SensorData sensor_data;
    sensor_data.temperature = temperature;
    sensor_data.humidity = humidity;

    return sensor_data;
}

// Function to apply sinusoidal offset
SensorData apply_offset(SensorData data) {
    time_t now = time(NULL);
    double offset_time = (double)now / (60.0 * 60.0); // 1 hour period
    double offset = 2.0 * sin(M_PI * offset_time) + 2.0; // ±2 °C
    double offset_humidity = 5.0 * sin(M_PI * offset_time) + 5.0; // ±5 %RH

    data.temperature += offset;
    data.humidity += offset_humidity;

    return data;
}

// Function to format data as ISO 8601 string
char* format_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    char *formatted_data = (char*)malloc(128 * sizeof(char)); // Allocate memory
    if (formatted_data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    snprintf(formatted_data, 128, "%s,%.2f,%.2f", timestamp, data.temperature, data.humidity);
    return formatted_data;
}

// Function to log data to file
int log_data(char *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s\n", data);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    SensorData raw_data, offset_data;
    char *formatted_data;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 2) == 0 && validate_crc(sensor_data + 3, 2) == 0) {
                // Convert data
                raw_data = convert_data(sensor_data);

                // Apply offset
                offset_data = apply_offset(raw_data);

                // Format data
                formatted_data = format_data(offset_data);
                if (formatted_data != NULL) {
                    // Log data
                    if (log_data(formatted_data) != 0) {
                        fprintf(stderr, "Failed to log data\n");
                    }
                    free(formatted_data); // Free allocated memory
                } else {
                    fprintf(stderr, "Failed to format data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

