int read_sht35(float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Wait for measurement to complete
    gpioDelay(MEASURE_DELAY_MS * 1000); // Convert ms to us

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0;
}

