#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define SI7021_MEASURE_CMD 0xE0
#define SI7021_TEMP_CMD 0xF3
#define SI7021_HUMID_CMD 0xF5
#define SI7021_RESET_CMD 0xFE

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the Si7021 sensor
int read_si7021(int fd, float *temperature, float *humidity) {
    uint8_t buf[3];
    int retries = 3;
    int result;

    // Measure Humidity
    while (retries > 0) {
        buf[0] = SI7021_HUMID_CMD;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write humidity command");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }
        usleep(10000); // Wait for measurement (datasheet says 10ms)

        result = read(fd, buf, 3);
        if (result == 3) {
            // Check CRC
            if (crc8(buf, 2) == buf[2]) {
                uint16_t raw_humidity = (buf[0] << 8) | buf[1];
                *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
                return 0; // Success
            } else {
                fprintf(stderr, "Humidity CRC error\n");
                return -1; // CRC error
            }
        } else {
            perror("Failed to read humidity data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "Failed to read humidity after multiple retries\n");
    return -1; // Failure after retries

    // Measure Temperature
    retries = 3;
    while (retries > 0) {
        buf[0] = SI7021_TEMP_CMD;
        if (write(fd, buf, 1) != 1) {
            perror("Failed to write temperature command");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }
        usleep(10000); // Wait for measurement (datasheet says 10ms)

        result = read(fd, buf, 3);
        if (result == 3) {
            // Check CRC
            if (crc8(buf, 2) == buf[2]) {
                uint16_t raw_temperature = (buf[0] << 8) | buf[1];
                *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;
                return 0; // Success
            } else {
                fprintf(stderr, "Temperature CRC error\n");
                return -1; // CRC error
            }
        } else {
            perror("Failed to read temperature data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "Failed to read temperature after multiple retries\n");
    return -1; // Failure after retries
}

// Function to log data to a CSV file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Function to handle errors
void handle_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
    if (log_file != NULL) {
        fprintf(log_file, "ERROR\n");
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    float temperature, humidity;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

