#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define SAMPLE_INTERVAL_SEC 1

// Global variables for signal handling
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, float *pressure, float *temperature) {
    uint8_t buffer[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, MEASURE_COMMAND); // No register address, command is direct
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion (datasheet specifies 20ms for continuous mode)
    gpioDelay(20000); // 20ms

    // Read 9 bytes from the sensor
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -2;
    }

    // Extract raw pressure and temperature values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    // Convert to physical units
    *pressure = (float)raw_pressure / 60.0f - 1000.0f; // Scale factor from datasheet
    *temperature = (float)raw_temperature / 200.0f - 45.0f;

    return 0;
}

// Function to log data to a file
int log_data(FILE *fp, float pressure, float temperature) {
    size_t bytes_written = fwrite(&pressure, sizeof(float), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing pressure to file\n");
        return -1;
    }
    bytes_written = fwrite(&temperature, sizeof(float), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing temperature to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open data file in binary append mode
    fp = fopen("airflow.dat", "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening data file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float pressure, temperature;
    int result;

    // Main loop
    while (!terminate) {
        result = read_sensor_data(i2c_handle, &pressure, &temperature);
        if (result == 0) {
            if (log_data(fp, pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Sleep for 1 second
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();

    return 0;
}

