#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x3603
#define SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    time_t timestamp;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read pressure from the sensor
float read_pressure() {
    char buf[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, MEASURE_COMMAND); // No register address needed for SDP800
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1.0; // Indicate error
    }

    // Wait for conversion (45 ms)
    gpioDelay(45000); // 45 ms

    // Read 9 bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1.0; // Indicate error
    }

    // Extract raw data
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];
    uint8_t crc_pressure = buf[2];
    uint8_t crc_temperature = buf[5];

    // CRC validation
    uint8_t calculated_pressure_crc = crc8(buf, 2);
    uint8_t calculated_temperature_crc = crc8(buf + 3, 2);

    if (calculated_pressure_crc != crc_pressure || calculated_temperature_crc != crc_temperature) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1.0; // Indicate error
    }

    // Convert to pressure in Pascals
    float pressure = (float)raw_pressure / SCALE_FACTOR;

    return pressure;
}

