        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float pressure = read_pressure();
        if (pressure >= 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Error reading pressure, skipping log.\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

