// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the sensor data
int read_sensor(int i2c_handle) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_value = (buffer[0] << 8) | buffer[1];

    // Mask off the status bits (bits 14 and 15)
    raw_value &= 0x3FFF; // 14-bit mask

    return raw_value;
}

