int calculate_pwm(float slpm) {
    int duty_cycle = (int)(slpm * 10.0); // Scale SLPM to 0-100
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    return duty_cycle;
}

