    while (!terminate) {
        // Read sensor data
        int raw_value = read_sensor(i2c_handle);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
