#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define LPS33HW_ADDR 0x5D
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C
#define BLOCK_DATA_UPDATE 0xB0
#define ODR_10HZ 0x02
#define ACTIVE_MODE 0x00
#define SLEEP_MS 1000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Function prototypes
int init_lps33hw();
int read_pressure(int32_t *pressure);
int read_temperature(int16_t *temperature);
void log_data(int32_t pressure, int16_t temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int32_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function to initialize the LPS33HW sensor
int init_lps33hw() {
    int status;

    // Check WHO_AM_I register
    status = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
        return -1;
    }
    if (status != 0xB1) {
        fprintf(stderr, "WHO_AM_I register value incorrect: 0x%X\n", status);
        return -1;
    }

    // Configure CTRL_REG1
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, BLOCK_DATA_UPDATE | ODR_10HZ | ACTIVE_MODE);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read pressure data from the LPS33HW
int read_pressure(int32_t *pressure) {
    char buffer[3];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3);
    if (status < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", status);
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)buffer[2]) << 16) | (((uint32_t)buffer[1]) << 8) | ((uint32_t)buffer[0]));
    *pressure = (*pressure << 8) >> 8; // Sign extend

    return 0;
}

// Function to read temperature data from the LPS33HW
int read_temperature(int16_t *temperature) {
    char buffer[2];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", status);
        return -1;
    }

    *temperature = (int16_t)(((uint16_t)buffer[1] << 8) | ((uint16_t)buffer[0]));

    return 0;
}

// Function to log data to a file
void log_data(int32_t pressure, int16_t temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime_r(&rawtime, timestamp);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure / 4096.0, 42.5 + (float)temperature / 480.0);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int status;
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW sensor
    if (init_lps33hw() != 0) {
        fprintf(stderr, "LPS33HW initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_pressure(&sensor_data.pressure) == 0 && read_temperature(&sensor_data.temperature) == 0) {
            // Log data
            log_data(sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Sleep for 1 second
        gpioDelay(SLEEP_MS);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

