#define MEASUREMENT_INTERVAL 2 // seconds
#define CO2_THRESHOLD_OFF 800
#define CO2_THRESHOLD_LOW 1199
#define CO2_THRESHOLD_HIGH 1200

// SCD30 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_GET_DATA_READY 0x0202

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the SCD30 sensor
int init_scd30() {
    // Start periodic measurement with ambient pressure compensation disabled
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(log_file, "%s I2C write error during start periodic measurement\n", __func__);
        fflush(log_file);
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to start

    return 0;
}

// Function to read data from the SCD30 sensor
int read_scd30(sensor_data_t *data) {
    char buf[2];
    buf[0] = (CMD_GET_DATA_READY >> 8) & 0xFF;
    buf[1] = CMD_GET_DATA_READY & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(log_file, "%s I2C write error during get data ready\n", __func__);
        fflush(log_file);
        return -1;
    }
    gpioDelay(10); // Wait for data ready

    char read_buf[18];
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(log_file, "%s I2C write error during read measurement\n", __func__);
        fflush(log_file);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 18) != 18) {
        fprintf(log_file, "%s I2C read error\n", __func__);
        fflush(log_file);
        return -1;
    }

    // Verify data ready status
    if (read_buf[0] != 0x00) {
        fprintf(log_file, "%s Data not ready\n", __func__);
        fflush(log_file);
        return -1;
    }

    // Extract data
    unsigned int co2_raw = (read_buf[0] << 8) | read_buf[1];
    unsigned int temperature_raw = (read_buf[2] << 8) | read_buf[3];
    unsigned int humidity_raw = (read_buf[4] << 8) | read_buf[5];

    // CRC Check
    if (crc8(&read_buf[0], 2) != read_buf[2]) {
        fprintf(log_file, "%s CO2 CRC check failed\n", __func__);
        fflush(log_file);
        return -1;
    }
    if (crc8(&read_buf[3], 2) != read_buf[5]) {
        fprintf(log_file, "%s Temperature CRC check failed\n", __func__);
        fflush(log_file);
        return -1;
    }

    // Convert to physical units (as per SCD30 datasheet)
    data->co2 = (float)co2_raw;
    data->temperature = -45 + ((float)temperature_raw / 65535.0) * 175;
    data->humidity = ((float)humidity_raw / 65535.0) * 100;

    return 0;
}

// Function to log data to a file
void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data->co2, data->temperature, data->humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the ventilation system
void control_ventilation(const sensor_data_t *data) {
    if (data->co2 < CO2_THRESHOLD_OFF) {
        printf("Ventilation: OFF\n");
    } else if (data->co2 < CO2_THRESHOLD_LOW) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(log_file, "Signal received, terminating...\n");
    fflush(log_file);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SCD30 sensor
    if (init_scd30() != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_scd30(&sensor_data) == 0) {
            log_data(&sensor_data);
            control_ventilation(&sensor_data);
        } else {
            fprintf(log_file, "Failed to read sensor data\n");
            fflush(log_file);
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Delay for measurement interval
    }

    // Stop periodic measurement
    char stop_buf[2];
    stop_buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    stop_buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    if (i2cWriteDevice(i2c_handle, stop_buf, 2) != 0) {
        fprintf(log_file, "%s I2C write error during stop periodic measurement\n", __func__);
        fflush(log_file);
    }
    gpioDelay(100); // Wait for the sensor to stop

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

