#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define SAMPLE_INTERVAL_MS 1000
#define CMD_MEASURE 0x362F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    float scale_factor;
} sensor_data_t;

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to start continuous measurement
int start_measurement() {
    char cmd[2] = {CMD_MEASURE[0], CMD_MEASURE[1]};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to verify CRC-8 checksum
int verify_checksum(const uint8_t *data) {
    uint8_t pressure_crc = data[2];
    uint8_t temperature_crc = data[5];
    uint8_t scale_factor_crc = data[8];

    uint8_t pressure_data[2] = {data[0], data[1]};
    uint8_t temperature_data[2] = {data[3], data[4]};
    uint8_t scale_factor_data[2] = {data[6], data[7]};

    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        return -1;
    }

    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    if (crc8(scale_factor_data, 2) != scale_factor_crc) {
        fprintf(stderr, "Scale Factor CRC check failed!\n");
        return -1;
    }

    return 0;
}

// Function to convert raw data to physical units
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    // Convert to physical units
    sensor_data.pressure = (float)raw_pressure / (float)raw_scale_factor;
    sensor_data.temperature = (float)raw_temperature / (float)raw_scale_factor;
    sensor_data.scale_factor = (float)raw_scale_factor;

    return sensor_data;
}

// Function to log sensor data with timestamp
void log_data(float pressure, float temperature, float scale_factor) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C, Scale Factor: %.2f\n",
           timestamp, pressure, temperature, scale_factor);
}

int main(int argc, char *argv[]) {
    int sample_interval = SAMPLE_INTERVAL_MS;

    // Parse command-line arguments
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sampling interval. Using default: %d ms\n", SAMPLE_INTERVAL_MS);
            sample_interval = SAMPLE_INTERVAL_MS;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start continuous measurement
    if (start_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[9];
    sensor_data_t converted_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Verify checksum
            if (verify_checksum(sensor_data) == 0) {
                // Convert data
                converted_data = convert_data(sensor_data);

                // Log data
                log_data(converted_data.pressure, converted_data.temperature, converted_data.scale_factor);
            } else {
                fprintf(stderr, "Checksum verification failed. Skipping logging.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping.\n");
        }

        // Wait for the next sample
        gpioDelay(sample_interval * 1000); // pigpioDelay takes microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

