        return -1;
    }

    // Wait for at least 45 ms for the conversion
    gpioDelay(45000); // 45 ms

    // Read 9 bytes of data
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading data from I2C. Read %d bytes, expected 9.\n", bytes_read);
        return -1;
    }

    return 0;
}

