sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Extract raw pressure and temperature values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Extract scale factors
    float pressure_scale_factor = (float)data[6] / 65536.0;
    float temperature_scale_factor = (float)data[7] / 65536.0;

    // Convert raw values to physical units
    sensor_data.pressure = raw_pressure / pressure_scale_factor;
    sensor_data.temperature = raw_temperature / temperature_scale_factor;

    return sensor_data;
}

// Function to log sensor data to stdout
void log_data(float pressure, float temperature) {
    printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
}

