    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[9];

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) == 0) {
            // Validate CRC for pressure
            uint8_t crc_pressure = crc8(data, 2);
            if (crc_pressure != data[2]) {
                fprintf(stderr, "CRC mismatch for pressure data!\n");
            }

            // Validate CRC for temperature
            uint8_t crc_temperature = crc8(data + 3, 2);
            if (crc_temperature != data[5]) {
                fprintf(stderr, "CRC mismatch for temperature data!\n");
            }

            // Convert data
            sensor_data_t sensor_data = convert_data(data);

            // Log data
            log_data(sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close the I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

