#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONFIG_VALUE 0x8000 // Enable temperature and humidity measurement, 14-bit resolution

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to the HDC1000
int hdc1000_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to HDC1000");
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from the HDC1000
int hdc1000_read(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from HDC1000");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read temperature and humidity from the HDC1000
int hdc1000_read_data(int fd, float *temperature, float *humidity) {
    uint16_t raw_temp, raw_humidity;

    // Write to configuration register
    if (hdc1000_write(fd, CONFIG_REG, CONFIG_VALUE) != 0) {
        fprintf(stderr, "Failed to configure HDC1000\n");
        return -1;
    }

    // Read temperature and humidity registers
    if (hdc1000_read(fd, TEMP_REG, &raw_temp) != 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }
    if (hdc1000_read(fd, HUMID_REG, &raw_humidity) != 0) {
        fprintf(stderr, "Failed to read humidity data\n");
        return -1;
    }

    // Convert raw values to Celsius and percentage RH
    *temperature = (float)raw_temp / 65536.0 * 165.0 - 40.0;
    *humidity = (float)raw_humidity / 65536.0 * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("HDC1000 sensor reader started. Press Ctrl+C to exit.\n");

    while (1) {
        ret = hdc1000_read_data(i2c_fd, &temperature, &humidity);
        if (ret == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(i2c_fd);
    return 0;
}

