#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define TEMP_CELSIUS_SCALE 175.72f
#define TEMP_CELSIUS_OFFSET -46.85f
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
float read_temperature();
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si7051_address;
    int retry_count;
    int retry_delay_ms;
} sensor_config_t;

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from the sensor
float read_temperature() {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %d, retry %d\n", result, retries + 1);
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(10000); // Wait for measurement (10ms)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading temperature data: %d, retry %d\n", result, retries + 1);
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // Convert raw data to temperature
        uint16_t raw_temperature = (buf[0] << 8) | buf[1];
        float temperature = (float)raw_temperature / TEMP_CELSIUS_SCALE + TEMP_CELSIUS_OFFSET;

        return temperature;
