#define ICP10101_REG_TEMP_MSB 0x03
#define ICP10101_REG_TEMP_LSB 0x04
#define ICP10101_REG_PRESS_MSB 0x01
#define ICP10101_REG_PRESS_LSB 0x02
#define ICP10101_REG_PRESS_XLSB 0x00

// Calibration data structure
typedef struct {
    uint16_t c0;
    uint16_t c1;
    uint16_t c00;
    uint16_t c10;
    uint16_t c01;
    uint16_t c11;
    uint16_t c20;
    uint16_t c21;
} icp10101_calibration_data_t;

// Global variables
int i2c_handle;
icp10101_calibration_data_t calibration_data;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_calibration_data(icp10101_calibration_data_t *calibration_data);
int trigger_measurement();
int read_sensor_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Function to initialize the ICP-10101 sensor
int initialize_sensor() {
    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, ICP10101_REG_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0x41) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, ICP10101_REG_RESET, 0x80) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    return 0;
}

// Function to read calibration data from the sensor
int read_calibration_data(icp10101_calibration_data_t *calibration_data) {
    char buffer[8];
    if (i2cReadI2CBlockData(i2c_handle, 0x50, buffer, 8) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calibration_data->c0 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calibration_data->c1 = (uint16_t)buffer[2] | ((uint16_t)buffer[3] << 8);
    calibration_data->c00 = (uint16_t)buffer[4] | ((uint16_t)buffer[5] << 8);
    calibration_data->c10 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);

    return 0;
}

// Function to trigger a measurement
int trigger_measurement() {
    if (i2cWriteByteData(i2c_handle, ICP10101_REG_MEASURE, 0x40) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    gpioDelay(7); // Wait for measurement to complete
    return 0;
}

// Function to read sensor data
int read_sensor_data(int32_t *temperature, int32_t *pressure) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, ICP10101_REG_PRESS_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *pressure = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);
    *temperature = (int32_t)buffer[3] | ((int32_t)buffer[4] << 8) | ((int32_t)buffer[5] << 16);

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temperature) {
    // Placeholder compensation formula (replace with actual formula from datasheet)
    return (double)raw_temperature / 100.0; // Example: raw_temperature / 100.0
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure) {
    // Placeholder compensation formula (replace with actual formula from datasheet)
    return (double)raw_pressure / 100.0; // Example: raw_pressure / 100.0
}

// Function to log data with timestamp
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration_data) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int32_t raw_temperature, raw_pressure;

        // Trigger measurement
        if (trigger_measurement() < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue; // Continue to the next iteration
        }

        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_pressure) < 0) {
