#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x25
#define MEASURE_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *device);
int i2c_write(int fd, uint16_t command);
int i2c_read(int fd, uint8_t *buffer, int count);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *raw_data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint16_t command) {
    uint8_t buffer[2];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;
    if (write(fd, buffer, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *buffer, int count) {
    if (read(fd, buffer, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Data processing function
sensor_data_t process_sensor_data(const uint8_t *raw_data) {
    sensor_data_t data;
    uint16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    uint16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];
    uint16_t raw_pressure_crc = raw_data[2];
    uint16_t raw_temperature_crc = raw_data[5];

    if (crc8(&raw_data[0], 2) != raw_data[2]) {
        fprintf(stderr, "CRC error for pressure\n");
        data.pressure = -999.0; // Indicate error
    } else {
        data.pressure = (float)raw_pressure / 60.0;
    }

    if (crc8(&raw_data[3], 2) != raw_data[5]) {
        fprintf(stderr, "CRC error for temperature\n");
        data.temperature = -999.0; // Indicate error
    } else {
        data.temperature = (float)raw_temperature / 200.0;
    }

    return data;
}

// Data logging function
int log_data(const sensor_data_t *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data->pressure, data->temperature);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device. Exiting.\n");
        return 1;
    }

    printf("I2C device opened successfully.\n");

    // Main loop
    while (program_running) {
        // Send measurement command
        if (i2c_write(i2c_fd, MEASURE_CMD) < 0) {
            fprintf(stderr, "Failed to send measurement command. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        // Wait for measurement (45 ms)
        usleep(45000); // 45 ms

        // Read sensor data
        uint8_t raw_data[9];
        if (i2c_read(i2c_fd, raw_data, 9) < 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        // Process sensor data
        sensor_data_t data = process_sensor_data(raw_data);

        // Log data
        if (data.pressure != -999.0 && data.temperature != -999.0) {
            if (log_data(&data) < 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Invalid sensor data. Not logging.\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

