// Read sensor data from the SDP800-500Pa sensor
int read_sensor_data(int *raw_pressure) {
    char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    char buffer[3];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(10); // Wait for measurement to complete (at least 8ms)

    if (i2cReadDevice(i2c_handle, buffer, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *raw_pressure = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Verify CRC-8 checksum
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Convert raw pressure data to Pascals
float convert_to_pressure(int raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE;
}

// Log data to CSV file
int log_data(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure_Pa\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    int raw_pressure;
    float pressure;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&raw_pressure) == 0) {
            if (verify_crc((uint8_t[]){buffer[0], buffer[1]}, 2)) {
                pressure = convert_to_pressure(raw_pressure);
                if (log_data(pressure) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                printf("Pressure: %.2f Pa\n", pressure);
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(1); // Read data every second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

