#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1048576 // 1 MB

int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read data from the HIH6130 sensor
int read_hih6130(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buf[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 40 ms)
    gpioDelay(50000); // 50 ms

    // Read 4 bytes from the sensor
    result = i2cReadDevice(i2c_handle, (char *)buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Check status bits (bits 6 and 7 of the first byte)
    if ((buf[0] & 0xC0) != 0) {
        fprintf(stderr, "Sensor status indicates an error.\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    unsigned int raw_temperature = ((buf[0] & 0x3F) << 8) | buf[1];
    unsigned int raw_humidity = (buf[2] << 6) | (buf[3] >> 2);

    *temperature = (float)raw_temperature * 165.0 / 16383.0 - 40.0;
    *humidity = (float)raw_humidity * 100.0 / 16383.0;

    return 0;
}

// Function to log data to a file
int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timestamp);

    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", filename);
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);

    return 0;
}

// Function to check the size of the log file and truncate it if necessary
int check_log_size(const char *filename) {
    FILE *fp;
    long file_size;

    fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file for size check: %s\n", filename);
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    file_size = ftell(fp);
    fclose(fp);

    if (file_size > MAX_LOG_SIZE) {
        fp = fopen(filename, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening log file for truncation: %s\n", filename);
            return -1;
        }
        fprintf(fp, "\n"); // Add a newline to start the file fresh
        fclose(fp);
    }

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        result = read_hih6130(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            // Log data
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Check log size
            check_log_size(LOG_FILE);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

