#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define TIMEOUT_US 10000 // 10ms timeout
#define SCALE_FACTOR 0.1
#define OFFSET 50.0

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read pressure from the MLX90824 sensor
float read_pressure() {
    int gpio_pin = GPIO_PIN;
    int i;
    unsigned int pulse_width;
    unsigned int status_nibble, data_nibble1, data_nibble2, data_nibble3;
    unsigned int checksum;
    unsigned int raw_value;
    float pressure;

    // Send start signal (falling edge)
    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_UP);
    gpioDelay(1000); // Wait 1ms

    // Wait for rising edge
    int start_time = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for rising edge.\n");
            return -1.0; // Sensor absent
        }
    }

    // Measure pulse width (synchronization pulse)
    start_time = gpioTick();
    while (gpioRead(gpio_pin) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for synchronization pulse.\n");
            return -1.0; // Bus error
        }
    }
    start_time = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for end of synchronization pulse.\n");
            return -1.0; // Bus error
        }
    }
    pulse_width = gpioTick() - start_time;

    // Validate pulse width
    if (pulse_width < 36 || pulse_width > 813) {
        fprintf(stderr, "Error: Invalid pulse width: %d us\n", pulse_width);
        return -1.0; // Bus error
    }

    // Read status nibble
    start_time = gpioTick();
    while (gpioRead(gpio_pin) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for start of status nibble.\n");
            return -1.0; // Bus error
        }
    }
    start_time = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for end of status nibble.\n");
            return -1.0; // Bus error
        }
    }
    status_nibble = gpioTick() - start_time;

    // Read data nibbles
    start_time = gpioTick();
    while (gpioRead(gpio_pin) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for start of data nibble 1.\n");
            return -1.0; // Bus error
        }
    }
    start_time = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for end of data nibble 1.\n");
            return -1.0; // Bus error
        }
    }
    data_nibble1 = gpioTick() - start_time;

    start_time = gpioTick();
    while (gpioRead(gpio_pin) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for start of data nibble 2.\n");
            return -1.0; // Bus error
        }
    }
    start_time = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
