#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x01
#define DEVICE_ID 0x0117
#define FILENAME "greenhouse_temps.dat"
#define SAMPLE_INTERVAL 60 // seconds

int i2c_handle;
FILE *fp;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a register from the TMP117
int read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to write a register to the TMP117
int write_register(int handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result != 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read the temperature from the TMP117
float read_temperature(int handle) {
    uint8_t data[2];
    if (read_register(handle, TEMP_REG, data, 2) != 0) {
        return -1000.0; // Indicate error with a very low temperature
    }

    int16_t raw_temp = (data[1] << 8) | data[0];
    float temperature = (float)raw_temp * 0.0078125;
    return temperature;
}

// Function to write the temperature to a file
int write_to_file(FILE *fp, float temperature) {
    size_t bytes_written = fwrite(&temperature, sizeof(float), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    uint8_t device_id[2];
    if (read_register(i2c_handle, DEVICE_ID_REG, device_id, 2) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (memcmp(device_id, DEVICE_ID, 2) != 0) {
        fprintf(stderr, "Error: Incorrect device ID (0x%04X, expected 0x%04X)\n", (int16_t)((device_id[1] << 8) | device_id[0]), DEVICE_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the file for appending
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", FILENAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature(i2c_handle);
        if (temperature > -999.0) { // Check for read error
            if (write_to_file(fp, temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness in case the loop is ever modified.
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

