#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd[1] = {MEASURE_HIGH_PRECISION};
    uint8_t data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write to I2C device.\n");
        return -1;
    }

    // Wait for conversion (at least 8.5 ms)
    gpioDelay(10); // Wait 10 ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read from I2C device.\n");
        return -1;
    }

    // Validate CRC checksums
    uint8_t temp_crc = crc8(data, 2);
    uint8_t hum_crc = crc8(data + 3, 2);

    if (temp_crc != data[2] || hum_crc != data[5]) {
        fprintf(stderr, "Error: CRC checksum validation failed.\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temp = (data[0] << 8) | data[1];
    uint16_t raw_hum = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (raw_temp / 65535.0);
    *humidity = -6.0 + 125.0 * (raw_hum / 65535.0);

    return 0;
}

// Function to log data to a file
int log_data(const char *filename, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", filename);
        return -1;
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, SHT40_ADDR);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

