// Structure to hold temperature readings
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
int i2c_handle;
CircularBuffer temp_buffer;
volatile sig_atomic_t terminate = 0;

