// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a reading to the circular buffer
void add_reading(CircularBuffer *cb, float temperature) {
    cb->buffer[cb->head] = temperature;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Initialize pigpio
int init_pigpio() {
