    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (big-endian)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = raw_temp * 0.0078125;

    return 0;
}

// Store the latest reading in the circular buffer
void store_reading(float temperature) {
    add_reading(&temp_buffer, temperature);
}

// Flush the buffer to a file
void flush_buffer_to_file() {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open temperature_log.dat for writing\n");
        return;
    }

    size_t bytes_written = fwrite(&temp_buffer, sizeof(temp_buffer), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Failed to write buffer to file\n");
    }

    fclose(fp);
}

