    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;
    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Store reading
            store_reading(temperature);
            printf("Temperature: %.4f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping.\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Flush buffer to file
    flush_buffer_to_file();

    // Terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

