#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAG_REG 0x01 // Example register for magnetic data
#define TEMP_REG 0x02 // Example register for temperature data
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int handle, int reg);
float convert_to_gauss(int raw_value);
float convert_to_celsius(int raw_value);
int log_data(float gauss, float celsius);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data from a specific register
int read_sensor_data(int handle, int reg) {
    int raw_value = i2cReadByteData(handle, reg);
    if (raw_value < 0) {
        fprintf(stderr, "Failed to read register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return raw_value;
}

// Convert raw magnetic data to Gauss
float convert_to_gauss(int raw_value) {
    return (float)raw_value * 0.1;
}

// Convert raw temperature data to Celsius
float convert_to_celsius(int raw_value) {
    return (float)raw_value * 0.01 - 25.0;
}

// Log data to a CSV file
int log_data(float gauss, float celsius) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("mag_temp_log.csv", "a+");
        if (log_file == NULL) {
