#include <time.h>
#include <signal.h>
#include <string.h>

#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define I2C_BUS 1
#define MAX_REINIT_ATTEMPTS 3
#define RETRY_DELAY_MS 100

int i2c_handle;
FILE *log_file;

// Function to handle Ctrl+C signal
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from TMP117
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    // Convert raw data to signed 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to Celsius
    *temperature = (float)raw_temp * 0.0078125;

    return 0;
}

// Function to log temperature to file
int log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature;
    int reinit_attempts = 0;

    // Main loop
    while (1) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Retrying in %d ms.\n", RETRY_DELAY_MS);
                reinit_attempts++;
                if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                    fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                    break;
                }
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            } else {
                reinit_attempts = 0; // Reset attempts on successful re-initialization
            }
        }
        gpioDelay(1000000); // Wait 1 second (1000000 microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

