#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define FLOW_REG 0x00 // Example register address
#define TEMP_REG 0x02 // Example register address
#define FLOW_SCALE 16384.0
#define TEMP_SCALE 4096.0
#define FLOW_OFFSET 0.1
#define TEMP_OFFSET 0.1
#define FLOW_SLOPE 0.8
#define TEMP_SLOPE 0.8
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_slpm;
    float temperature_celsius;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_flow(int raw_flow);
float convert_temperature(int raw_temp);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading I2C data: %d\n", bytes_read);
        return -1;
    }

    // Combine bytes to form 14-bit flow and 12-bit temperature
    int raw_flow = ((buffer[0] << 6) | (buffer[1] >> 2));
    int raw_temp = ((buffer[2] << 4) | (buffer[3] >> 4));

    // Data validation
    if (raw_flow < 0 || raw_flow > 16383 || raw_temp < 0 || raw_temp > 4095) {
        fprintf(stderr, "Invalid sensor data: flow=%d, temp=%d\n", raw_flow, raw_temp);
        return -1;
    }

    data->flow_slpm = convert_flow(raw_flow);
    data->temperature_celsius = convert_temperature(raw_temp);

    return 0;
}

// Function to convert raw flow data to SLPM
float convert_flow(int raw_flow) {
    return ((raw_flow / FLOW_SCALE) - FLOW_OFFSET) / FLOW_SLOPE * 25.0;
}

// Function to convert raw temperature data to Celsius
float convert_temperature(int raw_temp) {
    return ((raw_temp / TEMP_SCALE) - TEMP_OFFSET) / TEMP_SLOPE * 80.0 - 40.0;
}

// Function to log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f °C\n", timestamp, data.flow_slpm, data.temperature_celsius);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

