#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define LOG_FILE "sht31d_data.log"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SHT31-D sensor
int read_sht31d(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result == 0) break; // Success
        fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "I2C write failed after %d retries. Aborting.\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) break; // Success
        fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "I2C read failed after %d retries. Aborting.\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1; // Indicate failure
    }

    // Conversion
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0; // Indicate success
}

// Function to log data to a file
void log_data(FILE *log_file, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sht31d(i2c_handle, &temperature, &humidity) == 0) {
            log_data(log_file, temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

