#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN 0.0
#define P_MAX 800.0
#define T_MIN -40.0
#define T_MAX 125.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_kPa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int read_raw_pressure(int i2c_handle);
int read_raw_temperature(int i2c_handle);
float convert_pressure(int raw_pressure);
float convert_temperature(int raw_temperature);
char* get_iso8601_timestamp();
int log_data(float pressure_kPa, float temperature_C);
void signal_handler(int signal);

// Function to read raw pressure data from the sensor
int read_raw_pressure(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1; // Indicate error
    }
    return (buf[0] << 8) | buf[1]; // Combine bytes into a 16-bit value
}

// Function to read raw temperature data from the sensor
int read_raw_temperature(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1; // Indicate error
    }
    return (buf[0] << 8) | buf[1]; // Combine bytes into a 16-bit value
}

// Function to convert raw pressure to kPa
float convert_pressure(int raw_pressure) {
    return (raw_pressure - OUTPUT_MIN) * (P_MAX - P_MIN) / (OUTPUT_MAX - OUTPUT_MIN);
}

// Function to convert raw temperature to Celsius
float convert_temperature(int raw_temperature) {
    return raw_temperature * 0.01 - 40.0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log data to a file
int log_data(float pressure_kPa, float temperature_C) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f kPa, %.2f C\n", timestamp, pressure_kPa, temperature_C);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp); // Free the allocated memory
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_pressure = read_raw_pressure(i2c_handle);
        int raw_temperature = read_raw_temperature(i2c_handle);

        if (raw_pressure != -1 && raw_temperature != -1) {
            float pressure_kPa = convert_pressure(raw_pressure);
            float temperature_C = convert_temperature(raw_temperature);

            if (log_data(pressure_kPa, temperature_C) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

