#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0

// Global variables
int i2c_handle;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
double running_average = 0.0;

// Function prototypes
int initialize();
double read_temperature();
void update_buffer(double temperature);
double calculate_average();
void control_fan(double average_temperature);
void signal_handler(int signal);

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        double temperature = read_temperature();
        if (temperature != -1000.0) { // Error code from read_temperature
            update_buffer(temperature);
            double average_temperature = calculate_average();
            control_fan(average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying.\n");
        }
        gpioDelay(1000); // Wait 1 second
    }

    return 0;
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize temperature buffer with 0.0
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    return 0;
}

// Read temperature from LM75B
double read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

