#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define SCALE_PRESSURE 60.0
#define SCALE_TEMPERATURE 200.0
#define PRESSURE_THRESHOLD 5.0
#define LOG_FILE "airflow.log"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, float *pressure, float *temperature) {
    uint8_t data[9];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, MEASURE_CMD); // No register address needed for SDP810
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (45 ms)
    gpioDelay(45000); // 45 ms

    // Read 9 bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Extract raw data
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint8_t status = data[5];

    // CRC validation
    uint8_t crc_pressure = data[2];
    uint8_t crc_temperature = data[6];

    if (crc8(data, 2) != crc_pressure || crc8(data + 3, 2) != crc_temperature) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    // Convert to physical units
    *pressure = (float)raw_pressure / SCALE_PRESSURE;
    *temperature = (float)raw_temperature / SCALE_TEMPERATURE;

    return 0;
}

// Function to log data to a file
void log_data(FILE *log_file, float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float pressure, temperature;

    // Main loop
    while (!terminate) {
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);

            if (pressure > PRESSURE_THRESHOLD) {
                fprintf(stderr, "Warning: Pressure exceeds threshold (%.2f Pa > %.2f Pa)\n", pressure, PRESSURE_THRESHOLD);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Sleep for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

