#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define LED_CHIP "gpiochip0"
#define LED_LINE 0
#define DEFAULT_SLAVE_ADDRESS 0x4A
#define TEMPERATURE_REGISTER 0x00
#define HISTORICAL_TEMP_FILE "temperature_history.txt"
#define LOG_FILE "temperature_log.txt"
#define TEMPERATURE_THRESHOLD_HIGH 28.0
#define TEMPERATURE_THRESHOLD_LOW 27.0
#define HISTORICAL_TEMP_FILE_SIZE 256 // Maximum size of the file in bytes

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg, uint16_t *value);
float convert_to_celsius(uint16_t raw_temp);
int gpio_set_output(struct gpiod_chip *chip, int line, int value);
int gpio_set_direction(struct gpiod_chip *chip, int line, int direction);
int log_temperature(float temperature);
int load_historical_temperature(float *temperature);
void signal_handler(int sig);
int initialize_gpio();
int cleanup_gpio();
int initialize_i2c(int slave_address);
int cleanup_i2c();

// I2C read function with error handling and retries
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    int retries = 3;
    int result;
    uint8_t buf[2];

    while (retries > 0) {
        result = i2c_smbus_read_word_data(fd, reg);
        if (result >= 0) {
            *value = (uint16_t)result;
            return 0; // Success
        } else {
            perror("I2C read failed");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries. errno: %d\n", errno);
    return -1; // Failure after retries
}

// Convert raw temperature to Celsius
float convert_to_celsius(uint16_t raw_temp) {
    return (float)raw_temp * 0.0625;
}

// Set GPIO output value
int gpio_set_output(struct gpiod_chip *chip, int line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Failed to set GPIO output value");
        return -1;
    }
    return 0;
}

// Set GPIO direction
int gpio_set_direction(struct gpiod_chip *chip, int line, int direction) {
    int ret = gpiod_line_request_output(line, direction, "temperature_monitor");
    if (ret < 0) {
        perror("Failed to set GPIO direction");
        return -1;
    }
    return 0;
}

// Log temperature to stdout
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
    return 0;
}

// Load historical temperature from file
int load_historical_temperature(float *temperature) {
    FILE *fp = fopen(HISTORICAL_TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open historical temperature file");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) != NULL) {
        // Parse the line (assuming it's in the format "YYYY-MM-DD HH:MM:SS,temperature")
        char *token = strtok(line, ",");
        if (token != NULL) {
            time_t timestamp = time(NULL);
            struct tm *t = localtime(&timestamp);
            char timestamp_str[64];
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", t);

            if (strcmp(timestamp_str, token) == 0) {
                token = strtok(NULL, ",");
                if (token != NULL) {
                    *temperature = atof(token);
                    fclose(fp);
                    return 0; // Success
                }
            }
        }
    }

    fclose(fp);
    return -1; // Failure to load historical temperature
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize GPIO
int initialize_gpio() {
    int ret;

    chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, LED_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpio_set_direction(chip, line, PI_OUTPUT) != 0) {
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
int cleanup_gpio() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

// Initialize I2C
int initialize_i2c(int slave_address) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, slave_address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup I2C
int cleanup_i2c() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int slave_address = DEFAULT_SLAVE_ADDRESS;

    // Parse command-line arguments
    if (argc > 1) {
        slave_address = strtol(argv[1], NULL, 0);
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c(slave_address) != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup_i2c();
        return 1;
    }

    uint16_t raw_temp;
    float temperature;
    float historical_temperature = 0.0;

    // Main loop
    while (!terminate) {
        // Read temperature
        if (i2c_read_word(i2c_fd, TEMPERATURE_REGISTER, &raw_temp) == 0) {
            // Convert to Celsius
            temperature = convert_to_celsius(raw_temp);

            // Load historical temperature
            if (load_historical_temperature(&historical_temperature) != 0) {
                historical_temperature = 0.0; // Use default if loading fails
            }

            // Control LED based on temperature and hysteresis
            if (temperature > TEMPERATURE_THRESHOLD_HIGH && historical_temperature <= TEMPERATURE_THRESHOLD_LOW) {
                if (gpio_set_output(chip, line, 1) == 0) {
                    printf("LED turned ON\n");
                }
            } else if (temperature < TEMPERATURE_THRESHOLD_LOW && historical_temperature >= TEMPERATURE_THRESHOLD_HIGH) {
                if (gpio_set_output(chip, line, 0) == 0) {
                    printf("LED turned OFF\n");
                }
            } else if (temperature > TEMPERATURE_THRESHOLD_HIGH) {
                if (gpio_set_output(chip, line, 1) == 0) {
                    printf("LED turned ON\n");
                }
            } else if (temperature < TEMPERATURE_THRESHOLD_LOW) {
                if (gpio_set_output(chip, line, 0) == 0) {
                    printf("LED turned OFF\n");
                }
            }

            // Log temperature
            log_temperature(temperature);

            // Write historical temperature to file
            FILE *fp = fopen(HISTORICAL_TEMP_FILE, "w");
            if (fp != NULL) {
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
                fprintf(fp, "%s,%.2f\n", timestamp, temperature);
                fclose(fp);
            } else {
                perror("Failed to open historical temperature file for writing");
            }

            historical_temperature = temperature; // Update historical temperature
        } else {
            fprintf(stderr, "Failed to read temperature. errno: %d\n", errno);
        }

        sleep(1);
    }

    // Cleanup
    cleanup_gpio();
    cleanup_i2c();

    printf("Program terminated.\n");
    return 0;
}

