#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define SCALE_FACTOR_OFFSET 3
#define SCALE_FACTOR_SIZE 2
#define SCALE_FACTOR_SIGN 1
#define SCALE_FACTOR_MAGNITUDE 2
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, int command);
int read_sensor_data(int handle, uint8_t *data);
int validate_crc(uint8_t *data, int len, uint8_t crc);
int convert_data(uint8_t *data, sensor_data_t *sensor_data);
int log_data(sensor_data_t sensor_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send a command to the sensor
int send_command(int handle, int command) {
    int result = i2cWriteByteData(handle, command >> 8, command & 0xFF);
    if (result < 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, 9);
    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t *data, int len, uint8_t crc) {
    uint8_t crc_calculated = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    if (crc_calculated != crc) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }
    return 0;
}

// Convert raw data to physical units
int convert_data(uint8_t *data, sensor_data_t *sensor_data) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data->differential_pressure = (float)raw_pressure / (float)((uint16_t)data[SCALE_FACTOR_SIGN] << SCALE_FACTOR_MAGNITUDE | (uint16_t)data[SCALE_FACTOR_SIZE]);
    sensor_data->temperature = (float)raw_temperature / 200.0f;

    return 0;
}

// Log data to file
int log_data(sensor_data_t sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, sensor_data.differential_pressure, sensor_data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    uint8_t sensor_data[9];
    sensor_data_t sensor_data_t;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_COMMAND) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        // Wait for at least 45 ms
        gpioDelay(45000); // 45 ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Validate CRC
        if (validate_crc(sensor_data, 2, sensor_data[2]) != 0) {
            fprintf(stderr, "CRC validation failed for pressure\n");
            break;
        }
        if (validate_crc(sensor_data + 3, 2, sensor_data[5]) != 0) {
            fprintf(stderr, "CRC validation failed for temperature\n");
            break;
        }

        // Convert data
        if (convert_data(sensor_data, &sensor_data_t) != 0) {
            fprintf(stderr, "Failed to convert data\n");
            break;
        }

        // Log data
        if (log_data(sensor_data_t) != 0) {
            fprintf(stderr, "Failed to log data\n");
            break;
        }

        // Delay before next reading
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

