#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE0
#define MEASURE_HUMID_CMD 0xF5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 20
#define LOG_FILE "environment.log"
#define TIMESTAMP_FORMAT "%Y-%m-%dT%H:%M:%SZ"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(float *temperature, float *humidity) {
    uint8_t cmd;
    uint8_t data[2];
    int result;
    int retries = 0;

    // Read temperature
    cmd = MEASURE_TEMP_CMD;
    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, (char *)&cmd, 1);
        if (result == 0) {
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            result = i2cReadDevice(i2c_handle, (char *)data, 2);
            if (result == 2) {
                uint16_t raw_temp = (data[0] << 8) | data[1];
                *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading temperature data (attempt %d): %d\n", retries + 1, result);
            }
        } else {
            fprintf(stderr, "Error writing temperature command (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        gpioDelay(10 * 1000); // Small delay before retry
    }

    // Read humidity
    cmd = MEASURE_HUMID_CMD;
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(i2c_handle, (char *)&cmd, 1);
        if (result == 0) {
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            result = i2cReadDevice(i2c_handle, (char *)data, 2);
            if (result == 2) {
                uint16_t raw_humidity = (data[0] << 8) | data[1];
                *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading humidity data (attempt %d): %d\n", retries + 1, result);
            }
        } else {
            fprintf(stderr, "Error writing humidity command (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        gpioDelay(10 * 1000); // Small delay before retry
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to log data to file and stdout
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written immediately

    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
}

// Function to log errors to file and stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, t);

    fprintf(stderr, "%s: %s\n", timestamp, message);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("I2C initialization failed");
        cleanup();
        return 1;
    }

