    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure HDC1080
    if (config_hdc1080() != 0) {
        cleanup();
        return 1;
    }

