    log_file = fopen("enviro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping log entry.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

