#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define LOG_FILE "temperature_log.txt"

// CRC8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40 sensor
float read_temperature(int fd) {
    unsigned char buf[3];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        // Send measurement command
        if (write(fd, MEASURE_CMD, 2) != 2) {
            perror("Failed to send measurement command");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        usleep(10000); // Wait for conversion (10ms)

        // Read 3 bytes
        bytes_read = read(fd, buf, 3);
        if (bytes_read != 3) {
            perror("Failed to read temperature data");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        // CRC validation
        unsigned char crc = crc8(buf, 2);
        if (crc != buf[2]) {
            fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", crc, buf[2]);
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Convert to temperature
        unsigned int raw = (buf[0] << 8) | buf[1];
        float temperature = -45.0 + 175.0 * (float)raw / 65535.0;
        return temperature;
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1000.0; // Indicate error
}

// Function to log temperature to file
void log_temperature(float temperature) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    close(fd);
    exit(0);
}

int main() {
    int fd;
    float temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, STS40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        temperature = read_temperature(fd);
        if (temperature > -999.0) {
            log_temperature(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

