#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_MEASUREMENT 0xE000
#define BUFFER_SIZE 100
#define LOG_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define TIMESTAMP_FORMAT "%Y-%m-%dT%H:%M:%SZ"

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_reading_t;

// Circular buffer
sensor_reading_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Function prototypes
int initialize_i2c();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
int validate_crc(uint8_t *data, int len);
int convert_data(uint8_t *data, sensor_reading_t *reading);
int add_reading(sensor_reading_t reading);
int write_buffer_to_file();
void signal_handler(int signal);
int create_log_directory();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send a command to the SCD40
int send_command(uint16_t command) {
    uint8_t data[2];
    data[0] = (command >> 8) & 0xFF;
    data[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        syslog(LOG_ERR, "Failed to write command 0x%04X: %s", command, strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the SCD40
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        syslog(LOG_ERR, "Failed to read data: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t *data, int len) {
    uint8_t calculated_crc = crc8(data, len - 1);
    if (calculated_crc != data[len - 1]) {
        syslog(LOG_ERR, "CRC check failed");
        return -1;
    }
    return 0;
}

// Convert raw data to CO2, temperature, and humidity
int convert_data(uint8_t *data, sensor_reading_t *reading) {
    reading->co2 = (data[0] << 8) | data[1];
    reading->temperature = -45 + 175 * ((int16_t)((data[2] << 8) | data[3])) / 65535;
    reading->humidity = 100 * ((int16_t)((data[4] << 8) | data[5])) / 65535;

    // Clamp humidity to 0-100%
    if (reading->humidity < 0) reading->humidity = 0;
    if (reading->humidity > 100) reading->humidity = 100;

    return 0;
}

// Add a reading to the circular buffer
int add_reading(sensor_reading_t reading) {
    circular_buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    return 0;
}

// Write the buffer to a CSV file
int write_buffer_to_file() {
    // Create the log directory if it doesn't exist
    if (access(LOG_FILE, F_OK) == -1) {
        if (mkdir("/var/log/scd40_data", 0777) != 0) {
            syslog(LOG_ERR, "Failed to create log directory: %s", strerror(errno));
            return -1;
        }
    }

    // Open the CSV file in append mode
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open CSV file: %s", strerror(errno));
        return -1;
    }

    // Write the header row if the file is empty
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
    }

    // Write the data from the circular buffer
    for (int i = 0; i < buffer_count; i++) {
        time_t timestamp = circular_buffer[i].timestamp;
        uint16_t co2 = circular_buffer[i].co2;
        float temperature = circular_buffer[i].temperature;
        float humidity = circular_buffer[i].humidity;

        struct tm *timeinfo = localtime(&timestamp);
        char timestamp_str[64];
        strftime(timestamp_str, sizeof(timestamp_str), TIMESTAMP_FORMAT, timeinfo);

        fprintf(fp, "%s,%u,%.2f,%.2f\n", timestamp_str, co2, temperature, humidity);
    }

    // Flush the buffer to disk
    fflush(fp);

    // Close the file
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, stopping...");
    running = 0;
}

// Create the log directory if it doesn't exist
int create_log_directory() {
    if (access("/var/log/scd40_data", F_OK) == -1) {
        if (mkdir("/var/log/scd40_data", 0777) != 0) {
            syslog(LOG_ERR, "Failed to create log directory: %s", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main() {
    // Open syslog
    openlog("scd40_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Create the log directory
    if (create_log_directory() != 0) {
        syslog(LOG_ERR, "Failed to create log directory, exiting");
        closelog();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        syslog(LOG_ERR, "I2C initialization failed, exiting");
        closelog();
        return 1;
    }

    // Start periodic measurement
    if (send_command(START_PERIODIC_MEASUREMENT) != 0) {
        syslog(LOG_ERR, "Failed to start periodic measurement, exiting");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        // Read measurement
        uint8_t data[9];
        if (send_command(READ_MEASUREMENT) != 0) {
            syslog(LOG_ERR, "Failed to send read measurement command, retrying...");
            sleep(1);
            continue;
        }
        if (read_data(data, 9) != 0) {
            syslog(LOG_ERR, "Failed to read measurement data, retrying...");
            sleep(1);
            continue;
        }

        // Validate CRC
        if (validate_crc(data, 8) != 0) {
            syslog(LOG_ERR, "CRC validation failed, skipping reading");
            sleep(1);
            continue;
        }

        // Convert data
        sensor_reading_t reading;
        if (convert_data(data, &reading) != 0) {
            syslog(LOG_ERR, "Failed to convert data, skipping reading");
            sleep(1);
            continue;
        }

        // Add reading to buffer
        add_reading(reading);

        // Write buffer to file every 60 seconds
        if (time(NULL) % 60 == 0) {
            if (write_buffer_to_file() != 0) {
                syslog(LOG_ERR, "Failed to write buffer to file");
            }
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Stop periodic measurement
    if (send_command(STOP_PERIODIC_MEASUREMENT) != 0) {
        syslog(LOG_ERR, "Failed to stop periodic measurement");
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

