#define CMD_CONTINUOUS 0x362F
#define LOG_FILE "sdp810_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} SensorData;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, SensorData *data) {
    uint8_t buffer[9];
    int result;

    // Send continuous measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, CMD_CONTINUOUS); // No register address needed for SDP810
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for at least 45 ms
    gpioDelay(45000); // 45 ms

    // Read 9 bytes from the sensor
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Extract raw values
    uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    uint16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    uint16_t scale_factor = (buffer[6] << 8) | buffer[7];

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert to physical units
    data->pressure_Pa = (float)raw_pressure * scale_factor / 1000.0;
    data->temperature_C = -45.0 + 175.0 * (float)raw_temperature / 65535.0;

    return 0;
}

// Function to log data to a file
void log_data(FILE *log_file, float pressure_Pa, float temperature_C) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_Pa, temperature_C);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

