        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int32_t raw_pressure, raw_temperature;

        // Read sensor data
        if (read_sensor_data(&raw_pressure, &raw_temperature) == 0) {
            // Convert data
            sensor_data.pressure_hpa = convert_pressure(raw_pressure);
            sensor_data.temperature_celsius = convert_temperature(raw_temperature);

            // Log data
            if (log_data(sensor_data.pressure_hpa, sensor_data.temperature_celsius) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Print data to stdout
            printf("Pressure: %.2f hPa, Temperature: %.2f C\n", sensor_data.pressure_hpa, sensor_data.temperature_celsius);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

