#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x63
#define LED_PIN 17 // BCM numbering
#define PRESSURE_THRESHOLD 95000.0 // Pa
#define MEASUREMENT_COMMAND 0x4011
#define MEASUREMENT_DELAY_MS 20
#define SAMPLE_INTERVAL_S 1
#define LED_ON_TIME_MS 500
#define LED_OFF_TIME_MS 500
#define WARNING_LED_ON_TIME_MS 100
#define WARNING_LED_OFF_TIME_MS 100

// Calibration Coefficients
typedef struct {
    int16_t c0;
    int16_t c1;
    int16_t c00;
    int16_t c10;
    int16_t c01;
    int16_t c11;
    int16_t c20;
    int16_t c21;
} calibration_coeffs_t;

// Global variables
int i2c_fd = -1;
struct gpiod_line *led_line = NULL;
calibration_coeffs_t coeffs;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
int read_calibration_coefficients(int fd, calibration_coeffs_t *coeffs);
int trigger_measurement(int fd);
int read_sensor_data(int fd, uint32_t *pressure_raw, uint32_t *temperature_raw);
double calculate_pressure(uint32_t pressure_raw, uint32_t temperature_raw, calibration_coeffs_t coeffs);
double calculate_temperature(uint32_t temperature_raw, calibration_coeffs_t coeffs);
void control_led(int gpio, int state);
void signal_handler(int sig);

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (data == NULL || len <= 0) return -1;
    if (fd < 0) return -1;

    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    if (fd < 0) return -1;
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// Read calibration coefficients from OTP memory
int read_calibration_coefficients(int fd, calibration_coeffs_t *coeffs) {
    uint8_t data[14];

    if (i2c_read_bytes(fd, 0x66, data, 14) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return -1;
    }

    coeffs->c0 = (data[0] << 8) | data[1];
    coeffs->c1 = (data[2] << 8) | data[3];
    coeffs->c00 = (data[4] << 8) | data[5];
    coeffs->c10 = (data[6] << 8) | data[7];
    coeffs->c01 = (data[8] << 8) | data[9];
    coeffs->c11 = (data[10] << 8) | data[11];
    coeffs->c20 = (data[12] << 8) | data[13];

    return 0;
}

// Trigger a measurement
int trigger_measurement(int fd) {
    if (i2c_write_byte(fd, 0x00, MEASUREMENT_COMMAND) != 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int fd, uint32_t *pressure_raw, uint32_t *temperature_raw) {
    uint8_t data[6];

    if (i2c_read_bytes(fd, 0x00, data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    *pressure_raw = (data[0] << 16) | (data[1] << 8) | data[2];
    *temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5];

    return 0;
}

// Calculate pressure in Pascals
double calculate_pressure(uint32_t pressure_raw, uint32_t temperature_raw, calibration_coeffs_t coeffs) {
    double p = (double)pressure_raw;
    double t = (double)temperature_raw;

    double c0 = (double)coeffs.c0;
    double c1 = (double)coeffs.c1;
    double c00 = (double)coeffs.c00;
    double c10 = (double)coeffs.c10;
    double c01 = (double)coeffs.c01;
    double c11 = (double)coeffs.c11;
    double c20 = (double)coeffs.c20;

    double p_cal = c00 + c10 * p + c01 * t + c20 * p * p;

    return p_cal;
}

// Calculate temperature in Celsius
double calculate_temperature(uint32_t temperature_raw, calibration_coeffs_t coeffs) {
    double t = (double)temperature_raw;

    double c0 = (double)coeffs.c0;
    double c1 = (double)coeffs.c1;
    double c00 = (double)coeffs.c00;
    double c10 = (double)coeffs.c10;
    double c01 = (double)coeffs.c01;
    double c11 = (double)coeffs.c11;
    double c20 = (double)coeffs.c20;

    double t_cal = c0 + c1 * t + c00 + c10 * t + c01 * t + c11 * t + c20 * t;

    return t_cal;
}

// Control the LED
void control_led(int gpio, int state) {
    if (led_line == NULL) return; // Ensure LED line is initialized

    int ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        perror("Failed to set LED state");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_fd, &coeffs) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Request LED line
    led_line = gpiod_chip_open_by_number(0, "gpiochip0");
    if (!led_line) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "pressure_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(led_line, LED_PIN, &config, 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(led_line);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint32_t pressure_raw, temperature_raw;
        double pressure, temperature;

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in %d seconds.\n", SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        // Delay for measurement
        usleep(MEASUREMENT_DELAY_MS * 1000); // Convert ms to microseconds

        // Read sensor data
        if (read_sensor_data(i2c_fd, &pressure_raw, &temperature_raw) != 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        // Calculate pressure and temperature
        pressure = calculate_pressure(pressure_raw, temperature_raw, coeffs);
        temperature = calculate_temperature(temperature_raw, coeffs);

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Control LED based on pressure
        if (pressure < PRESSURE_THRESHOLD) {
            // Warning LED
            control_led(LED_PIN, 1); // Turn on LED
            usleep(WARNING_LED_ON_TIME_MS * 1000);
            control_led(LED_PIN, 0); // Turn off LED
            usleep(WARNING_LED_OFF_TIME_MS * 1000);
        } else {
            // Normal LED
            control_led(LED_PIN, 1); // Turn on LED
            usleep(LED_ON_TIME_MS * 1000);
            control_led(LED_PIN, 0); // Turn off LED
            usleep(LED_OFF_TIME_MS * 1000);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_S);
    }

    // Cleanup (should not reach here in normal operation due to the while loop)
    gpiod_line_release(led_line);
    close(i2c_fd);

    return 0;
}

