#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define OBJECT_TEMP_THRESHOLD_HIGH 30.0
#define OBJECT_TEMP_THRESHOLD_LOW 28.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int read_raw_temperature(int handle, int reg);
float convert_to_celsius(int raw_temp);
int control_fan(float object_temp);
int log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read raw temperature data from the sensor
int read_raw_temperature(int handle, int reg) {
    int raw_temp = i2cReadWordData(handle, reg);
    if (raw_temp < 0) {
        fprintf(stderr, "Failed to read temperature data from register 0x%02X: %d\n", reg, raw_temp);
        return -1;
    }
    return raw_temp;
}

// Convert raw temperature data to Celsius
float convert_to_celsius(int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Control the cooling fan based on object temperature
int control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > OBJECT_TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan turned ON\n");
    } else if (object_temp < OBJECT_TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF\n");
    }
    return 0;
}

// Log temperature data to file
int log_temperature(float ambient_temp, float object_temp) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, ambient_temp, object_temp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

