#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <time.h>

#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SERVER_PORT 8080

// Structure to hold temperature and humidity data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Global variables for graceful shutdown
int i2c_handle = -1;
int server_fd = -1;

// Function prototypes
int init_i2c();
SensorData read_sensor_data(int i2c_handle);
char* format_html(SensorData data);
int start_server(int port);
void handle_client(int client_socket);
void signal_handler(int signal);

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data from the SHT40 sensor
SensorData read_sensor_data(int i2c_handle) {
    SensorData data;
    unsigned char buf[6];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        if (i2cWriteByte(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(10); // Wait for measurement (at least 10ms)

        // Read 6 bytes of data
        bytes_read = i2cReadDevice(i2c_handle, buf, 6);
        if (bytes_read != 6) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d bytes read\n", retries + 1, bytes_read);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned short raw_temperature = (buf[0] << 8) | buf[1];
        unsigned short raw_humidity = (buf[3] << 8) | buf[4];

        data.temperature = -45.0 + 175.0 * (raw_temperature / 65535.0);
        data.humidity = -6.0 + 125.0 * (raw_humidity / 65535.0);
        if (data.humidity < 0.0) data.humidity = 0.0;
        if (data.humidity > 100.0) data.humidity = 100.0;

        return data;
    }

    // If all retries failed, return default values and log an error
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    data.temperature = -999.0; // Indicate error
    data.humidity = -999.0;    // Indicate error
    return data;
}

// Function to format the sensor data into an HTML page
char* format_html(SensorData data) {
    char* html = malloc(256); // Allocate memory for the HTML string
    if (html == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    snprintf(html, 256, "<html><body><h1>Temperature: %.2f &deg;C</h1><h1>Humidity: %.2f %%</h1></body></html>", data.temperature, data.humidity);
    return html;
}

// Function to start the HTTP server
int start_server(int port) {
    int server_fd;
    struct sockaddr_in address;
    int opt = 1;

    // Create socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    // Bind the socket to the specified port
    if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }
    return server_fd;
}

// Function to handle incoming client connections
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    char* html_page = NULL;
    SensorData sensor_data;

    // Receive data from the client
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0'; // Null-terminate the received data

    // Check if the client sent a GET request for the root URL
    if (strstr(buffer, "GET /") != NULL) {
        // Read sensor data
        sensor_data = read_sensor_data(i2c_handle);

        // Format HTML page
        if (sensor_data.temperature != -999.0 && sensor_data.humidity != -999.0) {
            html_page = format_html(sensor_data);
            if (html_page != NULL) {
                // Send the HTML page to the client
                send(client_socket, html_page, strlen(html_page), 0);
                free(html_page); // Free the allocated memory
            } else {
                fprintf(stderr, "Failed to format HTML page\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Returning default values.\n");
            char *default_html = "<html><body><h1>Failed to read sensor data</h1></body></html>";
            send(client_socket, default_html, strlen(default_html), 0);
        }
    } else {
        fprintf(stderr, "Invalid request received: %s\n", buffer);
        const char *error_response = "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n";
        send(client_socket, error_response, strlen(error_response), 0);
    }

    // Close the client socket
    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start the HTTP server
    server_fd = start_server(SERVER_PORT);
    if (server_fd < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("HTTP server started on port %d\n", SERVER_PORT);

    // Accept incoming connections and handle them
    struct sockaddr_in client_address;
    int client_socket;
    socklen_t client_len = sizeof(client_address);

    while (1) {
        client_socket = accept(server_fd, (struct sockaddr*)&client_address, &client_len);
        if (client_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for new connections
        }

        handle_client(client_socket);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

