#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG 0x0E
#define MEASUREMENT_STATUS 0x0B
#define TEMPERATURE_MSB 0x00
#define TEMPERATURE_LSB 0x01
#define HUMIDITY_MSB 0x02
#define HUMIDITY_LSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.temperature, &sensor_data.humidity) == 0) {
            // Log the data
            log_data(sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure the sensor
int configure_sensor() {
    // Set heater disabled and 14-bit resolution
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG\n");
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    int retry_count = 0;
    int status;

    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return 1;
    }

    // Wait for measurement to complete (polling MEASUREMENT_STATUS bit 0)
    while (retry_count < 10) {
        status = i2cReadByteData(i2c_handle, MEASUREMENT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_STATUS: %d\n", status);
            return 1;
        }

        if ((status & 0x01) == 0) {
            break; // Measurement complete
        } else {
            gpioDelay(100); // Wait 100 us
            retry_count++;
        }
    }

    if (retry_count >= 10) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return 1;
    }

    // Read temperature and humidity data
    uint16_t raw_temperature = i2cReadWordData(i2c_handle, TEMPERATURE_MSB);
    uint16_t raw_humidity = i2cReadWordData(i2c_handle, HUMIDITY_MSB);

    if (raw_temperature < 0 || raw_humidity < 0) {
        fprintf(stderr, "Error reading temperature or humidity data\n");
        return 1;
    }

    // Convert to Celsius and percentage relative humidity
    *temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
    *humidity = (float)raw_humidity / 65536.0 * 100.0;

    return 0;
}

// Log data to console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed, exiting...\n");
}

