#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25

// Define the continuous measurement command
#define MEASUREMENT_COMMAND 0x362F

// Define the CRC-8 checksum polynomial
#define CRC_POLYNOMIAL 0x31

// Global variable for the I2C handle
int i2c_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate the CRC-8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Send the continuous measurement command
        if (i2cWriteWordData(i2c_handle, MEASUREMENT_COMMAND >> 8, MEASUREMENT_COMMAND & 0xFF) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Wait for the measurement to complete (45 ms)
        gpioDelay(45000); // Delay in microseconds

        // Read 6 bytes of data from the sensor
        unsigned char data[6];
        if (i2cReadDevice(i2c_handle, data, 6) != 6) {
            fprintf(stderr, "Failed to read data from sensor\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Extract the raw pressure and temperature values
        int16_t pressure = (data[0] << 8) | data[1];
        int16_t temperature = (data[3] << 8) | data[4];

        // Print the raw pressure and temperature values
        printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);

        // Wait for 500 ms
        gpioDelay(500000); // Delay in microseconds
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

