#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0 // CE0 or CE1
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define TARGET_TEMP_FILE "profile.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static int target_temperature = 0; // Current target temperature
static int profile_index = 0; // Current profile index

// Function Prototypes
int read_target_temperature(const char *filename);
float read_thermocouple_temperature();
float calculate_pid(float current_temperature, float target_temperature, float *integral, float *previous_error);
void set_relay_duty_cycle(float duty_cycle);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read target temperature from file
int read_target_temperature(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open profile file %s\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read profile from file %s\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid format in profile file %s\n", filename);
        return -1;
    }

    char *endptr;
    target_temperature = strtol(token, &endptr, 10);
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid temperature value in profile file %s\n", filename);
        return -1;
    }

    token = strtok(NULL, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing time value in profile file %s\n", filename);
        return -1;
    }

    char *endptr;
    int time_seconds = strtol(token, &endptr, 10);
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid time value in profile file %s\n", filename);
        return -1;
    }

    if (time_seconds < 0 || time_seconds > 3600) {
        fprintf(stderr, "Error: Time value out of range in profile file %s\n", filename);
        return -1;
    }

    return 0;
}

// Function to read temperature from MAX6675 via SPI
float read_thermocouple_temperature() {
    unsigned char data[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spiRead(spi_handle, data, 2) == 2) {
            // Check for open circuit
            if (data[1] & 0x04) {
                fprintf(stderr, "Error: Thermocouple open circuit\n");
                return -273.15; // Return absolute zero as error indicator
            }

            // Combine the two bytes into a 16-bit value
            int16_t raw_temperature = ((data[0] << 8) | data[1]) >> 4;

            // Convert to Celsius (assuming 0.25 degree resolution)
            float temperature = (float)raw_temperature * 0.25;

            return temperature;
        } else {
            fprintf(stderr, "Error: SPI read failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Error: SPI read failed after %d retries\n", MAX_RETRIES);
    return -273.15; // Return absolute zero as error indicator
}

// Function to calculate PID output
float calculate_pid(float current_temperature, float target_temperature, float *integral, float *previous_error) {
    float error = target_temperature - current_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
