int read_target_temperature(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open profile file %s\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read profile from file %s\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid format in profile file %s\n", filename);
        return -1;
    }

    char *endptr;
    target_temperature = strtol(token, &endptr, 10);
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid temperature value in profile file %s\n", filename);
        return -1;
    }

    token = strtok(NULL, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing time value in profile file %s\n", filename);
        return -1;
    }

    char *endptr;
    int time_seconds = strtol(token, &endptr, 10);
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid time value in profile file %s\n", filename);
        return -1;
    }

