#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define NUM_SENSORS 3
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL 5 // seconds

// Default values
#define DEFAULT_SETPOINT 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01

// Global variables
static volatile int keep_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *heater_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static float setpoint = DEFAULT_SETPOINT;
static float kp = DEFAULT_KP;
static float ki = DEFAULT_KI;
static float kd = DEFAULT_KD;
static float integral = 0.0;
static float previous_error = 0.0;

// Function prototypes
float read_temperature(int sensor_id);
float calculate_pid(float setpoint, float actual_temperature, float kp, float ki, float kd, float *integral, float *previous_error);
void set_heater_state(int state);
void set_pwm_duty_cycle(float duty_cycle);
void log_data(float avg_temperature, float setpoint, float pid_output, float duty_cycle);
void signal_handler(int sig);
int initialize_gpio();
void cleanup_gpio();
int initialize_log_file();

// Function to read temperature from a DS18B20 sensor
float read_temperature(int sensor_id) {
    char filepath[256];
    FILE *fp;
    char buffer[256];
    float temperature = -1000.0; // Initialize to an invalid value
    int crc_error = 0;

    snprintf(filepath, sizeof(filepath), "/sys/bus/w1/devices/%d/w1_slave", sensor_id);

    fp = fopen(filepath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return temperature; // Return invalid temperature
    }

    // Read the file twice to ensure we get the latest data
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading from %s: %s\n", filepath, strerror(errno));
        fclose(fp);
        return temperature;
    }
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading from %s: %s\n", filepath, strerror(errno));
        fclose(fp);
        return temperature;
    }

    fclose(fp);

    // Check for CRC error
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC error on sensor %d\n", sensor_id);
        crc_error = 1;
    }

    if (!crc_error) {
        // Extract temperature from the second line
        char *temp_str = strstr(buffer, "t=");
        if (temp_str != NULL) {
            long temp_reading = strtol(temp_str + 2, NULL, 10);
            temperature = (float)temp_reading / 1000.0;
        }
    }

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float kp, float ki, float kd, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set the heater state (ON/OFF)
void set_heater_state(int state) {
    if (gpiod_line_set_value(heater_line, state) < 0) {
        fprintf(stderr, "Error setting heater state: %s\n", strerror(errno));
    }
}

// Function to set the PWM duty cycle
void set_pwm_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;

    int on_time = (int)((duty_cycle / 100.0) * 1000000.0); // Convert to microseconds
    int off_time = 1000000.0 - on_time; // Remaining time

    if (gpiod_line_set_value(pwm_line, 1) < 0) {
        fprintf(stderr, "Error setting PWM on: %s\n", strerror(errno));
    }
    usleep(on_time);
    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        fprintf(stderr, "Error setting PWM off: %s\n", strerror(errno));
    }
    usleep(off_time);
}

// Function to log data to a file
void log_data(float avg_temperature, float setpoint, float pid_output, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, avg_temperature, setpoint, pid_output, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, shutting down...\n");
    keep_running = 0;
}

// Function to initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    heater_line = gpiod_chip_get_line(chip, HEATER_GPIO);
    if (!heater_line) {
        fprintf(stderr, "Error getting heater GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!pwm_line) {
        fprintf(stderr, "Error getting PWM GPIO line: %s\n", strerror(errno));
        gpiod_line_release(heater_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(heater_line, "greenhouse", 0) < 0) {
        fprintf(stderr, "Error requesting heater GPIO line: %s\n", strerror(errno));
        gpiod_line_release(pwm_line);
        gpiod_line_release(heater_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(pwm_line, "greenhouse", 0) < 0) {
        fprintf(stderr, "Error requesting PWM GPIO line: %s\n", strerror(errno));
        gpiod_line_release(heater_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio() {
    if (heater_line) {
        gpiod_line_release(heater_line);
    }
    if (pwm_line) {
        gpiod_line_release(pwm_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to initialize the log file
int initialize_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:k:i:d:")) != -1) {
        switch (opt) {
            case 's':
                setpoint = atof(optarg);
                break;
            case 'k':
                kp = atof(optarg);
                break;
            case 'i':
                ki = atof(optarg);
                break;
            case 'd':
                kd = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s setpoint] [-k kp] [-i ki] [-d kd]\n", argv[0]);
                return 1;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize log file
    if (initialize_log_file() < 0) {
        cleanup_gpio();
        return 1;
    }

    // Set initial states
    set_heater_state(0); // Turn off heater initially
    set_pwm_duty_cycle(0.0); // Set PWM to 0

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperatures[NUM_SENSORS];
    float sum = 0.0;
    int sensor_count = 0;

    while (keep_running) {
        // Read temperatures from sensors
        for (int i = 0; i < NUM_SENSORS; i++) {
            temperatures[i] = read_temperature(i);
            if (temperatures[i] < -900.0) {
                fprintf(stderr, "Error reading from sensor %d, skipping\n", i);
                continue; // Skip sensor if reading fails
            }
            sum += temperatures[i];
            sensor_count++;
        }

        // Calculate average temperature
        float avg_temperature = 0.0;
        if (sensor_count > 0) {
            avg_temperature = sum / sensor_count;
        } else {
            avg_temperature = -1000.0; // Indicate no sensors
        }

        // Calculate PID output
        float pid_output = calculate_pid(setpoint, avg_temperature, kp, ki, kd, &integral, &previous_error);

        // Limit PID output to 0-100
        if (pid_output < 0.0) pid_output = 0.0;
        if (pid_output > 100.0) pid_output = 100.0;

        // Set PWM duty cycle based on PID output
        set_pwm_duty_cycle(pid_output);

        // Set heater state based on PID output
        if (pid_output > 0.0) {
            set_heater_state(1);
        } else {
            set_heater_state(0);
        }

        // Log data
        log_data(avg_temperature, setpoint, pid_output, pid_output);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    set_heater_state(0); // Turn off heater
    set_pwm_duty_cycle(0.0); // Set PWM to 0
    cleanup_gpio();
    fclose(log_file);

    return 0;
}

