#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_TRIGGER 0xAC
#define MEASUREMENT_COMMAND 0xBE
#define MEASUREMENT_COMMAND_2 0x08
#define MEASUREMENT_COMMAND_3 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLLING_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init();
int aht20_trigger_measurement();
int aht20_read_data(unsigned char *data);
float aht20_calculate_humidity(unsigned char *data);
int control_dehumidifier(float humidity);
void log_data(float humidity, int dehumidifier_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// AHT20 initialization function
int aht20_init() {
    char init_cmd[3] = {MEASUREMENT_COMMAND, MEASUREMENT_COMMAND_2, MEASUREMENT_COMMAND_3};
    int result;

    result = i2cWriteDevice(i2c_handle, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error initializing AHT20: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for initialization to complete
    return 0;
}

// AHT20 trigger measurement function
int aht20_trigger_measurement() {
    char trigger_cmd[3] = {MEASUREMENT_COMMAND, MEASUREMENT_COMMAND_2, MEASUREMENT_COMMAND_3};
    int result;

    result = i2cWriteDevice(i2c_handle, trigger_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(80); // Wait for measurement to complete
    return 0;
}

// AHT20 read data function
int aht20_read_data(unsigned char *data) {
    int result;
    unsigned char status_byte;

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    status_byte = data[0];
    if (status_byte != 0x00) {
        fprintf(stderr, "Error: Sensor not calibrated or busy (status byte: 0x%02X)\n", status_byte);
        return -1;
    }

    return 0;
}

// AHT20 calculate humidity function
float aht20_calculate_humidity(unsigned char *data) {
    unsigned long humidity_raw = ((unsigned long)data[1] << 12) | ((unsigned long)data[2] << 4) | (data[3] >> 4);
    float humidity = ((float)humidity_raw / 0x100000) * 100.0;
    return humidity;
}

// Dehumidifier control function
int control_dehumidifier(float humidity) {
    int dehumidifier_state = 0;

    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(GPIO_DEHUMIDIFIER, 1); // Activate dehumidifier
        dehumidifier_state = 1;
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(GPIO_DEHUMIDIFIER, 0); // Deactivate dehumidifier
        dehumidifier_state = 0;
    }
    return dehumidifier_state;
}

// Data logging function
