    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Humidity: %.2f%%, Dehumidifier: %s\n", timestamp, humidity, dehumidifier_state ? "ON" : "OFF");
}

