    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init() != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for dehumidifier control
    gpioSetMode(GPIO_DEHUMIDIFIER, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (aht20_trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Read data
        if (aht20_read_data(data) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate humidity
        humidity = aht20_calculate_humidity(data);

        // Control dehumidifier
        dehumidifier_state = control_dehumidifier(humidity);

        // Log data
        log_data(humidity, dehumidifier_state);

        // Wait before next measurement
        gpioDelay(500); // 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_DEHUMIDIFIER, 0); // Ensure dehumidifier is off
    gpioTerminate();

    return 0;
}

