#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define SERVER_URL "http://api.example.com/humidity"
#define LOG_FILE "/var/log/humidity_sensor.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 1

// Global variables
int i2c_fd = -1;
int socket_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    int status;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus);
int i2c_read_bytes(int fd, unsigned char *buf, int count);
int i2c_write_byte(int fd, unsigned char data);
int i2c_close(int fd);
int read_htu21d_data(int fd, float *humidity);
int post_humidity_data(const char *url, float humidity);
void signal_handler(int sig);
void log_message(int priority, const char *message);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, unsigned char *buf, int count) {
    if (count <= 0) return 0; // Avoid unnecessary operations

    int bytes_read = read(fd, buf, count);
    if (bytes_read < 0) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    } else if (bytes_read != count) {
        syslog(LOG_WARNING, "I2C read short read, expected %d, got %d", count, bytes_read);
        return -1; // Indicate short read
    }
    return bytes_read;
}

// I2C write byte function
int i2c_write_byte(int fd, unsigned char data) {
    int result = write(fd, &data, 1);
    if (result != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        syslog(LOG_ERR, "Failed to close I2C device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Read HTU21D data function
int read_htu21d_data(int fd, float *humidity) {
    unsigned char buf[3];
    int retries = 0;

    // Trigger measurement (no clock stretching)
    if (i2c_write_byte(fd, 0xE0) < 0) {
        syslog(LOG_ERR, "Failed to trigger measurement");
        return -1;
    }

    // Wait for measurement to complete (datasheet recommends at least 50ms)
    usleep(60000); // 60ms

    while (retries < MAX_RETRIES) {
        if (i2c_read_bytes(fd, buf, 3) == 3) {
            // Check status bit (bit 7 of byte 0)
            if (buf[0] & 0x80) {
                syslog(LOG_WARNING, "HTU21D busy");
                retries++;
                usleep(RETRY_DELAY_SEC * 1000000); // Exponential backoff
                continue;
            }

            // Convert raw data to humidity
            unsigned int raw_humidity = ((unsigned int)buf[0] << 8 | (unsigned int)buf[1]) & 0x3FFF; // Mask out status bit
            *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
            return 0; // Success
        } else {
            syslog(LOG_ERR, "Failed to read HTU21D data, retry %d", retries + 1);
            retries++;
            usleep(RETRY_DELAY_SEC * 1000000); // Exponential backoff
        }
    }

    syslog(LOG_ERR, "Failed to read HTU21D data after %d retries", MAX_RETRIES);
    return -1; // Failure
}

// Post humidity data function
int post_humidity_data(const char *url, float humidity) {
    struct sockaddr_in server_addr;
    char json_data[50];
    int retries = 0;

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    while (retries < MAX_RETRIES) {
        socket_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (socket_fd < 0) {
            syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_SEC * 1000000);
            continue;
        }

        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(80); // Assuming HTTP port 80
        if (inet_pton(AF_INET, url, &server_addr.sin_addr) <= 0) {
            syslog(LOG_ERR, "Invalid address/ Address not supported: %s", url);
            close(socket_fd);
            retries++;
            usleep(RETRY_DELAY_SEC * 1000000);
            continue;
        }

        if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
            close(socket_fd);
            retries++;
            usleep(RETRY_DELAY_SEC * 1000000);
            continue;
        }

        // Simple HTTP POST (replace with a proper library for real use)
        char post_data[256];
        snprintf(post_data, sizeof(post_data), "POST %s HTTP/1.1\r\n" \
                                         "Host: %s\r\n" \
                                         "Content-Type: application/json\r\n" \
                                         "Content-Length: %ld\r\n" \
                                         "Connection: close\r\n" \
                                         "\r\n" \
                                         "%s",
                 url, inet_ntoa(server_addr.sin_addr), strlen(json_data), json_data);

        if (send(socket_fd, post_data, strlen(post_data), 0) < 0) {
            syslog(LOG_ERR, "Failed to send data: %s", strerror(errno));
            close(socket_fd);
            retries++;
            usleep(RETRY_DELAY_SEC * 1000000);
