#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS 1
#define I2C_RETRY_COUNT 3
#define I2C_BACKOFF_MS 10
#define MOTION_DEBOUNCE_MS 500

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int init_aht20();
int read_temperature(float *temperature);
int read_humidity(float *humidity);
int read_motion();
void log_data(float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
void cleanup();
char* get_timestamp();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int motion_detected;
} sensor_data_t;

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Optional pull-down resistor
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0); // Open I2C device
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize AHT20 sensor
int init_aht20() {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int result = i2cWriteDevice(i2c_handle, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to send AHT20 initialization command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(20); // Wait for initialization (datasheet specifies 20ms)
    return 0;
}

// Function to read temperature from TMP117
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
        return -1;
    }

    int raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp * 0.0078125;
    return 0;
}

// Function to read humidity from AHT20
int read_humidity(float *humidity) {
    char cmd[3] = {0xAC, 0x33, 0x00};
    char buf[7];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to send AHT20 measurement command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(80); // Wait for measurement (datasheet specifies 80ms)

    result = i2cReadDevice(i2c_handle, buf, 7);
    if (result != 7) {
        fprintf(stderr, "Failed to read humidity data: %s\n", strerror(errno));
        return -1;
    }

    // Check for busy bit
    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 busy\n");
        return -1;
    }

    // Extract humidity data (20 bits)
    int raw_humidity = ((buf[1] << 12) | (buf[2] << 4) | (buf[3] >> 4));
    *humidity = (float)raw_humidity * 100.0 / 1048576.0;
    return 0;
}

// Function to read motion from PIR sensor
int read_motion() {
    int motion = gpioRead(PIR_GPIO);
    gpioDelay(MOTION_DEBOUNCE_MS); // Debounce
    return motion;
}

// Function to log data to CSV file
void log_data(float temperature, float humidity, int motion_detected) {
    char* timestamp = get_timestamp();
    fprintf(log_file, "%s,%.4f,%.4f,%d\n", timestamp, temperature, humidity, motion_detected);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize AHT20 sensor
    if (init_aht20() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    char filename[50];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "sensor_data_%Y-%m-%d.csv", timeinfo);
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    }
    fflush(log_file);

    float temperature, humidity;
    int motion_detected;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_temperature(&temperature) == 0 && read_humidity(&humidity) == 0) {
            // Read motion
            motion_detected = read_motion();

            // Log data
            log_data(temperature, humidity, motion_detected);

            printf("Temperature: %.4f C, Humidity: %.4f %%, Motion: %d\n", temperature, humidity, motion_detected);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

