#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int enable, int in1, int in2, int duration);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received signal, shutting down...");
    }
}

// Function to read the rain sensor
int read_rain_sensor() {
    int rain_detected = gpioRead(RAIN_SENSOR_PIN);
    if (rain_detected < 0) {
        log_event("Error reading rain sensor");
        return -1; // Indicate error
    }
    return rain_detected;
}

// Function to control the motor
void control_motor(int enable, int in1, int in2, int duration) {
    if (gpioWrite(enable, enable) < 0) {
        log_event("Error writing to motor enable pin");
        return;
    }

    if (gpioWrite(in1, 1) < 0) {
        log_event("Error writing to motor IN1 pin");
        gpioWrite(enable, 0); // Stop motor if IN1 write fails
        return;
    }
    if (gpioWrite(in2, 0) < 0) {
        log_event("Error writing to motor IN2 pin");
        gpioWrite(enable, 0); // Stop motor if IN2 write fails
        return;
    }

    log_event("Motor started");
    gpioDelay(duration * 1000000); // Delay for specified duration (microseconds)
    gpioWrite(in1, 0); // Stop motor
    gpioWrite(in2, 0); // Stop motor
    gpioWrite(enable, 0); // Stop motor
    log_event("Motor stopped");
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        log_event("Error setting rain sensor pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0) {
        log_event("Error setting motor enable pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        log_event("Error setting motor IN1 pin mode");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        log_event("Error setting motor IN2 pin mode");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 0) {
            log_event("Rain detected, starting motor");
            control_motor(1, 1, 0, MOTOR_RUN_TIME); // Enable motor, IN1 HIGH, IN2 LOW
        } else if (rain_detected > 0) {
            log_event("No rain detected, stopping motor");
            control_motor(0, 1, 0, 0); // Disable motor
        } else {
            log_event("Error reading rain sensor, skipping motor control");
        }

        sleep(2); // Poll every 2 seconds
    }

    // Clean up and exit
    log_event("Cleaning up and exiting");
    gpioWrite(MOTOR_ENABLE_PIN, 0); // Ensure motor is stopped
    gpioTerminate(); // Terminate pigpio
    return 0;
}

