// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read CPU load from /proc/stat
float read_cpu_load() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float cpu_load;

    // Read current CPU stats
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1.0; // Indicate error
    }
    fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
           &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);
    fclose(fp);

    // Read previous CPU stats (1 second ago)
    char prev_path[50];
    snprintf(prev_path, sizeof(prev_path), "/proc/stat/cpu/%s", "prev");
    fp = fopen(prev_path, "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat/cpu/prev");
        return -1.0; // Indicate error
    }
    fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
           &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice);
    fclose(fp);

    // Calculate CPU load
    unsigned long long prev_idle = prev_idle + prev_iowait;
    unsigned long long prev_non_idle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long long idle = idle + iowait;
    unsigned long long non_idle = user + nice + system + irq + softirq + steal + guest + guest_nice;
    unsigned long long totald = (unsigned long long)(non_idle - prev_non_idle);
    unsigned long long idled = (unsigned long long)(idle - prev_idle);

    cpu_load = (float)(totald - idled) / totald;

    return cpu_load;
}

// Function to map CPU load to RGB color values
void map_cpu_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load < 0.0) {
        cpu_load = 0.0;
    } else if (cpu_load > 1.0) {
        cpu_load = 1.0;
    }

    // Linear interpolation
    *red   = (int)(255.0 * (1.0 - cpu_load));
    *green = (int)(255.0 * cpu_load);
    *blue  = 0;
}

// Function to set the RGB LED color using pigpio PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN,   red   > 255 ? 255 : (red   < 0 ? 0 : red   ));
    gpioPWM(GREEN_PIN, green > 255 ? 255 : (green > 0 ? green : 0));
    gpioPWM(BLUE_PIN,  blue  > 255 ? 255 : (blue  > 0 ? blue  : 0));
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM range to 255
    gpioSetPWMrange(RED_PIN,   255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    int red, green, blue;
    float cpu_load;

    // Main loop
    while (!terminate) {
        // Read CPU load
        cpu_load = read_cpu_load();

        if (cpu_load < 0.0) {
            fprintf(stderr, "Error reading CPU load, exiting...\n");
            break;
        }

        // Map CPU load to RGB color values
        map_cpu_load_to_color(cpu_load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Wait for 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Turn off the LED (common anode, so set all pins low)
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

