#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255
#define TEMP_THRESHOLD_1 25.0
#define TEMP_THRESHOLD_2 40.0
#define TEMP_THRESHOLD_3 60.0
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
int buffer_index = 0;
int buffer_full = 0;
int running = 1;

// Structure for circular buffer
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

// Function prototypes
int initialize();
int read_max31855(uint8_t *data);
float extract_thermocouple_temp(uint8_t *data);
int check_fault(uint8_t *data);
int set_fan_speed(float temperature);
void add_to_buffer(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read data from MAX31855 via SPI
int read_max31855(uint8_t *data) {
    int result = spiXfer(spi_handle, data, data, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return 1;
    }
    return 0;
}

// Function to extract the thermocouple temperature from the data
float extract_thermocouple_temp(uint8_t *data) {
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    return raw_temp * 0.25;
}

// Function to check for faults in the MAX31855 data
int check_fault(uint8_t *data) {
    if (data[3] & 0x07) {
        fprintf(stderr, "MAX31855 Fault: ");
        if (data[3] & 0x01) fprintf(stderr, "Open Circuit ");
        if (data[3] & 0x02) fprintf(stderr, "Short to GND ");
        if (data[3] & 0x04) fprintf(stderr, "Short to VCC ");
        fprintf(stderr, "\n");
        return 1;
    }
    return 0;
}

// Function to set the fan speed based on temperature
int set_fan_speed(float temperature) {
    int duty_cycle = 0;

    if (temperature < TEMP_THRESHOLD_1) {
        duty_cycle = 0;
    } else if (temperature < TEMP_THRESHOLD_2) {
        duty_cycle = (int)((temperature - TEMP_THRESHOLD_1) / (TEMP_THRESHOLD_2 - TEMP_THRESHOLD_1) * PWM_RANGE);
    } else if (temperature < TEMP_THRESHOLD_3) {
        duty_cycle = 50 + (int)((temperature - TEMP_THRESHOLD_2) / (TEMP_THRESHOLD_3 - TEMP_THRESHOLD_2) * (PWM_RANGE - 50));
    } else {
        duty_cycle = 100 + (int)((temperature - TEMP_THRESHOLD_3) / (100.0 - TEMP_THRESHOLD_3) * (PWM_RANGE - 100));
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    }

    gpioPWM(FAN_GPIO, duty_cycle);
    return duty_cycle;
}

// Function to add data to the circular buffer
void add_to_buffer(float temperature, int duty_cycle) {
    LogEntry entry;
    entry.timestamp = time(NULL);
    entry.temperature = temperature;
    entry.duty_cycle = duty_cycle;

    buffer[buffer_index] = entry;
    buffer_index++;

    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
        buffer_full = 1;
    }
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer ---\n");
    int start_index = buffer_index;
    if (buffer_full) {
        start_index = 0;
    }
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp));
        printf("[%s] Temperature: %.2f C, Duty Cycle: %d\n", time_str, buffer[index].temperature, buffer[index].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    uint8_t data[4];
    float temperature;
    int duty_cycle;

    // Main loop
    while (running) {
        // Read temperature
        if (read_max31855(data)) {
            // Skip fan update for this cycle
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Extract temperature
        temperature = extract_thermocouple_temp(data);

        // Check for faults
        if (check_fault(data)) {
            // Skip fan update for this cycle
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Set fan speed
        duty_cycle = set_fan_speed(temperature);

        // Add to buffer
        add_to_buffer(temperature, duty_cycle);

        // Print buffer every 5 cycles
        if (buffer_full || (buffer_index % 5 == 0)) {
            print_buffer();
        }

        // Wait 1 second
        gpioDelay(1000);
    }

    // Cleanup
    gpioPWM(FAN_GPIO, 0); // Stop PWM
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

