#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0" // SPI device file
#define GPIO_CHIP "gpiochip0"       // GPIO chip name
#define GPIO_PIN 8                  // GPIO pin number (CE0)
#define LOG_FILE "rtd_log.csv"      // Log file name
#define SAMPLE_INTERVAL_SEC 5       // Sample interval in seconds
#define MAX_RETRIES 3               // Maximum number of retries for SPI communication

// Global variables
static int spi_fd = -1;             // SPI file descriptor
static struct gpiod_chip *gpio_chip = NULL; // GPIO chip structure
static struct gpiod_line *gpio_line = NULL; // GPIO line structure
static volatile sig_atomic_t terminate = 0; // Termination flag

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int spi_close(int fd);
int gpio_init(const char *chip_name, int pin);
int gpio_set_direction(struct gpiod_line *line, const char *direction);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_get_value(struct gpiod_line *line);
float read_temperature();
int log_temperature(float temperature);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode (CPHA = 1, CPOL = 1)
    uint8_t mode = 0x01; // SPI mode 1
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed (1 MHz)
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// SPI Close
int spi_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing SPI device");
        return -1;
    }
    return 0;
}

// GPIO Initialization
int gpio_init(const char *chip_name, int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "rtd_sensor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return line;
}

// GPIO Set Direction
int gpio_set_direction(struct gpiod_line *line, const char *direction) {
    if (gpiod_line_set_direction(line, direction) < 0) {
        perror("Error setting GPIO direction");
        return -1;
    }
    return 0;
}

// GPIO Set Value
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
