#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// Pressure deviation threshold (hPa)
#define PRESSURE_THRESHOLD 5.0

// Circular buffer size (60 seconds)
#define BUFFER_SIZE 60

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold pressure data and timestamp
typedef struct {
    time_t timestamp;
    float pressure;
} pressure_data_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
pressure_data_t pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle, int oss);
float calculate_pressure(int raw_temperature, int raw_pressure, bmp180_calibration_data_t calibration_data);
void add_pressure_reading(float pressure);
float calculate_rolling_average();
void trigger_alert(int gpio_pin, int state);
void signal_handler(int signal);

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calibration_data->ac1 = (data[0] << 8) | data[1];
    calibration_data->ac2 = (data[2] << 8) | data[3];
    calibration_data->ac3 = (data[4] << 8) | data[5];
    calibration_data->ac4 = (data[6] << 8) | data[7];
    calibration_data->ac5 = (data[8] << 8) | data[9];
    calibration_data->ac6 = (data[10] << 8) | data[11];
    calibration_data->b1 = (data[12] << 8) | data[13];
    calibration_data->b2 = (data[14] << 8) | data[15];
    calibration_data->mb = (data[16] << 8) | data[17];
    calibration_data->mc = (data[18] << 8) | data[19];
    calibration_data->md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int i2c_handle) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 0) != 0) {
        fprintf(stderr, "Error writing to MSB register for temperature read\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int i2c_handle, int oss) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (oss << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 0) != 0) {
        fprintf(stderr, "Error writing to MSB register for pressure read\n");
        return -1;
    }

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    return ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - oss);
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_temperature, int raw_pressure, bmp180_calibration_data_t calibration_data) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    b5 = (((long)raw_temperature - (long)calibration_data.ac6) * (long)calibration_data.ac5) >> 15;
    x1 = ((long)calibration_data.mc << 11) / (b5 + calibration_data.md);
    b6 = b5 + x1 - 4000;
    x2 = ((long)calibration_data.b2 * (b6 * b6) >> 12) >> 11;
    x3 = ((long)calibration_data.ac2 * b6) >> 11;
    b3 = (((((long)calibration_data.ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((long)calibration_data.ac3 * b6) >> 13;
    x2 = ((long)calibration_data.b1 * (b6 * b6) >> 12) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((unsigned long)calibration_data.ac4 * (unsigned long)(x3 + 32768)) >> 15;
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (float)p / 100.0; // Convert to hPa
}

// Function to add pressure reading to the circular buffer
void add_pressure_reading(float pressure) {
    pressure_buffer[buffer_index].timestamp = time(NULL);
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of the last 60 seconds
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += pressure_buffer[i].pressure;
    }
    return sum / BUFFER_SIZE;
}

// Function to trigger an alert on the specified GPIO pin
void trigger_alert(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration_data) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer function to read pressure every 50ms
    gpioSetTimerFuncEx(0, 50, timer_callback, NULL);

    // Main loop
    while (program_running) {
        // Do other tasks here if needed
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Set GPIO low
    gpioTerminate();

    return 0;
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    int raw_temperature, raw_pressure;
    float pressure;
    float rolling_average;

    // Read raw temperature and pressure
    raw_temperature = read_raw_temperature(i2c_handle);
    raw_pressure = read_raw_pressure(i2c_handle, OSS);

    if (raw_temperature == -1 || raw_pressure == -1) {
        fprintf(stderr, "Error reading temperature or pressure\n");
        return;
    }

    // Calculate pressure
    pressure = calculate_pressure(raw_temperature, raw_pressure, calibration_data);

    // Add pressure reading to the circular buffer
    add_pressure_reading(pressure);

    // Calculate rolling average
    rolling_average = calculate_rolling_average();

    // Check for pressure deviation and trigger alert
    if (fabs(pressure - rolling_average) > PRESSURE_THRESHOLD) {
        trigger_alert(ALERT_GPIO, 1); // Set GPIO high
        printf("Pressure deviation detected: %.2f hPa (rolling average: %.2f hPa)\n", pressure, rolling_average);
    } else {
        trigger_alert(ALERT_GPIO, 0); // Set GPIO low
    }

    printf("Temperature: %d, Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", raw_temperature, pressure, rolling_average);
}

