#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000
#define DUTY_RANGE 255
#define TEMP_MIN 40
#define TEMP_MAX 70

static volatile int running = 1;
static FILE *log_fp = NULL;

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(int temp) {
    if (temp < TEMP_MIN) {
        return 0;
    } else if (temp > TEMP_MAX) {
        return DUTY_RANGE;
    } else {
        // Linear mapping
        return (int)(((float)(temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * DUTY_RANGE);
    }
}

// Function to set fan speed using PWM
void set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(int temp, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_fp != NULL) {
        fprintf(log_fp, "%s, Temperature: %d, Duty Cycle: %d\n", timestamp, temp, duty_cycle);
        fflush(log_fp); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    int temp, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, DUTY_RANGE);

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider implementing a retry mechanism or exiting if errors persist
            sleep(5);
            continue; // Skip to the next iteration
        }

        // Calculate duty cycle
        duty_cycle = calculate_duty_cycle(temp);

        // Set fan speed
        set_fan_speed(duty_cycle);

        // Log data
        log_data(temp, duty_cycle);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_fan_speed(0); // Stop the fan
    fclose(log_fp);
    gpioTerminate();

    printf("Fan control stopped.\n");
    return 0;
}

