#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CALIB_00 0x88
#define BMP280_CHIP_ID 0xD0

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 1
#define BMP280_OVERSAMPLING_PRESS 1

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Calibration data
int16_t dig_T1, dig_T2, dig_T3;
int16_t dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temp);
double compensate_pressure(int32_t raw_press, double t_fine);
int log_data(double temperature, double pressure);
void signal_handler(int signal);
int check_chip_id();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read calibration data from the sensor
int read_calibration_data() {
    uint8_t buffer[26];
    if (read(i2c_fd, buffer, 26) != 26) {
        perror("Error reading calibration data");
        return -1;
    }

    dig_T1 = (buffer[1] << 8) | buffer[0];
    dig_T2 = (int16_t)((buffer[3] << 8) | buffer[2]);
    dig_T3 = (int16_t)((buffer[5] << 8) | buffer[4]);
    dig_P1 = (buffer[7] << 8) | buffer[6];
    dig_P2 = (int16_t)((buffer[9] << 8) | buffer[8]);
    dig_P3 = (int16_t)((buffer[11] << 8) | buffer[10]);
    dig_P4 = (int16_t)((buffer[13] << 8) | buffer[12]);
    dig_P5 = (int16_t)((buffer[15] << 8) | buffer[14]);
    dig_P6 = (int16_t)((buffer[17] << 8) | buffer[16]);
    dig_P7 = (int16_t)((buffer[19] << 8) | buffer[18]);
    dig_P8 = (int16_t)((buffer[21] << 8) | buffer[20]);
    dig_P9 = (int16_t)((buffer[23] << 8) | buffer[22]);

    return 0;
}

// Read raw temperature and pressure data
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t buffer[6];
    uint8_t status;

    // Set forced mode
    uint8_t ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | 0x03; // Forced mode
    if (write(i2c_fd, &ctrl_meas, 1) != 1) {
        perror("Error writing to CTRL_MEAS register");
        return -1;
    }

    // Wait for measurement to complete (polling status bit)
    int timeout = 100; // Timeout after 100 attempts
    while (timeout > 0) {
        status = read(i2c_fd, &status, 1);
        if (status < 0) {
            perror("Error reading status register");
            return -1;
        }
        if ((status & 0x04) == 0) break; // Status bit 3 is clear (measurement complete)
        usleep(1000); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement.\n");
        return -1;
    }

    // Read raw data
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading raw data");
        return -1;
    }

    *pressure = (buffer[0] << 12) | (buffer[1] << 4) | (buffer[2] >> 4);
    *temperature = (buffer[3] << 12) | (buffer[4] << 4) | (buffer[5] >> 4);

    return 0;
}

// Compensate temperature using calibration data
double compensate_temperature(int32_t raw_temp) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temp / 16384.0) - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using calibration data
double compensate_pressure(int32_t raw_press, double t_fine) {
    double var1, var2, p;
    double p_fine;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p_fine = 1048576.0 - (double)raw_press;
    p_fine = (p_fine - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p_fine * p_fine / 2147483648.0;
    var2 = p_fine * ((double)dig_P8) / 32768.0;
    p = (p_fine + (var1 + var2 + ((double)dig_P7)) / 16.0);
    return p / 100.0; // Return in hPa
}

// Log data to file
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Check chip ID
int check_chip_id() {
    uint8_t chip_id;
    if (read(i2c_fd, &chip_id, 1) != 1) {
        perror("Error reading chip ID");
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X. Expected 0x58.\n", chip_id);
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Check chip ID
    if (check_chip_id() < 0) {
        fprintf(stderr, "Failed to check chip ID. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("weather_data.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    double t_fine;

    // Main loop
    while (program_running) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read raw data. Continuing.\n");
            sleep(5);
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        t_fine = temperature * 5120.0;
        pressure = compensate_pressure(raw_pressure, t_fine);

        // Log data
        if (log_data(temperature, pressure) < 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        sleep(5);
    }

    // Close log file and I2C device
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

