// Log data to file
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Check chip ID
int check_chip_id() {
    uint8_t chip_id;
    if (read(i2c_fd, &chip_id, 1) != 1) {
        perror("Error reading chip ID");
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X. Expected 0x58.\n", chip_id);
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Check chip ID
    if (check_chip_id() < 0) {
        fprintf(stderr, "Failed to check chip ID. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("weather_data.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    double t_fine;

    // Main loop
    while (program_running) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read raw data. Continuing.\n");
            sleep(5);
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        t_fine = temperature * 5120.0;
        pressure = compensate_pressure(raw_pressure, t_fine);

        // Log data
        if (log_data(temperature, pressure) < 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        sleep(5);
    }

    // Close log file and I2C device
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

