#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_handle;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile sig_atomic_t program_running = 1;

// Function prototypes
double read_temperature();
void update_circular_buffer(double temperature);
double calculate_running_average();
void control_led(double average_temperature);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from LM75 sensor
double read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert to signed 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to Celsius
    double temperature = (double)raw_temp / 256.0;

    return temperature;
}

// Function to update the circular buffer
void update_circular_buffer(double temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the running average
double calculate_running_average() {
    pthread_mutex_lock(&buffer_mutex);
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / BUFFER_SIZE;
}

// Function to control the LED
void control_led(double average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        double temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            update_circular_buffer(temperature);
            double average_temperature = calculate_running_average();
            control_led(average_temperature);
            printf("Temperature: %.2f\u00b0C, Average Temperature: %.2f\u00b0C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

