#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define GPIO_HEATER 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define TARGET_TEMPERATURE 25.0 // Default target temperature
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define MAX_TEMPERATURE 80.0
#define MAX_RTD_CODE 32767
#define MIN_RTD_CODE -32768

// Global variables
int spi_handle;
double last_error = 0.0;
double integral = 0.0;
int running = 1;

// Function prototypes
int read_max31865(int spi_handle, uint8_t *data);
double convert_rtd_to_temperature(uint16_t rtd_code);
double pid_control(double setpoint, double actual_temperature);
void set_heater_pwm(int gpio, int duty_cycle);
void signal_handler(int signal);
int load_config(const char *filename, double *target_temperature, double *kp, double *ki, double *kd);

// Function to read data from MAX31865 via SPI
int read_max31865(int spi_handle, uint8_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01; // Read from register 0x01
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    data[0] = rx_buf[0];
    data[1] = rx_buf[1];

    return 0;
}

// Function to convert RTD code to temperature
double convert_rtd_to_temperature(uint16_t rtd_code) {
    double resistance;
    double temperature;

    // Check for fault
    if (rtd_code & 0x0001) {
        fprintf(stderr, "Error: RTD fault detected\n");
        return -1000.0; // Indicate an error
    }

    // Convert RTD code to resistance
    resistance = (double)((rtd_code & 0x3FFF) / 32768.0) * 430.0;

    // Callendar-Van Dusen equation
    temperature = 0.0;
    if (resistance > 100.0) {
        temperature = (resistance - 100.0) / 0.385 * 10.0; // Approximation for simplicity
    } else {
        temperature = 0.0; // Below 100 ohms, no temperature
    }

    return temperature;
}

// PID control function
double pid_control(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - last_error;
    double output = KP * error + KI * integral + KD * derivative;
    last_error = error;

    // Clamp the output to the range 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
    set_heater_pwm(GPIO_HEATER, 0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to load configuration from JSON file
int load_config(const char *filename, double *target_temperature, double *kp, double *ki, double *kd) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        if (filename == "config.json") {
            printf("Using default configuration...\n");
        } else {
            return -1; // Indicate failure
        }
    }

    json_t *target = json_object_get(root, "target_temperature");
    json_t *kp_obj = json_object_get(root, "kp");
    json_t *ki_obj = json_object_get(root, "ki");
    json_t *kd_obj = json_object_get(root, "kd");

    if (!json_is_real(target) || !json_is_real(kp_obj) || !json_is_real(ki_obj) || !json_is_real(kd_obj)) {
        fprintf(stderr, "Error: Invalid JSON format\n");
        json_decref(root);
        return -1;
    }

    *target_temperature = json_real_value(target);
    *kp = json_real_value(kp_obj);
    *ki = json_real_value(ki_obj);
    *kd = json_real_value(kd_obj);

    json_decref(root);
    return 0;
}

int main() {
    uint8_t rtd_data[2];
    double temperature;
    double pid_output;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_HEATER, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_HEATER, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_HEATER, PWM_RANGE);

    // Load configuration from file
    if (load_config("config.json", &TARGET_TEMPERATURE, &KP, &KI, &KD) != 0) {
        printf("Using default configuration...\n");
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MAX31865
    uint8_t config_data[2];
    config_data[0] = 0x80; // Configuration register address
    config_data[1] = 0xC1; // Configuration value (VBIAS, Auto-conversion, clear faults)

    if (spiWrite(spi_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error: Failed to initialize MAX31865\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Heater control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read RTD data
        if (read_max31865(spi_handle, rtd_data) != 0) {
            fprintf(stderr, "Error: Failed to read RTD data\n");
            running = 0; // Exit loop on error
            break;
        }

        // Convert RTD code to temperature
        temperature = convert_rtd_to_temperature((rtd_data[0] << 8) | rtd_data[1]);

        if (temperature < -999.0) {
            fprintf(stderr, "Error: Invalid temperature reading\n");
            running = 0; // Exit loop on error
            break;
        }

        // PID control
        pid_output = pid_control(TARGET_TEMPERATURE, temperature);

        // Set heater PWM duty cycle
        duty_cycle = (int)pid_output;
        set_heater_pwm(GPIO_HEATER, duty_cycle);

        // Check for failsafe conditions
        if (temperature > MAX_TEMPERATURE || (rtd_data[0] & 0x0001) || (rtd_data[0] & 0x0002) || (rtd_data[0] & 0x0004)) {
            fprintf(stderr, "Error: Failsafe triggered! Shutting down heater.\n");
            running = 0; // Exit loop on failsafe
            break;
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    set_heater_pwm(GPIO_HEATER, 0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

