    // Initialize MAX31865
    uint8_t config_data[2];
    config_data[0] = 0x80; // Configuration register address
    config_data[1] = 0xC1; // Configuration value (VBIAS, Auto-conversion, clear faults)

    if (spiWrite(spi_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error: Failed to initialize MAX31865\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Heater control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read RTD data
        if (read_max31865(spi_handle, rtd_data) != 0) {
            fprintf(stderr, "Error: Failed to read RTD data\n");
            running = 0; // Exit loop on error
            break;
        }

        // Convert RTD code to temperature
        temperature = convert_rtd_to_temperature((rtd_data[0] << 8) | rtd_data[1]);

        if (temperature < -999.0) {
            fprintf(stderr, "Error: Invalid temperature reading\n");
            running = 0; // Exit loop on error
            break;
        }

        // PID control
        pid_output = pid_control(TARGET_TEMPERATURE, temperature);

        // Set heater PWM duty cycle
        duty_cycle = (int)pid_output;
        set_heater_pwm(GPIO_HEATER, duty_cycle);

        // Check for failsafe conditions
        if (temperature > MAX_TEMPERATURE || (rtd_data[0] & 0x0001) || (rtd_data[0] & 0x0002) || (rtd_data[0] & 0x0004)) {
            fprintf(stderr, "Error: Failsafe triggered! Shutting down heater.\n");
            running = 0; // Exit loop on failsafe
            break;
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    set_heater_pwm(GPIO_HEATER, 0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

