// BMP180 read calibration data function
int bmp180_read_calibration_data(int fd) {
    uint8_t data[22];
    if (i2c_read(fd, BMP180_REG_CAL_AC1, &data[0]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_CAL_AC2, &data[1]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_CAL_AC3, &data[2]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_CAL_AC4, &data[3]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_CAL_AC5, &data[4]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_CAL_AC6, &data[5]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_CAL_B1, &data[6]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_CAL_B2, &data[7]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_CAL_MB, &data[8]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_CAL_MC, &data[9]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_CAL_MD, &data[10]) < 0) return -1;

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[3] << 8) | data[4];
    ac5 = (data[6] << 8) | data[7];
    ac6 = (data[5] << 8) | data[4];
    b1 = (data[9] << 8) | data[10];
    b2 = (data[8] << 8) | data[9];
    mb = (data[1] << 8) | data[0];
    mc = (data[13] << 8) | data[12];
    md = (data[15] << 8) | data[14];

    return 0;
}

// BMP180 read raw temperature function
int bmp180_read_raw_temperature(int fd) {
    if (i2c_write(fd, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    usleep(5000); // Wait 4.5ms
    uint8_t data[2];
    if (i2c_read(fd, BMP180_REG_MSB, &data[0]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_LSB, &data[1]) < 0) return -1;
    return (data[0] << 8) | data[1];
}

// BMP180 read raw pressure function
int bmp180_read_raw_pressure(int fd) {
    if (i2c_write(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    usleep(26000); // Wait 25.5ms for OSS = 3
    uint8_t data[3];
    if (i2c_read(fd, BMP180_REG_MSB, &data[0]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_LSB, &data[1]) < 0) return -1;
    if (i2c_read(fd, BMP180_REG_XLSB, &data[2]) < 0) return -1;
    return ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
}

