    unsigned long x1_u = ((unsigned long)ac3 * b6) / pow(2, 13);
    unsigned long x2_u = ((unsigned long)b1 * (b6 * b6) / pow(2, 12)) / pow(2, 16);
    unsigned long b4 = x1_u + x2_u + 32768;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long p;
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;
    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    float pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure;
}

// Log breach function
