int init_bmp180();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
double calculate_pressure(int raw_temperature, int raw_pressure);
int log_pressure(double pressure);
void toggle_logging();
void signal_handler(int signal);
int read_calibration_data();

// Function to read a 16-bit value from the BMP180
int16_t read_16bit(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_16bit_unsigned(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to initialize the BMP180 sensor
int init_bmp180()
{
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C handle is invalid\n");
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    // Set oversampling and power mode
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = (0x02 << 6) | (0x02 << 3) | 0x03; // Pressure OSS = 3, Normal mode
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf + 1, 1) != 0) {
        fprintf(stderr, "Failed to write to control register\n");
        return -1;
    }

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[1];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Request temperature reading
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf + 1, 1) != 0) {
        fprintf(stderr, "Failed to write to control register for temperature\n");
        return -1;
    }
