#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE0 8
#define SPI_CE1 7
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL_CE0 0
#define SPI_CHANNEL_CE1 1
#define SPI_SPEED 2000000 // 2 MHz

// Define MAX31855 fault codes
#define MAX31855_FAULT_OPEN_CIRCUIT 0x01
#define MAX31855_FAULT_SHORT_TO_GND 0x02
#define MAX31855_FAULT_SHORT_TO_VCC 0x04

// Define PI controller parameters
#define Kp 1.0
#define Ki 0.1
#define Integral 0.0
#define SafeDutyCycle 0.8

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double target_temperature = 25.0;

// Function prototypes
double read_temperature(int spi_channel);
double calculate_duty_cycle(double temperature);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
int initialize_spi(int ce_pin);
void cleanup();

// Function to initialize SPI
int initialize_spi(int ce_pin) {
    int spi_handle = spiOpen(ce_pin, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel CE%d: %d\n", ce_pin, spi_handle);
        return -1;
    }
    return spi_handle;
}

// Function to read temperature from MAX31855
double read_temperature(int spi_channel) {
    int handle;
    if (spi_channel == SPI_CHANNEL_CE0) {
        handle = initialize_spi(SPI_CE0);
        if (handle < 0) return -273.15; // Return absolute zero on error
    } else {
        handle = initialize_spi(SPI_CE1);
        if (handle < 0) return -273.15; // Return absolute zero on error
    }

    char tx_buf[4] = {0x00, 0x00, 0x00, 0x00};
    char rx_buf[4];

    int result = spiXfer(handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer error on channel %d: %d\n", spi_channel, result);
        spiClose(handle);
        return -273.15; // Return absolute zero on error
    }

    // Extract temperature data
    int16_t raw_temp = ((rx_buf[0] << 8) | rx_buf[1]) >> 2;
    double temperature = (double)raw_temp * 0.25;

    spiClose(handle);
    return temperature;
}

// Function to calculate duty cycle using PI controller
double calculate_duty_cycle(double temperature) {
    double error = target_temperature - temperature;
    Integral += error;

    // Anti-windup
    double derivative = error - (Integral / 10.0); // Smoothing the integral term

    double output = Kp * error + Ki * Integral;

    // Limit duty cycle
    double duty_cycle = output;
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > SafeDutyCycle) duty_cycle = SafeDutyCycle;

    return duty_cycle;
}

// Function to log data to file
void log_data(double temperature, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(HEATER_PIN, 0); // Turn off heater
    gpioSetMode(HEATER_PIN, PI_INPUT); // Set back to input
    gpioSetMode(SPI_CE0, PI_INPUT); // Set back to input
    gpioSetMode(SPI_CE1, PI_INPUT); // Set back to input
    gpioSetMode(SPI_MOSI, PI_INPUT); // Set back to input
    gpioSetMode(SPI_MISO, PI_INPUT); // Set back to input
    gpioSetMode(SPI_SCLK, PI_INPUT); // Set back to input

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
        printf("Target temperature set to: %.2f\n", target_temperature);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioSetMode(SPI_CE1, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    // Initialize SPI
    int spi_handle_ce0 = initialize_spi(SPI_CE0);
    int spi_handle_ce1 = initialize_spi(SPI_CE1);

    if (spi_handle_ce0 < 0 || spi_handle_ce1 < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double temperature = read_temperature(SPI_CHANNEL_CE0);
        if (temperature < -200) {
            fprintf(stderr, "MAX31855 Fault detected on CE0\n");
        } else if (temperature < -100) {
            fprintf(stderr, "MAX31855 Fault detected on CE1\n");
        } else if (temperature < -50) {
            fprintf(stderr, "MAX31855 Fault detected on both CE0 and CE1\n");
        } else {
            double duty_cycle = calculate_duty_cycle(temperature);
            gpioPWM(HEATER_PIN, (int)(duty_cycle * 255.0)); // pigpio uses 0-255 range
            log_data(temperature, duty_cycle);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

