#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM range
#define PWM_RANGE 255

// Define temperature thresholds (in millidegrees Celsius)
#define TEMP_THRESHOLD_LOW 40000
#define TEMP_THRESHOLD_MED 59999
#define TEMP_THRESHOLD_HIGH 60000

// Define the path to the temperature file
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read CPU temperature from file
int read_temperature() {
    FILE *fp;
    int temperature = 0;
    int ret;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    ret = fscanf(fp, "%d", &temperature);
    if (ret != 1) {
        fprintf(stderr, "Error reading temperature from file: %s\n", strerror(errno));
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temperature;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, PWM_RANGE - red);   // Invert for common anode
    gpioPWM(GREEN_PIN, PWM_RANGE - green); // Invert for common anode
    gpioPWM(BLUE_PIN, PWM_RANGE - blue);  // Invert for common anode
}

// Function to map temperature to RGB color
void map_temperature_to_color(int temperature, int *red, int *green, int *blue) {
    if (temperature < TEMP_THRESHOLD_LOW) {
        *red = 0;
        *green = 0;
        *blue = PWM_RANGE;
    } else if (temperature < TEMP_THRESHOLD_MED) {
        *red = 0;
        *green = PWM_RANGE;
        *blue = 0;
    } else {
        *red = PWM_RANGE;
        *green = 0;
        *blue = 0;
    }
}

int main() {
    int temperature;
    int red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range for each pin
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read CPU temperature
        temperature = read_temperature();
        if (temperature == -1) {
            // Error reading temperature, skip this cycle
            gpioDelay(500000); // 0.5 seconds
            continue;
        }

        // Map temperature to RGB color
        map_temperature_to_color(temperature, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Print temperature and RGB values
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temperature, red, green, blue);

        // Wait for 0.5 seconds
        gpioDelay(500000);
    }

    // Turn off LED (set all PWM channels to 255 for common anode)
    set_led_color(255, 255, 255);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

