#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <curl/curl.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY 5 // seconds
#define LOG_FILE "dht22.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int error;
} DHT22Data;

// Function prototypes
int read_dht22(DHT22Data *data);
int validate_checksum(uint8_t data[], int len);
int post_data(const char *json_data);
void signal_handler(int signal);
void log_message(const char *message);

// Callback function for libcurl to write received data
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    return real_size;
}

// Function to log messages with timestamps
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Function to read data from DHT22 sensor
int read_dht22(DHT22Data *data) {
    uint8_t raw_data[5] = {0};
    int i, j;

    // Start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1 ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30 us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read 40 bits (5 bytes)
    for (i = 0; i < 5; i++) {
        uint8_t byte = 0;
        for (j = 0; j < 8; j++) {
            // Wait for low signal (0)
            int count = 0;
            while (gpioRead(DHT22_GPIO) == 0) {
                count++;
                gpioDelay(1); // 1 us
                if (count > 200) { // Timeout after 200 us
                    log_message("DHT22: Timeout waiting for low signal.");
                    return -1; // Error
                }
            }

            // Wait for high signal (1)
            count = 0;
            while (gpioRead(DHT22_GPIO) == 1) {
                count++;
                gpioDelay(1); // 1 us
                if (count > 200) { // Timeout after 200 us
                    log_message("DHT22: Timeout waiting for high signal.");
                    return -1; // Error
                }
            }

            // Determine if bit is 0 or 1 based on the length of the high signal
            if (count > 40) { // Adjust threshold as needed
                byte |= (1 << (7 - j));
            }
            raw_data[i] = byte;
        }
    }

    // Validate checksum
    if (validate_checksum(raw_data, 5) != 0) {
        log_message("DHT22: Checksum error.");
        data->error = -1; // Indicate checksum error
        return -1;
    }

    // Convert data to temperature and humidity
    data->humidity = ((raw_data[0] << 8) | raw_data[1]) / 10.0;
    data->temperature = (((raw_data[2] & 0x7F) << 8) | raw_data[3]) / 10.0;
    if (raw_data[2] & 0x80) {
        data->temperature *= -1;
    }

    return 0; // Success
}

// Function to validate the 8-bit checksum
int validate_checksum(uint8_t data[], int len) {
    uint8_t checksum = 0;
    for (int i = 0; i < len - 1; i++) {
        checksum += data[i];
    }
    return (checksum == data[len - 1]) ? 0 : -1;
}

// Function to post data to the server
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            log_message(error_message);
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                char error_message[256];
                snprintf(error_message, sizeof(error_message), "HTTP POST failed with code: %ld", response_code);
                log_message(error_message);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        log_message("Failed to initialize libcurl.");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

int main() {
    DHT22Data dht22_data;
    char json_data[128];
    int retries = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("DHT22 sensor monitoring started.");

    while (running) {
        // Read DHT22 data
        if (read_dht22(&dht22_data) == 0) {
            // Format data as JSON
            snprintf(json_data, sizeof(json_data), "{\"temperature\":%.1f,\"humidity\":%.1f}", dht22_data.temperature, dht22_data.humidity);

            // Post data to server
            if (post_data(json_data) != 0) {
                log_message("Failed to post data to server.");
            } else {
                log_message("Data posted successfully.");
            }
        } else {
            log_message("Failed to read DHT22 data.");
        }

        // Wait before next reading
        sleep(5);
        retries = 0; // Reset retries
    }

    // Clean up
    log_message("DHT22 sensor monitoring stopped.");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

