#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting
#define OSS 3

// GPIO pin for interrupt
#define INTERRUPT_GPIO 4

// Debounce time (in microseconds)
#define DEBOUNCE_TIME 200000

// Global variables
int i2c_handle;
int logging_enabled = 0;
volatile unsigned int last_interrupt_time = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
double calculate_pressure(int raw_temperature, int raw_pressure);
void interrupt_handler(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);
int log_data(double pressure);

// Function to read a 16-bit value from the BMP180
int16_t read_int16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_uint16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_int16(BMP180_REG_CAL_AC1);
    ac2 = read_int16(BMP180_REG_CAL_AC2);
    ac3 = read_int16(BMP180_REG_CAL_AC3);
    ac4 = read_uint16(BMP180_REG_CAL_AC4);
    ac5 = read_uint16(BMP180_REG_CAL_AC5);
    ac6 = read_uint16(BMP180_REG_CAL_AC6);
    b1 = read_int16(BMP180_REG_CAL_B1);
    b2 = read_int16(BMP180_REG_CAL_B2);
    mb = read_int16(BMP180_REG_CAL_MB);
    mc = read_int16(BMP180_REG_CAL_MC);
    md = read_int16(BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data. Check sensor connection.\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[2];
    char write_buf[2];
    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for temperature read\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (int16_t)((buf[0] << 8) | buf[1]);
