// Function to read data from DHT22 sensor
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0};
    int retries = 0;
    int i;
    unsigned int bit = 0;
    unsigned int byte = 0;
    unsigned int data_buffer[5] = {0, 0, 0, 0, 0};
    unsigned int checksum = 0;
    unsigned int received_checksum = 0;
    unsigned int pulse_lengths[85]; // 40 data bits * 2 pulses per bit + start and end pulses

