    if (init_gpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio.");
        data.error = -1;
        return data;
    }

    dht22_handle = gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    if (dht22_handle < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode.");
        cleanup_gpio();
        data.error = -1;
        return data;
    }

    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 20-40us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read the response
    for (i = 0; i < 85; i++) {
        int count = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            count++;
            if (count > 1000) {
                syslog(LOG_ERR, "Timeout waiting for high signal.");
                cleanup_gpio();
                data.error = -1;
                return data;
            }
            gpioDelay(1); // 1 us
        }

        count = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
