    // Decode the data
    for (i = 0; i < 40; i++) {
        int index = 2 * i + 2; // Skip the start and end pulses
        if (pulse_lengths[index] > pulse_lengths[index + 1]) {
            data_buffer[i / 8] |= (1 << (7 - (i % 8)));
        }
