        perror("Error writing to fan control file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing fan control file");
        return -1;
    }

    return 0;
}

// Function to validate the fan speed
int validate_fan_speed(int speed) {
    if (speed < 0 || speed > MAX_TEMP) {
        fprintf(stderr, "Invalid fan speed: %d. Speed must be between 0 and %d\n", speed, MAX_TEMP);
        return -1;
    }
    return 0;
}

// Function to log the fan speed
int log_fan_speed(int speed) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (speed != 0 && (now - last_log_time) >= LOG_INTERVAL) {
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp == NULL) {
            perror("Error opening log file");
            return -1;
        }

        fprintf(fp, "%s Fan Speed: %d\n", buf, speed);
        if (fclose(fp) != 0) {
            perror("Error closing log file");
            return -1;
        }

        last_log_time = now;
    }
    return 0;
}

// Function to check if the requested fan speed is within the valid range
int check_max_state(int speed) {
    FILE *fp;
    char line[256];
    int max_state;

    fp = fopen(FAN_CONTROL_FILE, "r");
    if (fp == NULL) {
        perror("Error opening fan control file to check max state");
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading max state from file");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (sscanf(line, "%d", &max_state) != 1) {
        fprintf(stderr, "Error parsing max state from file\n");
        return -1;
    }

    if (speed > max_state) {
        fprintf(stderr, "Requested fan speed (%d) exceeds max allowed state (%d)\n", speed, max_state);
        return -1;
    }

    return 0;
}

int main() {
    int cpu_temp, fan_speed = 0;

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting fan control program...\n");

    while (1) {
        cpu_temp = read_cpu_temp();
        if (cpu_temp == -1) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in 5 seconds...\n");
            sleep(LOG_INTERVAL);
            continue;
        }

        if (cpu_temp < MIN_TEMP || cpu_temp > MAX_TEMP) {
            fprintf(stderr, "CPU temperature out of range: %d. Skipping fan control.\n", cpu_temp);
            sleep(LOG_INTERVAL);
            continue;
        }

        // Determine fan speed based on temperature
        if (cpu_temp < 45000) {
            fan_speed = 0;
        } else if (cpu_temp < 55000) {
            fan_speed = 1;
        } else if (cpu_temp < 65000) {
            fan_speed = 2;
        } else {
            fan_speed = 3;
        }

        // Validate fan speed
        if (validate_fan_speed(fan_speed) != 0) {
            fprintf(stderr, "Invalid fan speed. Skipping fan control.\n");
            sleep(LOG_INTERVAL);
            continue;
        }

        // Set fan speed
        if (set_fan_speed(fan_speed) != 0) {
            fprintf(stderr, "Failed to set fan speed. Skipping fan control.\n");
            sleep(LOG_INTERVAL);
            continue;
        }

        // Log fan speed
        log_fan_speed(fan_speed);

        printf("CPU Temperature: %d m°C, Fan Speed: %d\n", cpu_temp, fan_speed);

        sleep(LOG_INTERVAL);
    }

    return 0;
}

