#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define TARGET_TEMPERATURE 50.0 // Default target temperature
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define MAX_DUTY_CYCLE 100
#define MIN_DUTY_CYCLE 0

// MAX31855 Registers
#define MAX31855_CONFIG_REG 0x00
#define MAX31855_INT1_REG 0x01
#define MAX31855_INT2_REG 0x02
#define MAX31855_TEMP_REG 0x03
#define MAX31855_FAULT_REG 0x00

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double target_temperature = TARGET_TEMPERATURE;
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
void signal_handler(int signal);
int initialize();
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_pwm(double duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void cleanup();
int max31855_read_register(uint8_t reg, uint8_t *data, int len);
int max31855_write_register(uint8_t reg, uint8_t data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio and GPIO
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, 100); // Set PWM range to 0-100

    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read temperature from MAX31855 via SPI
double read_temperature() {
    uint8_t data[4];
    int16_t raw_temp;
    double temperature;

    if (max31855_read_register(MAX31855_TEMP_REG, data, 4) != 0) {
        fprintf(log_file, "Error reading temperature from MAX31855\n");
        fflush(log_file);
        return -1000.0; // Indicate error
    }

    raw_temp = (data[0] << 8) | data[1];
    raw_temp >>= 2; // Remove fault bits and sign extension

    temperature = raw_temp * 0.25;

    // Check for thermocouple open circuit fault
    if (data[3] & 0x01) {
        fprintf(log_file, "Thermocouple open circuit fault\n");
        fflush(log_file);
        set_pwm(0); // Disable heater
        integral = 0.0; // Reset integral term
        return -1000.0; // Indicate error
    }

    // Check for thermocouple short to GND fault
    if (data[3] & 0x02) {
        fprintf(log_file, "Thermocouple short to GND fault\n");
        fflush(log_file);
        set_pwm(0); // Disable heater
        integral = 0.0; // Reset integral term
        return -1000.0; // Indicate error
    }

    // Check for thermocouple short to VCC fault
    if (data[3] & 0x04) {
        fprintf(log_file, "Thermocouple short to VCC fault\n");
        fflush(log_file);
        set_pwm(0); // Disable heater
        integral = 0.0; // Reset integral term
        return -1000.0; // Indicate error
    }

    return temperature;
}

// Calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    return output;
}

// Set PWM duty cycle
void set_pwm(double duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    gpioPWM(HEATER_GPIO, (int)duty_cycle);
}

// Log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %.2f, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    set_pwm(0); // Turn off heater
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// MAX31855 read register function
int max31855_read_register(uint8_t reg, uint8_t *data, int len) {
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 500kHz, mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return 1;
    }

    char tx_buf[1];
    char rx_buf[len];

    tx_buf[0] = reg | 0x80; // Set MSB to 1 for read operation

    spiXfer(handle, tx_buf, rx_buf, len + 1); // Send register address and receive data

    spiClose(handle);

    for (int i = 0; i < len; i++) {
        data[i] = rx_buf[i + 1];
    }

    return 0;
}

// MAX31855 write register function
int max31855_write_register(uint8_t reg, uint8_t data) {
    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 500kHz, mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return 1;
    }

    char tx_buf[2];
    tx_buf[0] = reg & 0x7F; // Set MSB to 0 for write operation
    tx_buf[1] = data;

    spiWrite(handle, tx_buf, 2);
    spiClose(handle);
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            target_temperature = atof(argv[i + 1]);
            i++;
        }
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Heater control started. Target temperature: %.2f°C\n", target_temperature);

    while (running) {
        double temperature = read_temperature();
        if (temperature < -999.0) {
            fprintf(log_file, "Error reading temperature, disabling heater and resetting PID.\n");
            fflush(log_file);
            set_pwm(0);
            integral = 0.0;
            previous_error = 0.0;
            sleep(1); // Wait before retrying
            continue;
        }

        double pid_output = calculate_pid(target_temperature, temperature);
        double duty_cycle = (int)pid_output; // Convert PID output to duty cycle

        // Failsafe: Limit duty cycle
        if (duty_cycle > MAX_DUTY_CYCLE) {
            duty_cycle = MAX_DUTY_CYCLE;
        } else if (duty_cycle < MIN_DUTY_CYCLE) {
            duty_cycle = MIN_DUTY_CYCLE;
        }

        set_pwm(duty_cycle);
        log_data(temperature, duty_cycle, pid_output);

        sleep(1);
    }

    // Cleanup
    cleanup();

    return 0;
}

