#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

static volatile int running = 1;
static FILE *log_fp = NULL;

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli_celsius / 1000.0;
    return temp_celsius;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    if (temperature < 40.0) {
        return 0;
    } else if (temperature > 70.0) {
        return 100;
    } else {
        return (int)(((temperature - 40.0) / (70.0 - 40.0)) * 100.0);
    }
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log data to CSV file
int log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency to 25kHz\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }
    rewind(log_fp);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    while (running) {
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider a default temperature or exit if errors persist
        } else {
            duty_cycle = calculate_duty_cycle(temperature);
            if (set_pwm_duty_cycle(duty_cycle) != 0) {
                fprintf(stderr, "Error setting PWM duty cycle, using previous value.\n");
            } else {
                if (log_data(temperature, duty_cycle) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            }
        }

        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    set_pwm_duty_cycle(0); // Turn off the fan
    fclose(log_fp);
    gpioTerminate();

    printf("Cooling system stopped.\n");
    return 0;
}

