#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09

// Define I2C bus
#define I2C_BUS 1

// Define measurement command
#define MEASUREMENT_COMMAND 0x3608

// Define log file name
#define LOG_FILE "flow_log.txt"

// Define retry count
#define MAX_RETRIES 3

// Define pigpio log level
#define PIGPIO_LOG_LEVEL 5

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
int log_data(float flow1, float flow2);
void signal_handler(int signal);

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow rate from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    char buf[3];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        if (i2cWriteByteData(i2c_handle, (MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF) != 0) {
            fprintf(stderr, "Error writing measurement command to sensor (handle %d), retry %d\n", i2c_handle, retries + 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
            continue;
        }

        // Read 3 bytes from the sensor
        bytes_read = i2cReadDevice(i2c_handle, buf, 3);
        if (bytes_read == 3) {
            // Extract raw value
            uint16_t raw_value = (buf[0] << 8) | buf[1];

            // Validate CRC
            uint8_t crc = crc8(buf, 2);
            if (crc == buf[2]) {
                // Convert to flow rate
                *flow_rate = (float)raw_value * 0.01;

                return 0; // Success
            } else {
                fprintf(stderr, "CRC check failed for sensor (handle %d), retry %d\n", i2c_handle, retries + 1);
            }
        } else {
            fprintf(stderr, "Error reading data from sensor (handle %d), retry %d\n", i2c_handle, retries + 1);
        }

        gpioDelay(1000); // Wait 1ms before retrying
        retries++;
    }

    fprintf(stderr, "Failed to read sensor (handle %d) after %d retries\n", i2c_handle, MAX_RETRIES);
    return -1; // Failure
}

// Function to log data to a file
int log_data(float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    // Write data to log file
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);

    // Close log file
    fclose(log_file);
    log_file = NULL; // Reset to NULL after closing

    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C handles
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Terminate pigpio
    gpioTerminate();

    // Exit program
    exit(0);
}

int main() {
    float flow1, flow2;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read flow rates from both sensors
        if (read_sensor(i2c_handle1, &flow1) == 0) {
            printf("Sensor 1: Flow Rate = %.2f ml/min\n", flow1);
        } else {
            fprintf(stderr, "Failed to read from sensor 1\n");
        }

        if (read_sensor(i2c_handle2, &flow2) == 0) {
            printf("Sensor 2: Flow Rate = %.2f ml/min\n", flow2);
        } else {
            fprintf(stderr, "Failed to read from sensor 2\n");
        }

        // Log data
        if (log_data(flow1, flow2) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    return 0;
}

