#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A 17
#define ENCODER_B 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold the encoder state
typedef struct {
    int a;
    int b;
    int state;
} EncoderState;

// Function prototypes
int initialize_gpio();
EncoderState read_encoder();
double calculate_angle(EncoderState previous_state, EncoderState current_state);
int log_data(double angle);
void cleanup();
void signal_handler(int signal);

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetMode(ENCODER_B, PI_INPUT);

    // Enable pull-up resistors on the encoder pins
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    return 0;
}

// Function to read the current state of the encoder pins
EncoderState read_encoder() {
    EncoderState state;
    state.a = gpioRead(ENCODER_A);
    state.b = gpioRead(ENCODER_B);
    return state;
}

// Function to calculate the angular position based on the encoder state changes
double calculate_angle(EncoderState previous_state, EncoderState current_state) {
    int delta = (current_state.state ^ previous_state.state) & 0x07; // Extract the last 3 bits

    if (delta == 1) {
        return previous_state.state + 1.0; // Clockwise
    } else if (delta == 3) {
        return previous_state.state - 1.0; // Counter-clockwise
    } else {
        return previous_state.state; // No change
    }
}

// Function to log the data to a file
int log_data(double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, angle);
        fflush(log_file); // Ensure data is written to the file immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Function to handle signals (SIGINT, SIGTERM) and perform cleanup
void cleanup() {
    printf("Cleaning up and exiting...\n");
    running = 0;

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        cleanup();
    }
}

int main() {
    EncoderState previous_state = {0, 0, 0};
    EncoderState current_state;
    double angle;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        current_state = read_encoder();

        // Calculate the angular position
        angle = calculate_angle(previous_state, current_state);

        // Log the data
        if (log_data(angle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        previous_state = current_state;

        // Delay to avoid excessive CPU usage
        gpioDelay(1000); // 1 millisecond
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

