#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

// Mutex for pulse counter protection
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Global pulse counter
volatile int pulse_count = 0;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulse_count, double time_interval);
void log_rpm(double rpm);
void *timer_thread(void *arg);
void signal_handler(int signal);

// Structure to pass data to the timer thread
typedef struct {
    double *rpm;
} timer_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-down resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register ISR for rising edge detection
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Allocate memory for timer data
    timer_data_t *timer_data = malloc(sizeof(timer_data_t));
    if (timer_data == NULL) {
        fprintf(stderr, "Failed to allocate memory for timer data\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize timer data
    timer_data->rpm = malloc(sizeof(double));
    if (timer_data->rpm == NULL) {
        fprintf(stderr, "Failed to allocate memory for RPM value\n");
        free(timer_data);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Create timer thread
    pthread_t timer_thread_id;
    if (pthread_create(&timer_thread_id, NULL, timer_thread, timer_data) != 0) {
        fprintf(stderr, "Failed to create timer thread\n");
        free(timer_data->rpm);
        free(timer_data);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop (optional, can be used for other tasks)
    while (1) {
        // Do other tasks here
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    pthread_join(timer_thread_id, NULL);
    free(timer_data->rpm);
    free(timer_data);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    return 0;
}

// ISR function
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate RPM
double calculate_rpm(int pulse_count, double time_interval) {
    return (double)pulse_count / time_interval * 60.0;
}

// Function to log RPM to file
void log_rpm(double rpm) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fclose(log_file);
}

// Timer thread function
void *timer_thread(void *arg) {
    double *rpm = (double *)arg;
    struct timespec start_time, end_time;
    int initial_pulse_count;
    double time_interval;
    double rpm_value;

    // Get initial pulse count
    pthread_mutex_lock(&pulse_mutex);
    initial_pulse_count = pulse_count;
    pthread_mutex_unlock(&pulse_mutex);

    // Record start time
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Wait for 1 second
    gpioDelay(1000); // Sleep for 1 second

    // Record end time
    clock_gettime(CLOCK_MONOTONIC, &end_time);

    // Calculate time interval
    time_interval = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

    // Calculate RPM
    rpm_value = calculate_rpm(initial_pulse_count, time_interval);

    // Log RPM
    log_rpm(rpm_value);

    // Update global RPM value
    *rpm = rpm_value;

    pthread_exit(NULL);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(0);
}

