#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <gpiod.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x39
#define RED_REG 0x02
#define IR_REG 0x04
#define FIFO_DATA_START 0x08
#define FIFO_DATA_LENGTH 4
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_register(int reg);
int write_register(int reg, int value);
int read_fifo_data(int *red, int *ir);
int initialize_gpio();
int set_gpio_output(int gpio, int value);
int initialize_logging();
void log_data(int red, int ir);
void cleanup();
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Read a register
int read_register(int reg) {
    int value = i2cReadByteData(i2c_fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a register
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read FIFO data
int read_fifo_data(int *red, int *ir) {
    char buffer[FIFO_DATA_LENGTH];
    int bytes_read = i2cReadI2CBlockData(i2c_fd, FIFO_DATA_START, buffer, FIFO_DATA_LENGTH);

    if (bytes_read != FIFO_DATA_LENGTH) {
        fprintf(stderr, "Error reading FIFO data: %d\n", bytes_read);
        return -1;
    }

    *red = (buffer[0] << 8) | buffer[1];
    *ir = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line\n");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "adpd144ri", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output\n");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Set GPIO output
int set_gpio_output(int gpio, int value) {
    int ret = gpiod_line_set_value(led_line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Initialize logging
int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    return 0;
}

// Log data
void log_data(int red, int ir) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(led_line);
        return 1;
    }

    int red, ir;
    int led_state = 0;

    // Main loop
    while (!terminate) {
        // Verify sensor presence
