    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s LEVEL\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to detect rising edges
int detect_rising_edge() {
    int level = gpioRead(GPIO_INPUT);
    if (level == 1) {
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Debounce
        return 1;
    }
    return 0;
}

