    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (detect_rising_edge()) {
            if (log_audio_event() != 0) {
                fprintf(stderr, "Error logging audio event\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Clean up GPIO
    gpioWrite(GPIO_OUTPUT, 0); // Ensure GAIN is set to 60dB
    gpioTerminate();

    printf("Audio monitoring stopped.\n");
    return 0;
}

