#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDRESS 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float tvoc;
    float eco2;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
SensorData parse_sensor_data(uint8_t *data);
float calculate_iaq(SensorData data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from I2C
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 7);
    if (bytes_read != 7) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Parse sensor data
SensorData parse_sensor_data(uint8_t *data) {
    SensorData sensor_data;
    // Extract TVOC (ppb) from bytes 1-2 (big-endian)
    uint16_t tvoc_raw = (data[1] << 8) | data[2];
    sensor_data.tvoc = (float)tvoc_raw / 10.0;

    // Extract eCO2 (ppm) from bytes 5-6 (big-endian)
    uint16_t eco2_raw = (data[5] << 8) | data[6];
    sensor_data.eco2 = (float)eco2_raw;

    return sensor_data;
}

// Calculate IAQ index
float calculate_iaq(SensorData data) {
    float iaq = 100.0 - (data.tvoc / 10.0) - ((data.eco2 - 400.0) / 50.0);
    return iaq;
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
