#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define INTRUSION_THRESHOLD 5 // seconds
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int init_gpio(struct gpiod_chip *chip, int gpio_line) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ttp223_tamper";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, gpio_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the GPIO line value
int read_gpio(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to check for intrusion
int check_intrusion(int gpio_value, time_t *start_time, int *intrusion_count) {
    if (gpio_value == 1) {
        if (*intrusion_count == 0) {
            *start_time = time(NULL);
        }
        (*intrusion_count)++;
        if (*intrusion_count >= INTRUSION_THRESHOLD) {
            return 1; // Intrusion detected
        }
    } else {
        *intrusion_count = 0; // Reset count on release
    }
    return 0; // No intrusion
}

// Function to log intrusion events
void log_intrusion(time_t start_time) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("INTRUSION DETECTED: Touch event started at %s\n", timestamp);
}

// Function to cleanup GPIO resources
void cleanup_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup_gpio(NULL);
        return EXIT_FAILURE;
    }

    // Initialize GPIO line
    if (init_gpio(chip, GPIO_LINE) != 0) {
        cleanup_gpio(line);
        return EXIT_FAILURE;
    }

    time_t start_time = 0;
    int intrusion_count = 0;

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int gpio_value = read_gpio(line);
        if (gpio_value < 0) {
            cleanup_gpio(line);
            return EXIT_FAILURE;
        }

        if (check_intrusion(gpio_value, &start_time, &intrusion_count)) {
            log_intrusion(start_time);
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio(line);
    gpiod_chip_close(chip);

    printf("Tamper detection system stopped.\n");

    return EXIT_SUCCESS;
}

