#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Configuration
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 16 // 16-bit PCM
#define BUFFER_SIZE 1024
#define GPIO_PIN 17 // GPIO pin for L/R select
#define ALSA_DEVICE "default" // ALSA device name
#define ALSA_CARD "hw:0,0" // ALSA card name

// Global variables
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static FILE *audio_file = NULL;

// Function prototypes
int initialize_alsa(snd_pcm_t **pcm_handle, const char *device, const char *card);
int configure_alsa(snd_pcm_t *pcm_handle, unsigned int sample_rate, int channels, snd_pcm_format_t format);
int capture_audio(snd_pcm_t *pcm_handle, int buffer_size, short *buffer);
int write_to_file(FILE *file, const short *buffer, int buffer_size);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully.\n");
        running = 0;
    }
}

// Initialize ALSA
int initialize_alsa(snd_pcm_t **pcm_handle, const char *device, const char *card) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(pcm_handle, device, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device %s: %s\n", device, snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Sample rate doesn't match requested rate.  Expected %d, got %d\n", SAMPLE_RATE, rate);
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Configure ALSA
int configure_alsa(snd_pcm_t *pcm_handle, unsigned int sample_rate, int channels, snd_pcm_format_t format) {
    int err;
    snd_pcm_uframes_t frames = BUFFER_SIZE;

    if ((err = snd_pcm_prepare(pcm_handle)) < 0) {
        fprintf(stderr, "Error preparing PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_set_params(pcm_handle, format, sample_rate, channels, frames)) < 0) {
        fprintf(stderr, "Error setting ALSA parameters: %s\n", snd_strerror(err));
        return -1;
    }

    return 0;
}

// Capture audio data
int capture_audio(snd_pcm_t *pcm_handle, int buffer_size, short *buffer) {
    int err;
    size_t frames = buffer_size / (NUM_CHANNELS * (SAMPLE_SIZE / 8)); // Calculate frames based on buffer size and channels

    if ((err = snd_pcm_readi(pcm_handle, buffer, frames)) != frames) {
        fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
        return -1;
    }

    return 0;
}

// Write audio data to file
int write_to_file(FILE *file, const short *buffer, int buffer_size) {
    size_t bytes_written = fwrite(buffer, sizeof(short), buffer_size, file);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    int err;
    short *audio_buffer = NULL;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize ALSA
    if (initialize_alsa(&pcm_handle, ALSA_DEVICE, ALSA_CARD) != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ALSA
    if (configure_alsa(pcm_handle, SAMPLE_RATE, NUM_CHANNELS, SND_PCM_FORMAT_S16_LE) != 0) {
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Allocate audio buffer
    audio_buffer = (short *)malloc(BUFFER_SIZE * sizeof(short));
    if (audio_buffer == NULL) {
        fprintf(stderr, "Failed to allocate audio buffer\n");
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Open audio file for writing
    audio_file = fopen("audio_capture.pcm", "wb");
    if (audio_file == NULL) {
        fprintf(stderr, "Failed to open audio file: %s\n", strerror(errno));
        free(audio_buffer);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    // Main loop
    while (running) {
        // Capture audio data
        if (capture_audio(pcm_handle, BUFFER_SIZE, audio_buffer) == 0) {
            // Write audio data to file
            if (write_to_file(audio_file, audio_buffer, BUFFER_SIZE) != 0) {
                running = 0; // Stop on write error
            }
        } else {
            running = 0; // Stop on capture error
        }

        // Delay to control sampling rate
        usleep(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Clean up
    printf("Cleaning up...\n");
    free(audio_buffer);
    fclose(audio_file);
    snd_pcm_close(pcm_handle);
    gpioTerminate();

    printf("Audio capture stopped.\n");

    return 0;
}

