#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define MAX_DURATION 5 // seconds
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Exponential curve for fan speed based on flame duration
int calculate_fan_speed(int duration);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_event("System started");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) { // Flame detected (LOW signal)
            log_event("Flame detected");
            int duration = 0;
            while (running && flame_detected == 0) {
                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
                flame_detected = read_flame_sensor();
                if (flame_detected == 0) {
                    duration++;
                } else {
                    break;
                }
            }

            int fan_speed = calculate_fan_speed(duration);
            gpioPWM(FAN_PIN, fan_speed);
            log_event("Flame ended, fan speed set to: ", fan_speed);
        } else if (flame_detected == 1) {
            // No flame detected (HIGH signal)
            gpioPWM(FAN_PIN, 0); // Turn off the fan
            log_event("No flame detected, fan turned off");
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    log_event("System stopped");
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, PWM_RANGE);

    return 0;
}

// Read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Control the fan based on flame detection
void control_fan(int flame_detected) {
    if (flame_detected == 0) {
        // Flame detected, increase fan speed
        int duration = 0;
        while (running && flame_detected == 0) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
            flame_detected = read_flame_sensor();
            if (flame_detected == 0) {
                duration++;
            } else {
                break;
            }
        }
        int fan_speed = calculate_fan_speed(duration);
        gpioPWM(FAN_PIN, fan_speed);
    } else {
        // No flame detected, turn off the fan
        gpioPWM(FAN_PIN, 0);
    }
}

// Calculate fan speed using an exponential curve
int calculate_fan_speed(int duration) {
    if (duration > MAX_DURATION) {
        return PWM_RANGE; // Max speed
    }
    return (int)((PWM_RANGE - 1) * (1 - exp(-duration / MAX_DURATION)));
}

// Log events to file with ISO 8601 timestamp
void log_event(const char *event) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);
        fprintf(log_file, "%s %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Log file not open. Event: %s\n", event);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Signal received, shutting down...");
}

// Cleanup resources before exiting
void cleanup() {
    log_event("Cleaning up resources...");
    gpioPWM(FAN_PIN, 0); // Turn off the fan
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(FAN_PIN, PI_INPUT); // Set back to input
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
}

