// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    return spiXfer(spi_handle, (char*)tx_buf, (char*)rx_buf, len);
}

int main() {
    // Initialize configuration
    config.start_frequency = 77.0f;
    config.end_frequency = 79.0f;
    config.chirps = 64;
    config.samples = 256;
    config.frame_period = 0.1f; // 100 ms

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Write log header
    if (write_log_header() != 0) {
        fprintf(stderr, "Failed to write log header\n");
        close_spi();
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t heatmap_data[32768]; // 3.2 MHz * 100 ms / 10 ms (chirp duration) * 256 samples = 32768 bytes
    int frame_number = 0;

    // Main loop
    while (running) {
        // Trigger frame request
        gpioTrigger(23, 1, 1); // GPIO 23 as trigger

        // Wait for data ready
        while (gpioRead(24) == 0 && running) {
            gpioDelay(10); // Small delay to avoid busy-waiting
        }

        // Read heatmap data
        if (read_heatmap_data(heatmap_data, sizeof(heatmap_data)) != 0) {
            fprintf(stderr, "Failed to read heatmap data\n");
            running = 0; // Stop on read error
            continue; // Skip to next iteration
        }

        // Log data
        log_data(heatmap_data, sizeof(heatmap_data), frame_number);

        frame_number++;
        gpioDelay(100); // Delay between frames
    }

    // Cleanup
    close_spi();
    gpioTerminate();
    fclose(log_file);

    return 0;
}

