    if (read_heatmap_data(heatmap_data, sizeof(heatmap_data)) != 0) {
        fprintf(stderr, "Failed to read heatmap data in interrupt handler\n");
        return;
    }
    log_data(heatmap_data, sizeof(heatmap_data), -1); // Log without frame number
}

int read_heatmap_data(uint8_t *data, int count) {
    // Placeholder for reading data from SPI
    // Replace with actual SPI transfer and data parsing logic
    // based on the AWR1642 data format.
    // This example just copies data to the buffer.
    int bytes_read = spi_transfer(data, data, count);
    if (bytes_read != count) {
        fprintf(stderr, "SPI transfer failed or incomplete\n");
        return 1;
    }
    return 0;
}

void log_data(uint8_t *data, int count, int frame_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, ", timestamp, frame_number);

    for (int i = 0; i < count; i++) {
        fprintf(log_file, "%02X ", data[i]);
    }
    fprintf(log_file, "\n");

    fflush(log_file); // Ensure data is written to disk immediately
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int write_log_header() {
    log_file = fopen("radar_log.txt", "ab"); // Open in append binary mode
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Write magic number
    fwrite(&config.magic_number, sizeof(uint32_t), 1, log_file);

    // Write timestamp
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fwrite(timestamp, sizeof(char), strlen(timestamp), log_file);

    // Write configuration struct
    fwrite(&config.start_frequency, sizeof(float), 1, log_file);
    fwrite(&config.end_frequency, sizeof(float), 1, log_file);
    fwrite(&config.chirps, sizeof(int), 1, log_file);
    fwrite(&config.samples, sizeof(int), 1, log_file);
    fwrite(&config.frame_period, sizeof(float), 1, log_file);

    return 0;
}

