#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE 0.01
#define CONVERSION_TIME_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t exponent;
    uint16_t mantissa;
    float lux;
} sensor_data_t;

// Function prototypes
int init_i2c();
int config_opt3001();
int read_result(uint16_t *raw_data);
sensor_data_t process_data(uint16_t raw_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure OPT3001
int config_opt3001() {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = 0xCB; // Continuous conversion mode, 100ms conversion time, Auto range

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, buf, 2) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error configuring OPT3001 (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10); // Wait before retrying
        }
    }
    fprintf(stderr, "Failed to configure OPT3001 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read result register
int read_result(uint16_t *raw_data) {
    char buf[1];
    char read_buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        buf[0] = RESULT_REG;
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error writing to I2C (read result, attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10);
            continue;
        }

        if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
            fprintf(stderr, "Error reading from I2C (read result, attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10);
            continue;
        }

        *raw_data = (read_buf[0] << 8) | read_buf[1];
        return 0; // Success
    }
    fprintf(stderr, "Failed to read result from OPT3001 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Process raw data to lux
sensor_data_t process_data(uint16_t raw_data) {
    sensor_data_t data;
    data.mantissa = raw_data & 0x0FFF; // Mask out exponent
    data.exponent = (raw_data >> 12) & 0x0F; // Extract exponent
    data.lux = LUX_SCALE * (1 << data.exponent) * data.mantissa;
    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, data.lux);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure OPT3001
    if (config_opt3001() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    uint16_t raw_data;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_result(&raw_data) == 0) {
            sensor_data = process_data(raw_data);
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        gpioDelay(500); // Read every 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

