#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_SEC 1

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = POLL_INTERVAL_SEC;
    sleep_time.tv_nsec = 0;

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    struct gpiod_line_request *request;
    int value;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line request configuration
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_detect";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0; // No special flags needed

    // Request the line
    request = gpiod_line_request_config(&config);
    if (!request) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_line_request_release(request);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line as input with pull-up
    if (gpiod_line_request(line, request) != 0) {
        perror("Error requesting GPIO line as input with pull-up");
        gpiod_line_release(line);
        gpiod_line_request_release(request);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Flame detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the line value
        value = gpiod_line_request_get_value(request);
        if (value < 0) {
            perror("Error reading GPIO line value");
            break; // Exit loop on error
        }

        // Get current time
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the flame detection status
        if (value == 0) {
            printf("%s Flame Detected: YES\n", timestamp);
        } else {
            printf("%s Flame Detected: NO\n", timestamp);
        }

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }
    }

    // Cleanup
    gpiod_line_request_release(request);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Flame detection stopped.\n");

    return 0;
}

