#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define the GPIO pins connected to the TTP226 channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set each GPIO pin as an input
    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pins[i]);
            return -1;
        }
    }

    return 0;
}

// Function to read the state of each channel
int read_channel(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", gpio_pin);
        return -1;
    }
    return value;
}

// Function to log the channel states
void log_channel_states(int channel_states[]) {
    for (int i = 0; i < num_channels; i++) {
        printf("Channel %d: %d\n", i + 1, channel_states[i]);
    }
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Allocate memory for the channel states
    int *channel_states = (int *)malloc(num_channels * sizeof(int));
    if (channel_states == NULL) {
        fprintf(stderr, "Failed to allocate memory for channel states\n");
        gpioTerminate();
        return 1;
    }

    // Main loop to read and log the channel states
    while (program_running) {
        for (int i = 0; i < num_channels; i++) {
            channel_states[i] = read_channel(gpio_pins[i]);
            if (channel_states[i] < 0) {
                program_running = 0; // Exit loop if read fails
                break;
            }
        }

        if (program_running) {
            log_channel_states(channel_states);
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Free the allocated memory
    free(channel_states);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

