#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the TTP226 sensors
#define NUM_CHANNELS 8
const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    program_running = 0;
    printf("\nSIGINT received, exiting gracefully...\n");
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure a GPIO pin as input with a pull-down resistor
int configure_gpio(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pin);
        return -1;
    }
    if (gpioSetPullUpDown(gpio_pin, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to format the sensor data into a string
void format_sensor_data(int sensor_states[], char *buffer, size_t buffer_size) {
    buffer[0] = '\0'; // Initialize the buffer with an empty string
    for (int i = 0; i < NUM_CHANNELS; i++) {
        char state_str[3];
        snprintf(state_str, sizeof(state_str), "CH%d=%d", i + 1, sensor_states[i]);
        strcat(buffer, state_str);
        if (i < NUM_CHANNELS - 1) {
            strcat(buffer, " ");
        }
    }
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Configure GPIO pins
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (configure_gpio(sensor_pins[i]) != 0) {
            gpioTerminate();
            return 1;
        }
    }

    // Sampling loop
    while (program_running) {
        int sensor_states[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            sensor_states[i] = read_sensor(sensor_pins[i]);
        }

        char timestamp[20];
        get_timestamp(timestamp);

        char sensor_data[100];
        format_sensor_data(sensor_states, sensor_data, sizeof(sensor_data));

        printf("[%s] %s\n", timestamp, sensor_data);

        gpioDelay(100000); // 100 ms delay
    }

    // Terminate pigpio
    gpioTerminate();
    return 0;
}

