#include <signal.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 channels
const int gpio_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pins[i]);
            return -1;
        }
        if (gpioSetPullUpDown(gpio_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", gpio_pins[i]);
            return -1;
        }
    }
    return 0;
}

// Function to read the sensor data
int read_sensor_data(int *data) {
    for (int i = 0; i < num_channels; i++) {
        data[i] = gpioRead(gpio_pins[i]);
        if (data[i] < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", gpio_pins[i]);
            return -1;
        }
    }
    return 0;
}

// Function to format the data into a CSV string
void format_data(int *data, char *buffer, size_t buffer_size) {
    snprintf(buffer, buffer_size, "%ld,%d,%d,%d,%d,%d,%d,%d,%d\n",
             time(NULL), data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7]);
}

// Function to print the data to the console
void print_data(const char *data) {
    printf("%s", data);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Allocate memory for sensor data
    int *sensor_data = (int *)malloc(num_channels * sizeof(int));
    if (sensor_data == NULL) {
        fprintf(stderr, "Failed to allocate memory for sensor data\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Format data
            char data_string[256];
            format_data(sensor_data, data_string, sizeof(data_string));

            // Print data
            print_data(data_string);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait 50 ms
        gpioDelay(50);
    }

    // Free allocated memory
    free(sensor_data);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

