    if (initialize_gpio() != 0) {
        return 1;
    }

    // Allocate memory for sensor data
    int *sensor_data = (int *)malloc(num_channels * sizeof(int));
    if (sensor_data == NULL) {
        fprintf(stderr, "Failed to allocate memory for sensor data\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Format data
            char data_string[256];
            format_data(sensor_data, data_string, sizeof(data_string));

            // Print data
            print_data(data_string);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait 50 ms
        gpioDelay(50);
    }

    // Free allocated memory
    free(sensor_data);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

