#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_PART_ID 0x00
#define SI1145_HW_KEY 0x17
#define SI1145_CHLIST 0x01
#define SI1145_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float uv_index;
    int als_visible;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the Si1145 sensor
int initialize_sensor() {
    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, SI1145_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }
    printf("Si1145 PART ID: 0x%02X\n", part_id);

    // Write HW_KEY
    if (i2cWriteByteData(i2c_handle, SI1145_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing to HW_KEY register\n");
        return -1;
    }

    // Configure CHLIST
    if (i2cWriteByteData(i2c_handle, SI1145_CHLIST, 0x01) < 0) {
        fprintf(stderr, "Error writing to CHLIST register\n");
        return -1;
    }

    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, SI1145_ALS_FORCE, 0x06) < 0) {
        fprintf(stderr, "Error writing to ALS_FORCE register\n");
        return -1;
    }

    return 0;
}

// Read UV index and ALS visible data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int uv_index_raw, als_visible_raw;

    // Read UV index
    uv_index_raw = i2cReadByteData(i2c_handle, 0x2C); // UV index register
    if (uv_index_raw < 0) {
        fprintf(stderr, "Error reading UV index\n");
        data.uv_index = -1.0; // Indicate error
    } else {
        data.uv_index = (float)uv_index_raw / 10.0; // UV index is stored as a decimal value
    }

    // Read ALS visible
    als_visible_raw = i2cReadByteData(i2c_handle, 0x22); // ALS visible register
    if (als_visible_raw < 0) {
        fprintf(stderr, "Error reading ALS visible\n");
        data.als_visible = -1; // Indicate error
    } else {
        data.als_visible = als_visible_raw;
    }

    return data;
}

// Log data to CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, data.uv_index, data.als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();

        if (data.uv_index >= 0) {
            printf("UV Index: %.2f, ALS Visible: %d\n", data.uv_index, data.als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        log_data(data);
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

