    bytes_read = read(i2c_fd, data, 9);
    if (bytes_read != 9) {
        perror("Error reading flow data");
        return -1;
    }

    // Validate CRC for flow data
    if (validate_crc(data, 3, data[6])) {
        fprintf(stderr, "CRC validation failed for flow data\n");
        return -1;
    }

    // Convert raw flow data to ml/min
    int16_t raw_flow = (data[0] << 8) | data[1];
    *flow_rate = (float)raw_flow * SCALE_FACTOR;

    return 0;
}

// Function to log data to file
void log_data(float flow_rate1, float flow_rate2, float avg_flow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Sensor1: %.2f, Sensor2: %.2f, Avg: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow_rate1, flow_rate2, avg_flow);
    fflush(log_file);
}

// Function to control the alarm
void control_alarm(float avg_flow) {
    if (avg_flow < ALARM_THRESHOLD) {
        gpioWrite(GPIO_ALARM, 1); // Activate alarm
    } else {
        gpioWrite(GPIO_ALARM, 0); // Deactivate alarm
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd1 >= 0) {
        close(i2c_fd1);
    }
    if (i2c_fd2 >= 0) {
        close(i2c_fd2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_ALARM, 0); // Ensure alarm is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_ALARM, PI_OUTPUT);

    // Initialize I2C for both sensors
    i2c_fd1 = init_i2c(SLF3S_ADDR1);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1\n");
        cleanup();
        return 1;
    }

    i2c_fd2 = init_i2c(SLF3S_ADDR2);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow_rate1, flow_rate2, avg_flow;
    int read_success1, read_success2;

    // Main loop
    while (!terminate) {
        read_success1 = read_flow_rate(i2c_fd1, &flow_rate1);
        read_success2 = read_flow_rate(i2c_fd2, &flow_rate2);

        if (read_success1 == 0 && read_success2 == 0) {
            avg_flow = (flow_rate1 + flow_rate2) / 2.0;
            log_data(flow_rate1, flow_rate2, avg_flow);
            control_alarm(avg_flow);
        } else {
            fprintf(stderr, "Error reading flow data from one or more sensors\n");
        }

        gpioDelay(1000000); // 1-second delay
    }

    cleanup();
    return 0;
}

