// Structure to hold timestamp and sensor reading
typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(time_t timestamp, int reading);
void print_buffer();
void cleanup_gpio();
void signal_handler(int signal);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) {
            time_t current_time = time(NULL);
            add_to_buffer(current_time, sensor_value);
            printf("Obstacle detected at GPIO %d\n", GPIO_PIN);
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    return 0; // This line will not be reached due to the infinite loop
}

// Initialize pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
