#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x55
#define I2C_SPEED 400000 // 400 kHz
#define MODE_CONTROL_REG 0x1D
#define MODE_CONTROL_VALUE 0x10
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_REG 0x2A
#define ACCEL_Y_REG 0x2C
#define ACCEL_Z_REG 0x2E
#define ACCEL_SCALE 0.0009765625 // g/LSB
#define SAMPLE_INTERVAL_MS 500

// Global variables for signal handling
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(const char *bus, int address);
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int i2c_read_reg(int fd, unsigned char reg, unsigned char *value);
int i2c_read_word(int fd, unsigned char reg, short *value);
int i2c_close(int fd);
int log_data(FILE *fp, short x, short y, short z);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write register function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C register");
        return -1;
    }
    return 0;
}

// I2C read register function
int i2c_read_reg(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C register for read");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C register");
        return -1;
    }
    return 0;
}

// I2C read word function
int i2c_read_word(int fd, unsigned char reg, short *value) {
    unsigned char buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C register for read (word)");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C register (word)");
        return -1;
    }
    *value = (short)((buf[1] << 8) | buf[0]);
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C bus");
        return -1;
    }
    return 0;
}

// Log data function
int log_data(FILE *fp, short x, short y, short z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed. Exiting.\n");
        return 1;
    }

    // Initialize sensor
    if (i2c_write_reg(i2c_fd, MODE_CONTROL_REG, MODE_CONTROL_VALUE) < 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        i2c_close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        i2c_close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Main loop
    short x, y, z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    while (!terminate) {
        // Read sensor data
        if (i2c_read_word(i2c_fd, ACCEL_X_REG, &x) < 0) {
            fprintf(stderr, "Error reading X axis data. Retrying.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }
        if (i2c_read_word(i2c_fd, ACCEL_Y_REG, &y) < 0) {
            fprintf(stderr, "Error reading Y axis data. Retrying.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }
        if (i2c_read_word(i2c_fd, ACCEL_Z_REG, &z) < 0) {
            fprintf(stderr, "Error reading Z axis data. Retrying.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Log data
        if (log_data(csv_file, x, y, z) < 0) {
            fprintf(stderr, "Error logging data. Retrying.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Wait for the next sample
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    i2c_close(i2c_fd);
    fclose(csv_file);

    return 0;
}

