#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to track LED state
static volatile int led_state = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED
int control_led(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result < 0) {
        fprintf(stderr, "Error writing to LED on GPIO %d: %d\n", gpio_pin, result);
        return -1; // Indicate error
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting mode for SENSOR_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting mode for SENSOR_2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting mode for LED_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit loop on sensor read error
        }

        // Check if either sensor detects an obstacle (LOW signal)
        if (sensor1_value == 0 || sensor2_value == 0) {
            // Obstacle detected, turn LED ON
            if (control_led(LED_PIN, 1) < 0) {
                fprintf(stderr, "Error controlling LED, exiting...\n");
                break; // Exit loop on LED control error
            }
            led_state = 1; // Update LED state
        } else {
            // No obstacle detected, turn LED OFF
            if (control_led(LED_PIN, 0) < 0) {
                fprintf(stderr, "Error controlling LED, exiting...\n");
                break; // Exit loop on LED control error
            }
            led_state = 0; // Update LED state
        }

        // Wait 100 ms
