#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_LOG_FILE "stall_log.txt"
#define STALL_DURATION_SEC 2

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio);
int is_stall(int sensor1_value, int sensor2_value);
int log_stall();
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid sensor reading on GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
    return value;
}

// Function to determine if a stall has occurred
int is_stall(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log stall events with timestamp and avoid duplicates
int log_stall() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Stall detected\n", timestamp);
        fflush(log_file); // Ensure immediate write to file
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Indicate an error
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for sensors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open log file
    log_file = fopen(STALL_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", STALL_LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int stall_detected = 0;
    int sensor1_value, sensor2_value;

    printf("Monitoring conveyor belt for stalls...\n");

    while (program_running) {
        sensor1_value = read_sensor(SENSOR_1_GPIO);
        sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (is_stall(sensor1_value, sensor2_value)) {
            if (!stall_detected) {
                if (log_stall() == 0) {
                    printf("Stall detected and logged.\n");
                } else {
                    fprintf(stderr, "Error logging stall.\n");
                }
                stall_detected = 1; // Set stall flag
            }
        } else {
            stall_detected = 0; // Reset stall flag
        }

        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

