#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x0E

// Register addresses
#define DEVICE_ID_REG 0x00
#define X_AXIS_REG 0x01
#define Y_AXIS_REG 0x03
#define Z_AXIS_REG 0x05
#define CONFIG_REG 0x06

// Configuration values
#define CONTINUOUS_MODE 0x01
#define X_ENABLE 0x80
#define Y_ENABLE 0x40
#define Z_ENABLE 0x20
#define RANGE_50MT 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tmag5170_init();
int read_register(int reg);
int write_register(int reg, int value);
int read_magnetic_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_mT(int16_t raw_data);
int log_data(float x_mT, float y_mT, float z_mT);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the TMAG5170 sensor
int tmag5170_init() {
    // Verify device ID
    int device_id = read_register(DEVICE_ID_REG);
    if (device_id != 0x8D) {
        fprintf(stderr, "Error: Invalid device ID: 0x%X\n", device_id);
        return -1;
    }

    // Configure the sensor for continuous conversion mode with all axes enabled and 50 mT range
    if (write_register(CONFIG_REG, CONTINUOUS_MODE | X_ENABLE | Y_ENABLE | Z_ENABLE) != 0) {
        fprintf(stderr, "Error: Failed to configure sensor.\n");
        return -1;
    }

    return 0;
}

// Read a single register from the TMAG5170
int read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Write a single register to the TMAG5170
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read magnetic data from the TMAG5170
int read_magnetic_data(int16_t *x, int16_t *y, int16_t *z) {
    int x_high = i2cReadByteData(i2c_handle, X_AXIS_REG);
    int x_low = i2cReadByteData(i2c_handle, X_AXIS_REG + 1);
    int y_high = i2cReadByteData(i2c_handle, Y_AXIS_REG);
    int y_low = i2cReadByteData(i2c_handle, Y_AXIS_REG + 1);
    int z_high = i2cReadByteData(i2c_handle, Z_AXIS_REG);
    int z_low = i2cReadByteData(i2c_handle, Z_AXIS_REG + 1);

    if (x_high < 0 || x_low < 0 || y_high < 0 || y_low < 0 || z_high < 0 || z_low < 0) {
        fprintf(stderr, "Error reading magnetic data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((x_high << 8) | x_low);
    *y = (int16_t)((y_high << 8) | y_low);
    *z = (int16_t)((z_high << 8) | z_low);

    return 0;
}

// Convert raw magnetic data to milliTesla (mT)
float convert_to_mT(int16_t raw_data) {
    // Assuming 16-bit two's complement representation
    // and a scale factor of 0.1 mT/LSB for 50 mT range
    return (float)raw_data * 0.1;
}

// Log data to CSV file
int log_data(float x_mT, float y_mT, float z_mT) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_mT, y_mT, z_mT);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (tmag5170_init() != 0) {
        fprintf(stderr, "Error: TMAG5170 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_mT,Y_mT,Z_mT\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x_mT, y_mT, z_mT;

    // Main loop
    while (!terminate) {
        if (read_magnetic_data(&raw_x, &raw_y, &raw_z) == 0) {
            x_mT = convert_to_mT(raw_x);
            y_mT = convert_to_mT(raw_y);
            z_mT = convert_to_mT(raw_z);

            if (log_data(x_mT, y_mT, z_mT) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read magnetic data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

