#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 7
#define LOG_FILE "rpm_log.txt"

static volatile int pulse_count = 0;
static volatile int running = 1;

// Function to handle signals (Ctrl+C, termination)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Callback function for GPIO interrupt
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user; // Unused parameters
    pulse_count++;
}

// Function to add a pulse count atomically
int atomic_add(int *count, int increment) {
    int current = *count;
    *count = current + increment;
    return current; // Return the old value
}

// Function to calculate RPM
double calculate_rpm(int pulses_per_second) {
    return pulses_per_second * 60.0;
}

// Function to log RPM to a file
int log_rpm(double rpm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s %.2f\n", timestamp, rpm);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int pulses = atomic_add(&pulse_count, 1); // Increment pulse count atomically
        double rpm = calculate_rpm(pulses);

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Error logging RPM\n");
        }

        printf("RPM: %.2f\n", rpm);

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt
    gpioTerminate(); // Terminate pigpio

    return 0;
}

