// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the mutex
pthread_mutex_t log_mutex;

// Define the condition variable
pthread_cond_t log_cond;

// Define the previous state
int previous_state = 0;

// Define the current state
int current_state = 0;

// Define the direction
char direction = 'N';

// Function prototypes
void log_rotation_event(const char *direction);
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user);
void *log_thread(void *arg);
void signal_handler(int signal);

// Function to log rotation events to a file
void log_rotation_event(const char *direction) {
    pthread_mutex_lock(&log_mutex);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, (long)(time(NULL) - t) * 1000, direction);

    fclose(fp);
    pthread_mutex_unlock(&log_mutex);
}

// Interrupt service routine for sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;

    if (diff > 5000) {
        last_tick = tick;
        return;
    }

    if (level == PI_HIGH) {
        gpioSetAlertFuncEx(SENSOR_A_GPIO, sensor_a_isr, NULL);
        return;
    }

    if (previous_state == 0) {
        previous_state = level;
        return;
    }

    int new_state = level;
    if (new_state != previous_state) {
        if (new_state == 0) {
            // Sensor A is low
            if (previous_state == 1) {
                // Quadrature transition: A=0, B=1 -> CCW
                direction = 'C';
            } else if (previous_state == 0) {
                // Quadrature transition: A=0, B=0 -> N
            } else {
                // Quadrature transition: A=1, B=0 -> N
            }
        } else {
            // Sensor A is high
            if (previous_state == 1) {
                // Quadrature transition: A=1, B=1 -> N
            } else if (previous_state == 0) {
                // Quadrature transition: A=1, B=0 -> C
            } else {
                // Quadrature transition: A=0, B=1 -> N
            }
        }
        previous_state = new_state;
    }
}

// Interrupt service routine for sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;

    if (diff > 5000) {
        last_tick = tick;
        return;
    }

    if (level == PI_HIGH) {
        gpioSetAlertFuncEx(SENSOR_B_GPIO, sensor_b_isr, NULL);
        return;
    }

    if (previous_state == 0) {
        previous_state = level;
        return;
    }

    int new_state = level;
    if (new_state != previous_state) {
        if (new_state == 0) {
            // Sensor B is low
            if (previous_state == 1) {
                // Quadrature transition: A=1, B=0 -> C
                direction = 'C';
            } else if (previous_state == 0) {
                // Quadrature transition: A=0, B=0 -> N
            } else {
                // Quadrature transition: A=1, B=1 -> N
            }
        } else {
            // Sensor B is high
            if (previous_state == 1) {
                // Quadrature transition: A=0, B=1 -> C
            } else if (previous_state == 0) {
                // Quadrature transition: A=0, B=0 -> N
            } else {
                // Quadrature transition: A=1, B=1 -> N
            }
        }
        previous_state = new_state;
    }
}

// Thread function to log rotation events
void *log_thread(void *arg) {
    while (1) {
        pthread_cond_wait(&log_cond, &log_mutex);
        log_rotation_event(direction);
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    pthread_mutex_lock(&log_mutex);
    pthread_cond_signal(&log_cond);
    pthread_mutex_unlock(&log_mutex);
    pthread_exit(NULL);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Initialize mutex and condition variable
    if (pthread_mutex_init(&log_mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        gpioTerminate();
        return 1;
    }

    if (pthread_cond_init(&log_cond, NULL) != 0) {
        perror("Condition variable initialization failed");
        pthread_mutex_destroy(&log_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handlers
    gpioSetAlertFuncEx(SENSOR_A_GPIO, sensor_a_isr, NULL);
    gpioSetAlertFuncEx(SENSOR_B_GPIO, sensor_b_isr, NULL);

    // Create the log thread
    pthread_t log_thread_id;
    if (pthread_create(&log_thread_id, NULL, log_thread, NULL) != 0) {
        perror("Failed to create log thread");
        pthread_mutex_destroy(&log_mutex);
        pthread_cond_destroy(&log_cond);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Wait for a signal
        pause();
    }

    // Cleanup (should not reach here in normal operation)
    pthread_join(log_thread_id, NULL);
    pthread_mutex_destroy(&log_mutex);
    pthread_cond_destroy(&log_cond);
    gpioTerminate();

    return 0;
}

