#include <time.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define chip names
#define GPIOCHIP "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_touch_sensor(void);
int write_led(int value);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO
int init_gpio(void)
{
    int ret;
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", GPIOCHIP);
        return -1;
    }

    // Request touch sensor line
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
