// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static int led_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_led();
void signal_handler(int signal);

// Structure to hold libgpiod context
typedef struct {
    int chip;
    int line;
} libgpiod_context_t;

// Function to initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioWrite(LED_PIN, 0); // Turn LED off initially

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the LED state
void toggle_led() {
    led_state = !led_state;
    gpioWrite(LED_PIN, led_state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Release GPIO resources
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
