#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Define the size of the circular buffer
#define BUFFER_SIZE 100

// Structure to store touch events
typedef struct {
    int sensor_pin;
    long timestamp;
    int state;
} TouchEvent;

// Circular buffer
TouchEvent event_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_event(int sensor_pin, long timestamp, int state);
void print_log_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_1_PIN\n");
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_PIN\n");
        return -1;
    }

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

// Function to log a touch event
void log_event(int sensor_pin, long timestamp, int state) {
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp = timestamp;
    event_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_index == 0) {
        overflow_count++;
    }
}

// Function to print the log buffer contents
void print_log_buffer() {
    printf("Log Buffer Contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        if (event_buffer[index].sensor_pin != 0) {
            printf("  Index: %d, Sensor: %d, Timestamp: %ld, State: %d\n",
                   index, event_buffer[index].sensor_pin, event_buffer[index].timestamp, event_buffer[index].state);
        }
    }
    printf("Overflow Count: %d\n", overflow_count);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor_1_value = gpioRead(SENSOR_1_PIN);
        int sensor_2_value = gpioRead(SENSOR_2_PIN);

        // Check for touch events on sensor 1
        if (sensor_1_value == 1) {
            long timestamp = time(NULL);
            log_event(SENSOR_1_PIN, timestamp, sensor_1_value);
            gpioWrite(LED_1_PIN, sensor_1_value);
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        // Check for touch events on sensor 2
        if (sensor_2_value == 1) {
            long timestamp = time(NULL);
            log_event(SENSOR_2_PIN, timestamp, sensor_2_value);
            gpioWrite(LED_2_PIN, sensor_2_value);
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup and exit
    cleanup_gpio();
    print_log_buffer();
    return 0;
}

