    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if (rain_detected) {
        fprintf(fp, "%s Rain Detected\n", timestamp);
    } else {
        fprintf(fp, "%s No Rain\n", timestamp);
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    int previous_state = 1; // Assume no rain initially (active-low)

    while (running) {
        int current_state = read_rain_sensor(GPIO_PIN);

        if (current_state != previous_state) {
            if (log_rain_event(current_state) != 0) {
                fprintf(stderr, "Error logging rain event\n");
            }
            previous_state = current_state;
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

