    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Callback function for debouncing
void debounce(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
        if (gpio == SENSOR1_GPIO) {
            static SensorStates sensor_states = {0, 0};
            if (level == 0) { // Falling edge detected
                sensor_states.sensor1_state = level;
                log_data(sensor_states);
