#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define sensor I2C address
#define SI1182_ADDR 0x28

// Define register addresses
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04

// Define heart rate and SpO2 ranges
#define MIN_HEART_RATE 40
#define MAX_HEART_RATE 200
#define MIN_SPO2 80
#define MAX_SPO2 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *heart_rate, int *spo2);
int validate_sensor_data(int heart_rate, int spo2);
int log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the Si1182 sensor
int initialize_sensor() {
    // Verify sensor presence by reading PART_ID register
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }

    // Configure the sensor for continuous measurement
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01) < 0) { // Example configuration
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read heart rate and SpO2 data from the sensor
int read_sensor_data(int *heart_rate, int *spo2) {
    int heart_rate_raw, spo2_raw;

    // Read heart rate data
    heart_rate_raw = i2cReadByteData(i2c_handle, HEART_RATE_REG);
    if (heart_rate_raw < 0) {
        fprintf(stderr, "Error reading heart rate data: %d\n", heart_rate_raw);
        return -1;
    }

    // Read SpO2 data
    spo2_raw = i2cReadByteData(i2c_handle, SPO2_REG);
    if (spo2_raw < 0) {
        fprintf(stderr, "Error reading SpO2 data: %d\n", spo2_raw);
        return -1;
    }

    *heart_rate = heart_rate_raw;
    *spo2 = spo2_raw;

    return 0;
}

// Function to validate sensor data
int validate_sensor_data(int heart_rate, int spo2) {
    if (heart_rate < MIN_HEART_RATE || heart_rate > MAX_HEART_RATE) {
        fprintf(stderr, "Warning: Heart rate out of range: %d BPM\n", heart_rate);
        return -1;
    }

    if (spo2 < MIN_SPO2 || spo2 > MAX_SPO2) {
        fprintf(stderr, "Warning: SpO2 out of range: %d%%\n", spo2);
        return -1;
    }

    return 0;
}

// Function to log data to a file
int log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    int heart_rate, spo2;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&heart_rate, &spo2) == 0) {
            // Validate sensor data
            if (validate_sensor_data(heart_rate, spo2) == 0) {
                // Log data
                log_data(heart_rate, spo2);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's replacement for time_sleep
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

