#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define alarm duration (in milliseconds)
#define ALARM_DURATION 5000

// Define tilt threshold (HIGH)
#define TILT_THRESHOLD 1

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int activate_alarm(int gpio_pin, int duration_ms);
int deactivate_alarm(int gpio_pin);
int log_event(const char *event_type);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
    time_t start_time;
} SensorData;

SensorData sensor_data = {0, 0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioWrite(ALARM_PIN, 0); // Ensure alarm is initially off

    return 0; // Indicate success
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to activate the alarm
int activate_alarm(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Set alarm pin HIGH
    gpioDelay(duration_ms);  // Wait for specified duration
    gpioWrite(gpio_pin, 0); // Set alarm pin LOW
    return 0;
}

// Function to deactivate the alarm
int deactivate_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set alarm pin LOW
    return 0;
}

// Function to log events to file
int log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", buf, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return 1; // Indicate failure
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Clean up GPIO before exiting
        return 1; // Exit if log file opening fails
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for tilt events
        if (sensor1_value == TILT_THRESHOLD && sensor2_value == TILT_THRESHOLD) {
            // Tilt started
            if (sensor_data.sensor1_state == 0 && sensor_data.sensor2_state == 0) {
                log_event("tilt-start");
                sensor_data.start_time = time(NULL);
            }
        } else {
            // Tilt ended
            if (sensor1_value == 0 && sensor2_value == 0) {
                if (sensor_data.sensor1_state == TILT_THRESHOLD && sensor_data.sensor2_state == TILT_THRESHOLD) {
                    time_t current_time = time(NULL);
                    if (difftime(current_time, sensor_data.start_time) >= 2.0) {
                        log_event("threshold-exceeded");
                        activate_alarm(ALARM_PIN, ALARM_DURATION);
                    }
                    sensor_data.start_time = 0; // Reset start time
                }
            }
        }

        // Update sensor states
        sensor_data.sensor1_state = sensor1_value;
        sensor_data.sensor2_state = sensor2_value;

        gpioDelay(100); // Poll every 100 milliseconds
    }

