#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_ADDRESS 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_LSB 0x28
#define ACCEL_X_MSB 0x29
#define ACCEL_Y_LSB 0x2A
#define ACCEL_Y_MSB 0x2B
#define ACCEL_Z_LSB 0x2C
#define ACCEL_Z_MSB 0x2D
#define LED_GPIO 17
#define THRESHOLD 500
#define LOG_FILE "seismic_events.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor(int i2c_handle, int address);
int read_acceleration(int i2c_handle, int address, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
int log_event(float magnitude);
void control_led(int gpio, int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Omron D7S-A0011 sensor
int initialize_sensor(int i2c_handle, int address) {
    int retries = 3;
    while (retries > 0) {
        int result = i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00); // Clear power-down bit
        if (result >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to CTRL1_REG: %d, retries left: %d\n", result, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Reads acceleration data from the sensor
int read_acceleration(int i2c_handle, int address, float *x, float *y, float *z) {
    char buffer[6];
    int retries = 3;
    while (retries > 0) {
        int result = i2cReadI2CBlockData(i2c_handle, ACCEL_X_LSB, buffer, 6);
        if (result == 6) {
            // Convert little-endian to float
            *x = (float)((int16_t)((buffer[1] << 8) | buffer[0]));
            *y = (float)((int16_t)((buffer[3] << 8) | buffer[2]));
            *z = (float)((int16_t)((buffer[5] << 8) | buffer[4]));
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading acceleration data: %d, retries left: %d\n", result, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1; // Failure
}

// Calculates the Euclidean magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Logs an event to the log file
int log_event(float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Controls the LED state
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

int main(int argc, char *argv[]) {
    int address = DEFAULT_ADDRESS;
    if (argc > 1) {
        address = strtol(argv[1], NULL, 16);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle, address) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(i2c_handle, address, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                printf("Threshold exceeded! Magnitude: %.2f\n", magnitude);
                log_event(magnitude);
                control_led(LED_GPIO, 1); // Turn on LED
                gpioDelay(1000000);       // 1 second delay
                control_led(LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

