// Define GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return (value == 0) ? 1 : 0; // Active-low
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as input or output
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);
        int sensor4_value = read_sensor(SENSOR4_PIN);

        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1 || sensor4_value == -1) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }

        int any_object_detected = (sensor1_value || sensor2_value || sensor3_value || sensor4_value);

        control_led(LED_PIN, any_object_detected);

        gpioDelay(50); // 50 ms delay
    }

    // Clean up GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

