#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

// Configuration
#define NUM_SENSORS 5
const int SENSOR_PINS[NUM_SENSORS] = {2, 3, 4, 17, 27};
const char *LOG_FILE = "/var/log/flame_events.log";
const char *SYSLOG_LOG = "flame_monitor";

// Global variables
static volatile sig_atomic_t terminate = 0;
static int *sensor_lines = NULL;
static int sensor_pins[NUM_SENSORS] = SENSOR_PINS;
static int line_fds[NUM_SENSORS];
static int last_flame_states[NUM_SENSORS] = {1}; // Assume no flame initially
static int last_flame_times[NUM_SENSORS] = {0};

// Function prototypes
void signal_handler(int sig);
int initialize_gpio();
int read_sensor(int pin);
bool is_flame_detected(int pin);
void log_event(int pin);
void log_error(const char *message);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        syslog(LOG_USER | LOG_PID, "Received signal %d, terminating...", sig);
    }
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    sensor_lines = (int *)malloc(NUM_SENSORS * sizeof(int));
    if (sensor_lines == NULL) {
        log_error("Failed to allocate memory for sensor lines");
        gpioTerminate();
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpioSetMode(sensor_pins[i], PI_INPUT);
        if (sensor_lines[i] != 0) {
            log_error("Failed to set mode for pin " + (char)(sensor_pins[i] + '0'));
            free(sensor_lines);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

// Read sensor value using pigpio
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        log_error("Failed to read sensor value for pin " + (char)(pin + '0'));
        return -1;
    }
    return value;
}

// Check if flame is detected (LOW signal)
bool is_flame_detected(int pin) {
    int value = read_sensor(pin);
    if (value < 0) {
        return false; // Return false on error to avoid false positives
    }
    return (value == 0);
}

// Log event to file
void log_event(int pin) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, pin, pin);
    fflush(fp);
    fclose(fp);
}

// Log error to file and syslog
void log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_USER | LOG_ERR, "Failed to open log file for error logging");
        perror(message);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
