#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO chip and lines
#define GPIOCHIP "gpiochip0"
#define NUM_LINES 8

// Define BCM GPIO pins for the TTP226 channels
const int bcm_pins[NUM_LINES] = {5, 6, 13, 19, 26, 12, 16, 20};

// Structure to hold GPIO line information
struct gpiod_line {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int index;
};

// Global array of GPIO lines
struct gpiod_line lines[NUM_LINES];

// Function prototypes
int initialize_gpio();
int read_sensor(int index);
void log_event(int index, int pin);
void cleanup_gpio();
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Initializes the GPIO chip and lines
int initialize_gpio() {
    int i;
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Configure each line for input with pull-up resistor
    for (i = 0; i < NUM_LINES; i++) {
        lines[i].index = i;
        lines[i].chip = chip;

        // Create a line request configuration
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
        config.flags = 0; // No special flags needed

        // Request the line
        lines[i].line = gpiod_chip_get_line(chip, bcm_pins[i]);
        if (!lines[i].line) {
            fprintf(stderr, "Error getting line %d: %s\n", i, strerror(errno));
            gpiod_chip_close(chip);
            return -1;
        }

        // Request the line with pull-up resistor
        if (gpiod_line_request(lines[i].line, &config, 0) < 0) {
            fprintf(stderr, "Error requesting line %d: %s\n", i, strerror(errno));
            gpiod_line_release(lines[i].line);
            gpiod_chip_close(chip);
            return -1;
        }

        // Wait for the line to stabilize (optional, but good practice)
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100 * 1000 * 1000; // 100ms
        nanosleep(&ts, NULL);
    }

    return 0;
}

// Reads the state of a single sensor
int read_sensor(int index) {
    int pin = bcm_pins[index];
    int value = gpiod_line_get_value(lines[index].line);
    if (value < 0) {
        fprintf(stderr, "Error reading line %d: %s\n", index, strerror(errno));
        return -1;
    }
    return value;
}

// Logs an event to the console with ISO 8601 timestamp
void log_event(int index, int pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Sensor %d (BCM %d) touched\n", timestamp, index, pin);
}

// Cleans up GPIO resources
void cleanup_gpio() {
    int i;
    struct gpiod_line *line;

    for (i = 0; i < NUM_LINES; i++) {
        line = lines[i].line;
        if (line) {
            gpiod_line_release(line);
        }
    }

    gpiod_chip_close(lines[0].chip);
}

int main() {
    int i, prev_state[NUM_LINES];
    struct timespec ts;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize previous states
    for (i = 0; i < NUM_LINES; i++) {
        prev_state[i] = read_sensor(i);
        if (prev_state[i] < 0) {
            fprintf(stderr, "Failed to read initial state for sensor %d. Exiting.\n", i);
            cleanup_gpio();
            return 1;
        }
    }

    // Main loop
    while (1) {
        for (i = 0; i < NUM_LINES; i++) {
            int current_state = read_sensor(i);
            if (current_state < 0) {
                fprintf(stderr, "Error reading sensor %d, skipping.\n", i);
                continue; // Skip to the next sensor
            }

            if (current_state != prev_state[i]) {
                log_event(i, bcm_pins[i]);
                prev_state[i] = current_state;
            }
        }

        // Poll all pins every 50 milliseconds
        ts.tv_sec = 0;
        ts.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&ts, NULL);
    }

    return 0;
}

