    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure VEML7700 sensor
int config_veml7700() {
    uint16_t config_value = 0x0000; // ALS_GAIN = 1/8, ALS_IT = 100ms
    char buf[2];
    buf[0] = config_value & 0xFF; // Low byte
    buf[1] = (config_value >> 8) & 0xFF; // High byte

    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ambient light data
int read_ambient_light(int *raw_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *raw_value = (buf[1] << 8) | buf[0]; // Combine high and low bytes
    return 0;
}

// Convert raw data to lux
float convert_to_lux(int raw_value) {
    return (float)raw_value * 0.0576;
}

// Set LED brightness using PWM
int set_led_brightness(float lux) {
    int brightness = PWM_RANGE;

    if (lux < LUX_THRESHOLD_1) {
        brightness = PWM_RANGE;
    } else if (lux < LUX_THRESHOLD_2) {
        brightness = PWM_RANGE * 0.75;
    } else if (lux < LUX_THRESHOLD_3) {
        brightness = PWM_RANGE * 0.5;
    } else {
        brightness = PWM_RANGE * 0.25;
    }

    gpioPWM(GPIO_LED, brightness);
    return 0;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    gpioPWM(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_LED, PWM_RANGE);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Configure VEML7700 sensor
    if (config_veml7700() != 0) {
        fprintf(stderr, "VEML7700 configuration failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_value;
    float lux;
    int error_code;

    // Main loop
    while (!terminate) {
        // Read ambient light
        error_code = read_ambient_light(&raw_value);
        if (error_code != 0) {
            fprintf(stderr, "Error reading ambient light, error code: %d\n", error_code);
            log_data(0.0, 0, error_code);
            gpioDelay(1000000); // Wait 1 second
            continue;
        }

        // Convert to lux
        lux = convert_to_lux(raw_value);

        // Set LED brightness
        set_led_brightness(lux);

        // Log data
        log_data(lux, gpioGetPWMdutycycle(GPIO_LED), 0);

        // Wait 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

