    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Security Keypad Simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int any_touched = 0;
        int all_touched = 1;

        for (int i = TOUCH_CHANNEL_1; i <= TOUCH_CHANNEL_8; i++) {
            int channel = i;
            int state = debounce_touch(i);

            if (state == 1) {
                if (!any_touched) {
                    log_touch_event(channel);
                    any_touched = 1;
                }
            } else {
                all_touched = 0;
            }
        }

        control_led(any_touched);
        gpioDelay(50 * 1000); // Delay in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

