#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONTINUOUS_MODE 0x01
#define AUTO_SCALE 0x00
#define CONVERSION_TIME 0x03 // 100ms
#define CONFIG_VALUE 0xC810 // Continuous mode, Auto scale, 100ms conversion

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int write_config();
int read_result(int *lux);
float calculate_lux(int raw_value);
int log_data(float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, OPT3001_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write configuration to OPT3001
int write_config() {
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read result from OPT3001
int read_result(int *lux) {
    int raw_value = i2cReadWordData(i2c_handle, RESULT_REG);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading result register: %d\n", raw_value);
        return -1;
    }

    // Byte swap to match OPT3001's endianness
    *lux = ((raw_value & 0xFF) << 8) | ((raw_value & 0xFF00) >> 8);

    return 0;
}

// Calculate lux value
float calculate_lux(int raw_value) {
    int exponent = (raw_value >> 12) & 0x0F;
    int mantissa = raw_value & 0x0FFF;

    return mantissa * 0.01 * (1 << exponent);
}

// Log data to file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write configuration
    if (write_config() != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int lux_raw;
    float lux;
    while (!terminate) {
        // Read result
        if (read_result(&lux_raw) == 0) {
            // Calculate lux
            lux = calculate_lux(lux_raw);

            // Log data
            log_data(lux);

            // Print to stdout
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        // Wait 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

