#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DEBOUNCE_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;

// Function to get the current timestamp in the format YYYY-MM-DD HH:MM:SS
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log the touch event to the file
int log_touch_event(const char *event_type) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    char *timestamp = get_timestamp();
    fprintf(fp, "%s: %s\n", timestamp, event_type);
    fclose(fp);
    return 0;
}

// Callback function for touch sensor events
void touch_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_MS * 1000) { // Convert ms to microseconds
        if (level == 1) {
            log_touch_event("Touch Detected");
        } else {
            log_touch_event("Touch Released");
        }
        last_tick = current_tick;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-down resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback function
    gpioSetAlertFuncEx(GPIO_PIN, touch_callback, NULL);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Keep the program running until a signal is received
    while (running) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    return 0;
}

