#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define MEASURE_CMD 0x3608
#define CRC_POLYNOMIAL 0x31
#define FLOW_SCALE_FACTOR 90.0

int i2c_handle;
FILE *log_file;

// Function to initialize the I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send the measurement command
int send_measurement_command() {
    char cmd[2] = {0x36, 0x08};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate the CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t len, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate the CRC checksum
int validate_crc(const uint8_t *data, size_t len, uint8_t polynomial) {
    uint8_t crc = calculate_crc(data, len, polynomial);
    if (crc != data[len]) {
        return -1;
    }
    return 0;
}

// Function to convert the raw flow value to ml/min
float convert_flow_rate(uint16_t raw_flow) {
    return (float)raw_flow / FLOW_SCALE_FACTOR;
}

// Function to log the data to a CSV file
int log_data(float flow_rate, uint16_t raw_flow, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to handle errors and re-initialize I2C
int handle_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    i2cClose(i2c_handle);
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
        exit(EXIT_FAILURE);
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Initialize I2C
    if (init_i2c() != 0) {
        handle_error("Failed to initialize I2C. Exiting.");
    }

    // Send the measurement command
    if (send_measurement_command() != 0) {
        handle_error("Failed to send measurement command. Exiting.");
    }

    // Main loop
    while (1) {
        uint8_t data[3];
        if (read_sensor_data(data) == 0) {
            // Validate CRC
            if (validate_crc(data, 2, CRC_POLYNOMIAL) == 0) {
                // Extract raw flow value
                uint16_t raw_flow = (data[0] << 8) | data[1];

                // Convert flow rate
                float flow_rate = convert_flow_rate(raw_flow);

                // Get status string
                char status[64];
                if (flow_rate < 0.0 || flow_rate > 100.0) {
                    strcpy(status, "INVALID");
                } else {
                    strcpy(status, "OK");
                }

                // Log the data
                log_data(flow_rate, raw_flow, status);
            } else {
                fprintf(stderr, "CRC validation failed. Logging ERROR.\n");
                log_data(-1.0, 0, "ERROR");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Logging ERROR.\n");
            log_data(-1.0, 0, "ERROR");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

