#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define POLL_INTERVAL_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line27 = NULL;
static struct gpiod_line *line22 = NULL;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read the value of a GPIO line
int read_gpio(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data to a CSV file
int log_data(const char *timestamp, int left, int middle, int right, FILE *fp) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (line22) {
        gpiod_line_release(line22);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the lines for the GPIO pins
    line17 = gpiod_chip_get_line(chip, GPIO17);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    line22 = gpiod_chip_get_line(chip, GPIO22);

    if (!line17 || !line27 || !line22) {
        fprintf(stderr, "Error getting GPIO line(s)\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the lines as inputs
    if (gpiod_line_request_input(line17, "left_sensor") < 0 ||
        gpiod_line_request_input(line27, "middle_sensor") < 0 ||
        gpiod_line_request_input(line22, "right_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line(s) as input\n");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_line_release(line22);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("path_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_line_release(line22);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping this iteration.\n");
            usleep(POLL_INTERVAL_MS * 1000); // Sleep for the polling interval
            continue;
        }

        int left_value = read_gpio(line17);
        int middle_value = read_gpio(line27);
        int right_value = read_gpio(line22);

