    char timestamp[20];
    while (!terminate) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 0) { // Flame detected (active-low)
            if (get_timestamp(timestamp) == 0) {
                printf("%s - Flame detected!\n", timestamp);
                if (log_event(timestamp) != 0) {
                    fprintf(stderr, "Error logging event.\n");
