            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
        } else if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value.\n");
        }

        usleep(100000); // 100ms delay
    }

    // Clean up GPIO resources
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return 0;
}

