#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_DELAY 200 // milliseconds
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log touch event to file
int log_touch_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Warning: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Callback function for touch sensor
void touch_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 1) { // Rising edge (touch detected)
        if (current_tick - last_tick > DEBOUNCE_DELAY * 1000) { // Debounce
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (log_touch_event(timestamp) == 0) {
                    printf("Touch detected and logged.\n");
                } else {
                    fprintf(stderr, "Error logging touch event.\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
            last_tick = current_tick;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback function
    if (gpioSetAlertFuncEx(TOUCH_PIN, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO%d\n", TOUCH_PIN);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    gpioSetAlertFuncEx(TOUCH_PIN, NULL, NULL); // Disable callback
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

