#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the Hall-effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnet_log.txt"

// Structure to hold sensor data
typedef struct {
    int gpio;
    int sensor_id;
    int last_state;
} sensor_data_t;

// Global variables
FILE *log_file = NULL;
sensor_data_t sensors[3];

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int log_state_change(int sensor_id, int state);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP);

    // Initialize sensor data
    sensors[0].gpio = SENSOR1_GPIO;
    sensors[0].sensor_id = 1;
    sensors[0].last_state = gpioRead(SENSOR1_GPIO);

    sensors[1].gpio = SENSOR2_GPIO;
    sensors[1].sensor_id = 2;
    sensors[1].last_state = gpioRead(SENSOR2_GPIO);

    sensors[2].gpio = SENSOR3_GPIO;
    sensors[2].sensor_id = 3;
    sensors[2].last_state = gpioRead(SENSOR3_GPIO);

    return 0;
}

// Function to read sensor state
int read_sensor(int gpio) {
    int state = gpioRead(gpio);
    if (state < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log state change
int log_state_change(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: %d\n", timestamp, sensor_id, state);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < 3; i++) {
            int current_state = read_sensor(sensors[i].gpio);
            if (current_state < 0) {
                fprintf(stderr, "Error reading sensor %d, skipping\n", sensors[i].sensor_id);
                continue; // Skip to the next sensor
            }

            if (current_state != sensors[i].last_state) {
                log_state_change(sensors[i].sensor_id, current_state);
                sensors[i].last_state = current_state;
            }
        }

        gpioDelay(100); // Poll every 100 ms
    }

    return 0; // This line will not be reached due to the infinite loop
}

