        fprintf(log_file, "%s - Sensor %d: %d\n", timestamp, sensor_id, state);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < 3; i++) {
            int current_state = read_sensor(sensors[i].gpio);
            if (current_state < 0) {
                fprintf(stderr, "Error reading sensor %d, skipping\n", sensors[i].sensor_id);
                continue; // Skip to the next sensor
            }

            if (current_state != sensors[i].last_state) {
                log_state_change(sensors[i].sensor_id, current_state);
                sensors[i].last_state = current_state;
            }
        }

        gpioDelay(100); // Poll every 100 ms
    }

    return 0; // This line will not be reached due to the infinite loop
}

