// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define HEART_RATE_REG 0x2A
#define MOVING_AVG_SIZE 5
#define BPM_MIN 30
#define BPM_MAX 220

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for moving average filter
typedef struct {
    int buffer[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverageFilter;

// Function prototypes
int initialize_sensor();
int read_heart_rate(int *raw_bpm);
float calculate_bpm(int raw_bpm);
void update_moving_average(float new_bpm, MovingAverageFilter *filter);
int validate_bpm(float bpm);
void log_data(float bpm);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the Si1182 sensor
int initialize_sensor() {
    // Check PART_ID and HW_REV registers
    int part_id = i2cReadByteData(i2c_handle, 0x00);
    int hw_rev = i2cReadByteData(i2c_handle, 0x01);

    if (part_id < 0 || hw_rev < 0) {
        fprintf(stderr, "Error reading sensor registers. Check I2C connection.\n");
        return -1;
    }

    if (part_id != 0x02 || hw_rev != 0x01) {
        fprintf(stderr, "Incorrect sensor configuration. PART_ID: 0x%02X, HW_REV: 0x%02X\n", part_id, hw_rev);
        return -1;
    }

    // Configure the sensor (LED current, averaging, enable)
    if (i2cWriteByteData(i2c_handle, 0x03, 0x3F) < 0) { // LED current
        fprintf(stderr, "Error writing to LED current register.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x04, 0x04) < 0) { // Averaging
        fprintf(stderr, "Error writing to averaging register.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x05, 0x01) < 0) { // Enable
        fprintf(stderr, "Error writing to enable register.\n");
        return -1;
    }

    return 0;
}

// Read heart rate data from the sensor
int read_heart_rate(int *raw_bpm) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, HEART_RATE_REG);
        if (result >= 0) {
            *raw_bpm = result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error, retrying...\n");
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read heart rate after multiple retries.\n");
    return -1; // Failure
}

// Calculate BPM from raw heart rate data
float calculate_bpm(int raw_bpm) {
    return (float)raw_bpm * 0.5;
}

// Update the moving average filter
void update_moving_average(float new_bpm, MovingAverageFilter *filter) {
    // Remove the oldest value from the buffer
    filter->buffer[filter->index] = new_bpm;
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;

    if (filter->count < MOVING_AVG_SIZE) {
        filter->count++;
    }
}

// Validate BPM value
int validate_bpm(float bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX);
}

// Log data to file
void log_data(float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize moving average filter
    MovingAverageFilter bpm_filter = {{0}, 0, 0};

    // Main loop
    int raw_bpm;
    float bpm;
    while (!terminate) {
        // Read heart rate data
        if (read_heart_rate(&raw_bpm) == 0) {
            // Calculate BPM
            bpm = calculate_bpm(raw_bpm);

            // Update moving average
            update_moving_average(bpm, &bpm_filter);

            // Validate BPM
            if (validate_bpm(bpm)) {
                // Log data
                log_data(bpm);
            } else {
                fprintf(stderr, "Invalid BPM value: %.2f\n", bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

