#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_log.txt"

static volatile int keepRunning = 1;

// Signal handler for graceful shutdown
void signalHandler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully...\n", signum);
        keepRunning = 0;
    }
}

// Function to read the flame sensor
int readFlameSensor(int gpioPin) {
    return gpioRead(gpioPin);
}

// Function to log the flame detection event
void logFlameDetection(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - FLAME DETECTED\n", timestamp);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Enable pull-up resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set alert function for falling edge detection
    gpioSetAlertFuncEx(GPIO_PIN, fallingEdgeDetected, NULL);

    // Install signal handler
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keepRunning) {
        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

// Callback function for falling edge detection
void fallingEdgeDetected(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Flame detected (LOW to HIGH transition)
        printf("FLAME DETECTED\n");
        logFlameDetection(LOG_FILE);
    }
}

