#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO chip and lines
#define GPIOCHIP "gpiochip0"
#define NUM_CHANNELS 8

// Define GPIO pins for outputs
const int output_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

// Define GPIO pins for sensor inputs
const int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};

// Define GPIO pin for the counter display
const int counter_display_pin = 17;

// Define stabilization delay in milliseconds
#define STABILIZATION_DELAY_MS 200

// Define touch duration threshold in milliseconds
#define TOUCH_DURATION_MS 50

// Define the log file name
#define LOG_FILE "touch_log.txt"

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_line *line;
    int channel;
} gpio_line_t;

// Global variables
static struct gpiod_chip *chip;
static gpio_line_t sensor_lines[NUM_CHANNELS];
static gpio_line_t output_lines[NUM_CHANNELS];
static volatile int running = 1;
static int touch_count = 0;
static struct timespec last_touch_time[NUM_CHANNELS];
static int touch_detected[NUM_CHANNELS] = {0};

// Function prototypes
int init_gpio(void);
int read_sensor(int channel);
int write_output(int channel, int value);
int update_counter(int channel, int value);
int log_touch_event(int channel, int counter);
void display_counter(int counter);
void cleanup(void);
void signal_handler(int sig);
int stabilize(void);

// Function to initialize GPIO lines
int init_gpio(void) {
    int i;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i].channel = i + 1;
        sensor_lines[i].line = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i].line) {
            fprintf(stderr, "Error getting sensor line %d: %s\n", i + 1, strerror(errno));
            cleanup();
            return -1;
        }
    }

    // Get output lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        output_lines[i].channel = i + 1;
        output_lines[i].line = gpiod_chip_get_line(chip, output_pins[i]);
        if (!output_lines[i].line) {
            fprintf(stderr, "Error getting output line %d: %s\n", i + 1, strerror(errno));
            cleanup();
            return -1;
        }
    }

    // Request sensor lines for input
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(sensor_lines[i].line, NULL) < 0) {
            fprintf(stderr, "Error requesting sensor line %d for input: %s\n", i + 1, strerror(errno));
            cleanup();
            return -1;
        }
    }

    // Request output lines for output
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_output(output_lines[i].line, NULL, 0) < 0) {
            fprintf(stderr, "Error requesting output line %d for output: %s\n", i + 1, strerror(errno));
            cleanup();
            return -1;
        }
    }

    // Stabilize the system
    if (stabilize() != 0) {
        fprintf(stderr, "Error stabilizing GPIO system.\n");
        cleanup();
        return -1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(int channel) {
    int value = gpiod_line_get_value(sensor_lines[channel - 1].line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value for channel %d: %s\n", channel, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to write output value
int write_output(int channel, int value) {
    int ret = gpiod_line_set_value(output_lines[channel - 1].line, value);
    if (ret < 0) {
        fprintf(stderr, "Error writing output value for channel %d: %s\n", channel, strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// Function to update the counter
int update_counter(int channel, int value) {
    touch_count = (touch_count + value) % 256;
    return 0;
}

// Function to log touch event
int log_touch_event(int channel, int counter) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    fclose(fp);
    return 0;
}

// Function to display the counter on GPIO17
void display_counter(int counter) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        write_output(i + 1, (counter >> i) & 1);
    }
}

// Function to stabilize the GPIO system
int stabilize(void) {
    struct timespec delay = {0, 10000000}; // 10 ms
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_output(output_lines[i].line, NULL, 0) < 0) {
            fprintf(stderr, "Error requesting output line %d for output: %s\n", i + 1, strerror(errno));
            return -1;
        }
        if (gpiod_line_request_input(sensor_lines[i].line, NULL) < 0) {
            fprintf(stderr, "Error requesting sensor line %d for input: %s\n", i + 1, strerror(errno));
            return -1;
        }
    }
    nanosleep(&delay, NULL);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_release(output_lines[i].line) < 0) {
            fprintf(stderr, "Error releasing output line %d: %s\n", i + 1, strerror(errno));
            return -1;
        }
        if (gpiod_line_release(sensor_lines[i].line) < 0) {
            fprintf(stderr, "Error releasing sensor line %d: %s\n", i + 1, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to handle signals
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        running = 0;
    }
}

// Function to cleanup GPIO resources
void cleanup(void) {
    int i;

    // Release sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i].line) {
            gpiod_line_release(sensor_lines[i].line);
        }
    }

    // Release output lines
