int initialize_gpio();
int read_sensor(int pin);
int log_data(time_t timestamp, int sensor1, int sensor2, int sensor3, int sensor4);
void cleanup();
void signal_handler(int sig);

int main() {
    time_t current_time;
    int sensor_values[NUM_SENSORS];

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("tracking_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_sensor(sensor_pins[i]);
            if (sensor_values[i] == -1) {
                fprintf(stderr, "Error reading sensor %d. Continuing.\n", i + 1);
                sensor_values[i] = 1; // Set to a default value to avoid affecting the CSV
            }
        }

        // Get current timestamp
        current_time = time(NULL);

        // Log the data
        if (log_data(current_time, sensor_values[0], sensor_values[1], sensor_values[2], sensor_values[3]) != 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }

        // Wait for the next poll interval
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&ts, NULL);
    }

    return 0;
}

