int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", sensor_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return -1;
        }

        // Request the line as an input
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "tracking_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(lines[i], &config, 0) != 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", sensor_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    int value = gpiod_line_get_value(lines[pin - 17]);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return value;
}

// Log data to CSV file
int log_data(time_t timestamp, int sensor1, int sensor2, int sensor3, int sensor4) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%ld,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close GPIO lines
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received (%d). Shutting down...\n", sig);
    cleanup();
    exit(0);
}

