#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int control_led(int gpio_pin, int state);
int log_data(FILE *fp, int sensor1, int sensor2, int led_state);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control LED state
int control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0; // pigpio doesn't provide error codes for gpioWrite
}

// Function to log data to file
int log_data(FILE *fp, int sensor1, int sensor2, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, led_state) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    control_led(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Release GPIO resources
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("obstacle_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,led_state\n");
    }
    fflush(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Check if both sensors detect an obstacle (active-low)
        int led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;

        // Control LED
        control_led(LED_PIN, led_state);

        // Log data
        if (log_data(log_file, sensor1_value, sensor2_value, led_state) != 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            running = 0; // Exit loop on logging error
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(LED_PIN, 0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

