#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 17
#define CENTER_SENSOR 27
#define RIGHT_SENSOR 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetPullUpDown(CENTER_SENSOR, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    return 0;
}

// Function to read the sensor values
int read_sensors(int *left, int *center, int *right) {
    *left = gpioRead(LEFT_SENSOR);
    *center = gpioRead(CENTER_SENSOR);
    *right = gpioRead(RIGHT_SENSOR);

    if (*left < 0 || *center < 0 || *right < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1;
    }

    return 0;
}

// Function to log the sensor states to the console
void log_sensor_states(int left, int center, int right) {
    printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop to read and log sensor states
    int left, center, right;
    while (program_running) {
        if (read_sensors(&left, &center, &right) == 0) {
            log_sensor_states(left, center, right);
        } else {
            fprintf(stderr, "Failed to read sensors, retrying...\n");
        }
        gpioDelay(100); // Wait for 100 ms
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");

    return 0;
}

