#include <errno.h>

// Define GPIO pins
#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Exit program
    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);

    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as inputs
    if (gpiod_line_request_input(left_line, "left_sensor") < 0) {
        fprintf(stderr, "Error requesting left GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(middle_line, "middle_sensor") < 0) {
        fprintf(stderr, "Error requesting middle GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(right_line, "right_sensor") < 0) {
        fprintf(stderr, "Error requesting right GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int left_value = gpiod_line_get_value(left_line);
        int middle_value = gpiod_line_get_value(middle_line);
        int right_value = gpiod_line_get_value(right_line);

        if (left_value < 0 || middle_value < 0 || right_value < 0) {
            fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);

        usleep(100000); // 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    return 0;
}

