#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

// Define the GPIO chip and lines
#define GPIOCHIP "gpiochip0"
#define NUM_CHANNELS 8

// Define the BCM GPIO pins for each channel
const int bcm_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

// Structure to hold the GPIO lines
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_CHANNELS];

// Function prototypes
int read_channel(int channel);
int get_timestamp(char *timestamp_str, size_t size);
void log_data(const char *timestamp, int channel_states[NUM_CHANNELS]);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    // Release all GPIO lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    // Close the GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to read the state of a specific channel
int read_channel(int channel) {
    if (channel < 0 || channel >= NUM_CHANNELS) {
        fprintf(stderr, "Error: Invalid channel number: %d\n", channel);
        return -1; // Indicate an error
    }

    struct gpiod_line *line = lines[channel];
    if (line == NULL) {
        fprintf(stderr, "Error: Line %d not initialized\n", channel);
        return -1; // Indicate an error
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read line %d: %d\n", channel, value);
        return -1; // Indicate an error
    }

    return value;
}

// Function to get the current timestamp
int get_timestamp(char *timestamp_str, size_t size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_str, size, "%Y-%m-%d %H:%M:%S", tm_info);
    return 0;
}

// Function to log the data to the console
void log_data(const char *timestamp, int channel_states[NUM_CHANNELS]) {
    char output_string[256];
    snprintf(output_string, sizeof(output_string), "%s ", timestamp);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        char ch = (channel_states[i] == 0) ? '0' : '1';
        snprintf(output_string + strlen(output_string), sizeof(output_string) - strlen(output_string), "CH%d=%c ", i + 1, ch);
    }
    printf("%s\n", output_string);
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip %s\n", GPIOCHIP);
        return 1;
    }

    // Request all 8 lines as inputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        struct gpiod_line *line = gpiod_chip_get_line(chip, bcm_pins[i]);
        if (!line) {
            fprintf(stderr, "Error: Failed to get line %d\n", i);
            gpiod_chip_close(chip);
            return 1;
        }

        lines[i] = line; // Store the line for later release
        int ret = gpiod_line_request(line, &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to request line %d: %d\n", i, ret);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        int channel_states[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            channel_states[i] = read_channel(i);
            if (channel_states[i] == -1) {
                fprintf(stderr, "Error reading channel %d, skipping this iteration.\n", i);
                // Continue to the next iteration even if there's an error
            }
        }

        log_data(timestamp, channel_states);
        gpioDelay(200); // Poll every 200 ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

