#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define fade duration (seconds)
#define FADE_DURATION 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to generate a random hue value
int generate_random_hue() {
    int hue = rand() % 360;
    return hue;
}

// Function to convert HSV to RGB
void hsv_to_rgb(int h, int s, int v, int *r, int *g, int *b) {
    if (s == 0) {
        *r = *g = *b = v;
        return;
    }

    h = fmod(h, 360);
    h /= 60;
    int i = h;
    float f = h - i;
    float p = v * (1 - s);
    float q = v * (1 - s * f);
    float t = v * (1 - s * (1 - f));

    switch (i) {
        case 0:
            *r = v;
            *g = t;
            *b = p;
            break;
        case 1:
            *r = q;
            *g = v;
            *b = p;
            break;
        case 2:
            *r = p;
            *g = v;
            *b = t;
            break;
        case 3:
            *r = p;
            *g = q;
            *b = v;
            break;
        case 4:
            *r = t;
            *g = p;
            *b = v;
            break;
        default: // case 5:
            *r = v;
            *g = p;
            *b = q;
            break;
    }
}

// Function to fade between two colors
void fade_color(int current_r, int current_g, int current_b, int target_r, int target_g, int target_b, int *current_r_ptr, int *current_g_ptr, int *current_b_ptr, int target_r_ptr, int target_g_ptr, int target_b_ptr, int steps) {
    float delta_r = (float)(target_r - current_r) / steps;
    float delta_g = (float)(target_g - current_g) / steps;
    float delta_b = (float)(target_b - current_b) / steps;

    for (int i = 0; i < steps; i++) {
        *current_r_ptr = (int)(current_r + delta_r * (i + 1));
        *current_g_ptr = (int)(current_g + delta_g * (i + 1));
        *current_b_ptr = (int)(current_b + delta_b * (i + 1));
        gpioPWM(RED_PIN, 255 - *current_r_ptr);
        gpioPWM(GREEN_PIN, 255 - *current_g_ptr);
        gpioPWM(BLUE_PIN, 255 - *current_b_ptr);
        gpioDelay(1000); // Delay for 1ms (1000 us)
    }
}

int main() {
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

