#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x29
#define LED_GPIO 17
#define RED_THRESHOLD 200
#define ATIME 0x00 // 154ms
#define CONTROL 0x00 // 1x gain
#define SENSOR_ID_REG 0x12
#define SENSOR_ID 0x44

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_byte(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
int initialize_sensor(int fd);
int read_sensor_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_sensor_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *cal_red, float *cal_green, float *cal_blue);
void control_led(int gpio, int state);
void signal_handler(int sig);

// I2C read byte function
int i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read word function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    uint8_t data[2];
    data[0] = buf[0];
    if (write(fd, data, 1) != 1) {
        perror("I2C write (data) failed");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return (data[1] << 8) | data[0];
}

// I2C write word function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Initialize the TCS34725 sensor
int initialize_sensor(int fd) {
    if (i2c_write_byte(fd, 0x80, ATIME) < 0) return -1;
    if (i2c_write_byte(fd, 0x81, CONTROL) < 0) return -1;
    if (i2c_write_byte(fd, 0x0F, 0x01) < 0) return -1; // Enable RGBC
    if (i2c_write_byte(fd, 0x0E, 0x03) < 0) return -1; // Enable power
    return 0;
}

// Read sensor data
int read_sensor_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    *clear = i2c_read_word(fd, 0x14);
    *red   = i2c_read_word(fd, 0x16);
    *green = i2c_read_word(fd, 0x18);
    *blue  = i2c_read_word(fd, 0x1A);
    return 0;
}

// Calibrate sensor data
void calibrate_sensor_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *cal_red, float *cal_green, float *cal_blue) {
    *cal_red = (float)red / 255.0f; // Normalize to 0-1 range
    *cal_green = (float)green / 255.0f;
    *cal_blue = (float)blue / 255.0f;
}

// Control the LED
void control_led(int gpio, int state) {
    if (gpiod_line_set_value(led_line, state) < 0) {
        perror("Failed to set LED state");
    }
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "color_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    uint16_t clear, red, green, blue;
    float cal_red, cal_green, cal_blue;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            calibrate_sensor_data(clear, red, green, blue, &cal_red, &cal_green, &cal_blue);
            printf("C: %d, R: %d, G: %d, B: %d | C: %.2f, R: %.2f, G: %.2f, B: %.2f\n",
                   red, green, blue, clear, cal_red, cal_green, cal_blue);

            if (cal_red > RED_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
            } else {
                control_led(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting re-initialization.\n");
            close(i2c_fd);
            sleep(1); // Wait before re-initializing
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                terminate = 1; // Exit loop if re-initialization fails
                continue; // Skip to next iteration
            }
            if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                terminate = 1;
                continue;
            }
            if (initialize_sensor(i2c_fd) < 0) {
                fprintf(stderr, "Sensor re-initialization failed. Exiting.\n");
                terminate = 1;
            }
        }

        usleep(200000); // 200ms
    }

    // Cleanup
    control_led(LED_GPIO, 0); // Turn LED off
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

