        if (read_sensor_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            calibrate_sensor_data(clear, red, green, blue, &cal_red, &cal_green, &cal_blue);
            printf("C: %d, R: %d, G: %d, B: %d | C: %.2f, R: %.2f, G: %.2f, B: %.2f\n",
                   red, green, blue, clear, cal_red, cal_green, cal_blue);

            if (cal_red > RED_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
            } else {
                control_led(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting re-initialization.\n");
            close(i2c_fd);
            sleep(1); // Wait before re-initializing
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                terminate = 1; // Exit loop if re-initialization fails
                continue; // Skip to next iteration
            }
            if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                terminate = 1;
                continue;
            }
            if (initialize_sensor(i2c_fd) < 0) {
                fprintf(stderr, "Sensor re-initialization failed. Exiting.\n");
                terminate = 1;
            }
        }

        usleep(200000); // 200ms
    }

    // Cleanup
    control_led(LED_GPIO, 0); // Turn LED off
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

