// Define GPIO pins
#define LED_PIN 18
#define BH1750_ADDR 0x23

// Define wave parameters
#define NUM_LEDS 10
#define PWM_FREQ 800000 // 800 kHz
#define PWM_RANGE 1000

// Define BH1750 commands
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Global variables
int wave_id = -1; // Initialize to an invalid value
int i2c_handle = -1; // Initialize to an invalid value
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int init_i2c();
float read_lux();
int map_lux_to_brightness(float lux);
void generate_led_waveform(int brightness);
void send_led_data(int brightness);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Send continuous high-resolution mode command
    int result = i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE); // No register address needed for BH1750
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    int msb, lsb;
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        msb = i2cReadByteData(i2c_handle, 0x00);
        lsb = i2cReadByteData(i2c_handle, 0x01);

        if (msb >= 0 && lsb >= 0) {
            return (float)((msb << 8 | lsb) / 1.2);
        } else {
            fprintf(stderr, "Error reading from I2C, retrying (%d retries left)...\n", retries);
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "Failed to read lux value after multiple retries.\n");
    return -1.0; // Indicate error
}

// Map lux value to brightness (logarithmic mapping)
int map_lux_to_brightness(float lux) {
    if (lux < 0) return 0; // Handle invalid lux value
    if (lux > 1000) lux = 1000; // Cap lux value

    // Logarithmic mapping: brightness = log2(lux + 1) / log2(1001) * 1000
    float brightness_float = log2(lux + 1) / log2(1001) * 1000.0;
    int brightness = (int)brightness_float;

    // Clamp brightness to 0-1000
    if (brightness < 0) brightness = 0;
    if (brightness > 1000) brightness = 1000;

    return brightness;
}

