void generate_led_waveform(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 1000) brightness = 1000;

    // Create a simple waveform for a single LED (all LEDs the same brightness)
    gpioWaveClear();

    gpioPulse_t pulse[4];
    pulse[0].gpioOn = 1 << LED_PIN;
    pulse[0].gpioOff = 0;
    pulse[0].usDelay = 0.8 * 1000; // 800 ns

    pulse[1].gpioOn = 0;
    pulse[1].gpioOff = 1 << LED_PIN;
    pulse[1].usDelay = (brightness * 0.4) * 1000; // 400 ns * brightness

    pulse[2].gpioOn = 0;
    pulse[2].gpioOff = 0;
    pulse[2].usDelay = 0.45 * 1000; // 450 ns

    gpioWaveAddGeneric(3, pulse);

    wave_id = gpioWaveCreate();
    if (wave_id < 0) {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
        return;
    }

    gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT); // Send the wave once
    gpioWaveDelete(wave_id);
}

// Send LED data to the WS2812B strip
void send_led_data(int brightness) {
    gpioWaveClear();
    gpioPulse_t pulse[4];
    pulse[0].gpioOn = 1 << LED_PIN;
    pulse[0].gpioOff = 0;
    pulse[0].usDelay = 0.8 * 1000; // 800 ns

    pulse[1].gpioOn = 0;
    pulse[1].gpioOff = 1 << LED_PIN;
    pulse[1].usDelay = (brightness * 0.4) * 1000; // 400 ns * brightness

    pulse[2].gpioOn = 0;
    pulse[2].gpioOff = 0;
    pulse[2].usDelay = 0.45 * 1000; // 450 ns

    gpioWaveAddGeneric(3, pulse);
    wave_id = gpioWaveCreate();
    if (wave_id < 0) {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
        return;
    }
    gpioWaveTxSend(wave_id, PI_WAVE_MODE_REPEAT); // Send the wave repeatedly
    gpioWaveDelete(wave_id);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Create a waveform for the LED strip
    wave_id = gpioWaveCreate();
    if (wave_id < 0) {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        float lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux, using default value 0\n");
            lux = 0.0; // Use a default value to avoid further errors
        }

        // Map lux to brightness
        int brightness = map_lux_to_brightness(lux);

        // Generate LED waveform
        generate_led_waveform(brightness);

        // Send LED data
        send_led_data(brightness);

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    gpioWaveClear();
    gpioWaveDelete(wave_id);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
