#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 10
#define BH1750_ADDR 0x23
#define APA102_START_FRAME 0x00FFFFFE
#define APA102_END_FRAME 0x00FFFFFF
#define APA102_FRAME_SIZE (NUM_LEDS * 4) + 3

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750(uint16_t *lux);
float calculate_lux(uint16_t raw);
uint8_t map_lux_to_brightness(float lux);
int send_apa102_frame(uint8_t brightness);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// I2C initialization
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Send start measurement command (0x20 for high resolution mode)
    uint8_t cmd = 0x20;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    // Wait for measurement to complete (at least 120ms)
    usleep(150000); // 150ms

    return 0;
}

// SPI initialization
int init_spi() {
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // Configure SPI mode (CPOL=1, CPHA=1)
    uint8_t mode = SPI_MODE_1;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(uint16_t *lux) {
    uint8_t buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *lux = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Calculate lux value from raw reading
float calculate_lux(uint16_t raw) {
    return (float)raw / 1.2;
}

// Map lux value to brightness (0-31)
uint8_t map_lux_to_brightness(float lux) {
    if (lux < 10) {
        return 0;
    } else if (lux > 300) {
        return 31;
    } else {
        return (uint8_t)((lux - 10) * 31.0 / (300.0 - 10.0));
    }
}

// Send APA102 frame
int send_apa102_frame(uint8_t brightness) {
    uint8_t frame[APA102_FRAME_SIZE];
    memset(frame, 0, APA102_FRAME_SIZE);

    // Start frame
    frame[0] = APA102_START_FRAME;

    // LED frames
    for (int i = 0; i < NUM_LEDS; i++) {
        frame[1 + (i * 4)] = 0xE0 | brightness; // Global brightness
        frame[2 + (i * 4)] = 0x00; // Blue
        frame[3 + (i * 4)] = 0x00; // Green
        frame[4 + (i * 4)] = 0x00; // Red
    }

    // End frame
    frame[1 + (NUM_LEDS * 4)] = APA102_END_FRAME;

    // Send the frame
    uint8_t tx_buf[APA102_FRAME_SIZE];
    memcpy(tx_buf, frame, APA102_FRAME_SIZE);

    if (write(spi_fd, tx_buf, APA102_FRAME_SIZE) != APA102_FRAME_SIZE) {
        perror("Error writing to SPI device");
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off LEDs (optional, but good practice)
    if (spi_fd != -1) {
        uint8_t clear_frame[APA102_FRAME_SIZE];
        memset(clear_frame, 0, APA102_FRAME_SIZE);
        clear_frame[0] = APA102_END_FRAME;
        write(spi_fd, clear_frame, APA102_FRAME_SIZE);
        close(spi_fd);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Initialization complete. Starting main loop.\n");

    while (!terminate) {
        uint16_t raw_lux;
        if (read_bh1750(&raw_lux) == 0) {
            float lux = calculate_lux(raw_lux);
            uint8_t brightness = map_lux_to_brightness(lux);

            printf("Raw Lux: %d, Lux: %.2f, Brightness: %d\n", raw_lux, lux, brightness);

            if (send_apa102_frame(brightness) < 0) {
                fprintf(stderr, "Failed to send APA102 frame.\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        usleep(500000); // 500ms delay
    }

    cleanup();
    return 0;
}

