// Send APA102 frame
int send_apa102_frame(uint8_t brightness) {
    uint8_t frame[APA102_FRAME_SIZE];
    memset(frame, 0, APA102_FRAME_SIZE);

    // Start frame
    frame[0] = APA102_START_FRAME;

    // LED frames
    for (int i = 0; i < NUM_LEDS; i++) {
        frame[1 + (i * 4)] = 0xE0 | brightness; // Global brightness
        frame[2 + (i * 4)] = 0x00; // Blue
        frame[3 + (i * 4)] = 0x00; // Green
        frame[4 + (i * 4)] = 0x00; // Red
    }

    // End frame
    frame[1 + (NUM_LEDS * 4)] = APA102_END_FRAME;

    // Send the frame
    uint8_t tx_buf[APA102_FRAME_SIZE];
    memcpy(tx_buf, frame, APA102_FRAME_SIZE);

    if (write(spi_fd, tx_buf, APA102_FRAME_SIZE) != APA102_FRAME_SIZE) {
        perror("Error writing to SPI device");
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off LEDs (optional, but good practice)
    if (spi_fd != -1) {
        uint8_t clear_frame[APA102_FRAME_SIZE];
        memset(clear_frame, 0, APA102_FRAME_SIZE);
        clear_frame[0] = APA102_END_FRAME;
        write(spi_fd, clear_frame, APA102_FRAME_SIZE);
        close(spi_fd);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Initialization complete. Starting main loop.\n");

    while (!terminate) {
        uint16_t raw_lux;
        if (read_bh1750(&raw_lux) == 0) {
            float lux = calculate_lux(raw_lux);
            uint8_t brightness = map_lux_to_brightness(lux);

            printf("Raw Lux: %d, Lux: %.2f, Brightness: %d\n", raw_lux, lux, brightness);

            if (send_apa102_frame(brightness) < 0) {
                fprintf(stderr, "Failed to send APA102 frame.\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        usleep(500000); // 500ms delay
    }

    cleanup();
    return 0;
}

