#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// APA102 SPI Configuration
#define APA102_MOSI 10
#define APA102_SCLK 11
#define APA102_NUM_LEDS 30

// BH1750 I2C Configuration
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Global Variables
int i2c_handle_low = -1;
int i2c_handle_high = -1;
int spi_handle = -1;
int running = 1;

// Function Prototypes
int init_i2c();
int init_spi();
int read_bh1750(int i2c_handle);
float average_lux(int lux1, int lux2, int lux3);
int map_lux_to_brightness(float avg_lux);
void fade_led(int target_brightness);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle_low = i2cOpen(1, BH1750_ADDR_LOW, 0); // I2C bus 1, address 0x23
    if (i2c_handle_low < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x23: %d\n", i2c_handle_low);
        return -1;
    }

    i2c_handle_high = i2cOpen(1, BH1750_ADDR_HIGH, 0); // I2C bus 1, address 0x5C
    if (i2c_handle_high < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x5C: %d\n", i2c_handle_high);
        i2cClose(i2c_handle_low);
        return -1;
    }

    return 0;
}

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    char buffer[2];
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2; // Convert raw value to lux
    return (int)lux;
}

// Function to average lux readings
float average_lux(int lux1, int lux2, int lux3) {
    int valid_count = 0;
    float sum = 0.0;

    if (lux1 >= 0) {
        sum += lux1;
        valid_count++;
    }
    if (lux2 >= 0) {
        sum += lux2;
        valid_count++;
    }
    if (lux3 >= 0) {
        sum += lux3;
        valid_count++;
    }

    if (valid_count == 0) {
        return 0.0; // Return 0 if no valid readings
    }

    return sum / valid_count;
}

// Function to map lux to brightness level
int map_lux_to_brightness(float avg_lux) {
    // Map lux (0-1000) to brightness (0-31)
    // Inverse relationship: lower lux -> higher brightness
    int brightness = 31 - (int)((avg_lux / 1000.0) * 31.0);
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;
    return brightness;
}

// Function to fade LED brightness
void fade_led(int target_brightness) {
    int current_brightness = 0;
    int step = 5; // Fade step size (adjust as needed)

    while (current_brightness < target_brightness) {
        current_brightness += step;
        // Send start frame (4 bytes of 0x00)
        char start_frame[4] = {0x00, 0x00, 0x00, 0x00};
        spiWrite(spi_handle, start_frame, 4);

        // Send LED data (brightness, red, green, blue)
        for (int i = 0; i < APA102_NUM_LEDS; i++) {
            char led_data[4] = {0xE0 | current_brightness, 0x00, 0x00, 0x00}; // White light
            spiWrite(spi_handle, led_data, 4);
        }

        gpioDelay(50000); // Delay for 50ms (adjust as needed)
    }
}

// Signal handler for clean exit
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Turn off LEDs
    fade_led(0);

    // Close I2C
    if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
    if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);

    // Close SPI
    if (spi_handle >= 0) spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        i2cClose(i2c_handle_low);
        i2cClose(i2c_handle_high);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read lux values from BH1750 sensors
        int lux1 = read_bh1750(i2c_handle_low);
        int lux2 = read_bh1750(i2c_handle_high);
        int lux3 = read_bh1750(i2c_handle_low); // Reuse i2c_handle_low for the third sensor

        // Average lux readings
        float avg_lux = average_lux(lux1, lux2, lux3);

        // Map lux to brightness
