#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_DATA_REG 0x04
#define GPIO_LED 18
#define PWM_FREQUENCY 800000 // Hz
#define PWM_RANGE 255
#define GAMMA 2.2
#define MAX_LUX 120000.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for VEML7700 configuration
typedef struct {
    unsigned int integration_time;
    unsigned int gain;
} veml7700_config_t;

// Function prototypes
int init_i2c();
int init_gpio();
int init_veml7700(veml7700_config_t config);
int read_als_data(int *raw_data);
float convert_to_lux(int raw_data);
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO initialization
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    return 0;
}

// VEML7700 initialization
int init_veml7700(veml7700_config_t config) {
    // Set integration time and gain (example: 100ms, gain 1/8)
    // Refer to VEML7700 datasheet for register addresses and values
    // This is a placeholder, replace with actual register writes
    char config_data[2];
    config_data[0] = 0x00; // Example register address
    config_data[1] = config.integration_time; // Example value

    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing to VEML7700: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read ALS data from VEML7700
int read_als_data(int *raw_data) {
    char reg = ALS_DATA_REG;
    char data[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *raw_data = (data[1] << 8) | data[0];
    return 0;
}

// Convert raw ALS data to lux
float convert_to_lux(int raw_data) {
    return (float)raw_data * 0.0288; // Simplified lux calculation
}

// Map lux value to brightness using gamma correction
int map_lux_to_brightness(float lux) {
    float normalized_lux = lux / MAX_LUX;
    if (normalized_lux > 1.0) normalized_lux = 1.0;
    if (normalized_lux < 0.0) normalized_lux = 0.0;

    float brightness_float = 255.0 * pow(normalized_lux, 1.0 / GAMMA);
    int brightness = (int)brightness_float;
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    return brightness;
}

// Set LED brightness using PWM
void set_led_brightness(int brightness) {
    gpioPWM(GPIO_LED, brightness);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        cleanup();
        return 1;
    }

    veml7700_config_t veml7700_config = {100, 8}; // Example values
    if (init_veml7700(veml7700_config) != 0) {
        fprintf(stderr, "VEML7700 initialization failed, exiting\n");
        cleanup();
        return 1;
    }

    int raw_data;
    float lux;
    int brightness;

    // Main loop
    while (!terminate) {
        if (read_als_data(&raw_data) == 0) {
            lux = convert_to_lux(raw_data);
            brightness = map_lux_to_brightness(lux);
            set_led_brightness(brightness);

            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read ALS data, retrying...\n");
            // Attempt I2C re-initialization with retry
            int retries = 0;
            while (retries < MAX_RETRIES) {
                if (init_i2c() == 0) {
                    break; // I2C re-initialization successful
                } else {
                    fprintf(stderr, "I2C re-initialization failed, retry %d...\n", retries + 1);
                    retries++;
                    usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
                }
            }
            if (retries == MAX_RETRIES) {
                fprintf(stderr, "I2C re-initialization failed after %d retries, exiting\n", MAX_RETRIES);
                terminate = 1; // Exit loop if re-initialization fails repeatedly
            }
        }

        usleep(200000); // 200 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

