    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    return brightness;
}

// Set LED brightness using PWM
void set_led_brightness(int brightness) {
    gpioPWM(GPIO_LED, brightness);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        cleanup();
        return 1;
    }

    veml7700_config_t veml7700_config = {100, 8}; // Example values
    if (init_veml7700(veml7700_config) != 0) {
        fprintf(stderr, "VEML7700 initialization failed, exiting\n");
        cleanup();
        return 1;
    }

    int raw_data;
    float lux;
    int brightness;

    // Main loop
    while (!terminate) {
        if (read_als_data(&raw_data) == 0) {
            lux = convert_to_lux(raw_data);
            brightness = map_lux_to_brightness(lux);
            set_led_brightness(brightness);

            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read ALS data, retrying...\n");
            // Attempt I2C re-initialization with retry
            int retries = 0;
            while (retries < MAX_RETRIES) {
                if (init_i2c() == 0) {
                    break; // I2C re-initialization successful
                } else {
                    fprintf(stderr, "I2C re-initialization failed, retry %d...\n", retries + 1);
                    retries++;
                    usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
                }
            }
            if (retries == MAX_RETRIES) {
                fprintf(stderr, "I2C re-initialization failed after %d retries, exiting\n", MAX_RETRIES);
                terminate = 1; // Exit loop if re-initialization fails repeatedly
            }
        }

        usleep(200000); // 200 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

