        if (ret < 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Error requesting flame sensor line %d as input: %d", i + 1, ret);
            log_event(error_message);
            break;
        }
    }

    // Request buzzer and LED lines as outputs
    ret = gpiod_line_request(buzzer_line, "buzzer", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Error requesting buzzer line as output: %d", ret);
        log_event(error_message);
        break;
    }

    ret = gpiod_line_request(led_line, "led", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Error requesting LED line as output: %d", ret);
        log_event(error_message);
        break;
    }

    // Perform self-test
