        // Activate error pattern
        for (int i = 0; i < 5; i++) {
            activate_led(LED);
            usleep(100000);
            deactivate_led(LED);
            usleep(100000);
        }

        // Activate buzzer error pattern
        for (int i = 0; i < 3; i++) {
            activate_buzzer(BUZZER);
            usleep(200000);
            deactivate_buzzer(BUZZER);
            usleep(200000);
            activate_buzzer(BUZZER);
            usleep(600000);
            deactivate_buzzer(BUZZER);
            usleep(200000);
        }

        // Deactivate buzzer and LED
        deactivate_buzzer(BUZZER);
        deactivate_led(LED);

        // Exit with error code
        return 1;
    }

    log_event("Self-test passed. Starting main loop...");

    // Main loop
    while (keep_running) {
        // Read flame sensors
        int sensor1_value = read_flame_sensor(FLAME_SENSOR_1);
        int sensor2_value = read_flame_sensor(FLAME_SENSOR_2);
        int sensor3_value = read_flame_sensor(FLAME_SENSOR_3);

