#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define BLINK_RATE_MIN 0.5
#define BLINK_RATE_MAX 5.0
#define BUFFER_SIZE 60

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Structure to hold lux readings
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int init_gpio();
float read_bh1750();
float convert_to_lux(uint16_t raw_value);
void update_circular_buffer(CircularBuffer *cb, float value);
float calculate_average_lux(CircularBuffer *cb);
void control_led(float average_lux);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 0.0;
    }
}

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    int fd;
    char buffer[64];

    // Export GPIO
    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", GPIO_PIN);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to /sys/class/gpio/export");
        close(fd);
        return -1;
    }
    close(fd);

    // Set GPIO direction to output
