#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define the GPIO chip name
#define CHIP_NAME "gpiochip0"

// Define the number of segments in the display
#define NUM_SEGMENTS 8

// Define the digit to display (5)
#define DISPLAYED_DIGIT 5

// Define the delay between blinks (500ms)
#define BLINK_DELAY_MS 500

// Define the shift register timing constants (in nanoseconds)
#define SHIFT_DELAY_US 1
#define CLOCK_DELAY_US 1

// Function to initialize the GPIO chip
struct gpiod_chip *initialize_gpio_chip(const char *chip_name)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", chip_name);
        return NULL;
    }
    return chip;
}

// Function to request a GPIO line
struct gpiod_line *request_gpio_line(struct gpiod_chip *chip, int pin)
{
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", pin);
        return NULL;
    }
    if (gpiod_line_request_output(line, "seven_segment_display", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output\n", pin);
        return NULL;
    }
    return line;
}

// Function to shift out data to the 74HC595
void shift_out(struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line, unsigned char data)
{
    // Set the latch pin low to prepare for the data transmission
    gpiod_line_set_value(latch_line, 0);

    // Shift out the data bits MSB first
    for (int i = 0; i < NUM_SEGMENTS; i++) {
        // Set the data pin high or low based on the current bit
        gpiod_line_set_value(data_line, (data >> (NUM_SEGMENTS - 1 - i)) & 1);

        // Clock the data into the shift register
        gpiod_line_set_value(clock_line, 1);
        usleep(SHIFT_DELAY_US);

        // Reset the clock
        gpiod_line_set_value(clock_line, 0);
        usleep(CLOCK_DELAY_US);
    }

    // Set the latch pin high to latch the data into the shift register
    gpiod_line_set_value(latch_line, 1);
    usleep(SHIFT_DELAY_US);
}

// Function to display a digit on the seven-segment display
void display_digit(struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line, int digit)
{
    // Define the segment patterns for the digit 5
    unsigned char segment_pattern[10] = {
        0b00100, // 0
        0b00011, // 1
        0b01010, // 2
        0b01010, // 3
        0b01100, // 4
        0b00011, // 5
        0b00011, // 6
        0b10001, // 7
        0b10011, // 8
        0b10011  // 9
    };

    // Select the segment pattern for the digit
    unsigned char data = segment_pattern[digit];

    // Shift out the data
    shift_out(data_line, clock_line, latch_line, data);
}

// Function to blink the digit
void blink_digit(struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line)
{
    // Display the digit
    display_digit(data_line, clock_line, latch_line, DISPLAYED_DIGIT);

    // Wait for the blink delay
    usleep(BLINK_DELAY_MS * 1000); // Convert milliseconds to microseconds

    // Turn off the display (set all bits to 0)
    unsigned char off_pattern = 0b00000000;
    shift_out(data_line, clock_line, latch_line, off_pattern);

    // Wait for the blink delay
    usleep(BLINK_DELAY_MS * 1000);
}

int main()
{
    // Initialize the GPIO chip
    struct gpiod_chip *chip = initialize_gpio_chip(CHIP_NAME);
    if (!chip) {
        return EXIT_FAILURE;
    }

    // Request the GPIO lines
    struct gpiod_line *data_line = request_gpio_line(chip, DATA_PIN);
    struct gpiod_line *clock_line = request_gpio_line(chip, CLOCK_PIN);
    struct gpiod_line *latch_line = request_gpio_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop to blink the digit
    while (1) {
        blink_digit(data_line, clock_line, latch_line);
    }

    // Cleanup (this part will not be reached in the infinite loop)
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

