#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;

static volatile int running = 1;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    running = 0;
}

// Function to initialize the GPIO chip
int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line as output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request button line as input with pull-up
    if (gpiod_line_request_input(button_line, "button", 1) < 0) {
        perror("Error requesting button line as input");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to blink the LED
void blink_led() {
    int current_state = gpiod_line_get_value(led_line);
    if (current_state < 0) {
        perror("Error getting LED state");
        return;
    }

    gpiod_line_set_value(led_line, !current_state);
    usleep(1000000); // 1 second
    gpiod_line_set_value(led_line, current_state);
    usleep(1000000); // 1 second
}

