#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize a GPIO line
int init_gpio(struct gpiod_chip *chip, int pin, int direction)
{
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_request(line, "led_button", direction);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d, direction %s: %s\n", pin, direction == GPIOD_LINE_REQUEST_DIRECTION_OUTPUT ? "output" : "input", strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the LED state
int set_led_state(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line %d value to %d: %s\n", line->consumer->name, value, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to read the button state
int read_button_state(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get line %d value: %s\n", line->consumer->name, strerror(-value));
        return -1;
    }
    return value;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize LED line
    if (init_gpio(chip, LED_PIN, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT)) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    led_line = gpiod_line;
    set_led_state(led_line, 0); // Initialize LED to off

    // Initialize Button line
    if (init_gpio(chip, BUTTON_PIN, GPIOD_LINE_REQUEST_DIRECTION_INPUT)) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    button_line = gpiod_line;

    int button_pressed = 0;
    int last_button_state = 0; // Track the last button state for debouncing

    // Main loop
    while (running) {
        int button_state = read_button_state(button_line);
        if (button_state < 0) {
            break; // Exit loop on error
        }

        if (button_state == 1 && last_button_state == 0) {
            // Button pressed (rising edge)
            button_pressed = 1;
            set_led_state(led_line, 1); // Turn LED on
        } else if (button_state == 0 && last_button_state == 1) {
            // Button released (falling edge)
            button_pressed = 0;
            set_led_state(led_line, 0); // Turn LED off
        }

        last_button_state = button_state;
        usleep(50000); // Check every 50ms
    }

    // Cleanup
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

