#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for Red, Green, and Blue
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define the number of lines to open
#define NUM_LINES 3

// Define the PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Define the PWM period (10 ms)
#define PWM_PERIOD_NS 10000000 // 10 ms in nanoseconds

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *red_line = NULL;
struct gpiod_line *green_line = NULL;
struct gpiod_line *blue_line = NULL;

// Function prototypes
int initialize_gpio();
void set_duty_cycle(struct gpiod_line *line, int duty_cycle);
void set_rgb_color(int red, int green, int blue);
void cleanup_gpio();
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, cleaning up and exiting...\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize the GPIO lines
int initialize_gpio() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the lines for Red, Green, and Blue
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request the lines as outputs
    ret = gpiod_line_request_output(red_line, "rgb_led", 0);
    if (ret < 0) {
        perror("Error requesting Red line as output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(green_line, "rgb_led", 0);
    if (ret < 0) {
        perror("Error requesting Green line as output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(blue_line, "rgb_led", 0);
    if (ret < 0) {
        perror("Error requesting Blue line as output");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to set the duty cycle for a given line
void set_duty_cycle(struct gpiod_line *line, int duty_cycle) {
    // Calculate the number of high periods for the given duty cycle
    int num_high_periods = duty_cycle * PWM_PERIOD_NS / 100;

    // Set the value of the line
    gpiod_line_set_value(line, 1); // Set high
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = num_high_periods;
    nanosleep(&delay, NULL);

    // Set the value of the line
    gpiod_line_set_value(line, 0); // Set low
    delay.tv_nsec = PWM_PERIOD_NS - num_high_periods;
    nanosleep(&delay, NULL);
}

// Function to set the RGB color
void set_rgb_color(int red, int green, int blue) {
    set_duty_cycle(red_line, red);
    set_duty_cycle(green_line, green);
    set_duty_cycle(blue_line, blue);
}

// Function to cleanup the GPIO lines
void cleanup_gpio() {
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the GPIO lines
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    // Main loop to generate random RGB colors and update the LED
    while (1) {
        int red = rand() % 101;
        int green = rand() % 101;
        int blue = rand() % 101;

        set_rgb_color(red, green, blue);

        // Sleep for 100 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

