#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define LED_GPIO 18
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als();
int read_rgb(int *red, int *green, int *blue);
int log_data(int als, int red, int green, int blue);
void set_led_brightness(int als);
void signal_handler(int signal);

// Structure to hold RGB values
typedef struct {
    int red;
    int green;
    int blue;
} rgb_t;

// Function to initialize the ADPD188BI sensor
int initialize_sensor() {
    int status;
    int retries = 3;

    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, MODE_REG, 0x01);
        if (status >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to MODE_REG: %d. Retrying...\n", status);
            gpioDelay(100000); // 100 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to read ALS data from the sensor
int read_als() {
    int als_lsb, als_msb;
    int status;
    int retries = 3;

    while (retries > 0) {
        als_lsb = i2cReadByteData(i2c_handle, ALS_LSB_REG);
        if (als_lsb >= 0) {
            als_msb = i2cReadByteData(i2c_handle, ALS_MSB_REG);
            if (als_msb >= 0) {
                return (als_msb << 8) | als_lsb; // Combine LSB and MSB
            } else {
                fprintf(stderr, "Error reading ALS MSB: %d. Retrying...\n", als_msb);
                gpioDelay(100000);
                retries--;
            }
        } else {
            fprintf(stderr, "Error reading ALS LSB: %d. Retrying...\n", als_lsb);
            gpioDelay(100000);
            retries--;
        }
    }

    fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
    return -1; // Failure
}

// Function to read RGB data from the sensor
int read_rgb(int *red, int *green, int *blue) {
    int red_val, green_val, blue_val;
    int status;
    int retries = 3;

    while (retries > 0) {
        red_val = i2cReadByteData(i2c_handle, RED_REG);
        if (red_val >= 0) {
            green_val = i2cReadByteData(i2c_handle, GREEN_REG);
            if (green_val >= 0) {
                blue_val = i2cReadByteData(i2c_handle, BLUE_REG);
                if (blue_val >= 0) {
                    *red = red_val;
                    *green = green_val;
                    *blue = blue_val;
                    return 0; // Success
                } else {
                    fprintf(stderr, "Error reading BLUE data: %d. Retrying...\n", blue_val);
                    gpioDelay(100000);
                    retries--;
                }
            } else {
                fprintf(stderr, "Error reading GREEN data: %d. Retrying...\n", green_val);
                gpioDelay(100000);
                retries--;
            }
        } else {
            fprintf(stderr, "Error reading RED data: %d. Retrying...\n", red_val);
            gpioDelay(100000);
            retries--;
        }
    }

    fprintf(stderr, "Failed to read RGB data after multiple retries.\n");
    return -1; // Failure
}

// Function to log data to a CSV file
int log_data(int als, int red, int green, int blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to set LED brightness using PWM
void set_led_brightness(int als) {
    int duty_cycle = als / 256; // Map ALS (0-65535) to PWM range (0-255)
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(LED_GPIO, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int als = read_als();
        int red, green, blue;

        if (als >= 0 && read_rgb(&red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            set_led_brightness(als);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging and PWM.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

