    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int als = read_als();
        int red, green, blue;

        if (als >= 0 && read_rgb(&red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            set_led_brightness(als);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging and PWM.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

