#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDRESS 0x69
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLE_PERIOD_MS 50
#define CALIBRATION_SAMPLES 100
#define CALIBRATION_DELAY_MS 1000
#define ALERT_THRESHOLD_DPS 50.0

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration offsets
static float x_offset = 0.0;
static float y_offset = 0.0;
static float z_offset = 0.0;

// Function prototypes
int init_i2c();
int configure_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void calibrate_gyro();
void log_data(int16_t x, int16_t y, int16_t z);
void check_alert(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);
void cleanup();

// Structure to hold gyro data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return 0;
}

// Function to configure the gyroscope
int configure_gyro() {
    uint8_t ctrl_reg1_value = 0x0F; // Normal mode, all axes enabled, 100 Hz ODR
    uint8_t ctrl_reg4_value = 0x00; // 250 dps full-scale, continuous update

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    if (write(i2c_fd, &ctrl_reg1_value, 1) != 1) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }

    if (write(i2c_fd, &ctrl_reg4_value, 1) != 1) {
        perror("Error writing to CTRL_REG4");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading gyro data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calibrate the gyroscope
void calibrate_gyro() {
    int16_t x, y, z;
    float x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            x_sum += x;
            y_sum += y;
            z_sum += z;
        } else {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            return;
        }
        usleep(CALIBRATION_DELAY_MS * 1000); // Delay in microseconds
    }

    x_offset = x_sum / CALIBRATION_SAMPLES;
    y_offset = y_sum / CALIBRATION_SAMPLES;
    z_offset = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);
}

// Function to log data to a file
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check for alert conditions
void check_alert(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > ALERT_THRESHOLD_DPS || abs(y) > ALERT_THRESHOLD_DPS || abs(z) > ALERT_THRESHOLD_DPS) {
        fprintf(stderr, "Alert: High angular velocity detected!\n");
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[32];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        fprintf(log_file, "%s, ALERT: High angular velocity detected!\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Configure gyroscope
    if (configure_gyro() != 0) {
        fprintf(stderr, "Gyroscope configuration failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Check WHO_AM_I register
    uint8_t who_am_i;
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        perror("Error setting I2C slave address for WHO_AM_I");
        cleanup();
        return 1;
    }
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        cleanup();
        return 1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0xD3. Sensor may be absent.\n", who_am_i);
        cleanup();
        return 1;
    }

    // Calibrate the gyroscope
    calibrate_gyro();

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD_MS * 1000000; // Convert milliseconds to nanoseconds

    printf("Starting data acquisition...\n");

    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Apply calibration offsets
            x -= x_offset;
            y -= y_offset;
            z -= z_offset;

            // Log data
            log_data(x, y, z);

            // Check for alert conditions
            check_alert(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data in main loop\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

