    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADXL345 accelerometer
int adxl345_init() {
    // Check DEVID register
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Invalid DEVID (0x%X). Expected 0xE5.\n", devid);
        return -1;
    }

    // Configure for full-resolution, ±2g range
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the ADXL345
int read_acceleration(accelerometer_data_t *data) {
    char raw_data[6];
    int16_t x, y, z;

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g units (assuming ±2g range and full resolution)
    data->x = (float)x / 256.0f;
    data->y = (float)y / 256.0f;
    data->z = (float)z / 256.0f;

