    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    accelerometer_data_t data;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&data) == 0) {
            log_data(data);
            control_led(data.x, data.y, data.z);
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay (10 Hz)
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

