#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

// LSM303DLHC register addresses
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A 0x28
#define LSM303_ACCEL_OUT_X_H_A 0x29
#define LSM303_ACCEL_OUT_Y_L_A 0x2A
#define LSM303_ACCEL_OUT_Y_H_A 0x2B
#define LSM303_ACCEL_OUT_Z_L_A 0x2C
#define LSM303_ACCEL_OUT_Z_H_A 0x2D

#define LSM303_MAG_MR_REG_M 0x02
#define LSM303_MAG_OUT_X_H_M 0x03
#define LSM303_MAG_OUT_X_L_M 0x04
#define LSM303_MAG_OUT_Z_H_M 0x05
#define LSM303_MAG_OUT_Z_L_M 0x06
#define LSM303_MAG_OUT_Y_H_M 0x07
#define LSM303_MAG_OUT_Y_L_M 0x08

// Global variables
int i2c_handle_accel, i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_lsm303();
int read_accel_data(float *x, float *y, float *z);
int read_mag_data(float *x, float *y, float *z);
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
} sensor_data_t;

// Function to initialize the LSM303DLHC
int init_lsm303() {
    // Initialize accelerometer
    if (i2cWriteByteData(i2c_handle_accel, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }

    // Initialize magnetometer
    if (i2cWriteByteData(i2c_handle_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accel_data(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes, and convert to g
    *x = (float)((int16_t)((buffer[1] << 8) | buffer[0])) / 1000.0f;
    *y = (float)((int16_t)((buffer[3] << 8) | buffer[2])) / 1000.0f;
    *z = (float)((int16_t)((buffer[5] << 8) | buffer[4])) / 1000.0f;

    return 0;
}

// Function to read magnetometer data
int read_mag_data(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, LSM303_MAG_OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    // Combine high and low bytes, and convert to gauss
    *x = (float)((int16_t)((buffer[0] << 8) | buffer[1])) / 10.0f;
    *z = (float)((int16_t)((buffer[2] << 8) | buffer[3])) / 10.0f;
    *y = (float)((int16_t)((buffer[4] << 8) | buffer[5])) / 10.0f;

    return 0;
}

// Function to calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch) + mag_x * sin(roll) * sin(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;

    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Function to log data to a file
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles
    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C device for accelerometer: %d\n", i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C device for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303DLHC
    if (init_lsm303() < 0) {
        fprintf(stderr, "LSM303 initialization failed\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,heading,accel_x,accel_y,accel_z,mag_x,mag_y,mag_z\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_accel_data(&sensor_data.accel_x, &sensor_data.accel_y, &sensor_data.accel_z) == 0 &&
            read_mag_data(&sensor_data.mag_x, &sensor_data.mag_y, &sensor_data.mag_z) == 0) {

            // Calculate heading
            float heading = calculate_heading(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z,
                                               sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z);

            // Log data
            log_data(heading, sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z,
                     sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(100); // Sample every 100 ms
    }

    // Close I2C handles and log file
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

