int read_sensor_data(int i2c_handle, int *data);
int calculate_tdoa(int sensor1_data, int sensor2_data);
int log_data(FILE *fp, int sec, int nsec, int sensor1, int sensor2, int tdoa);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int i2c_handle;
    int sensor_number;
} sensor_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize a sensor
int initialize_sensor(int i2c_handle) {
    // Write to the control register to enable continuous measurement
    if (i2cWriteByteData(i2c_handle, CONTROL_REG, 0x80) != 0) {
        fprintf(stderr, "Error writing to control register\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, int *data) {
    // Read two bytes from the data register
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, DATA_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading data from sensor\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

// Function to calculate TDOA
int calculate_tdoa(int sensor1_data, int sensor2_data) {
    return sensor1_data - sensor2_data;
}

// Function to log data to a file
int log_data(FILE *fp, int sec, int nsec, int sensor1, int sensor2, int tdoa) {
    if (fprintf(fp, "%d,%d,%d,%d,%d,%d\n", sec, nsec, sensor1, sensor2, tdoa, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize both sensors
    if (initialize_sensor(i2c_handle1) != 0 || initialize_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Get current timestamp
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        int sec = ts.tv_sec;
        int nsec = ts.tv_nsec;

        // Read data from both sensors
        int sensor1_data, sensor2_data;
        if (read_sensor_data(i2c_handle1, &sensor1_data) != 0) {
            fprintf(stderr, "Error reading sensor 1 data, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US); // Wait before retrying
            continue;
        }
        if (read_sensor_data(i2c_handle2, &sensor2_data) != 0) {
            fprintf(stderr, "Error reading sensor 2 data, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US); // Wait before retrying
            continue;
        }

        // Calculate TDOA
        int tdoa = calculate_tdoa(sensor1_data, sensor2_data);

        // Log data
        if (log_data(log_file, sec, nsec, sensor1_data, sensor2_data, tdoa) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay for the sampling interval
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

