// ADIS16488A Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0b11000000000 // SPI mode 3 (CPOL=1, CPHA=1)

// Sensitivity values
#define GYRO_SENSITIVITY 0.005 // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// Sampling interval (milliseconds)
#define SAMPLING_INTERVAL 100

// Global variables
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile int running = 1;

// Structure to hold IMU data
typedef struct {
    double gyro_x;
    double gyro_y;
    double gyro_z;
    double accel_x;
    double accel_y;
    double accel_z;
} imu_data_t;

// Function prototypes
int spi_transfer(int handle, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_register(int handle, uint8_t reg_addr, uint16_t *data);
imu_data_t process_data(uint16_t gyro_x_raw, uint16_t gyro_y_raw, uint16_t gyro_z_raw, uint16_t accel_x_raw, uint16_t accel_y_raw, uint16_t accel_z_raw);
void log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// SPI transfer function
int spi_transfer(int handle, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int result = spiXfer(handle, tx_buf, rx_buf, len);
    if (result < 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a register from the ADIS16488A
int read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Construct the transmit buffer: MSB of register address is 0, LSB is the register address
    tx_buf[0] = 0x00; // MSB of register address
    tx_buf[1] = reg_addr; // LSB of register address

    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        return -1;
    }

    // Combine the two bytes to form the 16-bit data
    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to process raw data and convert to physical units
imu_data_t process_data(uint16_t gyro_x_raw, uint16_t gyro_y_raw, uint16_t gyro_z_raw, uint16_t accel_x_raw, uint16_t accel_y_raw, uint16_t accel_z_raw) {
    imu_data_t data;

    data.gyro_x = (double)gyro_x_raw * GYRO_SENSITIVITY;
    data.gyro_y = (double)gyro_y_raw * GYRO_SENSITIVITY;
    data.gyro_z = (double)gyro_z_raw * GYRO_SENSITIVITY;
    data.accel_x = (double)accel_x_raw * ACCEL_SENSITIVITY;
    data.accel_y = (double)accel_y_raw * ACCEL_SENSITIVITY;
    data.accel_z = (double)accel_z_raw * ACCEL_SENSITIVITY;

    return data;
}

