    fprintf(fp, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp_ms, data.gyro_x, data.gyro_y, data.gyro_z,
            data.accel_x, data.accel_y, data.accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to close SPI and file
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        cleanup();
        return 1;
    }

    // Write header row
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Main loop
    while (running) {
        uint16_t gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw;
        imu_data_t data;

        // Read sensor data
        if (read_register(spi_handle, X_GYRO, &gyro_x_raw) != 0) {
            fprintf(stderr, "Error reading X_GYRO register\n");
            continue; // Skip to the next iteration
        }
        if (read_register(spi_handle, Y_GYRO, &gyro_y_raw) != 0) {
            fprintf(stderr, "Error reading Y_GYRO register\n");
            continue;
        }
        if (read_register(spi_handle, Z_GYRO, &gyro_z_raw) != 0) {
            fprintf(stderr, "Error reading Z_GYRO register\n");
            continue;
        }
        if (read_register(spi_handle, X_ACCEL, &accel_x_raw) != 0) {
            fprintf(stderr, "Error reading X_ACCEL register\n");
            continue;
        }
        if (read_register(spi_handle, Y_ACCEL, &accel_y_raw) != 0) {
            fprintf(stderr, "Error reading Y_ACCEL register\n");
            continue;
        }
        if (read_register(spi_handle, Z_ACCEL, &accel_z_raw) != 0) {
            fprintf(stderr, "Error reading Z_ACCEL register\n");
            continue;
        }

        // Process data
        data = process_data(gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw);

        // Log data
        log_data(data);

        // Delay for the sampling interval
        gpioDelay(SAMPLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

