#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 for chip select

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_register(uint8_t reg_addr, uint16_t *data);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} sensor_data_t;

// Function to initialize SPI
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to perform SPI transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int result = spiXfer(spi_handle, tx_buf, rx_buf, len);
    if (result != len) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a register from the ADIS16448
int read_register(uint8_t reg_addr, uint16_t *data) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the transmit buffer: MSB of register address (0x80), LSB of register address
    tx_buf[0] = (reg_addr << 1) | 0x80; // Set MSB to 1 for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed during register read.\n");
        return -1;
    }

    // Extract the 16-bit data from the response
    *data = ((uint16_t)rx_buf[1] << 8) | (uint16_t)rx_buf[2];

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate CS initially

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data;

        // Read sensor data
        if (read_register(XGYRO_OUT, (uint16_t *)&data.gyro_x) != 0) {
            fprintf(stderr, "Error reading gyro_x\n");
            data.gyro_x = 0.0; // Set to a default value
        }
        if (read_register(YGYRO_OUT, (uint16_t *)&data.gyro_y) != 0) {
            fprintf(stderr, "Error reading gyro_y\n");
            data.gyro_y = 0.0;
        }
        if (read_register(ZGYRO_OUT, (uint16_t *)&data.gyro_z) != 0) {
            fprintf(stderr, "Error reading gyro_z\n");
            data.gyro_z = 0.0;
        }
        if (read_register(XACCL_OUT, (uint16_t *)&data.accel_x) != 0) {
            fprintf(stderr, "Error reading accel_x\n");
            data.accel_x = 0.0;
        }
        if (read_register(YACCL_OUT, (uint16_t *)&data.accel_y) != 0) {
            fprintf(stderr, "Error reading accel_y\n");
            data.accel_y = 0.0;
        }
        if (read_register(ZACCL_OUT, (uint16_t *)&data.accel_z) != 0) {
            fprintf(stderr, "Error reading accel_z\n");
            data.accel_z = 0.0;
        }

        // Apply scale factors
        data.gyro_x *= 0.02;  // dps/LSB
        data.gyro_y *= 0.02;  // dps/LSB
        data.gyro_z *= 0.02;  // dps/LSB
        data.accel_x *= 0.00025; // g/LSB
        data.accel_y *= 0.00025; // g/LSB
        data.accel_z *= 0.00025; // g/LSB

        // Print the data
        printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Accel X: %.6f g, Accel Y: %.6f g, Accel Z: %.6f g\n",
               data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

