        data.gyro_x *= 0.02;  // dps/LSB
        data.gyro_y *= 0.02;  // dps/LSB
        data.gyro_z *= 0.02;  // dps/LSB
        data.accel_x *= 0.00025; // g/LSB
        data.accel_y *= 0.00025; // g/LSB
        data.accel_z *= 0.00025; // g/LSB

        // Print the data
        printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Accel X: %.6f g, Accel Y: %.6f g, Accel Z: %.6f g\n",
               data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up
    spiClose(spi_handle);
    gpioWrite(CS_PIN, 0); // Deactivate CS
    gpioTerminate();

    return 0;
}

