#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // degrees/sec/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a 16-bit register from the ADIS16448
int16_t read_register(int reg_addr)
{
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message: read command (MSB = 1) + register address
    tx_buf[0] = 0x80 | (reg_addr & 0xFF); // Read command + register address
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract the 16-bit data from the response
    int16_t data = (rx_buf[1] << 8) | rx_buf[2];
    return data;
}

