    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int16_t gyro_x = read_register(X_GYRO_OUT);
        int16_t gyro_y = read_register(Y_GYRO_OUT);
        int16_t gyro_z = read_register(Z_GYRO_OUT);
        int16_t accel_x = read_register(X_ACCL_OUT);
        int16_t accel_y = read_register(Y_ACCL_OUT);
        int16_t accel_z = read_register(Z_ACCL_OUT);

        // Check for read errors
        if (gyro_x == -1 || gyro_y == -1 || gyro_z == -1 || accel_x == -1 || accel_y == -1 || accel_z == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to physical units
        float gyro_x_deg = gyro_x * GYRO_SCALE;
        float gyro_y_deg = gyro_y * GYRO_SCALE;
        float gyro_z_deg = gyro_z * GYRO_SCALE;
        float accel_x_g = accel_x * ACCL_SCALE;
        float accel_y_g = accel_y * ACCL_SCALE;
        float accel_z_g = accel_z * ACCL_SCALE;

