               gyro_x_deg, gyro_y_deg, gyro_z_deg, accel_x_g, accel_y_g, accel_z_g);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

