#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define ACCEL_XOUT_H_REG 0x3B
#define ACCEL_XOUT_L_REG 0x3C
#define ACCEL_YOUT_H_REG 0x3D
#define ACCEL_YOUT_L_REG 0x3E
#define ACCEL_ZOUT_H_REG 0x3F
#define ACCEL_ZOUT_L_REG 0x40
#define GYRO_XOUT_H_REG 0x43
#define GYRO_XOUT_L_REG 0x44
#define GYRO_YOUT_H_REG 0x45
#define GYRO_YOUT_L_REG 0x46
#define GYRO_ZOUT_H_REG 0x47
#define GYRO_ZOUT_L_REG 0x48

int i2c_fd = -1; // Global file descriptor for I2C

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from an I2C register
int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the MPU-6886 sensor
int init_mpu6886(int fd) {
    uint8_t who_am_i;

    // Check WHO_AM_I register
    if (i2c_read_reg(fd, WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x86) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x86\n", who_am_i);
        return -1;
    }

    // Wake up the sensor
    if (i2c_write_reg(fd, PWR_MGMT_1_REG, 0x00) != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }

    // Configure accelerometer range to +-2g
    if (i2c_write_reg(fd, ACCEL_CONFIG_REG, 0x00) != 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG register\n");
        return -1;
    }

    // Configure gyroscope range to +-250 dps
    if (i2c_write_reg(fd, GYRO_CONFIG_REG, 0x00) != 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read raw accelerometer data
int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    if (i2c_read_block(fd, ACCEL_XOUT_H_REG, buf, 6) != 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to read raw gyroscope data
int read_gyroscope(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    if (i2c_read_block(fd, GYRO_XOUT_H_REG, buf, 6) != 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int main() {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50000000; // 50 milliseconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, 0x68) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_mpu6886(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize MPU-6886 sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        if (read_accelerometer(i2c_fd, &accel_x, &accel_y, &accel_z) == 0) {
            // Read gyroscope data
            if (read_gyroscope(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
                // Print the raw data
                printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                       accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
            } else {
                fprintf(stderr, "Failed to read gyroscope data in main loop\n");
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data in main loop\n");
        }

        // Sleep for 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    return 0;
}

