#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x1A
#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0f // g
#define ACCEL_SCALE 1024.0f // Counts per g
#define POLL_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_mma8451q(int i2c_fd, int *x, int *y, int *z);
float calculate_magnitude(int x, int y, int z);
int check_threshold(float magnitude);
void control_led(int gpio, int state);
void log_impact();
void signal_handler(int signal);
void cleanup();

// Structure for accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    int x, y, z;
    float magnitude;
    while (!terminate) {
        // Read accelerometer data
        if (read_mma8451q(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check threshold
            if (check_threshold(magnitude)) {
                // Trigger LED
                control_led(LED_GPIO, 1);
                log_impact();
                gpioDelay(500); // 500 ms
                control_led(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        gpioDelay(POLL_INTERVAL_MS); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I_REG);
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I register returned 0x%X, expected 0x%X\n", who_am_i, WHO_AM_I_VALUE);
        close(i2c_fd);
        return -1;
    }

    printf("MMA8451Q sensor found at address 0x%X\n", MMA8451Q_ADDR);
    return 0;
}

// Read accelerometer data
int read_mma8451q(int i2c_fd, int *x, int *y, int *z) {
    char buf[6];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x01, buf, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Calculate magnitude of acceleration
float calculate_magnitude(int x, int y, int z) {
    return sqrtf((float)((x * x) + (y * y) + (z * z)) / ACCEL_SCALE);
}

// Check if magnitude exceeds threshold
int check_threshold(float magnitude) {
    return magnitude > ACCEL_THRESHOLD;
}

// Control LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Log impact to file
void log_impact() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Impact detected\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

