    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    if (open_log_file() < 0) {
        close(i2c_fd);
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!stop_flag) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

