int init_adxl345(int fd) {
    unsigned char devid;
    if (i2c_smbus_read_byte_data(fd, ADXL345_REG_DEVID) < 0) {
        perror("Error reading device ID");
        return -1;
    }
    devid = (unsigned char)i2c_smbus_read_byte_data(fd, ADXL345_REG_DEVID);

    if (devid != 0xE5) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", devid);
        return -1;
    }

    // Put sensor in standby mode
    if (i2c_smbus_write_byte_data(fd, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        perror("Error putting sensor in standby");
        return -1;
    }

    // Configure freefall parameters
    if (i2c_smbus_write_byte_data(fd, ADXL345_REG_THRESH_FF, 0x0A) < 0) {
        perror("Error setting freefall threshold");
        return -1;
    }
    if (i2c_smbus_write_byte_data(fd, ADXL345_REG_TIME_FF, 0x64) < 0) {
        perror("Error setting freefall time");
        return -1;
    }

    // Enable freefall interrupt
    if (i2c_smbus_write_byte_data(fd, ADXL345_REG_INT_ENABLE, 0x20) < 0) {
        perror("Error enabling freefall interrupt");
        return -1;
    }

    // Map interrupt to INT1
    if (i2c_smbus_write_byte_data(fd, ADXL345_REG_INT_MAP, 0x00) < 0) {
        perror("Error mapping interrupt");
        return -1;
    }

    // Put sensor in measurement mode
    if (i2c_smbus_write_byte_data(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        perror("Error putting sensor in measurement mode");
        return -1;
    }

    return 0;
