        int ret = gpiod_line_wait(gpio_line, &event, 100); // Timeout after 100ms
        if (ret < 0) {
            perror("Error polling GPIO");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
