    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.accel_x = data.accel_y = data.accel_z = 0.0f;
    } else {
        // Combine high and low bytes, convert to g
        data.accel_x = (float)((int16_t)(buffer[1] << 8 | buffer[0])) / 32768.0f * ACCEL_RANGE;
        data.accel_y = (float)((int16_t)(buffer[3] << 8 | buffer[2])) / 32768.0f * ACCEL_RANGE;
        data.accel_z = (float)((int16_t)(buffer[5] << 8 | buffer[4])) / 32768.0f * ACCEL_RANGE;
    }

    // Read gyroscope data (3 bytes)
    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_G, buffer + 6, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0f;
    } else {
        // Combine high and low bytes, convert to dps
        data.gyro_x = (float)((int16_t)(buffer[7] << 8 | buffer[6])) / 32768.0f * GYRO_RANGE;
        data.gyro_y = (float)((int16_t)(buffer[9] << 8 | buffer[8])) / 32768.0f * GYRO_RANGE;
        data.gyro_z = (float)((int16_t)(buffer[11] << 8 | buffer[10])) / 32768.0f * GYRO_RANGE;
    }

    return data;
}

// Calculate the magnitude of the acceleration vector
float calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Log sensor data to a CSV file
void log_data(sensor_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection state machine
void fall_detection(sensor_data_t data, float magnitude) {
    static float last_magnitude = 0.0f;
    static int state = 0; // 0: IDLE, 1: FREEFALL, 2: IMPACT

    if (state == 0) {
        if (magnitude < FREEFALL_THRESHOLD) {
            state = 1;
            printf("Freefall detected!\n");
        }
    } else if (state == 1) {
        if (magnitude >= IMPACT_THRESHOLD) {
            state = 2;
            printf("Impact detected!\n");
        } else {
            state = 0; // Return to IDLE if acceleration is below threshold
        }
    } else if (state == 2) {
        if (magnitude < FREEFALL_THRESHOLD) {
            state = 0; // Return to IDLE if acceleration is below threshold
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F);
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x69, got 0x%x\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Accel_Magnitude,Gyro_X,Gyro_Y,Gyro_Z\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        sensor_data_t data = read_sensor_data();
        float magnitude = calculate_acceleration_magnitude(data);
        log_data(data, magnitude);
        fall_detection(data, magnitude);
        gpioDelay(10000); // 10ms delay (104 Hz ODR)
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

