// Function to read a register from the ADIS16266
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: register address (MSB set) + data (dummy byte)
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read command
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    // Transfer the data
    int result = spiXfer(handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Extract the 16-bit data from the response
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Function to write a register to the ADIS16266
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: register address + data
    tx_buf[0] = reg_addr; // Clear MSB for write command
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    // Transfer the data
    int result = spiXfer(handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

