void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 0;
    int status;

    // Set CTRL_REG1 to enable normal mode and all axes
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }
    if (retries == 3) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after 3 retries.\n");
        return -1;
    }

    // Set CTRL_REG4 to set full-scale range to +-250 dps
    retries = 0;
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (status >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4 (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }
    if (retries == 3) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after 3 retries.\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F);
    if (who_am_i < 0 || who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I register check failed. Expected 0xD3, got 0x%02X\n", who_am_i);
        return -1;
    }

    printf("Gyroscope initialized successfully.\n");
    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];

    // Read 6 bytes starting from OUT_X_L
    int status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        data.x = 0; data.y = 0; data.z = 0; // Return 0s on error
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Log data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000L + ts.tv_nsec;

    fprintf(log_file, "%ld,%d,%d,%d\n", timestamp_ns, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Initialize the gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

