#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int flame_detected;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Enable pull-up resistor
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor value
        flame_detected = gpioRead(FLAME_SENSOR_GPIO);

        if (flame_detected == PI_BAD_GPIO) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s - ERROR: Failed to read GPIO %d\n", timestamp, FLAME_SENSOR_GPIO);
            fflush(log_file);
            fprintf(stderr, "ERROR: Failed to read GPIO %d\n", FLAME_SENSOR_GPIO);
        } else {
            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log data to file
            if (flame_detected == 0) {
                fprintf(log_file, "%s - Flame detected: YES\n", timestamp);
                fflush(log_file);
                printf("FLAME DETECTED!\n");
            } else {
                fprintf(log_file, "%s - Flame detected: NO\n", timestamp);
                fflush(log_file);
            }
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

