#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x53
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILE "vibration_log.csv"

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
sensor_data_t read_sensor_data();
char* get_iso8601_timestamp();
int write_to_csv(sensor_data_t data, char* timestamp);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data from registers
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint8_t buffer[6];

    // Read X axis
    if (read(i2c_fd, buffer, 6) != 6) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        data.x = 0; data.y = 0; data.z = 0; // Return default values
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Write data to CSV file
int write_to_csv(sensor_data_t data, char* timestamp) {
    if (csv_file == NULL) {
        fprintf(stderr, "CSV file is not open.\n");
        return -1;
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(csv_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    // Main loop
    while (program_running) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data();

        // Get timestamp
        char* timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp. Skipping this sample.\n");
            continue; // Skip to the next iteration
        }

        // Write data to CSV
        if (write_to_csv(sensor_data, timestamp) != 0) {
            fprintf(stderr, "Error writing to CSV. Skipping this sample.\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

