#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int log_data(FILE *fp, int sensor1_state, int sensor2_state);
void handle_signal(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorData;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file for appending
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop to monitor the sensors
    while (program_running) {
        // Read the sensor states
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Log the data to the file
        if (log_data(log_file, sensor1_state, sensor2_state) != 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }

        // Check if both sensors are triggered (logic 1)
        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("Conveyor halted!\n");
        }

        // Delay for 50 milliseconds
        gpioDelay(50);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the sensor state from a GPIO pin
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log the data to the file
int log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    if (fprintf(fp, "%ld.%03ld, Sensor1: %d, Sensor2: %d\n", ts.tv_sec, milliseconds, sensor1_state, sensor2_state) < 0) {
        perror("Error writing to log file");
        return 1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Function to handle signals (SIGINT, SIGTERM)
void handle_signal(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Function to cleanup GPIO resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

