        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%x, expected 0x2A\n", who_am_i);
        return -1;
    }

    // Set active mode, 100 Hz data rate, and standby time to 100ms
    if (i2c_write(fd, CTRL_REG1, DATA_RATE_100HZ) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register\n");
        return -1;
    }

    return 0;
}

