        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    printf("MMA8452Q initialized successfully\n");

    // Main loop
    while (program_running) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
