// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define CTRL_REG1 0x70
#define CTRL_REG4 0x0C
#define CTRL_REG3 0x00
#define CTRL_REG2 0x71
#define CTRL_REG6 0x72
#define CTRL_REG7 0x73
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Calibration constants
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detector threshold
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lis3mdl();
int read_magnetic_data(int16_t *x, int16_t *y, int16_t *z);
void apply_calibration(int16_t x, int16_t y, int16_t z, float *x_mga, float *y_mga, float *z_mga);
float calculate_magnitude(float x, float y, float z);
void log_data(float x, float y, float z);
void metal_detector_alert(float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

