#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Registers
#define ADXL354B_PARTID 0x01
#define ADXL354B_XDATA 0x08
#define ADXL354B_YDATA 0x0B
#define ADXL354B_ZDATA 0x0E
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_STATUS 0x04
#define ADXL354B_RESET 0x1F

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int adxl354b_init(int handle);
int read_acceleration_data(int handle, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Read bit set
    tx[1] = 0x00;       // Dummy byte

    int result = spiXfer(handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    return rx[1];
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2], rx[2];
    tx[0] = reg & 0x7F; // Write bit clear
    tx[1] = value;

    int result = spiXfer(handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// ADXL354B Initialization Function
int adxl354b_init(int handle) {
    // Reset the device
    if (spi_write_register(handle, ADXL354B_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1); // Wait 1 ms

    // Set measurement mode
    if (spi_write_register(handle, ADXL354B_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        return -1;
    }
    gpioDelay(100); // Wait for STABLE bit to be set

    // Verify Part ID
    int part_id = spi_read_register(handle, ADXL354B_PARTID);
    if (part_id != 0x1D) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x1D)\n", part_id);
        return -1;
    }

    printf("ADXL354B initialized successfully\n");
    return 0;
}

// Read Acceleration Data Function
int read_acceleration_data(int handle, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    // Read X, Y, and Z data
    raw_x = (spi_read_register(handle, ADXL354B_XDATA) << 8) | spi_read_register(handle, ADXL354B_XDATA + 1);
    raw_y = (spi_read_register(handle, ADXL354B_YDATA) << 8) | spi_read_register(handle, ADXL354B_YDATA + 1);
    raw_z = (spi_read_register(handle, ADXL354B_ZDATA) << 8) | spi_read_register(handle, ADXL354B_ZDATA + 1);

    // Convert to g-force units
    *x = (float)raw_x * 0.0000039;
    *y = (float)raw_y * 0.0000039;
    *z = (float)raw_z * 0.0000039;

    return 0;
}

// Log Data Function
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.4f g, Y: %.4f g, Z: %.4f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (adxl354b_init(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration_data(spi_handle, &x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

