#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16362 Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.0025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x_gyro;
    float y_gyro;
    float z_gyro;
    float x_accl;
    float y_accl;
    float z_accl;
} sensor_data_t;

// Function prototypes
int spi_read_register(uint8_t address, uint16_t *data);
sensor_data_t read_imu_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Function to read a register from the ADIS16362
int spi_read_register(uint8_t address, uint16_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Set MSB of address for read operation
    tx_buffer[0] = address | 0x80; // Read bit set
    tx_buffer[1] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    if (result != 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    *data = (rx_buffer[0] << 8) | rx_buffer[1];
    return 0;
}

// Function to read IMU data
sensor_data_t read_imu_data() {
    sensor_data_t data;
    uint16_t gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z;

    // Read gyroscope data
    if (spi_read_register(X_GYRO, &gyro_x) != 0) {
        data.x_gyro = 0.0; // Set to 0.0 on error
    } else {
        data.x_gyro = (float)gyro_x * GYRO_SCALE;
    }

    if (spi_read_register(Y_GYRO, &gyro_y) != 0) {
        data.y_gyro = 0.0;
    } else {
        data.y_gyro = (float)gyro_y * GYRO_SCALE;
    }

    if (spi_read_register(Z_GYRO, &gyro_z) != 0) {
        data.z_gyro = 0.0;
    } else {
        data.z_gyro = (float)gyro_z * GYRO_SCALE;
    }

    // Read accelerometer data
    if (spi_read_register(X_ACCL, &accl_x) != 0) {
        data.x_accl = 0.0;
    } else {
        data.x_accl = (float)accl_x * ACCL_SCALE;
    }

    if (spi_read_register(Y_ACCL, &accl_y) != 0) {
        data.y_accl = 0.0;
    } else {
        data.y_accl = (float)accl_y * ACCL_SCALE;
    }

    if (spi_read_register(Z_ACCL, &accl_z) != 0) {
        data.z_accl = 0.0;
    } else {
        data.z_accl = (float)accl_z * ACCL_SCALE;
    }

    return data;
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.x_gyro, data.y_gyro, data.z_gyro,
            data.x_accl, data.y_accl, data.z_accl);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

