// Signal handler for Ctrl+C
void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize GPIO lines
int init_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("Error getting GPIO17 line");
        gpiod_chip_close(chip);
        return -1;
    }

    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line27) {
        perror("Error getting GPIO27 line");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "obstacle_avoidance";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line17, &config, 0) < 0) {
        perror("Error requesting GPIO17 line");
        gpiod_line_release(line27);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(line27, &config, 0) < 0) {
        perror("Error requesting GPIO27 line");
        gpiod_line_release(line27);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read sensor values
int read_sensors() {
    unsigned int values[2];

    if (gpiod_line_request_get_values(line17, values, 2) < 0) {
        perror("Error getting sensor values");
        return -1;
    }

    return (values[0] << 1) | values[1];
}

// Function to log obstacle detection status
void log_status(int status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Obstacle status: %s\n", timestamp, status ? "Clear" : "Obstacle");
}

