    // Install signal handler
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        int sensor_status = read_sensors();
        if (sensor_status < 0) {
            fprintf(stderr, "Error reading sensors. Retrying.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        log_status(sensor_status);
        usleep(100000); // 100ms delay
    }

    // Cleanup
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

