#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// ADIS16266 Register Addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08
#define ADIS16266_MSC_CTRL 0x24

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize_spi();
int initialize_gpio();
int initialize_adis16266();
int read_adis16266_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_deg_per_sec(int16_t raw_data[3], float *deg_per_sec[3]);
void log_data(float deg_per_sec_x, float deg_per_sec_y, float deg_per_sec_z);
void signal_handler(int signal);

// Structure for grouping sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", CS_PIN);
        return -1;
    }
    gpioWrite(CS_PIN, 1); // Ensure CS is initially high
    return 0;
}

// Initialize ADIS16266
int initialize_adis16266() {
    char tx_buf[2];
    char rx_buf[2];

    // Write to MSC_CTRL register (0x24) to enable data ready mode
    tx_buf[0] = ADIS16266_MSC_CTRL | 0x80; // Read bit set
    tx_buf[1] = 0x03; // Enable data ready mode

    gpioWrite(CS_PIN, 0); // Select the device
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the device

    if (result != 0) {
        fprintf(stderr, "Error writing to MSC_CTRL register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read ADIS16266 data
int read_adis16266_data(int16_t *x, int16_t *y, int16_t *z) {
    char tx_buf[2];
    char rx_buf[2];
    int16_t temp;

    // Read X axis data
    tx_buf[0] = ADIS16266_XGYRO_OUT | 0x80; // Read bit set
    tx_buf[1] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the device
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the device

    if (result != 0) {
        fprintf(stderr, "Error reading X axis data: %d\n", result);
        return -1;
    }
    temp = (rx_buf[0] << 8) | rx_buf[1];
    *x = (int16_t)temp;

    // Read Y axis data
    tx_buf[0] = ADIS16266_YGYRO_OUT | 0x80; // Read bit set
    tx_buf[1] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the device
    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the device

    if (result != 0) {
        fprintf(stderr, "Error reading Y axis data: %d\n", result);
        return -1;
    }
    temp = (rx_buf[0] << 8) | rx_buf[1];
    *y = (int16_t)temp;

    // Read Z axis data
    tx_buf[0] = ADIS16266_ZGYRO_OUT | 0x80; // Read bit set
    tx_buf[1] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the device
    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deselect the device

    if (result != 0) {
        fprintf(stderr, "Error reading Z axis data: %d\n", result);
        return -1;
    }
    temp = (rx_buf[0] << 8) | rx_buf[1];
    *z = (int16_t)temp;

    return 0;
}

// Convert raw data to degrees per second
void convert_to_deg_per_sec(int16_t raw_data[3], float *deg_per_sec[3]) {
    *deg_per_sec[0] = (float)raw_data[0] * 0.02;
    *deg_per_sec[1] = (float)raw_data[1] * 0.02;
    *deg_per_sec[2] = (float)raw_data[2] * 0.02;
}

// Log data to console
void log_data(float deg_per_sec_x, float deg_per_sec_y, float deg_per_sec_z) {
    printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", deg_per_sec_x, deg_per_sec_y, deg_per_sec_z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADIS16266
    if (initialize_adis16266() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    int16_t raw_data[3];
    float deg_per_sec[3];

    // Main loop
    while (!terminate) {
        // Read data from ADIS16266
        if (read_adis16266_data(raw_data, raw_data, raw_data) == 0) {
            // Convert to degrees per second
            convert_to_deg_per_sec(raw_data, &deg_per_sec[0], &deg_per_sec[1], &deg_per_sec[2]);

            // Log the data
            log_data(deg_per_sec[0], deg_per_sec[1], deg_per_sec[2]);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

