#include <signal.h>
#include <unistd.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Sensitivity values
#define GYRO_SENSITIVITY 0.00875 // dps/LSB
#define ACCEL_SENSITIVITY 0.000061 // g/LSB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg)
{
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from an I2C register
int read_block(int handle, uint8_t reg, char *buffer, int count)
{
    int result = i2cReadI2CBlockData(handle, reg, buffer, count);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr(int handle)
{
    // Verify WHO_AM_I register
    int who_am_i = read_register(handle, WHO_AM_I);
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x6B)\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (write_register(handle, CTRL1_XL, 0x42) < 0) {
        return -1;
    }

    // Configure gyroscope
    if (write_register(handle, CTRL2_G, 0x42) < 0) {
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_accel_gyro(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z)
{
    char buffer[12];

    // Read gyroscope data
    if (read_block(handle, OUTX_L_G, buffer, 12) < 0) {
        return -1;
    }

    // Convert gyroscope data
    int16_t gyro_x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t gyro_y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t gyro_z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    *gyro_x = gyro_x_raw * GYRO_SENSITIVITY;
    *gyro_y = gyro_y_raw * GYRO_SENSITIVITY;
    *gyro_z = gyro_z_raw * GYRO_SENSITIVITY;

    // Read accelerometer data
    int16_t accel_x_raw = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t accel_y_raw = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t accel_z_raw = (int16_t)((buffer[11] << 8) | buffer[10]);

    *accel_x = accel_x_raw * ACCEL_SENSITIVITY;
    *accel_y = accel_y_raw * ACCEL_SENSITIVITY;
    *accel_z = accel_z_raw * ACCEL_SENSITIVITY;

    return 0;
}

