#include <unistd.h>
#include <pigpio.h>

// Define the I2C address of the FXOS8700 sensor
#define FXOS8700_ADDR 0x1D

// Define the register addresses for the FXOS8700
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

// Define the WHO_AM_I register
#define FXOS8700_WHO_AM_I 0x0D

// Define the expected WHO_AM_I value
#define FXOS8700_WHO_AM_I_VALUE 0xC7

// Global variable for the I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the FXOS8700 sensor
int initialize_sensor() {
    // Set the accelerometer to active mode and 100 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set the accelerometer to active mode and 100 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }

    // Set the magnetometer to hybrid mode
    if (i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG1, 0x1F) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG1\n");
        return -1;
    }

    // Set the magnetometer to hybrid mode
    if (i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG2, 0x20) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG2\n");
        return -1;
    }

    return 0;
}

// Function to read data from the FXOS8700 sensor
int read_sensor_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int result;

    // Read 12 bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Extract accelerometer data
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Extract magnetometer data
    *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

int main() {
    // Register the signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C connection
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify the sensor is present by reading the WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != FXOS8700_WHO_AM_I_VALUE) {
        fprintf(stderr, "FXOS8700 not found. WHO_AM_I returned 0x%X, expected 0x%X\n", who_am_i, FXOS8700_WHO_AM_I_VALUE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop to read and print sensor data
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (1) {
        // Read sensor data
        if (read_sensor_data(&accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            // Print the sensor data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Mag: X=%6d, Y=%6d, Z=%6d\n", accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

