#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36

// Tilt threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int read_accelerometer_data(accelerometer_data_t *data);
float calculate_tilt_angle(int16_t axis);
void log_tilt_event(float angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Set ADXL345 to measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to ADXL345 POWER_CTL register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(accelerometer_data_t *data) {
    char raw_data[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    data->x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    data->y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    data->z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    return 0;
}

// Function to calculate tilt angle
float calculate_tilt_angle(int16_t axis) {
    float angle = atan2(axis, 256.0) * 180.0 / M_PI;
    return angle;
}

// Function to log tilt event
void log_tilt_event(float angle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Tilt angle: %.2f degrees\n", timestamp, angle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    accelerometer_data_t accelerometer_data;
    float tilt_x, tilt_y, tilt_z;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer_data(&accelerometer_data) == 0) {
            // Calculate tilt angles
            tilt_x = calculate_tilt_angle(accelerometer_data.x);
            tilt_y = calculate_tilt_angle(accelerometer_data.y);
            tilt_z = calculate_tilt_angle(accelerometer_data.z);

            // Check for tilt events
            if (fabs(tilt_x) > TILT_THRESHOLD || fabs(tilt_y) > TILT_THRESHOLD || fabs(tilt_z) > TILT_THRESHOLD) {
                log_tilt_event(tilt_x);
                log_tilt_event(tilt_y);
                log_tilt_event(tilt_z);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

