#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5 // seconds
#define SAMPLE_RATE 1000 // milliseconds
#define THRESHOLD_MIN 1
#define THRESHOLD_MAX 1000

volatile sig_atomic_t program_running = 1;
int threshold = 0;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int validate_threshold(int threshold) {
    if (threshold < THRESHOLD_MIN || threshold > THRESHOLD_MAX) {
        fprintf(stderr, "Error: Threshold must be between %d and %d\n", THRESHOLD_MIN, THRESHOLD_MAX);
        return 0;
    }
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    threshold = atoi(argv[1]);
    if (validate_threshold(threshold) == 0) {
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        int high_count = 0;
        time_t start_time = time(NULL);

        while (time(NULL) - start_time < WINDOW_SIZE) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_RATE); // Delay for 1 ms
        }

        if (high_count > threshold) {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            printf("ALERT: %s - High count: %d\n", buf, high_count);
        } else {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            printf("Normal: %s - High count: %d\n", buf, high_count);
        }

        gpioDelay(1000); // Pause for 1 second
    }

    gpioTerminate();
    return 0;
}

