#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define chip file descriptor
static int chip_fd = -1;

// Define chip line file descriptor
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *door_a_line = NULL;
static struct gpiod_line *door_b_line = NULL;

// Define log file
static FILE *log_file = NULL;

// Define access log file
static FILE *access_log_file = NULL;

// Define SIGINT/SIGTERM handler flag
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int generate_random_code(char *code);
int read_user_input(char *input, size_t size);
int unlock_door(int door_pin);
int lock_door(int door_pin);
int log_access(const char *code);
int check_code(const char *entered_code);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal %d, exiting gracefully...\n", sig);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    chip_fd = open("/dev/gpiochip0", O_RDONLY);
    if (chip_fd < 0) {
        perror("Error opening GPIO chip");
        return -1;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        close(chip_fd);
        return -1;
    }

    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        perror("Error getting GPIO line for Door A");
        gpiod_chip_close(chip);
        close(chip_fd);
        return -1;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        perror("Error getting GPIO line for Door B");
        gpiod_line_release(door_a_line);
        gpiod_chip_close(chip);
        close(chip_fd);
        return -1;
    }

    if (gpiod_line_request_output(door_a_line, "door_access", 0) < 0) {
        perror("Error requesting GPIO line for Door A as output");
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        gpiod_chip_close(chip);
        close(chip_fd);
        return -1;
    }

    if (gpiod_line_request_output(door_b_line, "door_access", 0) < 0) {
        perror("Error requesting GPIO line for Door B as output");
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        gpiod_chip_close(chip);
        close(chip_fd);
        return -1;
    }

    return 0;
}

// Generate a random 6-digit code
int generate_random_code(char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Code buffer is NULL\n");
        return -1;
    }

    for (int i = 0; i < 6; i++) {
        code[i] = '0' + (rand() % 10);
    }
    code[6] = '\0'; // Null-terminate the string
    return 0;
}

// Read user input (with error handling for non-numeric input)
int read_user_input(char *input, size_t size) {
    if (input == NULL) {
        fprintf(stderr, "Error: Input buffer is NULL\n");
        return -1;
    }

    int c;
    int i = 0;

    while ((c = getchar()) != '\n' && c != EOF) {
        if (c >= '0' && c <= '9') {
            input[i++] = c;
        } else {
            // Clear the input buffer
            int temp = getchar(); // Consume any remaining characters in the buffer
            while (temp != EOF && temp != '\n') {
                temp = getchar();
            }
            break; // Exit the loop if a non-numeric character is encountered
        }
    }

    input[i] = '\0'; // Null-terminate the string
    return 0;
}

// Unlock a door (set GPIO HIGH)
int unlock_door(int door_pin) {
    if (door_pin != DOOR_A_PIN && door_pin != DOOR_B_PIN) {
        fprintf(stderr, "Error: Invalid door pin: %d\n", door_pin);
        return -1;
    }

    if (gpiod_line_set_value(door_a_line, door_pin == DOOR_A_PIN) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Lock a door (set GPIO LOW)
int lock_door(int door_pin) {
    if (door_pin != DOOR_A_PIN && door_pin != DOOR_B_PIN) {
        fprintf(stderr, "Error: Invalid door pin: %d\n", door_pin);
        return -1;
    }

    if (gpiod_line_set_value(door_a_line, door_pin == DOOR_A_PIN) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Log access to file
int log_access(const char *code) {
    if (access_log_file == NULL) {
        fprintf(stderr, "Error: Access log file is NULL\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(access_log_file, "%d-%02d-%02d %02d:%02d:%02d,%s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, code);
    fflush(access_log_file); // Ensure data is written to disk
    return 0;
}

// Check if the entered code matches the generated code
int check_code(const char *entered_code) {
    if (entered_code == NULL) {
        fprintf(stderr, "Error: Entered code is NULL\n");
        return -1;
    }

    char generated_code[7]; // Ensure enough space for the code + null terminator
    generate_random_code(generated_code);
    if (generated_code[6] != '\0') {
        fprintf(stderr, "Error: Failed to generate random code\n");
        return -1;
    }

    if (strcmp(entered_code, generated_code) == 0) {
        return 0; // Match
    } else {
        return -1; // No match
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    if (door_a_line) {
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_release(door_b_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (chip_fd > 0) {
        close(chip_fd);
    }

    if (access_log_file) {
        fclose(access_log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open access log file
    access_log_file = fopen("access_log.txt", "a");
    if (access_log_file == NULL) {
        perror("Error opening access log file");
        cleanup();
        return 1;
    }

    // Main loop
    char entered_code[7]; // Buffer for user input
    char generated_code[7]; // Buffer for generated code
    int code_matches;

    printf("Door Access System\n");
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        // Generate random code
        if (generate_random_code(generated_code) < 0) {
            fprintf(stderr, "Failed to generate random code. Continuing.\n");
            continue;
