#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE_2 0x21
#define LUX_SCALE_FACTOR 5.0
#define LUX_SCALE_DIVISOR 6.0

int i2c_fd = -1; // Global file descriptor for I2C
FILE *log_file = NULL; // Global file pointer for the log file

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to write a command to the BH1750 sensor
int write_bh1750_command(int fd, unsigned char command) {
    unsigned char buf[1];
    buf[0] = command;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the BH1750 sensor
int read_bh1750_data(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to calculate illuminance from raw data
float calculate_lux(unsigned int raw_value) {
    return (raw_value * LUX_SCALE_FACTOR) / LUX_SCALE_DIVISOR;
}

// Function to log the timestamp and illuminance value to a file
int log_data(FILE *fp, float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Lux: %.2f\n", timestamp, lux_value) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("light_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    unsigned char data[2];
    unsigned int raw_value;
    float lux_value;

    // Main loop
    while (1) {
        // Write the continuous high-resolution mode 2 command
        if (write_bh1750_command(i2c_fd, CONTINUOUS_HIGH_RES_MODE_2) < 0) {
            fprintf(stderr, "Error writing to BH1750, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for the conversion to complete (at least 180ms)
        usleep(200000); // 200ms

        // Read the two bytes of data
        if (read_bh1750_data(i2c_fd, data, 2) < 0) {
            fprintf(stderr, "Error reading from BH1750, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Combine the two bytes into a 16-bit unsigned integer
        raw_value = (data[0] << 8) | data[1];

        // Calculate the illuminance
        lux_value = calculate_lux(raw_value);

        // Log the data
        if (log_data(log_file, lux_value) < 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

