#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_PWM 18
#define PORT 12345
#define MOTION_SECRET "MySecretKey"
#define SAMPLE_RATE_MS 20
#define PLAYBACK_DURATION_S 5
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;

// Function prototypes
int init_mpr121();
int read_touch_data(int *touch_data);
float map_touch_to_frequency(int touch_data);
void play_tone(float frequency);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signum);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        cleanup();
        exit(0);
    }
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (new_socket >= 0) {
        close(new_socket);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioPWM(GPIO_PWM, 0); // Stop PWM
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure Electrode Filter
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode Filter Configuration
        fprintf(stderr, "Error: Failed to configure Electrode Filter\n");
        return -1;
    }

    // Configure Touch and Release Thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x30) < 0) { // Touch Threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x10) < 0) { // Release Threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure Baseline Filtering
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Set Baseline Filter Configuration
        fprintf(stderr, "Error: Failed to configure Baseline Filter\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x8F) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    return 0;
}

// Read touch data from MPR121
int read_touch_data(int *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }

    *touch_data = ((int)buf[1] << 8) | (int)buf[0];
    return 0;
}

// Map touch data to frequency (logarithmic scale)
float map_touch_to_frequency(int touch_data) {
    float frequency = 220.0 + 660.0 * log10f((float)touch_data / 4095.0);
    return frequency;
}

// Play tone using hardware PWM
void play_tone(float frequency) {
    int range = 1000; // PWM range
    int duty_cycle = range / 2; // 50% duty cycle
    gpioSetPWMfrequency(GPIO_PWM, (int)frequency);
    gpioSetPWMrange(GPIO_PWM, range);
    gpioPWM(GPIO_PWM, duty_cycle);
}

// Log frequency to file
void log_frequency(float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Frequency: %.2f Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t bytes_received;

    // Receive client message
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        close(client_socket);
        return;
    }

    // Check for motion detected command
    if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0) {
        // Check for secret key
        if (strstr(buffer, MOTION_SECRET) != NULL) {
            printf("Motion detected and secret key found!\n");

            // Read touch data
            int touch_data;
            if (read_touch_data(&touch_data) == 0) {
                // Map touch data to frequency
                float frequency = map_touch_to_frequency(touch_data);

                // Play tone
                play_tone(frequency);

                // Log frequency
                log_frequency(frequency);

