#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Configuration
#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define LED_GPIO 17
#define PWM_CHIP "gpiochip0"
#define PWM_NUM 0
#define PWM_PERIOD 1000000 // 1 kHz
#define SAMPLE_INTERVAL_MS 100

// LSM303DLHC Magnetometer Registers
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define OUT_X_H_M 0x09
#define OUT_Y_L_M 0x0A
#define OUT_Y_H_M 0x0B
#define OUT_Z_L_M 0x0C
#define OUT_Z_H_M 0x0D

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int init_gpio(int gpio_pin);
int init_pwm(int chip, int num, int period);
int read_magnetometer_data(int fd, int *x, int *y, int *z);
float calculate_magnitude(int x, int y, int z);
int set_led_brightness(int brightness);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// GPIO initialization
int init_gpio(int gpio_pin) {
    int chip = 0; // Default GPIO chip
    struct gpiod_chip *chip_ptr = gpiod_chip_open_by_name("gpiochip0");
    if (!chip_ptr) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_ptr = gpiod_chip_get_line(chip_ptr, gpio_pin);
    if (!line_ptr) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "magnetometer_led_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line_ptr, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip_ptr);
        return -1;
    }

    chip_ptr = NULL; // No longer needed
    return 0;
}

// PWM initialization
int init_pwm(int chip, int num, int period) {
    int fd = open("/sys/class/pwm/pwmchip0/pwm"+to_string(num), O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM device");
        return -1;
    }

    // Export PWM if it doesn't exist
    if (access("/sys/class/pwm/pwmchip0/pwm"+to_string(num), F_OK) == -1) {
        char export_path[100];
        snprintf(export_path, sizeof(export_path), "/sys/class/pwm/pwmchip0/export");
        int export_fd = open(export_path, O_WRONLY);
        if (export_fd < 0) {
            perror("Error opening PWM export file");
            close(fd);
            return -1;
        }
        char num_str[10];
        snprintf(num_str, sizeof(num_str), "%d", num);
        if (write(export_fd, num_str, strlen(num_str)) < 0) {
            perror("Error writing to PWM export file");
            close(export_fd);
            close(fd);
            return -1;
        }
        close(export_fd);
    }

    // Set PWM period
    char period_path[100];
    snprintf(period_path, sizeof(period_path), "/sys/class/pwm/pwmchip0/pwm"+to_string(num)+"/period");
    int period_fd = open(period_path, O_WRONLY);
    if (period_fd < 0) {
        perror("Error opening PWM period file");
        close(fd);
        return -1;
    }
    char period_str[20];
    snprintf(period_str, sizeof(period_str), "%d", period);
    if (write(period_fd, period_str, strlen(period_str)) < 0) {
        perror("Error writing to PWM period file");
        close(period_fd);
        close(fd);
        return -1;
    }
    close(period_fd);

    // Enable PWM
    char enable_path[100];
    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/pwmchip0/pwm"+to_string(num)+"/enable");
    int enable_fd = open(enable_path, O_WRONLY);
    if (enable_fd < 0) {
        perror("Error opening PWM enable file");
        close(fd);
        return -1;
    }
    char enable_str[2];
    snprintf(enable_str, sizeof(enable_str), "1");
    if (write(enable_fd, enable_str, strlen(enable_str)) < 0) {
        perror("Error writing to PWM enable file");
        close(enable_fd);
        close(fd);
        return -1;
    }
    close(enable_fd);

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int fd, int *x, int *y, int *z) {
    unsigned char buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude of Z-axis field
float calculate_magnitude(int x, int y, int z) {
    return fabs(z);
}

// Set LED brightness using PWM
int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 100) brightness = 100;

    char duty_path[100];
    snprintf(duty_path, sizeof(duty_path), "/sys/class/pwm/pwmchip0/pwm%d/duty", PWM_NUM);
    int duty_fd = open(duty_path, O_WRONLY);
    if (duty_fd < 0) {
        perror("Error opening PWM duty file");
        return -1;
    }

    char duty_str[20];
    snprintf(duty_str, sizeof(duty_str), "%d", brightness * PWM_PERIOD / 100);
    if (write(duty_fd, duty_str, strlen(duty_str)) < 0) {
        perror("Error writing to PWM duty file");
        close(duty_fd);
        return -1;
    }
    close(duty_fd);

    return 0;
}

// Cleanup resources
void cleanup() {
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(LED_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize PWM
    if (init_pwm(PWM_CHIP, PWM_NUM, PWM_PERIOD) < 0) {
        fprintf(stderr, "PWM initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    int x, y, z;
    float magnitude;
    int brightness;

    // Configure magnetometer (10 Hz continuous conversion)
    unsigned char config_data[2] = {CTRL_REG1_M, 0x18}; // Continuous conversion, 10 Hz
    if (write(i2c_fd, config_data, 2) != 2) {
        perror("Error configuring magnetometer");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Map magnitude to brightness (0-100)
            brightness = (int)((magnitude / 1000.0) * 100); // Scale to 0-100
            if (brightness > 100) brightness = 100;
            if (brightness < 0) brightness = 0;

            // Set LED brightness
            if (set_led_brightness(brightness) < 0) {
                fprintf(stderr, "Error setting LED brightness.\n");
            }
        } else {
            fprintf(stderr, "Error reading magnetometer data. Skipping.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

