#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L Registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03

// Hard iron offsets
#define HARD_IRON_SAMPLES 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold hard iron offsets
typedef struct {
    float x;
    float y;
    float z;
} HardIronOffsets;

// Function prototypes
int init_hmc5883l();
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z);
HardIronOffsets calculate_hard_iron_offsets(int16_t *raw_data, int num_samples);
void apply_hard_iron_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z, HardIronOffsets offsets, int16_t *corrected_x, int16_t *corrected_y, int16_t *corrected_z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Configuration Register A: 8-sample averaging, 15 Hz output rate
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to Configuration Register A\n");
        return -1;
    }

    // Configuration Register B: Gain setting (1.3 Gauss)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to Configuration Register B\n");
        return -1;
    }

    // Mode Register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to Mode Register\n");
        return -1;
    }

    return 0;
}

// Read raw data from HMC5883L
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading data from HMC5883L\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[4] << 8) | data[5]);
    *z = (int16_t)((data[2] << 8) | data[3]);

    return 0;
}

// Calculate hard iron offsets
HardIronOffsets calculate_hard_iron_offsets(int16_t *raw_data, int num_samples) {
    HardIronOffsets offsets = {0.0, 0.0, 0.0};
    float sum_x = 0.0, sum_y = 0.0, sum_z = 0.0;

    for (int i = 0; i < num_samples; i++) {
        sum_x += raw_data[i].x;
        sum_y += raw_data[i].y;
        sum_z += raw_data[i].z;
        gpioDelay(1); // Small delay for averaging
    }

    offsets.x = sum_x / num_samples;
    offsets.y = sum_y / num_samples;
    offsets.z = sum_z / num_samples;

    return offsets;
}

// Apply hard iron offsets
void apply_hard_iron_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z, HardIronOffsets offsets, int16_t *corrected_x, int16_t *corrected_y, int16_t *corrected_z) {
    *corrected_x = raw_x - offsets.x;
    *corrected_y = raw_y - offsets.y;
    *corrected_z = raw_z - offsets.z;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_data[HARD_IRON_SAMPLES];
    int16_t corrected_x, corrected_y, corrected_z;
    HardIronOffsets offsets;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_hmc5883l(&raw_data[0], &raw_data[1], &raw_data[2]) < 0) {
            fprintf(stderr, "Error reading magnetometer data\n");
            break; // Exit loop on error
        }

        // Calculate hard iron offsets
        offsets = calculate_hard_iron_offsets(raw_data, HARD_IRON_SAMPLES);

        // Apply hard iron offsets
        apply_hard_iron_offsets(raw_data[0].x, raw_data[0].y, raw_data[0].z, offsets, &corrected_x, &corrected_y, &corrected_z);

        // Print corrected values
        printf("%d %d %d\n", corrected_x, corrected_y, corrected_z);

        gpioDelay(500); // Wait 500 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

