#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG 0x30
#define OUT_X_L_A 0x28

// GPIO pin for INT1 interrupt
#define INT1_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer
accelerometer_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int initialize_gpio();
int initialize_lsm303d();
int read_accelerometer_data(accelerometer_data_t *data);
void store_data(accelerometer_data_t data);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void print_buffer();
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c() {
    i2c_fd = i2cOpen(1, LSM303D_ADDR, 0); // I2C bus 1, address 0x1D, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioSetMode(INT1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    if (gpioSetPullUpDown(INT1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting GPIO pull-up: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize LSM303D
int initialize_lsm303d() {
    // Verify WHO_AM_I register
    int who_am_i = i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 50 Hz ODR, all axes enabled, +-2g full-scale
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Set interrupt threshold and duration
    if (i2c_smbus_write_byte_data(i2c_fd, INT1_CFG, 0x2A) < 0) {
        fprintf(stderr, "Error writing to INT1_CFG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(accelerometer_data_t *data) {
    char raw_data[6];
    int retries = 3;

    while (retries > 0) {
        if (i2c_smbus_read_i2c_block_data(i2c_fd, OUT_X_L_A, raw_data, 6) >= 0) {
            // Combine high and low bytes for each axis
            data->x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
            data->y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
            data->z = (int16_t)((raw_data[5] << 8) | raw_data[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            retries--;
            gpioDelay(1000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read accelerometer data after multiple retries.\n");
    return -1; // Failure
}

// Function to store data in the circular buffer
void store_data(accelerometer_data_t data) {
    buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    print_buffer();
}

// Function to print the contents of the circular buffer
void print_buffer() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Interrupt triggered\n", timestamp);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        printf("  %04d-%02d-%02d %02d:%02d:%02d: X=%6d, Y=%6d, Z=%6d\n",
               t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec,
               buffer[index].x, buffer[index].y, buffer[index].z);
    }
}

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // unused
    program_running = 0;
    printf("Caught signal, exiting...\n");

    // Disable accelerometer
    if (i2c_fd >= 0) {
        i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, 0x00);
        i2cClose(i2c_fd);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (initialize_lsm303d() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(INT1_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    accelerometer_data_t data;
    while (program_running) {
        if (read_accelerometer_data(&data) == 0) {
            store_data(data);
        } else {
            fprintf(stderr, "Failed to read accelerometer data, skipping.\n");
        }

        gpioDelay(10000); // 10 ms delay (10000 microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

