#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *solenoid_1_line = NULL;
struct gpiod_line *solenoid_2_line = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(struct gpiod_line *line, int value);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, cleaning up...\n", sig);

        // De-energize solenoids
        if (solenoid_1_line) {
            gpio_set_value(solenoid_1_line, 0);
        }
        if (solenoid_2_line) {
            gpio_set_value(solenoid_2_line, 0);
        }

        // Release GPIO lines
        if (solenoid_1_line) {
            gpiod_line_release(solenoid_1_line);
        }
        if (solenoid_2_line) {
            gpiod_line_release(solenoid_2_line);
        }

        // Unexport GPIO pins
        gpio_unexport(SOLENOID_1_PIN);
        gpio_unexport(SOLENOID_2_PIN);

        printf("Cleanup complete. Exiting.\n");
        exit(0);
    }
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    char chip[64];
    FILE *fp;

    snprintf(chip, sizeof(chip), "%s", CHIP_NAME);

    fp = fopen("/sys/class/gpio/export", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    FILE *fp;

    fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s", direction);
    fclose(fp);
    return 0;
}

// Function to set the value of a GPIO line (0 or 1)
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pins
    if (gpio_export(SOLENOID_1_PIN) < 0) return 1;
    if (gpio_export(SOLENOID_2_PIN) < 0) {
        gpio_unexport(SOLENOID_1_PIN);
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(SOLENOID_1_PIN, "out") < 0) {
        gpio_unexport(SOLENOID_1_PIN);
        gpio_unexport(SOLENOID_2_PIN);
        return 1;
    }
    if (gpio_set_direction(SOLENOID_2_PIN, "out") < 0) {
        gpio_unexport(SOLENOID_1_PIN);
        gpio_unexport(SOLENOID_2_PIN);
        return 1;
    }

    // Initialize solenoid lines
    solenoid_1_line = gpiod_chip_open_by_name(CHIP_NAME);
    if (!solenoid_1_line) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        gpio_unexport(SOLENOID_1_PIN);
        gpio_unexport(SOLENOID_2_PIN);
        return 1;
    }

    solenoid_2_line = gpiod_chip_open_by_name(CHIP_NAME);
    if (!solenoid_2_line) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        gpiod_line_release(solenoid_1_line);
        gpio_unexport(SOLENOID_1_PIN);
        gpio_unexport(SOLENOID_2_PIN);
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "solenoid_actuator";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(solenoid_1_line, 0, &config) < 0) {
        fprintf(stderr, "Error requesting solenoid 1 line: %s\n", strerror(errno));
        gpiod_line_release(solenoid_1_line);
        gpiod_line_release(solenoid_2_line);
        gpio_unexport(SOLENOID_1_PIN);
        gpio_unexport(SOLENOID_2_PIN);
        return 1;
    }

    if (gpiod_line_request(solenoid_2_line, 0, &config) < 0) {
        fprintf(stderr, "Error requesting solenoid 2 line: %s\n", strerror(errno));
        gpiod_line_release(solenoid_1_line);
        gpiod_line_release(solenoid_2_line);
        gpio_unexport(SOLENOID_1_PIN);
        gpio_unexport(SOLENOID_2_PIN);
        return 1;
    }

    // De-energize solenoids at startup
    if (gpio_set_value(solenoid_1_line, 0) < 0) {
        gpiod_line_release(solenoid_1_line);
        gpiod_line_release(solenoid_2_line);
        gpio_unexport(SOLENOID_1_PIN);
        gpio_unexport(SOLENOID_2_PIN);
        return 1;
    }
    if (gpio_set_value(solenoid_2_line, 0) < 0) {
        gpiod_line_release(solenoid_1_line);
        gpiod_line_release(solenoid_2_line);
        gpio_unexport(SOLENOID_1_PIN);
        gpio_unexport(SOLENOID_2_PIN);
        return 1;
    }

    // Main loop
    while (1) {
        // Energize solenoid 1
        if (gpio_set_value(solenoid_1_line, 1) < 0) {
            gpiod_line_release(solenoid_1_line);
            gpiod_line_release(solenoid_2_line);
            gpio_unexport(SOLENOID_1_PIN);
            gpio_unexport(SOLENOID_2_PIN);
            return 1;
        }
        if (gpio_set_value(solenoid_2_line, 0) < 0) {
            gpiod_line_release(solenoid_1_line);
            gpiod_line_release(solenoid_2_line);
            gpio_unexport(SOLENOID_1_PIN);
            gpio_unexport(SOLENOID_2_PIN);
            return 1;
        }

        // Wait 500 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 500 * 1000 * 1000; // 500 ms
        nanosleep(&ts, NULL);

        // De-energize solenoid 1
        if (gpio_set_value(solenoid_1_line, 0) < 0) {
            gpiod_line_release(solenoid_1_line);
            gpiod_line_release(solenoid_2_line);
            gpio_unexport(SOLENOID_1_PIN);
            gpio_unexport(SOLENOID_2_PIN);
            return 1;
        }
        if (gpio_set_value(solenoid_2_line, 1) < 0) {
            gpiod_line_release(solenoid_1_line);
            gpiod_line_release(solenoid_2_line);
            gpio_unexport(SOLENOID_1_PIN);
            gpio_unexport(SOLENOID_2_PIN);
            return 1;
        }

        // Wait 500 ms
        ts.tv_sec = 0;
        ts.tv_nsec = 500 * 1000 * 1000; // 500 ms
        nanosleep(&ts, NULL);
    }

    return 0;
}

