#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

// Define GPIO pins for door locks
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART ports
#define UART_PRIMARY "/dev/serial0"
#define UART_SECONDARY "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define expected code
#define EXPECTED_CODE "123456"

// Define timeout duration (in seconds)
#define TIMEOUT_DURATION 5

// Define unlock duration (in seconds)
#define UNLOCK_DURATION 2

// Global variables
static volatile int running = 1;
static int uart_fd_primary = -1;
static int uart_fd_secondary = -1;
static char code_buffer_primary[7] = {0};
static char code_buffer_secondary[7] = {0};
static int code_index_primary = 0;
static int code_index_secondary = 0;

// Function prototypes
int initialize_gpio();
int initialize_uart(const char *port);
int read_uart(int fd, char *buffer, int buffer_size);
int validate_code(const char *code);
void unlock_doors();
void lock_doors();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Initialize locks to locked state (LOW)
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    return 0;
}

// Function to initialize UART
int initialize_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s\n", port);
        return -1;
