#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME 1 // seconds
#define FAILSAFE_TIMEOUT 10 // seconds
#define POLL_INTERVAL 50 // milliseconds

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_pir_sensor(void);
int energize_relay(void);
int de_energize_relay(void);
void failsafe(void);
void log_event(const char *event);
void signal_handler(int sig);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Received signal, shutting down...");
        terminate = 1;
    }
}

// Initialize GPIO
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", "gpiochip0");
        return -1;
    }

    // Request PIR sensor line
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request Relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get Relay line");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request PIR line for input
    ret = gpiod_line_request_input(pir_line, "motion_sensor");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request PIR line for input: %s", gpiod_line_name(pir_line));
        gpiod_line_release(relay_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request Relay line for output
    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request Relay line for output: %s", gpiod_line_name(relay_line));
        gpiod_line_release(relay_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read PIR sensor
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor value: %s", gpiod_line_name(pir_line));
        return -1;
    }
    return value;
}

// Energize relay
int energize_relay(void) {
    int ret = gpiod_line_set_value(relay_line, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to energize relay: %s", gpiod_line_name(relay_line));
        return -1;
    }
    log_event("Relay energized");
    return 0;
}

// De-energize relay
int de_energize_relay(void) {
    int ret = gpiod_line_set_value(relay_line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to de-energize relay: %s", gpiod_line_name(relay_line));
        return -1;
    }
    log_event("Relay de-energized");
    return 0;
}

// Failsafe mechanism
void failsafe(void) {
    log_event("Failsafe triggered: Relay de-energized");
    de_energize_relay();
}

// Log event
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, event);
}

// Cleanup GPIO resources
void cleanup(void) {
    log_event("Cleaning up GPIO resources...");

    if (relay_line) {
        de_energize_relay();
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    log_event("GPIO cleanup complete");
}

int main(void) {
    int pir_value;
    time_t motion_start_time = 0;
    int failsafe_triggered = 0;

    // Open syslog
    openlog("motion_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event("System started");

    // Main loop
    while (!terminate) {
        pir_value = read_pir_sensor();
        if (pir_value < 0) {
            // Handle read error, but continue running
            usleep(POLL_INTERVAL * 1000); // Sleep to avoid busy-waiting
            continue;
        }

        if (pir_value == 1) {
            if (motion_start_time == 0) {
                motion_start_time = time(NULL);
            }

            if (failsafe_triggered == 0) {
                if (time(NULL) - motion_start_time > FAILSAFE_TIMEOUT) {
                    failsafe_triggered = 1;
                    failsafe();
                }
            }

            if (energize_relay() == 0) {
                sleep(RELAY_ON_TIME);
                de_energize_relay();
            }
        } else {
            motion_start_time = 0;
            failsafe_triggered = 0;
        }

        usleep(POLL_INTERVAL * 1000); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

