#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the duration of each relay activation (in seconds)
#define RELAY_DURATION 300

// Define the pause duration between relay activations (in seconds)
#define PAUSE_DURATION 60

// Define the total number of relays
#define NUM_RELAYS 4

// Define the timer interval (in seconds)
#define TIMER_INTERVAL 60

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_states[NUM_RELAYS] = {1, 1, 1, 1}; // Initialize all relays to OFF (HIGH)
int current_relay = 0; // Index of the current relay to activate

// Function prototypes
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void pause();
void signal_handler(int signal);
void log_event(const char *message);
int initialize_gpio();
void cleanup_gpio();

// Function to activate a relay
void activate_relay(int relay_number) {
    if (!program_running) return; // Check if the program should exit

    int gpio_pin = (relay_number - 1) * 4 + 4; // Calculate GPIO pin based on relay number
    if (gpio_pin < 0 || gpio_pin > 31) {
        log_event("Error: Invalid GPIO pin for relay.");
        return;
    }

    if (relay_states[relay_number - 1] == 1) { // Check if relay is already ON
        log_event("Warning: Relay already ON.");
        return;
    }

    if (gpioWrite(gpio_pin, 0) != 0) { // Set GPIO pin to LOW (ON)
        log_event("Error: Failed to activate relay.");
        return;
    }

    relay_states[relay_number - 1] = 0; // Update relay state
    char message[100];
    snprintf(message, sizeof(message), "Relay %d activated", relay_number);
    log_event(message);
    current_relay = relay_number; // Update current relay
}

// Function to deactivate a relay
void deactivate_relay(int relay_number) {
    if (!program_running) return; // Check if the program should exit

    int gpio_pin = (relay_number - 1) * 4 + 4; // Calculate GPIO pin based on relay number
    if (gpio_pin < 0 || gpio_pin > 31) {
        log_event("Error: Invalid GPIO pin for relay.");
        return;
    }

    if (relay_states[relay_number - 1] == 0) { // Check if relay is already OFF
        log_event("Warning: Relay already OFF.");
        return;
    }

    if (gpioWrite(gpio_pin, 1) != 0) { // Set GPIO pin to HIGH (OFF)
        log_event("Error: Failed to deactivate relay.");
        return;
    }

    relay_states[relay_number - 1] = 1; // Update relay state
    char message[100];
    snprintf(message, sizeof(message), "Relay %d deactivated", relay_number);
    log_event(message);
    current_relay = 0; // Reset current relay
}

// Function to pause the program
void pause() {
    if (!program_running) return; // Check if the program should exit

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, pause, NULL) != 0) {
        log_event("Error: Failed to set timer function.");
        return;
    }
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received signal, shutting down...");
        program_running = 0; // Set the flag to exit the main loop
    }
}

// Function to log events to syslog
void log_event(const char *message) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("Error: pigpio initialisation failed");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    gpioWrite(RELAY1_GPIO, 1);
    gpioWrite(RELAY2_GPIO, 1);
    gpioWrite(RELAY3_GPIO, 1);
    gpioWrite(RELAY4_GPIO, 1);

    return 0; // Indicate success
}

// Function to cleanup the pigpio library and GPIO pins
void cleanup_gpio() {
    // Deactivate all relays
    gpioWrite(RELAY1_GPIO, 1);
    gpioWrite(RELAY2_GPIO, 1);
    gpioWrite(RELAY3_GPIO, 1);
    gpioWrite(RELAY4_GPIO, 1);

    gpioTerminate();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    log_event("Irrigation system started");

    // Main loop
    while (program_running) {
        if (current_relay > 0) {
            activate_relay(current_relay);
        } else {
            pause();
        }
    }

    // Cleanup GPIO and exit
    cleanup_gpio();
    log_event("Irrigation system stopped");
    return 0;
}

