#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_CONFIG 0x1C
#define SAMPLE_RATE 100 // Hz
#define BUFFER_SIZE 100
#define G_PER_LSB 16384.0

// Global variables
static int i2c_fd = -1;
static int running = 1;
static int timer_fd = -1;
static int sysfs_fd = -1;
static volatile sig_atomic_t timer_active = 0;

// Data structure for storing acceleration data
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

// Circular buffer
AccelData accel_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int init_mpu6050();
int open_sysfs_timer();
void close_sysfs_timer();
int read_accel_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int sig);
void cleanup();
void write_to_sysfs(const char *data);
int read_from_sysfs(char *buffer, size_t buffer_size);

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return 0;
}

// Function to initialize MPU6050
int init_mpu6050() {
    uint8_t wake_up = 0x00;
    if (write(i2c_fd, &wake_up, 1) != 1) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    uint8_t config = 0x00; // +-2g range
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Error writing to ACCEL_CONFIG");
        return -1;
    }
    return 0;
}

// Function to open the sysfs timer
int open_sysfs_timer() {
    char timer_path[64];
    snprintf(timer_path, sizeof(timer_path), "/sys/kernel/mm/iio/devices/iio:device0/timer");
    timer_fd = open(timer_path, O_RDWR);
    if (timer_fd < 0) {
        perror("Error opening sysfs timer");
        return -1;
    }
    return 0;
}

// Function to close the sysfs timer
void close_sysfs_timer() {
    if (timer_fd != -1) {
        close(timer_fd);
        timer_fd = -1;
    }
}

// Function to write to the sysfs timer
void write_to_sysfs(const char *data) {
    ssize_t bytes_written = write(timer_fd, data, strlen(data));
    if (bytes_written < 0) {
        perror("Error writing to sysfs timer");
    }
}

// Function to read from the sysfs timer
int read_from_sysfs(char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(timer_fd, buffer, buffer_size);
    if (bytes_read < 0) {
        perror("Error reading from sysfs timer");
        return -1;
    }
    return bytes_read;
}

// Function to read acceleration data from MPU6050
int read_accel_data(float *x, float *y, float *z) {
    uint8_t data[6];
    if (read(i2c_fd, data, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    int16_t raw_x = (data[0] << 8) | data[1];
    int16_t raw_y = (data[2] << 8) | data[3];
    int16_t raw_z = (data[4] << 8) | data[5];

    *x = (float)raw_x / G_PER_LSB;
    *y = (float)raw_y / G_PER_LSB;
    *z = (float)raw_z / G_PER_LSB;

    return 0;
}

// Function to log data to the circular buffer
void log_data(float x, float y, float z) {
    accel_buffer[buffer_index].x = x;
    accel_buffer[buffer_index].y = y;
    accel_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (timer_fd != -1) {
        close(timer_fd);
    }
    if (sysfs_fd != -1) {
        close(sysfs_fd);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open sysfs timer
    if (open_sysfs_timer() != 0) {
        fprintf(stderr, "Failed to open sysfs timer. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    float x, y, z;
    while (running) {
        // Read acceleration data
        if (read_accel_data(&x, &y, &z) == 0) {
            // Log data to buffer
            log_data(x, y, z);

            // Prepare data for sysfs output
            char data[256];
            snprintf(data, sizeof(data), "X:%.2f Y:%.2f Z:%.2f", x, y, z);

            // Write to sysfs timer
            write_to_sysfs(data);

            // Read from sysfs timer (for debugging)
            char read_data[256];
            read_from_sysfs(read_data, sizeof(read_data));
            printf("Sysfs Output: %s\n", read_data);
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        // Wait for the next sample
        struct timespec req, rem;
        req.tv_sec = 0;
        req.tv_nsec = 1000000000 / SAMPLE_RATE; // 10ms = 100Hz
        nanosleep(&req, &rem);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

