    *y = (float)raw_y / G_PER_LSB;
    *z = (float)raw_z / G_PER_LSB;

    return 0;
}

// Function to log data to the circular buffer
void log_data(float x, float y, float z) {
    accel_buffer[buffer_index].x = x;
    accel_buffer[buffer_index].y = y;
    accel_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (timer_fd != -1) {
        close(timer_fd);
    }
    if (sysfs_fd != -1) {
        close(sysfs_fd);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open sysfs timer
    if (open_sysfs_timer() != 0) {
        fprintf(stderr, "Failed to open sysfs timer. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    float x, y, z;
    while (running) {
        // Read acceleration data
        if (read_accel_data(&x, &y, &z) == 0) {
            // Log data to buffer
            log_data(x, y, z);

            // Prepare data for sysfs output
            char data[256];
            snprintf(data, sizeof(data), "X:%.2f Y:%.2f Z:%.2f", x, y, z);

            // Write to sysfs timer
            write_to_sysfs(data);

            // Read from sysfs timer (for debugging)
            char read_data[256];
            read_from_sysfs(read_data, sizeof(read_data));
            printf("Sysfs Output: %s\n", read_data);
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        // Wait for the next sample
        struct timespec req, rem;
        req.tv_sec = 0;
        req.tv_nsec = 1000000000 / SAMPLE_RATE; // 10ms = 100Hz
        nanosleep(&req, &rem);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

