#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 100

// Define cooldown time (in milliseconds)
#define COOLDOWN_TIME 500

// Global variables
static volatile int running = 1;
static volatile unsigned long last_activation_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void deactivate_relay();
void log_alarm();
void cleanup_gpio();
void signal_handler(int signal);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sound sensor
        int sound_detected = read_sound_sensor();

        // Check if sound is detected and relay is not active
        if (sound_detected && !gpioRead(RELAY_PIN)) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Activate relay
            activate_relay();

            // Log alarm
            log_alarm();

            // Debounce and cooldown
            gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds
            last_activation_time = gpioTick(); // Record the time the relay was activated
            gpioDelay(COOLDOWN_TIME * 1000); // Convert milliseconds to microseconds
        }

        // Poll at 100 ms interval
        gpioDelay(100 * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup GPIO and exit
    cleanup_gpio();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set sound sensor pin as input
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Ensure relay is initially off
    deactivate_relay();

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate relay
void activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Set relay pin HIGH
    printf("Relay activated!\n");
}

// Deactivate relay
void deactivate_relay() {
    gpioWrite(RELAY_PIN, 0); // Set relay pin LOW
    printf("Relay deactivated!\n");
}

// Log alarm to file
void log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing!\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s: Sound detected and alarm triggered\n", timestamp);
    fclose(fp);
}

// Cleanup GPIO
void cleanup_gpio() {
    deactivate_relay(); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0; // Set running to 0 to exit the main loop
    printf("Signal received (%d). Shutting down...\n", signal);
}

