#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <time.h>

// Configuration
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi
#define MPU6050_ADDR 0x68      // MPU6050 I2C address
#define GYRO_SENSITIVITY 131.0 // LSB/(deg/s) for +-250 dps range
#define SAMPLE_RATE 100       // Samples per second
#define BUFFER_SIZE (SAMPLE_RATE * 6) // 6 bytes per sample
#define THRESHOLD 50.0         // Threshold for angular velocity magnitude

// Gyroscope registers
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75

// Data structure for gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t gyro_buffer;
bool running = true;

// Function prototypes
int init_i2c(const char *bus);
int init_mpu6050(int fd);
gyro_data_t read_gyro_data(int fd);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
double calculate_magnitude(gyro_data_t data);
void callback_function(double magnitude);
void signal_handler(int signal);

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Initialize MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (clear sleep bit in PWR_MGMT_1)
    uint8_t wake_up_data[2] = {0x6B, 0x00};
    if (write(fd, wake_up_data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i_data[1] = {0x75};
    if (read(fd, who_am_i_data, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i_data[0] != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i_data[0]);
        return -1;
    }

    printf("MPU6050 initialized successfully\n");
    return 0;
}

// Read gyroscope data from MPU6050
gyro_data_t read_gyro_data(int fd) {
    gyro_data_t data;
    uint8_t gyro_data[6];

    // Read all 6 bytes of gyroscope data at once
    if (read(fd, gyro_data, 6) != 6) {
        perror("Error reading gyroscope data");
        data.x = 0; data.y = 0; data.z = 0; // Return 0s on error
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((gyro_data[0] << 8) | gyro_data[1]);
    data.y = (int16_t)((gyro_data[2] << 8) | gyro_data[3]);
    data.z = (int16_t)((gyro_data[4] << 8) | gyro_data[5]);

    return data;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate the magnitude of the angular velocity vector
double calculate_magnitude(gyro_data_t data) {
    double x = (double)data.x / GYRO_SENSITIVITY;
    double y = (double)data.y / GYRO_SENSITIVITY;
    double z = (double)data.z / GYRO_SENSITIVITY;
    return sqrt(x * x + y * y + z * z);
}

// Callback function to be triggered when the threshold is exceeded
void callback_function(double magnitude) {
    printf("Threshold exceeded! Magnitude: %.2f deg/s\n", magnitude);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Initialize I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read gyroscope data
        gyro_data_t gyro_data = read_gyro_data(i2c_fd);

        // Add data to circular buffer
        add_to_buffer(&gyro_buffer, gyro_data);

        // Calculate magnitude
        double magnitude = calculate_magnitude(gyro_data);

        // Check if threshold is exceeded
        if (magnitude > THRESHOLD) {
            callback_function(magnitude);
        }

        // Delay to achieve desired sample rate
        usleep(1000000 / SAMPLE_RATE); // microseconds
    }

    // Clean up
    close(i2c_fd);

    return 0;
}

