#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define MAX_RETRIES 3
#define TIMEOUT_US 1000000 // 1 second

// Global variables for signal handling
static volatile int running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int ppm;
    bool error;
} SensorData;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_mh_z19b(int uart_fd, int *ppm, bool *error);
int validate_checksum(unsigned char *data, int length);
int log_data(int ppm, bool error);
void signal_handler(int signal);
void log_error(const char *message);

// Function to initialize the UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = serOpen(device, baud_rate, 0); // 0 for default flags
    if (fd < 0) {
        fprintf(stderr, "Error opening UART: %s\n", device);
        return -1;
    }
    return fd;
}

// Function to read data from the MH-Z19B sensor
int read_mh_z19b(int uart_fd, int *ppm, bool *error) {
    unsigned char command[9] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char response[9];
    int retries = 0;
    int bytes_read = 0;
    int i;

    while (retries < MAX_RETRIES) {
        // Send the read command
        if (serWrite(uart_fd, command, 9) != 9) {
            log_error("Failed to send read command");
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Wait for data to be available
        while (serDataAvailable(uart_fd) < 9) {
            gpioDelay(1); // Wait 1ms
            if (running == 0) return -1; // Check for signal
        }

        // Read the response
        for (i = 0; i < 9; i++) {
            response[i] = serReadByte(uart_fd);
            if (response[i] < 0) {
                log_error("Failed to read byte from UART");
                *error = true;
                return -1;
            }
        }

        // Validate checksum
        if (validate_checksum(response, 8) != 0) {
            log_error("Checksum validation failed");
            *error = true;
            return -1;
        }

        // Extract CO2 value
        *ppm = (response[2] << 8) | response[3];
        *error = false;
        return 0; // Success
    }

    log_error("Failed to read CO2 after multiple retries");
    *error = true;
    return -1; // Failure after retries
}

// Function to validate the checksum
int validate_checksum(unsigned char *data, int length) {
    unsigned char checksum = 0;
    for (int i = 1; i < length; i++) {
        checksum += data[i];
    }
    unsigned char calculated_checksum = 0xFF - checksum + 1;
    return (calculated_checksum != data[length]);
}

// Function to log the data to a JSON file
int log_data(int ppm, bool error) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char json_string[200];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"ppm\": %d, \"error\": %s}\n",
             timestamp, ppm, error ? "true" : "false");

    if (log_file == NULL) {
        log_file = fopen(CO2_LOG_FILE, "a");
        if (log_file == NULL) {
            log_error("Failed to open log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s", json_string) < 0) {
        log_error("Failed to write to log file");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s - ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    int ppm;
    bool error;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        result = read_mh_z19b(uart_fd, &ppm, &error);
        if (result == 0) {
            log_data(ppm, error);
            printf("%d ppm\n", ppm);
        } else {
            log_error("Failed to read CO2");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Clean up
    serClose(uart_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

