#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L Registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03

// GPIO pin for output
#define OUTPUT_GPIO 17

// Hard-iron offsets
#define HARD_IRON_X 100
#define HARD_IRON_Y -50

// Target heading
#define TARGET_HEADING 90.0

// Circular buffer size
#define BUFFER_SIZE 100

// I2C retry settings
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int configure_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float compensate_heading(int16_t x, int16_t y);
void control_gpio(float heading);
void add_to_buffer(float heading);
float get_from_buffer(int index);
void signal_handler(int signal);

// Function to configure the HMC5883L
int configure_hmc5883l() {
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70);
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing to CONFIG_A (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to configure HMC5883L after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20);
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing to CONFIG_B (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to configure HMC5883L after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00);
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing to MODE (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to configure HMC5883L after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        status = i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, 6);
        if (status == 6) break; // Success
        fprintf(stderr, "Error reading magnetometer data (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read magnetometer data after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Function to compensate heading
float compensate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to control GPIO
void control_gpio(float heading) {
    float diff = heading - TARGET_HEADING;
    if (fabs(diff) > 10.0) {
        gpioWrite(OUTPUT_GPIO, 1); // High
    } else {
        gpioWrite(OUTPUT_GPIO, 0); // Low
    }
}

// Function to add data to the circular buffer
void add_to_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get data from the circular buffer
float get_from_buffer(int index) {
    return heading_buffer[index];
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure HMC5883L
    if (configure_hmc5883l() != 0) {
        fprintf(stderr, "HMC5883L configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode
    gpioSetMode(OUTPUT_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Compensate heading
            heading = compensate_heading(x, y);

            // Control GPIO
            control_gpio(heading);

            // Add to buffer
            add_to_buffer(heading);

            // Print heading
            printf("Heading: %.2f\n", heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

