#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds
#define LUX_THRESHOLD_RED 50
#define LUX_THRESHOLD_GREEN 150
#define LUX_THRESHOLD_BLUE 300

// Define BH1750 continuous high-resolution mode
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
float read_lux();
void control_relays(float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_RELAY_PIN, PI_OUTPUT);

    gpioWrite(RED_RELAY_PIN, 0); // Ensure relays are off initially
    gpioWrite(GREEN_RELAY_PIN, 0);
    gpioWrite(BLUE_RELAY_PIN, 0);

    return 0;
}

// Initialize I2C bus
int initialize_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    unsigned char buf[2];
    int bytes_read;

    // Send start measurement command
    unsigned char command[1] = {BH1750_CONTINUOUS_HIGH_RES_MODE};
    if (write(i2c_fd, command, 1) != 1) {
        perror("Error writing to I2C device");
        return -1.0;
    }

    // Wait for measurement to complete (at least 120ms)
    gpioDelay(150); // Delay in microseconds

    // Read 2 bytes of data
    bytes_read = read(i2c_fd, buf, 2);
    if (bytes_read != 2) {
        perror("Error reading from I2C device");
        return -1.0;
    }

    // Convert data to lux value
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Control relays based on lux value
void control_relays(float lux) {
    int red_state = 0;
    int green_state = 0;
    int blue_state = 0;

    if (lux < LUX_THRESHOLD_RED) {
        red_state = 1;
    }
    if (lux >= LUX_THRESHOLD_RED && lux < LUX_THRESHOLD_GREEN) {
        green_state = 1;
    }
    if (lux >= LUX_THRESHOLD_GREEN && lux < LUX_THRESHOLD_BLUE) {
        blue_state = 1;
    }
    if (lux >= LUX_THRESHOLD_BLUE) {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    gpioWrite(RED_RELAY_PIN, red_state);
    gpioWrite(GREEN_RELAY_PIN, green_state);
    gpioWrite(BLUE_RELAY_PIN, blue_state);
}

// Log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off relays
    gpioWrite(RED_RELAY_PIN, 0);
    gpioWrite(GREEN_RELAY_PIN, 0);
    gpioWrite(BLUE_RELAY_PIN, 0);

    // Close I2C bus
    if (i2c_fd > 0) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            control_relays(lux);
            log_data(lux, gpioRead(RED_RELAY_PIN), gpioRead(GREEN_RELAY_PIN), gpioRead(BLUE_RELAY_PIN));
        } else {
            fprintf(stderr, "Error reading lux value. Retrying...\n");
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

