    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            control_relays(lux);
            log_data(lux, gpioRead(RED_RELAY_PIN), gpioRead(GREEN_RELAY_PIN), gpioRead(BLUE_RELAY_PIN));
        } else {
            fprintf(stderr, "Error reading lux value. Retrying...\n");
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

