#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the stepper motor
#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22

// Define GPIO pins for the buttons
#define BUTTON_LOCK 24
#define BUTTON_UNLOCK 23

// Define the number of steps for a quarter turn
#define STEPS_PER_QUARTER_TURN 512

// Define the delay between steps (in milliseconds)
#define STEP_DELAY 2

// Global variable to track the current lock state
volatile int lock_state = 0; // 0 = unlocked, 1 = locked

// Function prototypes
void step_forward();
void step_backward();
void rotate_steps(int steps, int direction);
void lock_door();
void unlock_door();
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to step the motor forward
void step_forward() {
    gpioWrite(IN1, 1);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY * 1000); // Delay in microseconds
}

// Function to step the motor backward
void step_backward() {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 1);
    gpioDelay(STEP_DELAY * 1000); // Delay in microseconds
}

// Function to rotate the motor a specified number of steps in a given direction
void rotate_steps(int steps, int direction) {
    if (direction == 1) { // Clockwise (forward)
        for (int i = 0; i < steps; i++) {
            step_forward();
        }
    } else { // Counter-clockwise (backward)
        for (int i = 0; i < steps; i++) {
            step_backward();
        }
    }
}

// Function to lock the door
void lock_door() {
    if (lock_state == 0) {
        printf("Locking door...\n");
        rotate_steps(STEPS_PER_QUARTER_TURN, 1); // Rotate clockwise
        lock_state = 1;
    } else {
        printf("Door already locked.\n");
    }
}

// Function to unlock the door
void unlock_door() {
    if (lock_state == 1) {
        printf("Unlocking door...\n");
        rotate_steps(STEPS_PER_QUARTER_TURN, -1); // Rotate counter-clockwise
        lock_state = 0;
    } else {
        printf("Door already unlocked.\n");
    }
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    if (gpio == BUTTON_LOCK) {
        if (level == 0) { // Button is pressed (active-low)
            lock_door();
        }
    } else if (gpio == BUTTON_UNLOCK) {
        if (level == 0) { // Button is pressed (active-low)
            unlock_door();
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);

    gpioSetMode(BUTTON_LOCK, PI_INPUT);
    gpioSetMode(BUTTON_UNLOCK, PI_INPUT);

    // Set pull-up resistors (internal pull-ups are active-low)
    gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP);

    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register the callback function for button presses
    gpioSetAlertFunc(BUTTON_LOCK, button_callback);
    gpioSetAlertFunc(BUTTON_UNLOCK, button_callback);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running until a signal is received)
    while (1) {
        gpioDelay(100000); // Sleep for 0.1 seconds to reduce CPU usage
    }

    return 0;
}

