#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_DIR 1
#define PWM_PERIOD 1000000 // 1 kHz
#define PWM_DUTY_CYCLE 500000 // 50% duty cycle
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_pigpio();
int init_pwm();
int init_logging();
int read_mpu6050(float *pitch, float *roll);
void set_servo_angle(float angle);
void log_data(float pitch, float roll, float servo_angle);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// I2C initialization
int init_i2c() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            perror("Error opening I2C bus");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Error setting I2C slave address");
            close(i2c_fd);
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Wake up the MPU-6050
        uint8_t data[2] = {PWR_MGMT_1, 0x00};
        if (write(i2c_fd, data, 2) != 2) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0; // Success
    }
    fprintf(stderr, "Failed to initialize I2C after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// pigpio initialization
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// PWM initialization
int init_pwm() {
    int fd = open("/sys/class/pwm/pwmchip2/pwm0", O_WRONLY);
    if (fd < 0) {
        perror("Error opening PWM device");
        return -1;
    }

    // Enable PWM
    if (write(fd, "enable", 6) != 6) {
        perror("Error enabling PWM");
        close(fd);
        return -1;
    }

    // Set PWM direction
    if (write(fd, "dir", 3) != 3) {
        perror("Error setting PWM direction");
        close(fd);
        return -1;
    }

    // Set PWM period
    char period_str[20];
    snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD);
    if (write(fd, period_str, strlen(period_str)) != strlen(period_str)) {
        perror("Error setting PWM period");
        close(fd);
        return -1;
    }

    // Set PWM duty cycle
    char duty_cycle_str[20];
    snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", PWM_DUTY_CYCLE);
    if (write(fd, duty_cycle_str, strlen(duty_cycle_str)) != strlen(duty_cycle_str)) {
        perror("Error setting PWM duty cycle");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Logging initialization
int init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

// MPU-6050 reading
int read_mpu6050(float *pitch, float *roll) {
    uint8_t data[14];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(i2c_fd, data, 14) != 14) {
            perror("Error reading from I2C device");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Combine high and low bytes for accelerometer data
        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];

        // Combine high and low bytes for gyroscope data
        int16_t gyro_x = (data[8] << 8) | data[9];
        int16_t gyro_y = (data[10] << 8) | data[11];
        int16_t gyro_z = (data[12] << 8) | data[13];

        // Convert accelerometer data to pitch and roll (assuming +/- 2g range)
        *pitch = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
        *roll = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;

        return 0; // Success
    }
    fprintf(stderr, "Failed to read MPU-6050 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Servo control
void set_servo_angle(float angle) {
    // Map angle (0-180) to PWM duty cycle (0-PWM_PERIOD)
    int duty_cycle = (int)(PWM_PERIOD * angle / 180.0);
    char duty_cycle_str[20];
    snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", duty_cycle);
    int fd = open("/sys/class/pwm/pwmchip2/pwm0/duty_cycle", O_WRONLY);
    if (fd < 0) {
        perror("Error opening duty_cycle file");
        return;
    }
    if (write(fd, duty_cycle_str, strlen(duty_cycle_str)) != strlen(duty_cycle_str)) {
        perror("Error setting PWM duty cycle");
    }
    close(fd);
}

// Data logging
void log_data(float pitch, float roll, float servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, pitch, roll, servo_angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(SERVO_PIN, 0); // Stop PWM
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize resources
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    if (init_pigpio() != 0) {
        fprintf(stderr, "pigpio initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    if (init_pwm() != 0) {
        fprintf(stderr, "PWM initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    if (init_logging() != 0) {
        fprintf(stderr, "Logging initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    float pitch, roll;
    float servo_angle;

    // Main loop
    while (program_running) {
