        return 1;
    }

    if (init_pigpio() != 0) {
        fprintf(stderr, "pigpio initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    if (init_pwm() != 0) {
        fprintf(stderr, "PWM initialization failed. Exiting.\n");
        cleanup();
