#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    time_t time;
    int relay_number;
    int state; // 0 = off, 1 = on
} schedule_entry_t;

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *schedule_file = NULL;
schedule_entry_t *schedule = NULL;
int schedule_size = 0;

// Function prototypes
void signal_handler(int signal);
int read_schedule(const char *filename, schedule_entry_t **schedule, int *schedule_size);
int parse_schedule(const char *filename, schedule_entry_t **schedule, int *schedule_size);
void fade_lamp(int relay_number, int state);
void turn_off_all_lamps();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    turn_off_all_lamps();
    cleanup();
    exit(0);
}

// Function to read the schedule from the file
int read_schedule(const char *filename, schedule_entry_t **schedule, int *schedule_size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    *schedule_size = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        (*schedule_size)++;
    }

    rewind(fp);
    *schedule = (schedule_entry_t *)malloc(*schedule_size * sizeof(schedule_entry_t));
    if (*schedule == NULL) {
        perror("Error allocating memory for schedule");
        fclose(fp);
        return -1;
    }

    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%*[^:]:%*[^:]:%*[^:]:%d,%d,%d",
                   NULL, NULL, NULL, &((*schedule)[i].time), &((*schedule)[i].relay_number), &((*schedule)[i].state)) == 3) {
            i++;
        } else {
            fprintf(stderr, "Error parsing line: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

// Function to parse the schedule from the file
int parse_schedule(const char *filename, schedule_entry_t **schedule, int *schedule_size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    *schedule_size = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        (*schedule_size)++;
    }

    rewind(fp);
    *schedule = (schedule_entry_t *)malloc(*schedule_size * sizeof(schedule_entry_t));
    if (*schedule == NULL) {
        perror("Error allocating memory for schedule");
        fclose(fp);
        return -1;
    }

    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%*[^:]:%*[^:]:%*[^:]:%d,%d,%d",
                   NULL, NULL, NULL, &((*schedule)[i].time), &((*schedule)[i].relay_number), &((*schedule)[i].state)) == 3) {
            i++;
        } else {
            fprintf(stderr, "Error parsing line: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

// Function to fade the lamp brightness
void fade_lamp(int relay_number, int state) {
    time_t now = time(NULL);
    int i;

    for (i = 0; i < schedule_size; i++) {
        if (now == schedule[i].time) {
            // Transition to the new state
            if (state != schedule[i].state) {
                int duty_cycle = 0;
                if (state == 1) {
                    duty_cycle = 100;
                }
                gpioPWM(relay_number, duty_cycle);
                schedule[i].state = state;
                return;
            }
            break; // Exit the loop if the time matches
        }
    }

    // Find the closest schedule entry
    int closest_index = 0;
    long long time_diff = difftime(now, schedule[0].time);

    for (i = 1; i < schedule_size; i++) {
        long long time_diff_current = difftime(now, schedule[i].time);
        if (time_diff_current < 0) {
            time_diff_current += 86400; // Handle time wrap-around
        }
        if (time_diff_current < time_diff) {
            time_diff = time_diff_current;
            closest_index = i;
        }
    }

    // Fade in or out
    if (state != schedule[closest_index].state) {
        int duty_cycle = 0;
        if (state == 1) {
            duty_cycle = 100;
        }
        int start_duty_cycle = (state == 1) ? 0 : 100;
        int end_duty_cycle = (state == 1) ? 100 : 0;

        for (int j = 0; j < 1800; j++) {
            int progress = j * 100 / 1800;
            int current_duty_cycle = start_duty_cycle + (int)(((float)(j) / 1800.0) * (end_duty_cycle - start_duty_cycle));
            gpioPWM(relay_number, current_duty_cycle);
            gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 100ms (100Hz)
        }
    }
}

// Function to turn off all lamps
void turn_off_all_lamps() {
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);
}

// Function to cleanup resources
void cleanup() {
    if (schedule != NULL) {
        free(schedule);
    }
    if (schedule_file != NULL) {
        fclose(schedule_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Set initial relay states to off
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Read the schedule from the file
    if (read_schedule(SCHEDULE_FILE, &schedule, &schedule_size) != 0) {
        fprintf(stderr, "Failed to read schedule. Exiting.\n");
        turn_off_all_lamps();
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        time_t now = time(NULL);
        int i;

        // Check if the current time matches an entry in the schedule
        for (i = 0; i < schedule_size; i++) {
            if (difftime(now, schedule[i].time) == 0) {
                fade_lamp(schedule[i].relay_number, schedule[i].state);
                break;
            }
        }

        gpioDelay(1000000); // Check every second
    }

    // Cleanup and exit
    turn_off_all_lamps();
    cleanup();
    return 0;
}

