#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 30.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds

// Global variables
volatile int echo_start = 0;
volatile int echo_end = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float getDistance();
int mapDistanceToFrequency(float distance);
void setBuzzerFrequency(int frequency);
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Shutting down...\n");
        setBuzzerFrequency(0); // Silence the buzzer
        gpioTerminate();       // Terminate pigpio
        exit(0);
    }
