float getDistance() {
    triggerSensor();

    echo_start = gpioTick();
    echo_received = 0; // Reset flag

    long pulseWidth = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

    if (pulseWidth > 0) {
        echo_end = gpioTick();
        echo_received = 1; // Set flag to indicate successful reading
    } else {
        fprintf(stderr, "Error: Timeout waiting for echo.\n");
        return -1.0; // Indicate error
    }

    if (echo_received) {
        long duration = echo_end - echo_start;
        float distance = (duration * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2
        return distance;
    } else {
        return -1.0; // Indicate error
    }
}

// Function to map distance to frequency
int mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
        return (int)frequency;
    }
}

// Function to set the buzzer frequency
void setBuzzerFrequency(int frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(BUZZER_PIN, frequency);
        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
    } else {
        gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range for buzzer
    gpioSetPWMrange(BUZZER_PIN, 200); // Set PWM range to 200 for finer control

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (1) {
        float distance = getDistance();

        if (distance > 0) {
            int frequency = mapDistanceToFrequency(distance);
            setBuzzerFrequency(frequency);
            printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);
        } else {
            fprintf(stderr, "Error: Invalid distance reading.\n");
        }

        gpioDelay(60000); // Wait 60 ms
    }

    return 0;
}

