#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor
#define GYRO_SCALE 131.0f

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_open(const char *device);
int i2c_write(int fd, uint8_t reg, uint8_t value);
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_close(int fd);
int mpu6050_init(int fd);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float convert_to_dps(int16_t raw_data);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2];
    data[0] = reg;
    data[1] = value;
    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address to I2C device");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// MPU-6050 initialization function
int mpu6050_init(int fd) {
    if (i2c_write(fd, PWR_MGMT_1, 0x00) < 0) { // Wake up the sensor
        fprintf(stderr, "Error initializing MPU-6050\n");
        return -1;
    }
    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (i2c_read(fd, GYRO_XOUT_H, data, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Convert raw data to degrees per second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / GYRO_SCALE;
}

// Log data to file function
void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open("/dev/i2c-1");
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init(i2c_fd) < 0) {
        i2c_close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2c_close(i2c_fd);
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float x_dps, y_dps, z_dps;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            x_dps = convert_to_dps(raw_x);
            y_dps = convert_to_dps(raw_y);
            z_dps = convert_to_dps(raw_z);

            // Log data
            log_data(x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        // Wait 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device and log file
    i2c_close(i2c_fd);
    fclose(log_file);

    return 0;
}

