// Define GPIO pins
#define BUTTON_GPIO 17
#define BUZZER_GPIO 18

// Define melody notes (frequency, duration in ms)
const unsigned int melody[] = {
    {440, 200}, {494, 200}, {523, 200}, {587, 200}, {659, 200}, {698, 200}, {784, 200}, {880, 200},
    {988, 200}, {1047, 200}, {0, 200} // Rest
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int playing = 0;
volatile unsigned int last_interrupt_time = 0;

// Function prototypes
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Interrupt handler function
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned int current_time = gpioTick();
    if (current_time - last_interrupt_time > 50000) { // Debounce: 50ms
        last_interrupt_time = current_time;

        if (!playing) {
            play_melody();
        } else {
            stop_melody();
        }
    }
}

// Function to play the melody
void play_melody() {
    playing = 1;
    int note_index = 0;
    while (playing && note_index < melody_length) {
        if (gpioHardwarePWM(BUZZER_GPIO, melody[note_index].first, 128) < 0) {
            fprintf(stderr, "Error setting PWM: %d\n", gpioHardwarePWM(BUZZER_GPIO, melody[note_index].first, 128));
            break;
        }
        gpioDelay(melody[note_index].second * 1000); // Convert ms to us
        note_index++;
    }
    stop_melody();
}

// Function to stop the melody
void stop_melody() {
    playing = 0;
    gpioHardwarePWM(BUZZER_GPIO, 0, 0); // Stop PWM
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d to input\n", BUTTON_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d to output\n", BUZZER_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistor on BUTTON_GPIO
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set interrupt handler for falling edge detection
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO%d\n", BUTTON_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell is ready. Press the button (GPIO%d) to play the melody.\n", BUTTON_GPIO);

    // Main loop
    while (1) {
        gpioDelay(100000); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

