#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/time.h>

#define GPIO_PIN 17
#define DEFAULT_TIMEOUT_MS 1000
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3

// Structure to hold the last 5 events
typedef struct {
    int events[WINDOW_SIZE];
    int count;
} EventWindow;

// Global variables
static volatile sig_atomic_t keep_running = 1;
static int timeout_ms = DEFAULT_TIMEOUT_MS;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static EventWindow event_window;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int log_event(int value);
void earthquake_alert(int value);
void signal_handler(int sig);
int setup();
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        keep_running = 0;
        fprintf(stderr, "Signal received, exiting gracefully.\n");
    }
}

// Read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_event_read(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Log event to file
int log_event(int value) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[30];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03dZ", (int)(tv.tv_usec / 1000));

    if (log_file != NULL) {
        fprintf(log_file, "%s %d\n", timestamp, value);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

// Earthquake alert simulation
void earthquake_alert(int value) {
    static int alert_count = 0;
    static time_t last_alert_time = 0;
    time_t current_time = time(NULL);

    if (value == 1) {
        alert_count++;
        if (alert_count >= EARTHQUAKE_THRESHOLD) {
            if (difftime(current_time, last_alert_time) >= 1.0) { // Check for at least 1 second
                printf("EARTHQUAKE ALERT!\n");
                last_alert_time = current_time;
            }
        }
    } else {
        alert_count = 0;
    }
}

// Setup GPIO line
int setup() {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request line as input
    ret = gpiod_line_request_input(line, "vibration_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting line as input: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    // Initialize event window
    event_window.count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        event_window.events[i] = 0;
    }

    return 0;
}

// Cleanup GPIO line and chip
void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    struct gpiod_line_event *event;
    int value;
    int ret;

    // Parse command-line arguments
    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize log file
    log_file = fopen("vibration_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Setup GPIO line
    if (setup() != 0) {
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Wait for event with timeout
        ret = gpiod_line_event_wait(line, timeout_ms * 1000); // Convert ms to microseconds
        if (ret < 0) {
            fprintf(stderr, "Error waiting for event: %s\n", strerror(-ret));
            break; // Exit loop on error
        }

        // Read sensor value
        value = read_sensor(line);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        // Log event
        if (log_event(value) != 0) {
            fprintf(stderr, "Error logging event, exiting.\n");
            break;
        }

        // Earthquake alert simulation
        earthquake_alert(value);

        // Update event window
        event_window.events[event_window.count % WINDOW_SIZE] = value;
        event_window.count++;

        // Consume the event
        event = gpiod_line_event_read(line);
        if (event == NULL) {
            fprintf(stderr, "Error reading event, exiting.\n");
            break;
        }
        gpiod_line_event_release(event);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

