#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define MAGNETOMETER_ADDRESS 0x1E
#define MAGNETOMETER_REG_X_MSB 0x03
#define MAGNETOMETER_REG_X_LSB 0x04
#define MAGNETOMETER_REG_Z_MSB 0x05
#define MAGNETOMETER_REG_Z_LSB 0x06
#define MAGNETOMETER_REG_Y_MSB 0x07
#define MAGNETOMETER_REG_Y_LSB 0x08
#define MAGNETOMETER_MODE_CONTINUOUS 0x00
#define MAGNETOMETER_DATA_RATE_15HZ 0x14
#define HARD_IRON_X_OFFSET 10
#define HARD_IRON_Y_OFFSET -5
#define HARD_IRON_Z_OFFSET 20
#define CALIBRATION_FILE "calibration.dat"
#define LOG_FILE "mag_log.csv"
#define NUM_DIRECTIONS 8

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold calibration data
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
} calibration_data_t;

calibration_data_t calibration = {HARD_IRON_X_OFFSET, HARD_IRON_Y_OFFSET, HARD_IRON_Z_OFFSET};

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z);
float calculate_heading(float x, float y);
char* get_compass_direction(float heading);
int log_data(FILE *fp, float x, float y, float z, float heading, char* direction);
void signal_handler(int signal);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (len == 0) return 0; // Nothing to read
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (i2c_read_bytes(fd, MAGNETOMETER_REG_X_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

