#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_MS 200

static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal)
{
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to toggle the relay state
int toggle_relay(int gpio, int *relay_state)
{
    int current_state = gpioRead(gpio);
    *relay_state = !current_state; // Toggle the state
    gpioWrite(gpio, *relay_state);
    return *relay_state;
}

// Function to log relay state to a JSON file
int log_relay_state(const char *filename, int relay_state)
{
    FILE *fp = fopen(filename, "a");
    if (fp == NULL)
    {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"\n", timestamp, relay_state ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetMode(TOUCH_GPIO, PI_INPUT);
    gpioSetPullUpDown(TOUCH_GPIO, PI_PUD_DOWN); // Enable pull-down resistor

    // Set up signal handling
    signal(SIGINT, signal_handler);

    int relay_state = 0; // Initial relay state (OFF)
    int last_relay_state = 0;

    // Set up ISR for touch sensor
    if (gpioSetISRFuncEx(TOUCH_GPIO, RISING_EDGE, 0, debounce_isr, NULL) != 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (running)
    {
        // Main loop
        gpioDelay(100); // Reduce CPU usage

        // Check for touch and debounce
        if (gpioRead(TOUCH_GPIO) == 1)
        {
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_MS * 1000) // Convert ms to microseconds
            {
                // Toggle relay state
                relay_state = toggle_relay(RELAY_GPIO, &relay_state);

                // Log relay state
                if (log_relay_state("relay_log.json", relay_state) != 0)
                {
                    fprintf(stderr, "Failed to log relay state\n");
                }

                last_touch_time = current_time;
            }
        }
    }

    // Cleanup before exiting
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    log_relay_state("relay_log.json", 0); // Log final state
    gpioTerminate();

    return 0;
}

// Debounce ISR function
void debounce_isr(int gpio, int level, unsigned int tick, void *user)
{
    // This function is called when the touch sensor is touched
    // It is called from the ISR, so it doesn't need to be reentrant
    unsigned long current_time = gpioTick();
    if (current_time - last_touch_time > DEBOUNCE_MS * 1000) // Convert ms to microseconds
    {
        toggle_relay(RELAY_GPIO, &last_relay_state);
        last_touch_time = current_time;
    }
}

