#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4];
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_moisture_level(void);
int control_relay(int relay_number, int state);
int log_event(int relay_number, int moisture_level, int state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig)
{
    if (sig == SIGINT || sig == SIGTERM)
    {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Initialize GPIO pins
int initialize_gpio(void)
{
    int i;
    struct gpiod_line_request_config config;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request lines for each relay
    for (i = 0; i < 4; i++)
    {
        lines[i] = gpiod_chip_get_line(chip, RELAY1_PIN + i);
        if (!lines[i])
        {
            perror("Error getting GPIO line");
            gpiod_chip_close(chip);
            return -1;
        }

        // Configure the line as output with active low
        memset(&config, 0, sizeof(config));
        config.consumer = "irrigation";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0; // Initial value 1 (inactive)

        if (gpiod_line_request(lines[i], &config, 0) < 0)
        {
            perror("Error requesting GPIO line");
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

// Read a simulated soil moisture level
int read_moisture_level(void)
{
    static int seed = 0;
    int moisture_level;

    // Seed the random number generator
    if (seed == 0)
    {
        srand(time(NULL));
        seed = 1; // Seed only once
    }

    // Generate a random number between 0 and 100
    moisture_level = rand() % 101;

    return moisture_level;
}

// Control a relay (activate or deactivate)
int control_relay(int relay_number, int state)
{
    int pin;

    if (relay_number < 1 || relay_number > 4)
    {
        fprintf(stderr, "Error: Invalid relay number: %d\n", relay_number);
        return -1;
    }

    pin = RELAY1_PIN + (relay_number - 1);

    // Set the GPIO line to the desired state
    if (gpiod_line_set_value(lines[relay_number - 1], state) < 0)
    {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Log an event to the log file
int log_event(int relay_number, int moisture_level, int state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write the log entry to the file
    if (fprintf(log_file, "%s - Relay %d - Moisture: %d - State: %s\n",
                timestamp, relay_number, moisture_level, state ? "ON" : "OFF") < 0)
    {
        perror("Error writing to log file");
        return -1;
    }

    // Flush the buffer to ensure the log entry is written immediately
    fflush(log_file);

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void)
{
    int i;

    // Deactivate all relays
    for (i = 0; i < 4; i++)
    {
        control_relay(i + 1, 1); // Deactivate (active low)
        gpiod_line_release(lines[i]);
    }

    // Close the GPIO chip
    if (chip)
    {
        gpiod_chip_close(chip);
    }

    // Close the log file
    if (log_file)
    {
        fclose(log_file);
    }
}

int main(void)
{
    int moisture_level, i;

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0)
    {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file)
    {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate)
    {
        // Read the simulated soil moisture level
        moisture_level = read_moisture_level();

        // Log the moisture level
        if (moisture_level >= 0 && moisture_level <= 100)
        {
            if (log_event(0, moisture_level, 0) < 0) // Log moisture level
            {
                fprintf(stderr, "Error logging moisture level.\n");
            }
        } else {
            fprintf(stderr, "Invalid moisture level: %d\n", moisture_level);
        }

        // Check if the moisture level is below 30 and control relays
        if (moisture_level < 30)
        {
            for (i = 1; i <= 4; i++)
            {
                // Activate relay i
                if (control_relay(i, 0) < 0) // Activate relay (active low)
                {
                    fprintf(stderr, "Error activating relay %d.\n", i);
                } else {
                    // Log the relay activation
                    if (log_event(i, moisture_level, 0) < 0) {
                        fprintf(stderr, "Error logging relay activation.\n");
                    }
                    sleep(1); // Wait 1 second

                    // Deactivate relay i
                    if (control_relay(i, 1) < 0) // Deactivate relay (active low)
                    {
                        fprintf(stderr, "Error deactivating relay %d.\n", i);
                    } else {
                        // Log the relay deactivation
                        if (log_event(i, moisture_level, 1) < 0) {
                            fprintf(stderr, "Error logging relay deactivation.\n");
                        }
                    }
                }
            }
        }

        sleep(10); // Wait 10 seconds
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Program terminated.\n");
    return 0;
}

