#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Moisture thresholds
#define MOISTURE_THRESHOLD_LOW 50
#define MOISTURE_THRESHOLD_HIGH 50

// Servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Nozzle sweep angles
#define NOZZLE_ANGLE_0 0
#define NOZZLE_ANGLE_45 45
#define NOZZLE_ANGLE_90 90
#define NOZZLE_ANGLE_135 135
#define NOZZLE_ANGLE_180 180

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
volatile sig_atomic_t watering_cycle_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void set_servo_pulse_width(int gpio, int pulse_width);
int open_valve(int gpio);
int close_valve(int gpio);
int sweep_nozzle(int gpio, int start_angle, int end_angle, int step_size, int duration_ms);
int check_moisture_level(int moisture_level);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down gracefully...\n", signal);
        program_running = 0;
        watering_cycle_running = 0;
        set_servo_pulse_width(VALVE_SERVO_PIN, 0);
        set_servo_pulse_width(NOZZLE_SERVO_PIN, 0);
        cleanup_gpio();
        exit(0);
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(VALVE_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_SERVO_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Cleanup GPIO
void cleanup_gpio() {
    set_servo_pulse_width(VALVE_SERVO_PIN, 0);
    set_servo_pulse_width(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();
}

// Set servo pulse width
void set_servo_pulse_width(int gpio, int pulse_width) {
    int retries = 0;
    int result;

    while (retries < 3) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return; // Success
        } else {
            fprintf(stderr, "Error setting servo pulse width for GPIO %d: %d. Retrying...\n", gpio, result);
            gpioDelay(100 * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Failed to set servo pulse width for GPIO %d after multiple retries.\n", gpio);
}

// Open the water valve
int open_valve(int gpio) {
    int pulse_width = 1500; // 90 degrees
    set_servo_pulse_width(gpio, pulse_width);
    return 0;
}

// Close the water valve
int close_valve(int gpio) {
    int pulse_width = 500; // 0 degrees
    set_servo_pulse_width(gpio, pulse_width);
    return 0;
}

// Sweep the nozzle through a series of angles
int sweep_nozzle(int gpio, int start_angle, int end_angle, int step_size, int duration_ms) {
    int angles[] = {start_angle, start_angle + step_size, start_angle + 2 * step_size, start_angle + 3 * step_size, end_angle};
    int num_steps = 5; // Number of steps in the array

    for (int i = 0; i < num_steps; i++) {
        int angle = angles[i];
        int pulse_width = 1500 + (angle / 45) * 1000; // Map angle to pulse width (500-2500 us)
        set_servo_pulse_width(gpio, pulse_width);
        gpioDelay(duration_ms);
    }
    return 0;
}

// Check moisture level and determine watering action
int check_moisture_level(int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD_LOW) {
        return 1; // Water
    } else if (moisture_level >= MOISTURE_THRESHOLD_HIGH) {
        return 0; // Don't water
    } else {
        return 1; // Water (between thresholds)
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (program_running && watering_cycle_running) {
        // Simulate moisture readings
        int moisture_level = 20;
        moisture_level = (moisture_level + 1) % 5; // Cycle through 20, 40, 60, 80, 100

        printf("Moisture level: %d\n", moisture_level);

        // Check moisture level and perform watering action
        if (check_moisture_level(moisture_level)) {
            printf("Watering...\n");

            // Open the valve
            if (open_valve(VALVE_SERVO_PIN) != 0) {
                fprintf(stderr, "Failed to open valve. Critical error!\n");
                program_running = 0; // Stop the program
                break;
            }

            // Sweep the nozzle
            if (sweep_nozzle(NOZZLE_SERVO_PIN, NOZZLE_ANGLE_0, NOZZLE_ANGLE_180, 45, 200) != 0) {
                fprintf(stderr, "Failed to sweep nozzle. Error!\n");
                program_running = 0; // Stop the program
                break;
            }

            // Close the valve
            if (close_valve(VALVE_SERVO_PIN) != 0) {
                fprintf(stderr, "Failed to close valve. Critical error!\n");
                program_running = 0; // Stop the program
                break;
            }

            printf("Watering cycle complete.\n");
        }

        gpioDelay(5000); // Wait 5 seconds before next cycle
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Plant watering system stopped.\n");
    return 0;
}

