#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDRESS 0x68
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define GYRO_SENSITIVITY 131.0f // LSB/(deg/s) for ±250 deg/sec

// MPU-6050 Registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_setup(const char *bus, int address);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
void i2c_close(int fd);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function to initialize the I2C bus
int i2c_setup(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a single byte to a register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a single byte from a register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to read a block of data from the I2C device
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for block read");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to close the I2C device
void i2c_close(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

// Function to log data to a file
void log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to close I2C and file
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, GYRO_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Wake up the MPU-6050
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t gyro_data[6];
    gyro_data_t gyro_data_converted;

    while (program_running) {
        // Read gyroscope data
        if (i2c_read_block(i2c_fd, GYRO_XOUT_H, gyro_data, 6) < 0) {
            fprintf(stderr, "Failed to read gyroscope data. Retrying.\n");
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // Convert raw data to degrees/second
        int16_t raw_x = (gyro_data[0] << 8) | gyro_data[1];
        int16_t raw_y = (gyro_data[2] << 8) | gyro_data[3];
        int16_t raw_z = (gyro_data[4] << 8) | gyro_data[5];

        gyro_data_converted.x = (float)raw_x / GYRO_SENSITIVITY;
        gyro_data_converted.y = (float)raw_y / GYRO_SENSITIVITY;
        gyro_data_converted.z = (float)raw_z / GYRO_SENSITIVITY;

        // Log the data
        log_data(log_file, gyro_data_converted.x, gyro_data_converted.y, gyro_data_converted.z);

        // Delay to achieve desired sampling rate
        usleep(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

