#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 50000       // 50ms timeout
#define GATE_TIMEOUT_US 60000  // 60ms gate timeout

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
double measure_distance(void);
int log_distance(double distance);
void cleanup_gpio(void);
void signal_handler(int sig);
int gpio_get_value(struct gpiod_line *line, int *value);
int gpio_set_value(struct gpiod_line *line, int value);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully.\n");
}

// Initialize GPIO
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip, trigger_line);
        return -1;
    }

    // Request trigger line as output
    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip, trigger_line);
        gpiod_chip_close(chip, echo_line);
        return -1;
    }

    // Request echo line as input
    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip, trigger_line);
        gpiod_chip_close(chip, echo_line);
        return -1;
    }

    return 0;
}

// Measure distance using HC-SR04
double measure_distance(void) {
    struct timespec start, end;
    long long start_ns, end_ns, pulse_width_ns;
    int value;
    int timeout_count = 0;

    // Trigger the sensor
    if (gpio_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Error setting trigger high\n");
        return -1.0;
    }
    nanosleep(&(struct timespec){0, 10}, NULL); // 10 us trigger pulse
    if (gpio_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error setting trigger low\n");
        return -1.0;
    }

    // Wait for echo to go high
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
    timeout_count = 0;
    while (gpio_get_value(echo_line, &value) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        pulse_width_ns = end_ns - start_ns;
        if (pulse_width_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0;
        }
        timeout_count++;
        if (timeout_count > 1000) {
            fprintf(stderr, "Timeout waiting for echo high (1000 iterations)\n");
            return -1.0;
        }
    }

    // Measure pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
    timeout_count = 0;
    while (gpio_get_value(echo_line, &value) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        pulse_width_ns = end_ns - start_ns;
        if (pulse_width_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1.0;
        }
        timeout_count++;
        if (timeout_count > 1000) {
            fprintf(stderr, "Timeout waiting for echo low (1000 iterations)\n");
            return -1.0;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
    pulse_width_ns = end_ns - start_ns;

    // Calculate distance
    double distance = (double)pulse_width_ns * SPEED_OF_SOUND / 2.0;

    return distance;
}

// Log distance to file
int log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        perror("Log file not opened");
        return -1;
    }

    if (distance == -1.0) {
        fprintf(log_file, "%s, -1\n", timestamp);
        fprintf(stderr, "Error: Logging -1 to file.\n");
    } else {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int gpio_get_value(struct gpiod_line *line, int *value) {
    int ret = gpiod_line_get_value(line, value);
    if (ret < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return 0;
}

int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

int main(void) {
    double distance;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    printf("Starting distance measurements. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        distance = measure_distance();

        if (distance > 0) {
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            log_distance(-1.0);
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        // Wait 1 second
        sleep(1);
    }

    // Cleanup and exit
    printf("Cleaning up and exiting.\n");
    cleanup_gpio();
    fclose(log_file);
    return 0;
}

