#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pin for relay control
#define RELAY_PIN 18

// Distance threshold in cm
#define DISTANCE_THRESHOLD 50

// I2C handle
int i2c_handle;

// Function prototypes
int vl53l1x_reset(int i2c_handle);
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void control_relay(int gpio_pin, int state);
void signal_handler(int signal);

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0044
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to reset the VL53L1X sensor
int vl53l1x_reset(int i2c_handle) {
    char buf[2];
    buf[0] = 0x00; // Reset command
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error resetting VL53L1X: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms
    return 0;
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init(int i2c_handle) {
    char buf[2];
    // Recommended settings from the datasheet
    buf[0] = 0x01; // Ranging mode: short distance
    buf[1] = 0x00; // Intermeasurement period: 100ms
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error setting ranging mode: %d\n", result);
        return -1;
    }

    buf[0] = 0x01; // Start continuous ranging
    buf[1] = 0x00; // Intermeasurement period: 100ms
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting continuous ranging: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int i2c_handle) {
    char buf[1];
    char data[2];
    int result;

    // Read range status
    buf[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, data, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading range status from I2C: %d\n", result);
        return -1;
    }

    // Read distance
    buf[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading distance from I2C: %d\n", result);
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_relay(RELAY_PIN, 0); // Turn off relay
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Reset the sensor
    if (vl53l1x_reset(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X reset failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            if (distance <= DISTANCE_THRESHOLD * 10) { // Convert cm to mm
                control_relay(RELAY_PIN, 1); // Turn on relay
            } else {
                control_relay(RELAY_PIN, 0); // Turn off relay
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

