#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor
#define GYRO_SENSITIVITY 131.0

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the MPU-6050
int init_mpu6050(int i2c_handle) {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set gyroscope full-scale range to ±250 dps
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope full-scale range\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int i2c_handle, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw data to degrees/second
void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *dps_x, float *dps_y, float *dps_z) {
    *dps_x = (float)raw_x / GYRO_SENSITIVITY;
    *dps_y = (float)raw_y / GYRO_SENSITIVITY;
    *dps_z = (float)raw_z / GYRO_SENSITIVITY;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int16_t raw_x, raw_y, raw_z;
        float dps_x, dps_y, dps_z;

        // Read gyroscope data
        if (read_gyro_data(i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees/second
            convert_to_dps(raw_x, raw_y, raw_z, &dps_x, &dps_y, &dps_z);

            // Print the results
            printf("X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", dps_x, dps_y, dps_z);
        } else {
            fprintf(stderr, "Error: Failed to read or process gyroscope data\n");
        }

        // Delay for 100ms
        gpioDelay(100000);
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

