#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the log file name
#define LOG_FILE "smart_lighting.log"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize a GPIO pin as an output
int initialize_gpio(int gpio) {
    if (gpioSetMode(gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", gpio);
        return -1;
    }
    return 0;
}

// Function to set the PWM duty cycle for a relay
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to log an event to the log file
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Function to simulate the sunrise effect
int simulate_sunrise() {
    int duty_cycle = 0;
    int increment = 5; // Increment duty cycle by 5 each second
    int i;

    for (i = 0; i < 1800 && program_running; ++i) {
        // Calculate the duty cycle based on the elapsed time (in seconds)
        duty_cycle = (i % 600) / 120; // 600 seconds / 5 increments = 120 seconds per increment

        // Set the duty cycle for each relay
        if (set_pwm_duty_cycle(RELAY1_GPIO, duty_cycle) != 0) return -1;
        if (set_pwm_duty_cycle(RELAY2_GPIO, duty_cycle) != 0) return -1;
        if (set_pwm_duty_cycle(RELAY3_GPIO, duty_cycle) != 0) return -1;
        if (set_pwm_duty_cycle(RELAY4_GPIO, duty_cycle) != 0) return -1;

        // Log the event
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Sunrise: Duty cycle set to %d", duty_cycle);
        if (log_event(log_message) != 0) return -1;

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Ensure all relays are fully on at the end
    set_pwm_duty_cycle(RELAY1_GPIO, 255);
    set_pwm_duty_cycle(RELAY2_GPIO, 255);
    set_pwm_duty_cycle(RELAY3_GPIO, 255);
    set_pwm_duty_cycle(RELAY4_GPIO, 255);

    log_event("Sunrise complete. All relays fully on.");
    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize the GPIO pins
    if (initialize_gpio(RELAY1_GPIO) != 0 ||
        initialize_gpio(RELAY2_GPIO) != 0 ||
        initialize_gpio(RELAY3_GPIO) != 0 ||
        initialize_gpio(RELAY4_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency to 1 kHz
    if (gpioSetPWMfrequency(RELAY1_GPIO, 1000) != 0 ||
        gpioSetPWMfrequency(RELAY2_GPIO, 1000) != 0 ||
        gpioSetPWMfrequency(RELAY3_GPIO, 1000) != 0 ||
        gpioSetPWMfrequency(RELAY4_GPIO, 1000) != 0) {
        gpioTerminate();
        return 1;
    }

    // Simulate the sunrise effect
    if (simulate_sunrise() != 0) {
        gpioTerminate();
        return 1;
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

