int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *cb, float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *cb, float x, float y, float z) {
    cb->buffer[cb->head] = x;
    cb->buffer[(cb->head + 1) % BUFFER_SIZE] = y;
    cb->buffer[(cb->head + 2) % BUFFER_SIZE] = z;
    cb->head = (cb->head + 3) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to check if the threshold is exceeded
void check_threshold(float x, float y, float z) {
    if (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
