    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
}

// Initialize the MPU-6050 sensor
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the MPU-6050
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050. Retrying...\n");
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
