        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read Gyro Data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[12];
    uint8_t rx_buf[12];

    // Construct the transmit buffer (burst read)
    tx_buf[0] = GYRO_XOUT_H | 0x80; // MSB = 1 for burst read
    memset(tx_buf + 1, 0, 11); // Fill with dummy data for the remaining bytes

    if (spi_transfer(fd, tx_buf, rx_buf, 12) == -1) {
        return -1;
    }

    // Extract data
    *x = (int16_t)((rx_buf[1] << 8) | rx_buf[0]);
    *y = (int16_t)((rx_buf[3] << 8) | rx_buf[2]);
    *z = (int16_t)((rx_buf[5] << 8) | rx_buf[4]);

    return 0;
}

// Convert to Degrees per Second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / GYRO_SCALE;
}

// Log Data
int log_data(FILE *fp, float x_rate, float y_rate, float z_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    char timestamp[64];
    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        perror("fprintf");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Cleanup
void cleanup(int sig) {
    printf("Cleaning up...\n");
    terminate = 1;

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (chip != NULL) {
        gpiod_line_set_value(line, 1); // Deassert CS
        gpiod_line_release(line);
        gpiod_chip_close(chip);
    }

    if (log_fp != NULL) {
        fclose(log_fp);
    }

    exit(0);
}

// Signal Handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        cleanup(sig);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, 8); // GPIO8 is CE0
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "gyro", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpiod_line_request_output(line, "gyro", 0);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    float x_rate, y_rate, z_rate;
    int retries = 0;

    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_gyro_data(spi_fd, &raw_x, &raw_y, &raw_z) == 0) {
                x_rate = convert_to_dps(raw_x);
                y_rate = convert_to_dps(raw_y);
                z_rate = convert_to_dps(raw_z);

                if (log_data(log_fp, x_rate, y_rate, z_rate) != -1) {
                    printf("X: %.2f, Y: %.2f, Z: %.2f\n", x_rate, y_rate, z_rate);
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Error logging data. Retrying...\n");
                }
            } else {
                fprintf(stderr, "Error reading gyro data. Retrying...\n");
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read gyro data after %d retries. Continuing...\n", MAX_RETRIES);
        }

        usleep(10000); // 10 ms delay
    }

    cleanup(0);

    return 0;
}

