// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s
#define BUFFER_SIZE 64
#define LED_GPIO 17
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define THRESHOLD_DEGS_PER_SEC 200.0

// MPU-6050 Registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Global variables
int spi_handle;
int led_gpio;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int spi_init(int channel, int speed);
int spi_transfer(int handle, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int mpu6050_init(int handle);
int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z);
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps);
void add_to_buffer(float x_dps, float y_dps, float z_dps);
void print_buffer();
void signal_handler(int signal);
void led_blink(int gpio, int frequency, int range);
void cleanup();

// SPI initialization function
int spi_init(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", handle);
        return -1;
    }
    return handle;
}

// SPI transfer function
int spi_transfer(int handle, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int result = spiXfer(handle, tx_buf, rx_buf, len);
    if (result != len) {
        fprintf(stderr, "Error: spiXfer failed (%d)\n", result);
        return -1;
    }
    return 0;
}

// MPU-6050 initialization function
int mpu6050_init(int handle) {
    // Wake up the MPU-6050 (clear sleep bit)
    uint8_t wake_up = 0x00; // WAKE_UP bit
    if (spi_transfer(handle, (uint8_t *)&wake_up, (uint8_t *)&wake_up, 1) != 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050\n");
        return -1;
    }

    // Configure gyroscope sensitivity (optional, default is 131 LSB/deg/s)
    uint8_t gyro_config = 0x00; // Full scale range = +/- 250 deg/s
    if (spi_transfer(handle, (uint8_t *)&gyro_config, (uint8_t *)&gyro_config, 1) != 0) {
        fprintf(stderr, "Error: Failed to configure gyroscope sensitivity\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data function
int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[1];
    uint8_t rx_buf[2];

    // Read X axis data
    tx_buf[0] = GYRO_XOUT_H | 0x80; // MSB read bit
    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to read X axis data\n");
        return -1;
    }
    *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    // Read Y axis data
    tx_buf[0] = GYRO_YOUT_H | 0x80; // MSB read bit
    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to read Y axis data\n");
        return -1;
    }
    *y = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    // Read Z axis data
    tx_buf[0] = GYRO_ZOUT_H | 0x80; // MSB read bit
    if (spi_transfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to read Z axis data\n");
        return -1;
    }
    *z = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Convert raw data to degrees per second
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / GYRO_SENSITIVITY;
    *y_dps = (float)y / GYRO_SENSITIVITY;
    *z_dps = (float)z / GYRO_SENSITIVITY;
}

// Add data to the circular buffer
void add_to_buffer(float x_dps, float y_dps, float z_dps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    gyro_buffer[buffer_index].timestamp = ts;
    gyro_buffer[buffer_index].x = (int16_t)(x_dps * GYRO_SENSITIVITY);
    gyro_buffer[buffer_index].y = (int16_t)(y_dps * GYRO_SENSITIVITY);
    gyro_buffer[buffer_index].z = (int16_t)(z_dps * GYRO_SENSITIVITY);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print the circular buffer as CSV
void print_buffer() {
    FILE *fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_data.csv for writing\n");
        return;
    }

    fprintf(fp, "Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct timespec ts = gyro_buffer[i].timestamp;
        fprintf(fp, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, gyro_buffer[i].x, gyro_buffer[i].y, gyro_buffer[i].z);
    }

    fclose(fp);
    printf("Gyro data saved to gyro_data.csv\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// LED blink function
void led_blink(int gpio, int frequency, int range) {
    gpioSetPWMfrequency(gpio, frequency);
    gpioSetPWMrange(gpio, range);
    gpioPWM(gpio, 128); // 50% duty cycle
    gpioDelay(500000);  // 500ms
    gpioPWM(gpio, 0);   // Turn off LED
    gpioDelay(500000);  // 500ms
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(led_gpio, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    led_gpio = LED_GPIO;
    gpioSetMode(led_gpio, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spi_init(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle < 0) {
        cleanup();
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init(spi_handle) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x_dps, y_dps, z_dps;

    printf("Starting gyroscope data acquisition...\n");

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(spi_handle, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            convert_to_dps(raw_x, raw_y, raw_z, &x_dps, &y_dps, &z_dps);

            // Add to circular buffer
            add_to_buffer(x_dps, y_dps, z_dps);

            // Check for threshold violation
            if (fabs(x_dps) > THRESHOLD_DEGS_PER_SEC || fabs(y_dps) > THRESHOLD_DEGS_PER_SEC || fabs(z_dps) > THRESHOLD_DEGS_PER_SEC) {
                led_blink(led_gpio, PWM_FREQUENCY, PWM_RANGE);
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data\n");
        }

        gpioDelay(10000); // 10ms delay (adjust as needed)
    }

    // Print and save the circular buffer
    print_buffer();

    // Cleanup and exit
    cleanup();
    return 0;
}

