#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define PROXIMITY_REG 0x22
#define AMBIENT_REG 0x20
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SLEEP_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
struct gpiod_line *gpio_line = NULL;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg, uint8_t *value);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *ambient, uint16_t *proximity);
void log_data(FILE *fp, uint16_t ambient, uint16_t proximity);
void set_gpio_value(struct gpiod_line *line, int value);
void cleanup(int signal);

// I2C read function with retry
int i2c_read_register(int fd, uint8_t reg, uint8_t *value) {
    int retries = RETRY_COUNT;
    uint8_t buf[1];
    buf[0] = reg;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
            perror("Error: i2c_SLAVE");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            continue;
        }

        if (write(fd, buf, 1) != 1) {
            perror("Error: write");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (read(fd, value, 1) != 1) {
            perror("Error: read");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0; // Success
    }
    fprintf(stderr, "Error: I2C read failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int retries = RETRY_COUNT;
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
            perror("Error: i2c_SLAVE");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (write(fd, buf, 2) != 2) {
            perror("Error: write");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0; // Success
    }
    fprintf(stderr, "Error: I2C write failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Read sensor data function
int read_sensor_data(int fd, uint16_t *ambient, uint16_t *proximity) {
    uint8_t ambient_lsb, ambient_msb, proximity_lsb, proximity_msb;

    if (i2c_read_register(fd, AMBIENT_REG, &ambient_lsb) != 0) return -1;
    if (i2c_read_register(fd, AMBIENT_REG + 1, &ambient_msb) != 0) return -1;
    if (i2c_read_register(fd, PROXIMITY_REG, &proximity_lsb) != 0) return -1;
    if (i2c_read_register(fd, PROXIMITY_REG + 1, &proximity_msb) != 0) return -1;

    *ambient = (uint16_t)((ambient_msb << 8) | ambient_lsb);
    *proximity = (uint16_t)((proximity_msb << 8) | proximity_lsb);

    return 0;
}

// Log data function
void log_data(FILE *fp, uint16_t ambient, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u\n", timestamp, ambient, proximity);
    fflush(fp); // Ensure data is written to file immediately
}

// Set GPIO value function
void set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO value.\n");
    }
}

// Cleanup function
void cleanup(int signal) {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO line
    gpio_line = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_line) {
        perror("Error: Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "biometric_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    gpio_line = gpiod_chip_get_line(gpio_line, GPIO_PIN);
    if (!gpio_line) {
        perror("Error: Failed to get GPIO line");
        fclose(log_file);
        close(i2c_fd);
        gpiod_chip_close(gpio_line);
        return 1;
    }

    if (gpiod_line_request(gpio_line, &config, 0) != 0) {
        perror("Error: Failed to request GPIO line");
        fclose(log_file);
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_line);
        return 1;
    }

    uint16_t ambient, proximity;

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_fd, &ambient, &proximity) == 0) {
            log_data(log_file, ambient, proximity);

            if (proximity > 100) {
                set_gpio_value(gpio_line, 1); // Set GPIO high
            } else {
                set_gpio_value(gpio_line, 0); // Set GPIO low
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        usleep(SLEEP_MS * 1000); // Sleep for 100ms
    }

    return 0;
}

