        fclose(log_file);
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_line);
        return 1;
    }

    uint16_t ambient, proximity;

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_fd, &ambient, &proximity) == 0) {
            log_data(log_file, ambient, proximity);

            if (proximity > 100) {
                set_gpio_value(gpio_line, 1); // Set GPIO high
            } else {
                set_gpio_value(gpio_line, 0); // Set GPIO low
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        usleep(SLEEP_MS * 1000); // Sleep for 100ms
    }

    return 0;
}

