void log_data(time_t timestamp, int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);

// Function to read a single byte from the SPI device
int spi_read_register(uint8_t address, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set the read bit in the address byte
    tx_buf[0] = address | 0x80; // Read bit set
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

