            // Combine the two bytes into a 16-bit value
            int16_t value = (int16_t)((data & 0xFF) << 8 | (data >> 8));
            return value;
        } else {
            fprintf(stderr, "SPI read failed, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "SPI read failed after multiple retries\n");
    return 0; // Return 0 on failure
}

