    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,X rate,Y rate\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyro data
        int16_t x_rate = read_gyro_axis(X_AXIS_REG);
        int16_t y_rate = read_gyro_axis(Y_AXIS_REG);

        // Get timestamp
        time_t current_time = time(NULL);

        // Log data
        log_data(current_time, x_rate, y_rate);

        // Delay before next sample
        gpioDelay(SAMPLE_DELAY);
    }

    // Clean up
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

