// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

// Define alert duration (milliseconds)
#define ALERT_DURATION 2000

// Define sensor state (HIGH when tilted)
#define SENSOR_STATE_HIGH 1
#define SENSOR_STATE_LOW 0

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_event(const char *message);
void trigger_alert();
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

SensorStates current_states = {SENSOR_STATE_LOW, SENSOR_STATE_LOW};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to read sensor state
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log events to file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", buf, message);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return 1;
    }
}

// Function to trigger the alert
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1); // Set HIGH
    gpioDelay(ALERT_DURATION * 1000); // Delay for 2 seconds
    gpioWrite(ALERT_PIN, 0); // Set LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Seismic event detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        // Update sensor states
        current_states.sensor1_state = sensor1_state;
        current_states.sensor2_state = sensor2_state;

        // Check for simultaneous HIGH state for 500ms
        if (current_states.sensor1_state == SENSOR_STATE_HIGH &&
            current_states.sensor2_state == SENSOR_STATE_HIGH) {
            // Log the event
            log_event("Seismic event detected!");

            // Trigger the alert
            trigger_alert();
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is LOW
    gpioTerminate();

    return 0;
}

