#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define LED_PIN 17
#define THRESHOLD 20.0
#define BUFFER_SIZE 100

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    struct timespec timestamp[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t buffer;

// Function prototypes
int init_gpio();
int init_spi();
int init_circular_buffer(circular_buffer_t *cb);
int read_gyro_data(int *x_rate);
double convert_to_dps(int raw_data);
void add_to_buffer(circular_buffer_t *cb, struct timespec timestamp);
double calculate_average_dps(circular_buffer_t *cb);
void control_led(double average_dps);
void signal_handler(int signal);
void cleanup();

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn off LED initially

    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize circular buffer
int init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
    return 0;
}

// Read gyroscope data
int read_gyro_data(int *x_rate) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of address to 1 for read operation
    tx_buf[0] = 0x02 | 0x80; // RATE_XL
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    *x_rate = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Convert raw data to degrees per second
double convert_to_dps(int raw_data) {
    return (double)raw_data / 200.0; // 200 LSB/deg/s
}

// Add timestamp to circular buffer
void add_to_buffer(circular_buffer_t *cb, struct timespec timestamp) {
    cb->timestamp[cb->head] = timestamp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average angular rate from circular buffer
double calculate_average_dps(circular_buffer_t *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    double sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        int index = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE; // Correct index calculation
        sum += convert_to_dps((int32_t)((cb->timestamp[index].tv_sec << 32) | cb->timestamp[index].tv_nsec));
    }
    return sum / cb->count;
}

// Control LED based on average angular rate
void control_led(double average_dps) {
    if (fabs(average_dps) > THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize
    if (init_gpio() != 0) {
        return 1;
    }

    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    if (init_circular_buffer(&buffer) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int x_rate_raw;
    struct timespec timestamp;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x_rate_raw) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &timestamp);
            add_to_buffer(&buffer, timestamp);
            double average_dps = calculate_average_dps(&buffer);
            control_led(average_dps);
            printf("X Rate: %d, Avg DPS: %.2f\n", x_rate_raw, average_dps);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

