    if (cb->count == 0) {
        return 0.0;
    }

    double sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        int index = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE; // Correct index calculation
        sum += convert_to_dps((int32_t)((cb->timestamp[index].tv_sec << 32) | cb->timestamp[index].tv_nsec));
    }
    return sum / cb->count;
}

// Control LED based on average angular rate
void control_led(double average_dps) {
    if (fabs(average_dps) > THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize
    if (init_gpio() != 0) {
        return 1;
    }

    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    if (init_circular_buffer(&buffer) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int x_rate_raw;
    struct timespec timestamp;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x_rate_raw) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &timestamp);
            add_to_buffer(&buffer, timestamp);
            double average_dps = calculate_average_dps(&buffer);
            control_led(average_dps);
            printf("X Rate: %d, Avg DPS: %.2f\n", x_rate_raw, average_dps);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

