#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Default fade duration (seconds)
#define DEFAULT_FADE_DURATION 60

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int parse_arguments(int argc, char *argv[], int *fade_duration);
int set_lamp_brightness(int gpio, int brightness);
int fade_lamp(int gpio, int start_brightness, int end_brightness, int duration);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully...\n", signal);
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(LAMP1_GPIO, 255);
    gpioSetPWMrange(LAMP2_GPIO, 255);
    gpioSetPWMrange(LAMP3_GPIO, 255);

    // Set PWM frequency (100 Hz)
    gpioSetPWMfrequency(LAMP1_GPIO, 100);
    gpioSetPWMfrequency(LAMP2_GPIO, 100);
    gpioSetPWMfrequency(LAMP3_GPIO, 100);

    return 0; // Indicate success
}

// Parse command-line arguments
int parse_arguments(int argc, char *argv[], int *fade_duration) {
    if (argc > 1) {
        *fade_duration = atoi(argv[1]);
        if (*fade_duration < 1 || *fade_duration > 3600) {
            fprintf(stderr, "Error: Fade duration must be between 1 and 3600 seconds.\n");
            return 1; // Indicate failure
        }
    } else {
        *fade_duration = DEFAULT_FADE_DURATION;
    }
    return 0; // Indicate success
}

// Set lamp brightness using PWM
int set_lamp_brightness(int gpio, int brightness) {
    if (brightness < 0 || brightness > 255) {
        fprintf(stderr, "Error: Brightness must be between 0 and 255.\n");
        return 1; // Indicate failure
    }
    gpioPWM(gpio, brightness);
    return 0; // Indicate success
}

// Fade lamp brightness over a specified duration
int fade_lamp(int gpio, int start_brightness, int end_brightness, int duration) {
    int steps = duration * 100; // 100 Hz PWM frequency
    int increment = (end_brightness - start_brightness) / steps;
    int current_brightness = start_brightness;

    for (int i = 0; i < steps; i++) {
        current_brightness += increment;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > 255) current_brightness = 255;

        if (set_lamp_brightness(gpio, current_brightness) != 0) {
            return 1; // Indicate failure
        }
        gpioDelay(10); // Delay for 10ms (100 Hz)
    }

    return 0; // Indicate success
}

// Cleanup GPIO resources
void cleanup() {
    printf("Cleaning up GPIO resources...\n");
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int fade_duration = DEFAULT_FADE_DURATION;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &fade_duration) != 0) {
        return 1; // Exit if argument parsing fails
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Sunset Simulator started. Fade duration: %d seconds\n", fade_duration);

    // Fade lamps sequentially
    if (fade_lamp(LAMP1_GPIO, 255, 0, fade_duration) != 0) {
        cleanup();
        return 1;
    }
    if (fade_lamp(LAMP2_GPIO, 255, 0, fade_duration) != 0) {
        cleanup();
        return 1;
    }
    if (fade_lamp(LAMP3_GPIO, 255, 0, fade_duration) != 0) {
        cleanup();
        return 1;
    }

    // Cleanup and exit
    cleanup();
    printf("Smart Sunset Simulator finished.\n");
    return 0;
}

