    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a relay
int set_relay_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to cycle through the traffic light states
void cycle_traffic_light() {
    int red_state = 0; // 0 = OFF, 1 = ON
    int yellow_state = 0;
    int green_state = 0;
    int yellow2_state = 0;

    while (program_running) {
        // Red light
        if (set_relay_state(RED_RELAY, red_state) != 0 ||
            set_relay_state(YELLOW_RELAY, yellow_state) != 0 ||
            set_relay_state(GREEN_RELAY, green_state) != 0 ||
