            fprintf(stderr, "Error setting relay states for Red light\n");
            break;
        }
        printf("Red light ON\n");
        gpioDelay(RED_DURATION);

        // Red + Yellow light
        if (set_relay_state(RED_RELAY, !red_state) != 0 ||
            set_relay_state(YELLOW_RELAY, yellow_state) != 0 ||
            set_relay_state(GREEN_RELAY, green_state) != 0 ||
