            set_relay_state(YELLOW_RELAY, !yellow_state) != 0 ||
            set_relay_state(GREEN_RELAY, green_state) != 0 ||
            set_relay_state(YELLOW_RELAY_2, !yellow2_state) != 0) {
            fprintf(stderr, "Error setting relay states for Yellow light\n");
            break;
        }
        printf("Yellow light ON\n");
        gpioDelay(YELLOW_DURATION);

        // Green light
        if (set_relay_state(RED_RELAY, !red_state) != 0 ||
            set_relay_state(YELLOW_RELAY, !yellow_state) != 0 ||
            set_relay_state(GREEN_RELAY, green_state) != 0 ||
            set_relay_state(YELLOW_RELAY_2, !yellow2_state) != 0) {
            fprintf(stderr, "Error setting relay states for Green light\n");
            break;
        }
        printf("Green light ON\n");
        gpioDelay(GREEN_DURATION);
    }
}

