    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_RELAY, PI_OUTPUT) != 0 ||
        gpioSetMode(YELLOW_RELAY, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_RELAY, PI_OUTPUT) != 0 ||
        gpioSetMode(YELLOW_RELAY_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        gpioTerminate();
        return 1;
    }

