#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_DELAY_MS 100
#define LOG_FILE "touch_relay.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status();
void toggle_relay();
void log_message(const char *message);
void signal_handler(int signal);

// Function to initialize the MPR121
int initialize_mpr121() {
    char buf[2];
    int status;

    // Reset MPR121
    buf[0] = 0x80; // Reset register
    buf[1] = 0x63; // Reset value
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        log_message("Error: Failed to reset MPR121.");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Stop Mode
    buf[0] = 0x5E; // Stop mode register
    buf[1] = 0x00; // Stop mode value
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        log_message("Error: Failed to set MPR121 to stop mode.");
        return -1;
    }

    // Enable electrode 0
    buf[0] = 0x5D; // Electrode enable register
    buf[1] = 0x01; // Enable electrode 0
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        log_message("Error: Failed to enable electrode 0.");
        return -1;
    }

    // Touch Threshold
    buf[0] = 0x41; // Touch threshold register
    buf[1] = TOUCH_THRESHOLD;
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        log_message("Error: Failed to set touch threshold.");
        return -1;
    }

    // Release Threshold
    buf[0] = 0x42; // Release threshold register
    buf[1] = RELEASE_THRESHOLD;
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        log_message("Error: Failed to set release threshold.");
        return -1;
    }

    // Debounce
    buf[0] = 0x5B; // Debounce register
    buf[1] = DEBOUNCE_DELAY_MS; // Debounce delay
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        log_message("Error: Failed to set debounce.");
        return -1;
    }

    // Charge Time
    buf[0] = 0x5C; // Charge time register
    buf[1] = 0x0D; // Charge time value
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        log_message("Error: Failed to set charge time.");
        return -1;
    }

    // Run Mode
    buf[0] = 0x5E; // Run mode register
    buf[1] = 0x0D; // Run mode value
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        log_message("Error: Failed to set run mode.");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status() {
    char buf[2];
    int status;
    int touch_status;

    buf[0] = 0x00; // Touch status register
    status = i2cWriteDevice(i2c_handle, buf, 1);
    if (status != 0) {
        log_message("Error: Failed to write to touch status register.");
        return -1;
    }

    status = i2cReadDevice(i2c_handle, buf, 2);
    if (status != 0) {
        log_message("Error: Failed to read touch status.");
        return -1;
    }

    touch_status = (buf[1] << 8) | buf[0];
    return touch_status;
}

// Function to toggle the relay state
void toggle_relay() {
    int current_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_state);
    log_message("Relay toggled.");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received, shutting down...");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    log_message("Program started.");

    // Set GPIO17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, LOW); // Initialize relay to OFF

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error: Failed to open I2C device.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
