#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration (milliseconds)
#define DISPENSE_DURATION 1000

// Define delay between dispenses (milliseconds)
#define DELAY_BETWEEN_DISPENSES 5000

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int pin, int duration_ms);
int deactivate_solenoid(int pin);
int dispense();
int log_dispense(int solenoid1_pin, int solenoid2_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down gracefully...\n");
        program_running = 0; // Set the flag to exit the main loop

        // Deactivate solenoids
        deactivate_solenoid(SOLENOID_1_PIN);
        deactivate_solenoid(SOLENOID_2_PIN);

        // Terminate pigpio
        gpioTerminate();

        exit(0); // Exit the program
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to activate a solenoid
int activate_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO%d\n", pin);
        return 1; // Indicate failure
    }
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    return 0; // Indicate success
}

// Function to deactivate a solenoid
int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO%d\n", pin);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to perform a single dispense cycle
int dispense() {
    // Activate solenoid 1
    if (activate_solenoid(SOLENOID_1_PIN, DISPENSE_DURATION) != 0) {
        fprintf(stderr, "Failed to activate solenoid 1\n");
        return 1;
    }

    // Deactivate solenoid 1
    if (deactivate_solenoid(SOLENOID_1_PIN) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid 1\n");
        return 1;
    }

    // Activate solenoid 2
    if (activate_solenoid(SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
        fprintf(stderr, "Failed to activate solenoid 2\n");
        return 1;
    }

    // Deactivate solenoid 2
    if (deactivate_solenoid(SOLENOID_2_PIN) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid 2\n");
        return 1;
    }

    return 0; // Indicate success
}

// Function to log a dispense event
int log_dispense(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening dispense_log.txt for writing\n");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, GPIO%d, GPIO%d, %d ms\n", timestamp, solenoid1_pin, solenoid2_pin, duration_ms);
    fclose(fp);

    return 0; // Indicate success
}

