    if (fp == NULL) {
        fprintf(stderr, "Error opening dispense_log.txt for writing\n");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, GPIO%d, GPIO%d, %d ms\n", timestamp, solenoid1_pin, solenoid2_pin, duration_ms);
    fclose(fp);

    return 0; // Indicate success
}

