    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (dispense() != 0) {
            fprintf(stderr, "Dispense failed\n");
        }

        if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        gpioDelay(DELAY_BETWEEN_DISPENSES * 1000); // Delay between dispenses
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();

    return 0;
}

