// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

// PID Constants
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// PWM Range
#define PWM_RANGE 255

// Global Variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
void log_message(const char *message);
void stop_motors();
void signal_handler(int signal);
float calculate_pid(float error, float *integral, float *previous_error);
void set_motor_speed(int motor, int speed);

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping motors and exiting.\n");
        program_running = 0;
    }
}

// Logging Function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, (float)rand() / RAND_MAX, (float)rand() / RAND_MAX, (int)rand() % PWM_RANGE, (int)rand() % PWM_RANGE);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Stop Motors Function
void stop_motors() {
    set_motor_speed(0, 0); // Motor 0 (A) stopped
    set_motor_speed(1, 0); // Motor 1 (B) stopped
}

// PID Calculation Function
float calculate_pid(float error, float *integral, float *previous_error) {
    float proportional = Kp * error;
    *integral += Ki * error;
    float derivative = Kd * (error - *previous_error);
    float output = proportional + *integral + derivative;
    *previous_error = error;
    return output;
}

// Set Motor Speed Function
void set_motor_speed(int motor, int speed) {
    if (motor == 0) { // Motor A
        gpioPWM(MOTOR_A_ENABLE, 1); // Enable motor A
        if (speed > 0) {
            gpioPWM(MOTOR_A_FORWARD, (int)speed);
            gpioPWM(MOTOR_A_BACKWARD, 0);
        } else if (speed < 0) {
            gpioPWM(MOTOR_A_FORWARD, 0);
            gpioPWM(MOTOR_A_BACKWARD, (int)-speed);
        } else {
            gpioPWM(MOTOR_A_FORWARD, 0);
            gpioPWM(MOTOR_A_BACKWARD, 0);
        }
    } else if (motor == 1) { // Motor B
        gpioPWM(MOTOR_B_ENABLE, 1); // Enable motor B
        if (speed > 0) {
            gpioPWM(MOTOR_B_FORWARD, (int)speed);
            gpioPWM(MOTOR_B_BACKWARD, 0);
        } else if (speed < 0) {
            gpioPWM(MOTOR_B_FORWARD, 0);
            gpioPWM(MOTOR_B_BACKWARD, (int)-speed);
        } else {
            gpioPWM(MOTOR_B_FORWARD, 0);
            gpioPWM(MOTOR_B_BACKWARD, 0);
        }
    } else {
        log_message("Error: Invalid motor number.");
    }
}

