        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float integral = 0.0;
    float previous_error = 0.0;
    float tilt_error;
    float distance;

    // Main loop
    while (program_running) {
        // Simulate tilt error
        tilt_error = (float)(rand() % 200) - 100.0; // Random value between -100 and 100

        // Simulate distance sensor
        distance = (float)(rand() % 398) + 2.0; // Random value between 2 and 400

        // Calculate PID output
        float pid_output = calculate_pid(tilt_error, &integral, &previous_error);

        // Scale PID output to PWM range
        int motor_a_speed = (int)(pid_output * 0.5); // Adjust scaling factor as needed
        int motor_b_speed = (int)(pid_output * 0.5);

        // Clamp motor speeds to +/- 255
        if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
        if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
        if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
        if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;

        // Set motor speeds
        set_motor_speed(0, motor_a_speed);
        set_motor_speed(1, motor_b_speed);

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            log_message("Obstacle detected! Reversing both motors.");
            stop_motors();
            gpioDelay(500); // Reverse for 500ms
            set_motor_speed(0, -128); // Reverse Motor A at 50%
            set_motor_speed(1, -128); // Reverse Motor B at 50%
            gpioDelay(500); // Move forward for 500ms
            stop_motors();
        }

        // Log data
        log_message("Tilt Error: %.2f, Distance: %.2f, Motor A: %d, Motor B: %d".format(tilt_error, distance, motor_a_speed, motor_b_speed));

        gpioDelay(50); // Control loop frequency
    }

    // Stop motors
    stop_motors();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

