#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Global variable to store the relay state
static int relay_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initializes the pigpio library and sets up the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO4 as input (touch sensor)
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);

    // Set GPIO17 as output (relay)
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    return 0; // Indicate success
}

// Reads the touch sensor and returns 1 if touched, 0 otherwise
int read_touch_sensor() {
    // Read the digital value from the touch sensor
    int touch_value = gpioRead(TOUCH_SENSOR_PIN);

    // Debounce the touch sensor
    gpioDelay(50); // 50 ms delay

    // Return 1 if touched (HIGH), 0 otherwise (LOW)
    return (touch_value == 1) ? 1 : 0;
}

// Toggles the relay state
void toggle_relay() {
    // Toggle the relay state
    relay_state = !relay_state;

    // Set the relay pin HIGH to energize the relay
    gpioWrite(RELAY_PIN, 1);

    // Wait for 1 second
    gpioDelay(1000); // 1000 ms = 1 second

    // Set the relay pin LOW to de-energize the relay
    gpioWrite(RELAY_PIN, 0);

    // Update the relay state variable
    relay_state = 0; // Ensure it's off after toggling
}

// Cleans up the GPIO pins and terminates the pigpio library
void cleanup_gpio() {
    // De-energize the relay
    gpioWrite(RELAY_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Smart Light Switch running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the touch sensor
        if (read_touch_sensor()) {
            // Toggle the relay
            toggle_relay();
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10); // 10 ms delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

