#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Configuration
#define DEFAULT_SAMPLING_RATE 8000
#define DEFAULT_PERIOD_SIZE 1024
#define DEFAULT_SENSITIVITY 1.0
#define DEFAULT_RED_PIN 17
#define DEFAULT_GREEN_PIN 18
#define DEFAULT_BLUE_PIN 27
#define DEFAULT_MOOD_LIGHT_DURATION 5 // seconds
#define DEFAULT_MOOD_LIGHT_FREQUENCY 0.5 // Hz
#define DEFAULT_MOOD_LIGHT_AMPLITUDE 255 // PWM value

// Global variables
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static int red_pin = DEFAULT_RED_PIN;
static int green_pin = DEFAULT_GREEN_PIN;
static int blue_pin = DEFAULT_BLUE_PIN;
static double sensitivity = DEFAULT_SENSITIVITY;
static int sampling_rate = DEFAULT_SAMPLING_RATE;
static int period_size = DEFAULT_PERIOD_SIZE;
static int red_pwm = DEFAULT_MOOD_LIGHT_AMPLITUDE;
static int green_pwm = DEFAULT_MOOD_LIGHT_AMPLITUDE;
static int blue_pwm = DEFAULT_MOOD_LIGHT_AMPLITUDE;
static int mood_light_duration = DEFAULT_MOOD_LIGHT_DURATION;
static double mood_light_frequency = DEFAULT_MOOD_LIGHT_FREQUENCY;

// Function prototypes
void signal_handler(int signal);
int initialize_alsa();
int capture_audio(short *buffer, int frames);
double calculate_rms(const short *buffer, int frames);
void map_rms_to_rgb(double rms, double sensitivity, int *red_pwm, int *green_pwm, int *blue_pwm);
void set_led_color(int red_pwm, int green_pwm, int blue_pwm);
void simulate_alsa_audio();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        running = 0;
    }
}

// Initialize ALSA
int initialize_alsa() {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, 1)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        return -1;
    }

    unsigned int rate = sampling_rate;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_prepare(pcm_handle)) < 0) {
        fprintf(stderr, "Error preparing PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_resume(pcm_handle)) < 0) {
        fprintf(stderr, "Error resuming PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    return 0;
}

// Capture audio
int capture_audio(short *buffer, int frames) {
    int err = snd_pcm_readi(pcm_handle, buffer, frames);
    if (err == -EPIPE) {
        fprintf(stderr, "Overrun occurred\n");
        snd_pcm_prepare(pcm_handle);
        return -1;
    } else if (err < 0) {
        fprintf(stderr, "Error reading PCM device: %s\n", snd_strerror(err));
        return -1;
    } else if (err != frames) {
        fprintf(stderr, "Short read, read %d frames, expected %d\n", err, frames);
        return -1;
    }
    return 0;
}

// Calculate RMS amplitude
double calculate_rms(const short *buffer, int frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        sum_sq += (double)buffer[i] * (double)buffer[i];
    }
    return sqrt(sum_sq / frames);
}

