#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_S 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log events to a file
void log_event(const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
    free(timestamp);
}

// Function to execute raspivid command
int execute_raspivid() {
    char command[100];
    snprintf(command, sizeof(command), "raspivid -o /home/pi/videos/%Y%m%d_%H%M%S.h264 -t %d", VIDEO_DURATION_S);
    int status = system(command);
    if (status == -1) {
        log_event("Error executing raspivid command.");
        return -1;
    }
    return status;
}

// Function to read sensor value with debouncing
int read_sensor() {
    int value = gpioRead(SENSOR_PIN);
    gpioDelay(DEBOUNCE_MS * 1000); // Debounce delay in microseconds
    return value;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    log_event("Motion detection started.");

    // Main loop
    while (running) {
        if (read_sensor() == 0) { // Obstacle detected (active-low)
            char *timestamp = get_iso8601_timestamp();
            char filename[50];
            snprintf(filename, sizeof(filename), "/home/pi/videos/%Y%m%d_%H%M%S.h264", localtime(&time(NULL)));
            char command[100];
            snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_S);
            int status = system(command);
            if (status == 0) {
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Motion detected at %s, raspivid command executed successfully.", timestamp);
                log_event(log_message);
            } else {
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Motion detected at %s, raspivid command failed with status %d.", timestamp, status);
                log_event(log_message);
            }
            free(timestamp);
            gpioDelay(1000000); // Delay to prevent multiple triggers
        }
        gpioDelay(100000); // Check every 0.1 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

