#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor
#define GYRO_SENSITIVITY 131.0

// Sampling rate divider
#define SAMPLE_RATE_DIVIDER 125

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_degps(int16_t raw_data);
int log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) == 0) { // Wake up the sensor
            if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) == 0) { // Set full-scale range to ±250°/s
                return 0; // Initialization successful
            } else {
                fprintf(stderr, "Error writing to GYRO_CONFIG register.\n");
            }
        } else {
            fprintf(stderr, "Error writing to PWR_MGMT_1 register.\n");
        }
        retries--;
        gpioDelay(10000); // Wait 10ms before retrying
    }
    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Initialization failed
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int retries = 3;
    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) == 6) {
            *x = (int16_t)((buf[0] << 8) | buf[1]);
            *y = (int16_t)((buf[2] << 8) | buf[3]);
            *z = (int16_t)((buf[4] << 8) | buf[5]);
            return 0; // Data read successfully
        } else {
            fprintf(stderr, "Error reading gyroscope data.\n");
        }
        retries--;
        gpioDelay(10000); // Wait 10ms before retrying
    }
    fprintf(stderr, "Failed to read gyroscope data after multiple retries.\n");
    return -1; // Data read failed
}

// Convert raw data to degrees per second
float convert_to_degps(int16_t raw_data) {
    return (float)raw_data / GYRO_SENSITIVITY;
}

// Log data to file
int log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (log_file != NULL) {
        fprintf(log_file, "%lld,%.2f,%.2f,%.2f\n", timestamp_ms, x, y, z);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set sampling rate divider
    if (i2cWriteByteData(i2c_handle, 0x1B, SAMPLE_RATE_DIVIDER) != 0) {
        fprintf(stderr, "Error setting sampling rate divider.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x_degps, y_degps, z_degps;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            x_degps = convert_to_degps(raw_x);
            y_degps = convert_to_degps(raw_y);
            z_degps = convert_to_degps(raw_z);

            // Log data
            if (log_data(x_degps, y_degps, z_degps) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data. Attempting re-initialization.\n");
            if (init_mpu6050() != 0) {
                fprintf(stderr, "Failed to re-initialize MPU-6050.\n");
            }
        }

        gpioDelay(10000); // Sample at 100 Hz (10 ms interval)
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

