#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// Alarm duration (seconds)
#define ALARM_DURATION 5

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int adxl345_init();
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int detect_freefall(int16_t x, int16_t y, int16_t z);
void trigger_alarm();
void log_freefall_event(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(27, PI_OUTPUT);

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    accelerometer_data_t accel_data;
    int freefall_detected = 0;
    time_t start_time = 0;

    while (1) {
        // Read accelerometer data
        if (read_accelerometer_data(&accel_data.x, &accel_data.y, &accel_data.z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue; // Continue to the next iteration
        }

        // Detect freefall
        if (detect_freefall(accel_data.x, accel_data.y, accel_data.z)) {
            if (!freefall_detected) {
                freefall_detected = 1;
                start_time = time(NULL);
            } else {
                if (time(NULL) - start_time >= FREEFALL_DURATION) {
                    // Freefall detected
                    trigger_alarm();
                    log_freefall_event(accel_data.x, accel_data.y, accel_data.z);
                }
            }
        } else {
            freefall_detected = 0;
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    return 0;
}

// Initialize ADXL345
int adxl345_init() {
    // Set DATA_FORMAT register to enable full resolution and ±2g range
    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Failed to write to DATA_FORMAT register\n");
        return -1;
    }

    // Set POWER_CTL register to enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to write to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    // Read 6 bytes starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw data to g-force
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 256.0;
}

// Detect freefall
int detect_freefall(int16_t x, int16_t y, int16_t z) {
    float x_g = convert_to_g(x);
    float y_g = convert_to_g(y);
    float z_g = convert_to_g(z);

    if (abs(x_g) < FREEFALL_THRESHOLD && abs(y_g) < FREEFALL_THRESHOLD && abs(z_g) < FREEFALL_THRESHOLD) {
        return 1;
    } else {
        return 0;
    }
}

// Trigger alarm
void trigger_alarm() {
    gpioWrite(27, 1); // Set GPIO27 high
    gpioDelay(ALARM_DURATION * 1000000); // Wait for 5 seconds
    gpioWrite(27, 0); // Set GPIO27 low
}

// Log freefall event
void log_freefall_event(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, convert_to_g(x), convert_to_g(y), convert_to_g(z));
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");

    // Close I2C connection
    i2cClose(i2c_handle);

    // Set GPIO low
    gpioWrite(27, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

