#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 100000       // 100 ms timeout
#define MAX_DISTANCE 400.0      // Maximum measurable distance in cm

// Mutex for protecting shared variables
pthread_mutex_t pulse_mutex;

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user);
double calculate_distance(unsigned int pulse_width_us);
void log_distance(double distance_cm);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) {
        // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        start_tick = tick;
        echo_received = 1;
        pthread_mutex_unlock(&pulse_mutex);
    } else if (level == 0) {
        // Falling edge
        pthread_mutex_lock(&pulse_mutex);
        end_tick = tick;
        echo_received = 1;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate distance in centimeters
double calculate_distance(unsigned int pulse_width_us) {
    return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Convert us to s
}

// Function to log distance to a file
void log_distance(double distance_cm) {
    FILE *fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening distance_log.txt");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(fp, "%lld,%.2f\n", timestamp_ns, distance_cm);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up interrupt callback
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(200); // 200 ms delay

        unsigned int pulse_width_us = 0;
        double distance_cm = 0.0;

        pthread_mutex_lock(&pulse_mutex);
        if (echo_received) {
            pulse_width_us = end_tick - start_tick;
            echo_received = 0; // Reset echo_received after reading
        } else {
            pulse_width_us = 0; // No echo received
        }
        pthread_mutex_unlock(&pulse_mutex);

        if (pulse_width_us > 0 && pulse_width_us <= TIMEOUT_US) {
            distance_cm = calculate_distance(pulse_width_us);

            if (distance_cm <= MAX_DISTANCE) {
                log_distance(distance_cm);
            } else {
                fprintf(stderr, "Distance out of range: %.2f cm\n", distance_cm);
            }
        } else {
            fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width_us);
        }
    }

    return 0;
}

