#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG2 0x21
#define CTRL_REG3 0x22
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Default values
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
int buzzer_gpio = 17;
double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
double impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int config_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double convert_to_g(int16_t raw);
double calculate_magnitude(double x, double y, double z);
void detect_freefall(double magnitude);
void detect_impact(double magnitude);
void activate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    double x;
    double y;
    double z;
} accelerometer_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, 0x18, 0); // Bus 1, address 0x18, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the LIS3DH
int config_lis3dh() {
    // CTRL_REG1: 0x77 (100 Hz, ±2g)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: 0x00 (High-resolution mode disabled)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw data to g
double convert_to_g(int16_t raw) {
    return (double)raw / 16384.0;
}

// Function to calculate acceleration magnitude
double calculate_magnitude(double x, double y, double z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to detect freefall
void detect_freefall(double magnitude) {
    if (magnitude < freefall_threshold) {
        printf("Freefall detected!\n");
        activate_buzzer();
    }
}

// Function to detect impact
void detect_impact(double magnitude) {
    if (magnitude > impact_threshold) {
        printf("Impact detected!\n");
        activate_buzzer();
    }
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(buzzer_gpio, 1); // Turn buzzer on
    gpioDelay(1000);           // Wait for 1 second
    gpioWrite(buzzer_gpio, 0); // Turn buzzer off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(buzzer_gpio, 0); // Ensure buzzer is off
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(buzzer_gpio, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (config_lis3dh() < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double x_g, y_g, z_g, magnitude;

    printf("Fall detection system started. Freefall threshold: %.2f g, Impact threshold: %.2f g\n", freefall_threshold, impact_threshold);

    while (program_running) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Convert to g
            x_g = convert_to_g(x);
            y_g = convert_to_g(y);
            z_g = convert_to_g(z);

            // Calculate magnitude
            magnitude = calculate_magnitude(x_g, y_g, z_g);

            // Detect freefall and impact
            detect_freefall(magnitude);
            detect_impact(magnitude);

            printf("X: %.2f g, Y: %.2f g, Z: %.2f g, Magnitude: %.2f g\n", x_g, y_g, z_g, magnitude);
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(10); // 100 Hz data rate (10 ms delay)
    }

    cleanup();
    return 0;
}

