#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Default I2C address
#define DEFAULT_I2C_ADDR 0x18

// Default threshold
#define DEFAULT_THRESHOLD 2.0f

// Global variables
int i2c_handle;
float threshold = DEFAULT_THRESHOLD;
int i2c_address = DEFAULT_I2C_ADDR;

// Function prototypes
int initialize_i2c(int address);
int configure_sensor(int handle);
int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
float calculate_g(int16_t raw_value);
void log_event(int16_t x, int16_t y, int16_t z, float g);
void shutdown_system();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    float g;
} sensor_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Error: Invalid I2C address. Must be between 0x08 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Error: Threshold must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = initialize_i2c(i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Error: Sensor configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    float g_x, g_y, g_z;
    while (1) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Calculate g values
            g_x = calculate_g(x);
            g_y = calculate_g(y);
            g_z = calculate_g(z);

            // Check for threshold exceedance
            if (fabs(g_x) > threshold || fabs(g_y) > threshold || fabs(g_z) > threshold) {
                log_event(x, y, z, g_x);
                shutdown_system();
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    return 0;
}

// Initialize I2C
int initialize_i2c(int address) {
    int handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Configure the LIS3DH sensor
int configure_sensor(int handle) {
    // Set CTRL_REG1: ±2g, High-resolution mode, 100 Hz output data rate
    if (i2cWriteByteData(handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Set CTRL_REG4: High-resolution mode, enable all axes
    if (i2cWriteByteData(handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG4: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read acceleration data from the LIS3DH
int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, OUT_X_L | 0x80, buffer, 6) < 0) { // Read multiple bytes with auto-increment
        fprintf(stderr, "Error: Could not read acceleration data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate g value from raw acceleration data
float calculate_g(int16_t raw_value) {
    return (float)raw_value * 0.0009765625f; // 2g / 2048
}

// Log event to file
void log_event(int16_t x, int16_t y, int16_t z, float g) {
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - X: %d, Y: %d, Z: %d, G: %.4f\n", s, x, y, z, g);
    fclose(fp);
}

// Shutdown system
void shutdown_system() {
    printf("Shutting down system...\n");
    log_event(0, 0, 0, 0.0); // Log shutdown event
    system("sudo shutdown -h now");
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

