#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define line-following logic
#define CENTER_NO_LINE_THRESHOLD 5

// Define alert duration
#define ALERT_DURATION 2 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int alert_count = 0;

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Circular buffer
SensorReadings buffer[5];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
SensorReadings read_sensors();
void update_circular_buffer(SensorReadings readings);
int detect_alert();
void handle_alert();
void stop_robot();
void move_forward();
void turn_left();
void turn_right();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    return 0;
}

// Function to read sensor values
SensorReadings read_sensors() {
    SensorReadings readings;
    readings.left = gpioRead(LEFT_SENSOR);
    readings.center = gpioRead(CENTER_SENSOR);
    readings.right = gpioRead(RIGHT_SENSOR);
    return readings;
}

// Function to update the circular buffer
void update_circular_buffer(SensorReadings readings) {
    buffer[buffer_index] = readings;
    buffer_index = (buffer_index + 1) % 5;
}

// Function to detect an alert condition
int detect_alert() {
    int no_line_count = 0;
    for (int i = 0; i < 5; i++) {
        if (buffer[i].center == 1) {
            no_line_count++;
        }
    }
    return (no_line_count == CENTER_NO_LINE_THRESHOLD);
}

// Function to handle the alert
void handle_alert() {
    gpioWrite(ALERT_PIN, 1); // Activate alert
    gpioDelay(ALERT_DURATION * 1000000); // Wait for alert duration
    gpioWrite(ALERT_PIN, 0); // Deactivate alert
}

// Placeholder functions for motor control
void stop_robot() {
    // No action needed, just log
    printf("Stopping robot\n");
}

void move_forward() {
    // No action needed, just log
    printf("Moving forward\n");
}

void turn_left() {
    // No action needed, just log
    printf("Turning left\n");
}

void turn_right() {
    // No action needed, just log
    printf("Turning right\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        SensorReadings readings = read_sensors();
        update_circular_buffer(readings);

        printf("Left: %d, Center: %d, Right: %d\n", readings.left, readings.center, readings.right);

        if (readings.center == 0) {
            move_forward();
        } else if (readings.left == 0) {
            turn_left();
        } else if (readings.right == 0) {
            turn_right();
        } else {
            stop_robot();
        }

        if (detect_alert()) {
            handle_alert();
        }

        gpioDelay(10000); // Poll every 10 ms
    }

    // Clean up GPIO
    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");
    return 0;
}

