// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD 5.0 // mT
#define SAMPLE_INTERVAL_MS 100
#define MAX_POLL_ATTEMPTS 50
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor_data(int *field_raw);
float convert_to_mT(int field_raw);
int control_relay(int state);
int log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    int field_raw;
    float field_mT;
} sensor_data_t;

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int field_raw;
        float field_mT;

        if (read_sensor_data(&field_raw) == 0) {
            field_mT = convert_to_mT(field_raw);

            if (field_mT > FIELD_THRESHOLD * 100) {
                if (control_relay(1) == 0) { // Activate relay
                    log_event("Relay activated");
                } else {
                    log_event("Failed to activate relay");
                }
            } else {
                if (control_relay(0) == 0) { // Deactivate relay
                    log_event("Relay deactivated");
                } else {
                    log_event("Failed to deactivate relay");
                }
            }

            log_event("Sensor reading");
        } else {
            log_event("Failed to read sensor data");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_sensor_data(int *field_raw) {
    int msb, lsb;
    int attempts = 0;

    while (attempts < MAX_POLL_ATTEMPTS) {
        // Start measurement
        if (i2cWriteByteData(i2c_handle, 0xC1, 0x01) < 0) {
            fprintf(stderr, "Failed to write to I2C (start conversion): %d\n", i2c_handle);
            log_event("Failed to write to I2C (start conversion)");
            gpioDelay(1000); // Wait before retrying
            attempts++;
            continue;
        }

        // Wait for conversion to complete (polling 0xC1 until it reads 0x00)
        while (1) {
            int result = i2cReadByte(i2c_handle);
            if (result < 0) {
                fprintf(stderr, "Failed to read from I2C (polling): %d\n", i2c_handle);
                log_event("Failed to read from I2C (polling)");
                gpioDelay(1000); // Wait before retrying
                attempts++;
                break; // Exit polling loop
            }

            if (result == 0x00) {
                break; // Conversion complete
            }
            gpioDelay(10); // Small delay to avoid busy-waiting
        }

        if (result != 0x00) {
            fprintf(stderr, "Timeout waiting for conversion (attempt %d)\n", attempts + 1);
            log_event("Timeout waiting for conversion");
            attempts++;
            continue; // Retry
        }

        // Read 2 bytes from register 0xC0
        if (i2cReadByteData(i2c_handle, 0xC0) < 0) {
            fprintf(stderr, "Failed to read from I2C (read 2 bytes): %d\n", i2c_handle);
            log_event("Failed to read from I2C (read 2 bytes)");
            gpioDelay(1000); // Wait before retrying
            attempts++;
            continue; // Retry
        }

        msb = i2cReadByteData(i2c_handle, 0xC2);
        lsb = i2cReadByteData(i2c_handle, 0xC3);

        if (msb < 0 || lsb < 0) {
            fprintf(stderr, "Failed to read from I2C (read 2 bytes): %d\n", i2c_handle);
            log_event("Failed to read from I2C (read 2 bytes)");
            gpioDelay(1000); // Wait before retrying
            attempts++;
            continue; // Retry
        }

        *field_raw = (msb << 8) | lsb;
        return 0; // Success
    }

    fprintf(stderr, "Sensor read timeout after %d attempts\n", MAX_POLL_ATTEMPTS);
    log_event("Sensor read timeout after multiple attempts");
    return 1; // Failure
}

float convert_to_mT(int field_raw) {
    return (float)field_raw * 25.0 / 1000.0;
}

int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_GPIO);
        log_event("Failed to write to GPIO");
        return 1;
    }
    return 0;
}

int log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
    return 0;
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

void cleanup() {
    log_event("Cleaning up...");
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    log_event("Shutdown complete");
}

