#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024

// Global variables for graceful shutdown
int server_fd = -1;
int client_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int setup_gpio();
int setup_socket();
void handle_client(int client_socket);
void log_event(const char *event);
void signal_handler(int signum);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (setup_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize socket
    if (setup_socket() != 0) {
        fprintf(stderr, "Failed to setup socket. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    // Accept incoming connections
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
    if (client_fd < 0) {
        perror("Accept failed");
        log_event("Error: Accept failed");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    printf("Connection accepted from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));

    // Handle client commands
    handle_client(client_fd);

    // Cleanup resources before exiting
    close(client_fd);
    close(server_fd);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Server shutdown gracefully.\n");
    return 0;
}

// Initialize pigpio library
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Setup TCP socket
int setup_socket() {
    struct sockaddr_in server_addr;

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        return 1;
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 5) < 0) {
        perror("Listen failed");
        close(server_fd);
        return 1;
    }

    return 0;
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        // Remove trailing whitespace
        int i = bytes_received - 1;
        while (i > 0 && buffer[i] == ' ') {
            i--;
        }
        buffer[i + 1] = '\0';

        // Process command
        if (strcmp(buffer, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1); // Turn relay ON
            log_event("Relay ON");
        } else if (strcmp(buffer, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0); // Turn relay OFF
            log_event("Relay OFF");
        } else {
            log_event("Invalid command");
        }
    }

    if (bytes_received < 0) {
        perror("Receive failed");
        log_event("Error: Receive failed");
    }

    // Close client socket
    close(client_socket);
}

// Log events to file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("relay_log.txt", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
    }

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        log_event("Server shutdown signal received");

        // Turn off the relay
        gpioWrite(GPIO_PIN, 0);

        // Close sockets
        if (client_fd != -1) {
            close(client_fd);
        }
        if (server_fd != -1) {
            close(server_fd);
        }

        // Close log file
        if (log_file != NULL) {
            fclose(log_file);
        }

        // Terminate pigpio
        gpioTerminate();

        exit(0);
    }
}

