        return -1;
    }

    *handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (*handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", *handle2);
        i2cClose(*handle1);
        return -1;
    }

    return 0;
}

