int start_measurement(int handle) {
    char buf[2] = {(START_MEASUREMENT_COMMAND >> 8) & 0xFF, START_MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
        return -1;
    }
    return 0;
}

