int read_flow_rate(int handle, float *flow_rate) {
    char buf[1] = {0x00}; // Dummy byte to trigger reading
    char data[3];
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error triggering read: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(handle, data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading flow rate: %d\n", result);
        return -1;
