#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor run duration (seconds)
#define MOTOR_RUN_DURATION 5

// Define dry-to-wet transition threshold
#define DRY_TO_WET_THRESHOLD 3

// Global variables
static volatile int running = 1;
static int dry_count = 0;
static time_t last_rain_time = 0;

// Function prototypes
int read_rain_sensor();
void control_motor(int state);
void log_message(int priority, const char *message);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
void control_motor(int state) {
    int result;

    result = gpioWrite(MOTOR_ENA_PIN, state);
    if (result != 0) {
        log_message(LOG_ERR, "Error writing to ENA pin");
        return;
    }

    result = gpioWrite(MOTOR_IN1_PIN, state);
    if (result != 0) {
        log_message(LOG_ERR, "Error writing to IN1 pin");
        gpioWrite(MOTOR_ENA_PIN, 0); // Ensure ENA is off on error
        return;
    }

    result = gpioWrite(MOTOR_IN2_PIN, !state); // Invert for correct motor direction
    if (result != 0) {
        log_message(LOG_ERR, "Error writing to IN2 pin");
        gpioWrite(MOTOR_ENA_PIN, 0); // Ensure ENA is off on error
        return;
    }
}

// Function to log messages using syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set RAIN_SENSOR_PIN mode");
        return 1;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN mode");
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN mode");
        return 1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN2_PIN mode");
        return 1;
    }

    // Set pull-up resistor on RAIN_SENSOR_PIN
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to cleanup GPIO
void cleanup_gpio() {
    // Stop the motor
    control_motor(0);

    // Set all GPIOs LOW
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);

    gpioTerminate();
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Log startup message
    log_message(LOG_INFO, "Rain window controller started");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read rain sensor
        int rain_detected = (read_rain_sensor() == 0); // LOW indicates rain

        // Log rain detection
        if (rain_detected) {
            log_message(LOG_INFO, "Rain detected");
            time_t current_time = time(NULL);
            if (last_rain_time == 0) {
                last_rain_time = current_time;
            }
        } else {
            // Check for dry-to-wet transition
            if (rain_detected && !dry_count) {
                dry_count = 0;
                last_rain_time = time(NULL);
            } else if (!rain_detected) {
                dry_count++;
                if (dry_count >= DRY_TO_WET_THRESHOLD) {
                    dry_count = 0; // Reset counter after 3 consecutive dry readings
                }
            } else {
                dry_count = 0; // Reset counter if rain is detected
            }

            // Log dry state
            if (!rain_detected) {
                log_message(LOG_INFO, "Dry");
            }
        }

        // Check if it's time to close the window
        if (rain_detected && (time(NULL) - last_rain_time) > 1) {
            // Close the window
            log_message(LOG_INFO, "Closing window");
            control_motor(1); // Start the motor
            gpioDelay(MOTOR_RUN_DURATION * 1000); // Run for 5 seconds
            control_motor(0); // Stop the motor
            log_message(LOG_INFO, "Window closed");
            last_rain_time = time(NULL); // Reset rain time after closing
        }

        gpioDelay(200); // Poll every 200 ms
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Log shutdown message
    log_message(LOG_INFO, "Rain window controller stopped");

    // Close syslog
    closelog();

    return 0;
}

