    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read PIR sensor
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds

            // Re-read PIR sensor after debounce
            if (read_pir_sensor()) {
                // Motion detected, activate floodlight
                if (activate_floodlight() == 0) {
                    // Log event
                    log_event("Motion Detected", "Floodlight activated");
                    printf("Motion detected! Floodlight activated.\n");
                } else {
                    log_event("Motion Detected", "Failed to activate floodlight");
                    fprintf(stderr, "Failed to activate floodlight\n");
                }

                // Wait for floodlight duration
                gpioDelay(FLOODLIGHT_DURATION * 1000000); // Convert seconds to microseconds

                // Deactivate floodlight
                if (deactivate_floodlight() == 0) {
                    // Log event
                    log_event("Floodlight Deactivated", "Floodlight deactivated");
                    printf("Floodlight deactivated.\n");
                } else {
                    log_event("Floodlight Deactivated", "Failed to deactivate floodlight");
                    fprintf(stderr, "Failed to deactivate floodlight\n");
                }
            }
        }

        gpioDelay(100000); // Poll every 100 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_floodlight();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

