#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define MPR121_SOFT_RESET 0x80
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCH_STATUS 0x00
#define MPR121_DEBOUNCE_REG 0x5B
#define MPR121_FFI_SFI_CDT_REG 0x2C
#define MPR121_AUTO_CONFIG_REG_START 0x7B
#define MHD_NHD_NCL_FDL_REG 0x5B
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x0B
#define TOUCH_STATUS_MASK 0x0FFF // Mask to get only the touch status

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void toggle_relay(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, MPR121_SOFT_RESET, 0x63);
    if (status < 0) {
        fprintf(stderr, "Error: Soft reset failed: %d\n", status);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Configure baseline filtering
    status = i2cWriteByteData(i2c_handle, MHD_NHD_NCL_FDL_REG, 0x10);
    if (status < 0) {
        fprintf(stderr, "Error: Baseline filtering configuration failed: %d\n", status);
        return -1;
    }

    // Set debounce
    status = i2cWriteByteData(i2c_handle, MPR121_DEBOUNCE_REG, 0x0A);
    if (status < 0) {
        fprintf(stderr, "Error: Debounce configuration failed: %d\n", status);
        return -1;
    }

    // Set FFI/SFI/CDT
    status = i2cWriteByteData(i2c_handle, MPR121_FFI_SFI_CDT_REG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: FFI/SFI/CDT configuration failed: %d\n", status);
        return -1;
    }

    // Auto-config
    status = i2cWriteByteData(i2c_handle, MPR121_AUTO_CONFIG_REG_START, 0x0C);
    if (status < 0) {
        fprintf(stderr, "Error: Auto-config failed: %d\n", status);
        return -1;
    }

    // Enable exactly 12 electrodes
    status = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C);
    if (status < 0) {
        fprintf(stderr, "Error: Enable electrodes failed: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read touch status from the MPR121
int read_touch_status(int i2c_handle) {
    int status = i2cReadWordData(i2c_handle, MPR121_TOUCH_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read touch status: %d\n", status);
        return -1;
    }
    return status & TOUCH_STATUS_MASK; // Mask to get only the touch status
}

// Function to toggle the relay
void toggle_relay(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    static int relay_state = 0; // 0 = OFF, 1 = ON

    if (level == 1) { // Rising edge
        uint32_t current_tick = gpioTick();
        if (current_tick - last_tick > 200000) { // 200ms debounce
            relay_state = !relay_state;
            gpioWrite(gpio, relay_state);
            printf("Relay toggled to %d\n", relay_state);
            last_tick = current_tick;
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on startup

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer interrupt (every 10ms)
    gpioSetTimerFuncEx(0, 10, toggle_relay, RELAY_GPIO);

    printf("MPR121 relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status >= 0) {
            printf("Touch status: 0x%04X\n", touch_status);
        }
        gpioDelay(10000); // 10ms delay
    }

    // Clean up
    gpioSetTimerFuncEx(0, 0, NULL, RELAY_GPIO); // Disable timer
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

