        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Accept client connection
        client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t *)&addrlen);
        if (client_fd < 0) {
            syslog(LOG_USER, "Accept failed: %s", strerror(errno));
            continue; // Continue accepting connections
        }

        syslog(LOG_USER, "Client connected from %s:%d", inet_ntoa(address.sin_addr), ntohs(address.sin_port));

