        pthread_t client_thread;
        if (pthread_create(&client_thread, NULL, (void *(*)(void *))handle_client, &client_fd) != 0) {
            syslog(LOG_USER, "Error creating client thread: %s", strerror(errno));
            close(client_fd);
        }
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

