        syslog(LOG_USER, "Error setting servo line low: %s", strerror(errno));
        return -1;
    }

    gettimeofday(&start, NULL);
    while (1) {
        gettimeofday(&end, NULL);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
        if (elapsed_us >= PWM_PERIOD_US) {
            break;
        }
    }

    if (gpiod_line_set_value(servo_line, 0) < 0) {
        syslog(LOG_USER, "Error setting servo line low: %s", strerror(errno));
        return -1;
    }

    gettimeofday(&start, NULL);
    while (1) {
        gettimeofday(&end, NULL);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
        if (elapsed_us >= PWM_PERIOD_US) {
            break;
        }
    }

    if (gpiod_line_set_value(servo_line, 1) < 0) {
        syslog(LOG_USER, "Error setting servo line high: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(servo_line, 0) < 0) {
        syslog(LOG_USER, "Error setting servo line low: %s", strerror(errno));
        return -1;
    }

    gettimeofday(&end, NULL);
    elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);

    if (elapsed_us >= PWM_PERIOD_US) {
        syslog(LOG_USER, "PWM period exceeded: %ld", elapsed_us);
        return -1;
    }

    return 0;
}

// Read PIR sensor
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        syslog(LOG_USER, "Error reading PIR line: %s", strerror(errno));
        return -1;
    }
    return value;
}

// Handle client connection
int handle_client(int client_fd) {
    int angle;
    char buffer[MAX_COMMAND_LENGTH];
    ssize_t bytes_sent;

    while (keep_running) {
        // Read command from client
        if (read_command_from_socket(client_fd, &angle) == 0) {
            // Set servo angle
            if (set_servo_angle(angle) != 0) {
                syslog(LOG_USER, "Error setting servo angle");
            }
        } else {
            syslog(LOG_USER, "Error reading command");
        }

        // Check for PIR sensor activity
        int pir_value = read_pir_sensor();
        if (pir_value == 1) {
            // Log PIR event
            log_event("PIR:1");
            bytes_sent = send(client_fd, "PIR:1", strlen("PIR:1"), 0);
            if (bytes_sent < 0) {
                syslog(LOG_USER, "Error sending PIR:1: %s", strerror(errno));
            }
        } else if (pir_value == 0) {
            // Log PIR event
            log_event("PIR:0");
            bytes_sent = send(client_fd, "PIR:0", strlen("PIR:0"), 0);
            if (bytes_sent < 0) {
                syslog(LOG_USER, "Error sending PIR:0: %s", strerror(errno));
            }
        } else {
            syslog(LOG_USER, "Error reading PIR sensor");
        }

        // Check for disconnection
        if (keep_running == 0) break;
        if (select(client_fd + 1, NULL, NULL, NULL, NULL) == -1) {
            syslog(LOG_USER, "Select error: %s", strerror(errno));
            break;
        }
    }

    // Close client socket
    close(client_fd);
    syslog(LOG_USER, "Client disconnected");
    return 0;
}

// Log event
void log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_USER, "Error opening log file: %s", strerror(errno));
        return;
    }

    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);

    syslog(LOG_USER, "%s %s", timestamp, message);
}

// Cleanup resources
void cleanup(void) {
    syslog(LOG_USER, "Cleaning up resources...");

    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (server_fd != -1) {
        close(server_fd);
    }
    if (pwm_thread != 0) {
        pthread_join(pwm_thread, NULL);
    }

    closelog();
}

int main(void) {
    int client_fd;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int angle;

    // Initialize syslog
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_USER, "GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Initialize socket
    server_fd = init_socket();
    if (server_fd < 0) {
        syslog(LOG_USER, "Socket initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Create PWM thread
    if (pthread_create(&pwm_thread, NULL, pwm_thread_func, NULL) != 0) {
        syslog(LOG_USER, "Error creating PWM thread: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Accept client connection
        client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t *)&addrlen);
        if (client_fd < 0) {
            syslog(LOG_USER, "Accept failed: %s", strerror(errno));
            continue; // Continue accepting connections
        }

        syslog(LOG_USER, "Client connected from %s:%d", inet_ntoa(address.sin_addr), ntohs(address.sin_port));

        // Handle client connection in a separate thread
        pthread_t client_thread;
        if (pthread_create(&client_thread, NULL, (void *(*)(void *))handle_client, &client_fd) != 0) {
            syslog(LOG_USER, "Error creating client thread: %s", strerror(errno));
            close(client_fd);
        }
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

