#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1000
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static int threshold = DEFAULT_THRESHOLD;
static float scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static long tare_offset = 0;
static int num_samples = 10; // Number of samples for startup tare

// Function prototypes
int read_hx711();
float calculate_weight(long raw_value, float tare_offset, float scale);
int control_solenoid(int state);
void signal_handler(int signal);
int init_gpio();
void cleanup_gpio();
void log_message(int priority, const char *message);
int parse_arguments(int argc, char *argv[]);

// Function to read data from HX711
int read_hx711() {
    int i, bit, data = 0;
    long start_time;

    // Wait for DOUT to go LOW
    int timeout = 0;
    while (gpioRead(HX711_DOUT) == 1 && timeout < 1000) {
        gpioDelay(1); // Wait 1 ms
        timeout++;
    }
    if (timeout >= 1000) {
        log_message(LOG_ERR, "HX711 timeout waiting for DOUT LOW");
        return 0; // Indicate error
    }

    start_time = time(NULL);

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Short delay
    }

    // Send one additional clock pulse for gain selection (Channel A, Gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 32-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight
float calculate_weight(long raw_value, float tare_offset, float scale) {
    return (raw_value - tare_offset) / scale;
}

// Function to control the solenoid
int control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    return 0;
}

// Cleanup GPIO
void cleanup_gpio() {
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
}

// Log message to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                return 1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Perform startup tare
    log_message(LOG_INFO, "Performing startup tare...");
    long raw_sum = 0;
    for (int i = 0; i < num_samples; i++) {
        long raw_value = read_hx711();
        if (raw_value == 0) {
            log_message(LOG_ERR, "Error reading HX711 during startup tare");
            cleanup_gpio();
            return 1;
        }
        raw_sum += raw_value;
        gpioDelay(10); // Small delay between samples
    }
    tare_offset = raw_sum / num_samples;
    log_message(LOG_INFO, "Startup tare complete. Offset: %ld", tare_offset);

    // Main loop
    while (running) {
        long raw_sum = 0;
        for (int i = 0; i < 5; i++) {
            long raw_value = read_hx711();
            if (raw_value == 0) {
                log_message(LOG_ERR, "Error reading HX711");
                continue; // Skip to the next iteration
            }
            raw_sum += raw_value;
            gpioDelay(10); // Small delay between samples
        }
        float average_raw = raw_sum / 5;
        float weight = calculate_weight(average_raw, tare_offset, scale);

        char log_message_buffer[100];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Weight: %.2f grams", weight);
        log_message(LOG_INFO, log_message_buffer);

        if (weight > threshold) {
            log_message(LOG_INFO, "Weight exceeds threshold, activating solenoid");
            control_solenoid(1); // Activate solenoid
            gpioDelay(duration);  // Keep solenoid active for specified duration
            control_solenoid(0); // Deactivate solenoid
            log_message(LOG_INFO, "Solenoid deactivated");
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup and exit
    cleanup_gpio();
    closelog();
    return 0;
}

