#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <unistd.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/lights/control"
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_KEEPALIVE 60
#define MQTT_QOS 0
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    syslog(LOG_USER, "Signal received: %d. Shutting down...", signum);
    running = 0;
}

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF (LOW)
    syslog(LOG_USER, "GPIO %d initialized as output. Current state: OFF", GPIO_PIN);
    return 0;
}

// Function to set the relay state
void set_relay_state(int state) {
    if (state == 0) {
        gpioWrite(GPIO_PIN, 0); // OFF
        syslog(LOG_USER, "Relay set to OFF");
    } else {
        gpioWrite(GPIO_PIN, 1); // ON
        syslog(LOG_USER, "Relay set to ON");
    }
}

// Function to handle MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0 && message->payload != NULL) {
        char *payload = (char *)message->payload;
        char *endptr;

        int state = (int)strtol(payload, &endptr, 10);

        if (endptr == payload) {
            syslog(LOG_ERR, "Invalid state value: %s", payload);
        } else if (*endptr != '\0') {
            syslog(LOG_ERR, "Payload contains non-terminating NUL character: %s", payload);
        } else {
            if (state == 0 || state == 1) {
                set_relay_state(state);
            } else {
                syslog(LOG_ERR, "Invalid state value: %d", state);
            }
        }
    } else {
        syslog(LOG_ERR, "Empty payload received: %s", message->topic);
    }
}

// Function to connect to the MQTT broker
int connect_mqtt() {
    int rc;

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Out of memory.");
        return -1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, message_callback);
    mosquitto_subscribe_callback_set(mosq, NULL);

    rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    syslog(LOG_USER, "Connected to MQTT broker and subscribed to topic: %s", MQTT_TOPIC);
    return 0;
}

// Function to disconnect from the MQTT broker
void disconnect_mqtt() {
    int rc = mosquitto_disconnect(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to disconnect from MQTT broker: %s", mosquitto_strerror(rc));
    }
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    syslog(LOG_USER, "Disconnected from MQTT broker.");
}

int main() {
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_USER, "Starting relay controller...");

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    // Connect to MQTT broker
    if (connect_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT connection failed. Exiting.");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        int rc = mosquitto_loop(mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s. Retrying connection in 5 seconds.", mosquitto_strerror(rc));
            disconnect_mqtt();
            sleep(5);
            if (connect_mqtt() != 0) {
                syslog(LOG_ERR, "MQTT reconnection failed. Exiting.");
                running = 0; // Exit loop if reconnection fails
            }
        }
    }

    // Cleanup
    set_relay_state(0); // Ensure relay is OFF on exit
    disconnect_mqtt();
    gpioTerminate();
    closelog();

    syslog(LOG_USER, "Relay controller stopped.");
    return 0;
}

