#define SERVO4_INITIAL_WIDTH 500
#define SERVO5_INITIAL_WIDTH 2500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Error: Pulse width out of range (500-2500 us). Value: %d\n", pulse_width);
        return -1; // Indicate an error
    }

    if (gpioPWM(gpio_pin, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set PWM for GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return 0; // Indicate success
}

int main() {
