        return 1;
    }
    if (set_servo_pulse_width(SERVO2_PIN, SERVO2_INITIAL_WIDTH) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_servo_pulse_width(SERVO3_PIN, SERVO3_INITIAL_WIDTH) != 0) {
