#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DAWN 200
#define LUX_THRESHOLD_DUSK 50
#define HYSTERESIS 10
#define I2C_BUS 1
#define ONE_TIME_HIGH_RES_MODE 0x10 // Corrected value

// Global variables
static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int read_bh1750(int i2c_handle, float *lux);
int control_relay(int gpio, int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize relay to OFF (LOW)
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(int i2c_handle, float *lux) {
    char config_cmd = ONE_TIME_HIGH_RES_MODE; // Corrected value
    char data[2];
    int result;

    // Send configuration command
    result = i2cWriteByteData(i2c_handle, 0x00, config_cmd); // BH1750 address is 0x23, but we are writing to register 0x00
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, data, 2); // BH1750 address is 0x23, but we are reading from register 0x00
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    // Convert data to lux
    unsigned int raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control relay (ON/OFF)
int control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state == 1 ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(GPIO_RELAY, 0); // Turn off relay
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON
    int last_lux = 0; // Store the last lux value for hysteresis

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Chicken coop lighting system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read lux value
        if (read_bh1750(i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Control relay based on lux value and hysteresis
            if (lux < (last_lux + HYSTERESIS) && lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
                control_relay(GPIO_RELAY, 1);
                relay_state = 1;
            } else if (lux > (last_lux - HYSTERESIS) && lux > LUX_THRESHOLD_DUSK && relay_state == 1) {
                control_relay(GPIO_RELAY, 0);
                relay_state = 0;
            }

            // Log data
            log_data(lux, relay_state);

            // Update last lux value
            last_lux = (int)lux;
        } else {
            fprintf(stderr, "Failed to read lux value\n");
            log_data(-1, relay_state); // Log error
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

