#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define HYSTERESIS 0.5
#define SAMPLE_INTERVAL_SEC 1
#define DEBOUNCE_TIMEOUT_MS 100

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;
int running = 1;

// Structure to pass data to the ISR
typedef struct {
    int gpio;
    int level;
    uint32_t tick;
} isr_data_t;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
float calculate_lpm(int pulse_count);
void control_solenoid(float lpm);
void log_data(float lpm, int solenoid_state);
void signal_handler(int signal);
void cleanup();

// ISR data structure
isr_data_t isr_data;

// Function to increment pulse count safely
void increment_pulse_count() {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Interrupt service routine (ISR)
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge
        increment_pulse_count();
    }
}

// Function to calculate LPM
float calculate_lpm(int pulse_count) {
    return (pulse_count / PULSES_PER_LITER) * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(float lpm) {
    static int solenoid_state = 1; // 1 = open, 0 = closed

    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1) {
        gpioWrite(SOLENOID_GPIO, 0); // Close solenoid
        solenoid_state = 0;
        log_data(lpm, solenoid_state);
    } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0) {
        gpioWrite(SOLENOID_GPIO, 1); // Open solenoid
        solenoid_state = 1;
        log_data(lpm, solenoid_state);
    }
}

// Function to log data to file
void log_data(float lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "Open" : "Closed");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    log_data(0.0, -1); // Log shutdown event
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    running = 0; // Stop the main loop
    gpioWrite(SOLENOID_GPIO, 1); // Ensure solenoid is open on exit
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", FLOW_SENSOR_GPIO);
        cleanup();
        return 1;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", SOLENOID_GPIO);
        cleanup();
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up ISR
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT_MS, pulse_counter_isr, &isr_data) != 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d\n", FLOW_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read pulse count
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next sample
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        float lpm = calculate_lpm(current_pulse_count);

        // Control solenoid
        control_solenoid(lpm);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

