#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

// Configuration
#define CONFIG_FILE "config.ini"
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVO_MIN_PULSEWIDTH 1000
#define DEFAULT_SERVO_MAX_PULSEWIDTH 2000
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18

// Global variables (minimize usage)
static volatile int running = 1;
static FILE *log_file = NULL;
static int server_fd = -1;

// Structure to hold configuration data
typedef struct {
    char server_ip[20];
    int server_port;
    float calibration_factor;
} Config;

// Function prototypes
int read_config(Config *config);
int initialize_gpio();
int read_hx711(int *raw_value);
float calibrate_weight(int raw_value, float calibration_factor);
int set_servo_pulsewidth(int pulsewidth);
int dispense_ingredient(float target_weight, float calibration_factor);
int handle_client(int client_fd);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from file
int read_config(Config *config) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        // Use default values
        strcpy(config->server_ip, DEFAULT_SERVER_IP);
        config->server_port = DEFAULT_SERVER_PORT;
        config->calibration_factor = DEFAULT_CALIBRATION_FACTOR;
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "server_ip") == 0) {
                strncpy(config->server_ip, value, sizeof(config->server_ip) - 1);
                config->server_ip[sizeof(config->server_ip) - 1] = '\0';
            } else if (strcmp(key, "server_port") == 0) {
                config->server_port = atoi(value);
            } else if (strcmp(key, "calibration_factor") == 0) {
                config->calibration_factor = atof(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    return 0;
}

// Function to read raw data from HX711
int read_hx711(int *raw_value) {
    int i;
    int data = 0;

    // Wait for the HX711 to be ready (DATA pin LOW)
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "HX711 not ready (DATA pin HIGH for %d attempts)\n", timeout);
        return -1; // Indicate error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // Short delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    *raw_value = data;
    return 0;
}

// Function to calibrate the raw value
float calibrate_weight(int raw_value, float calibration_factor) {
    return (float)raw_value / calibration_factor;
}

// Function to set the servo pulse width
int set_servo_pulsewidth(int pulsewidth) {
    if (pulsewidth < 1000 || pulsewidth > 2000) {
        fprintf(stderr, "Invalid pulsewidth: %d\n", pulsewidth);
        return -1;
    }
    gpioServo(SERVO_PIN, pulsewidth);
    return 0;
}

// Function to dispense the ingredient
int dispense_ingredient(float target_weight, float calibration_factor) {
    int raw_value;
    float actual_weight;

    // Open the servo
    if (set_servo_pulsewidth(DEFAULT_SERVO_MIN_PULSEWIDTH) != 0) {
        fprintf(stderr, "Failed to open servo\n");
        return -1;
    }

    // Wait for stabilization
    gpioDelay(1000); // 1 second

    // Read the raw value from HX711
    if (read_hx711(&raw_value) != 0) {
        fprintf(stderr, "Failed to read HX711\n");
        return -1;
    }

    // Calibrate the weight
    actual_weight = calibrate_weight(raw_value, calibration_factor);

    // Close the servo
    if (set_servo_pulsewidth(DEFAULT_SERVO_MAX_PULSEWIDTH) != 0) {
        fprintf(stderr, "Failed to close servo\n");
        return -1;
    }

    return (int)actual_weight;
}

// Function to handle client connections
int handle_client(int client_fd) {
    float target_weight;
    int actual_weight;

    if (recv(client_fd, &target_weight, sizeof(float), 0) != sizeof(float)) {
        perror("Error receiving target weight");
        log_event("Error receiving target weight from client");
        return -1;
    }

    actual_weight = dispense_ingredient(target_weight, DEFAULT_CALIBRATION_FACTOR);

    char response[50];
    snprintf(response, sizeof(response), "Actual weight: %.2f grams", actual_weight);

    send(client_fd, response, strlen(response), 0);
    log_event(response);

    close(client_fd);
    return 0;
}

// Function to log events
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (server_fd != -1) {
        close(server_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    Config config;
    int client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);

    // Read configuration
    if (read_config(&config) != 0) {
        strcpy(config.server_ip, DEFAULT_SERVER_IP);
        config.server_port = DEFAULT_SERVER_PORT;
        config.calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
