#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce time
#define DEFAULT_DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static int debounce_time_ms = DEFAULT_DEBOUNCE_TIME;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
int log_relay_state(int state);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN to input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to RELAY_PIN\n");
        return 1;
    }
    return 0;
}

// Function to log the relay state with a timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Turn off the relay
    control_relay(0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_time_ms = atoi(optarg);
                if (debounce_time_ms <= 0) {
                    fprintf(stderr, "Invalid debounce time. Using default value.\n");
                    debounce_time_ms = DEFAULT_DEBOUNCE_TIME;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
                return 1;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 0; // Store the last known touch state

    printf("Touch-controlled relay started. Debounce time: %d ms\n", debounce_time_ms);

    // Main loop
    while (running) {
        int touch_state = read_touch_sensor();

        if (touch_state == 1 && last_touch_state == 0) {
            // Rising edge detected
            int current_relay_state = control_relay(!control_relay(0)); // Toggle the relay
            log_relay_state(current_relay_state);
            last_touch_state = 1; // Update last touch state
            gpioDelay(debounce_time_ms * 1000); // Debounce delay
        } else if (touch_state == 0 && last_touch_state == 1) {
            // Falling edge detected, reset last touch state
            last_touch_state = 0;
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_relay(0);
    gpioTerminate();

    return 0;
}

