#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_INITIAL_PULSE 1500
#define SERVO_INCREMENT 10
#define SERVO_DECREMENT 10
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int setup_termios() {
    struct termios tty;
    if (tcgetattr(STDIN_FILENO, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    tty.c_lflag &= ~(ICANON | ECHO);
    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(STDIN_FILENO, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

int restore_termios() {
    struct termios tty;
    if (tcgetattr(STDIN_FILENO, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    tty.c_lflag |= (ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (setup_termios() != 0) {
        gpioTerminate();
        return 1;
    }

    int current_angle = 90;
    int pulse_width = SERVO_INITIAL_PULSE;

    signal(SIGINT, signal_handler);

    while (!terminate) {
        if (getchar() == '+') {
            current_angle += SERVO_INCREMENT;
            if (current_angle > 180) current_angle = 180;
            pulse_width = SERVO_MIN_PULSE + (int)(((float)current_angle / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
            gpioServo(SERVO_PIN, pulse_width);
            printf("Angle: %d\n", current_angle);
        } else if (getchar() == '-') {
            current_angle -= SERVO_DECREMENT;
            if (current_angle < 0) current_angle = 0;
            pulse_width = SERVO_MIN_PULSE + (int)(((float)current_angle / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
            gpioServo(SERVO_PIN, pulse_width);
            printf("Angle: %d\n", current_angle);
        } else if (getchar() == 'q') {
            break;
        }
    }

    gpioServo(SERVO_PIN, 0); // Stop PWM
    gpioTerminate();
    restore_termios();
    return 0;
}

