    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_LINE);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(*chip);
        return -1;
    }

    int ret = gpiod_line_request_input_flags(*line, "motor_rpm", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(-ret));
        gpiod_chip_close(*chip);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to read the GPIO line value
int read_gpio(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(-value));
        return -1;
    }
    return value;
}

// Function to count pulses with debouncing
int count_pulses(struct gpiod_line *line, int *pulse_count) {
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        int value = read_gpio(line);
        if (value < 0) {
            return -1; // Propagate error
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000;

        if (value == 1) { // Rising edge
            if (elapsed_ms >= DEBOUNCE_MS) {
                (*pulse_count)++;
                return 0; // Return after one pulse
            }
        }

        usleep(1000); // Check every 1 ms
    }

    return -1; // Exit loop due to signal
}

