    log_file = fopen("motor_rpm.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    int pulse_count = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    printf("Monitoring motor RPM... (Ctrl+C to exit)\n");

    while (running) {
        if (count_pulses(line, &pulse_count) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double time_interval = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;
            if (time_interval >= SAMPLE_INTERVAL_SEC) {
                double rpm = calculate_rpm(pulse_count, time_interval);
                if (log_rpm(rpm) != 0) {
                    fprintf(stderr, "Error logging RPM.\n");
                }
                printf("RPM: %.2f\n", rpm);
                pulse_count = 0;
                clock_gettime(CLOCK_MONOTONIC, &start_time);
            }
        } else {
            fprintf(stderr, "Error counting pulses.\n");
        }
        usleep(10000); // Sleep for 10 ms to avoid busy-waiting
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (line != NULL) {
        gpiod_line_release(line);
    }

    printf("Exiting.\n");
    return 0;
}

