#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int touch_state, relay_state = 0;
    unsigned int last_touch_time = 0;
    int failsafe_active = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        touch_state = gpioRead(TOUCH_SENSOR_GPIO);

        if (touch_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO%d\n", TOUCH_SENSOR_GPIO);
            gpioTerminate();
            return 1;
        }

        if (touch_state == 1) {
            unsigned int current_time = gpioTick();

            if (!failsafe_active) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                printf("Relay state: %s\n", relay_state ? "ON" : "OFF");
                last_touch_time = current_time;
                failsafe_active = 1;
            } else {
                if ((current_time - last_touch_time) > 1000000) { // 10 seconds in microseconds
                    gpioWrite(RELAY_GPIO, 0); // Force relay OFF
                    relay_state = 0;
                    printf("Relay forced OFF due to failsafe.\n");
                    failsafe_active = 0;
                }
            }
        } else {
            failsafe_active = 0;
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup before exiting
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

