int disable_valve(int disable) {
    if (gpioWrite(23, disable) != 0) {
        fprintf(stderr, "Error disabling valve\n");
        return -1;
    }
    return 0;
}

// Function to log data to a file
int log_data(double flow_rate, int pwm_duty_cycle) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    if (log_file != NULL) {
        fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, pwm_duty_cycle);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        target_flow_rate = strtod(argv[1], &endptr);
        if (*endptr != '\0' || target_flow_rate < TARGET_FLOW_MIN || target_flow_rate > TARGET_FLOW_MAX) {
            fprintf(stderr, "Error: Invalid target flow rate. Using default: %.2f L/min\n", TARGET_FLOW_DEFAULT);
            target_flow_rate = TARGET_FLOW_DEFAULT;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", VALVE_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to input mode\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range for GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return 1;
    }

    // Initialize valve position to 0
    if (set_valve_position(0) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize valve enable to HIGH
    if (enable_valve(1) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        disable_valve(1);
        gpioTerminate();
        return 1;
    }

    // Register interrupt handler
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register interrupt handler\n");
        fclose(log_file);
        disable_valve(1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Sample flow rate
        int pulse_count_sample = pulse_count;
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
        double flow_rate = calculate_flow_rate(pulse_count_sample, SAMPLE_INTERVAL_MS);

        // Calculate error
        double error = target_flow_rate - flow_rate;

        // Calculate PWM duty cycle
        double pwm_duty_cycle = calculate_pwm_duty_cycle(error, Kp, target_flow_rate);

        // Set valve position
        if (set_valve_position((int)pwm_duty_cycle) != 0) {
            fprintf(stderr, "Error setting valve position\n");
        }

        // Log data
        if (log_data(flow_rate, (int)pwm_duty_cycle) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Update pulse count
        pulse_count = 0; // Reset pulse count for the next sample

        // Print flow rate and PWM duty cycle to console
        printf("Flow Rate: %.2f L/min, PWM Duty Cycle: %d\n", flow_rate, (int)pwm_duty_cycle);
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    disable_valve(1);
    set_valve_position(0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

