#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define valid tag
const unsigned char valid_tag[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Global variables
FILE *log_file = NULL;
int spi_fd = -1;

// Function prototypes
int read_rfid();
int authenticate_tag();
int read_button();
void engage_lock(int lock_pin);
void disengage_lock(int lock_pin);
void log_access(const char *message);
void signal_handler(int signal);

// Function to read RFID tag via SPI
int read_rfid() {
    unsigned char data[10];
    int result = spiXfer(spi_fd, data, data, 10);

    if (result != 10) {
        log_access("SPI read error");
        return -1; // Indicate error
    }

    // Check if no tag is present (all bytes are 0)
    if (data[0] == 0 && data[1] == 0 && data[2] == 0 && data[3] == 0 && data[4] == 0 && data[5] == 0 && data[6] == 0 && data[7] == 0 && data[8] == 0 && data[9] == 0) {
        log_access("No tag present");
        return -1; // Indicate no tag
    }

    // Check if the tag is valid
    for (int i = 0; i < 10; i++) {
        if (data[i] != valid_tag[i]) {
            log_access("Invalid tag");
            return -1; // Indicate invalid tag
        }
    }

    return 0; // Indicate success
}

// Function to authenticate the tag
int authenticate_tag() {
    if (read_rfid() != 0) {
        return -1; // Tag authentication failed
    }
    return 0; // Tag authentication successful
}

// Function to read the button press with debouncing
int read_button() {
    int button_state = digitalRead(BUTTON_PIN);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    if (button_state != digitalRead(BUTTON_PIN)) {
        return 0; // Button not pressed
    }
    return (button_state == LOW); // Button is pressed (active-low)
}

// Function to engage the lock
void engage_lock(int lock_pin) {
    gpioWrite(lock_pin, 1); // Engage the lock (HIGH)
}

// Function to disengage the lock
void disengage_lock(int lock_pin) {
    gpioWrite(lock_pin, 0); // Disengage the lock (LOW)
}

// Function to log access attempts
void log_access(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Release both locks
    engage_lock(LOCK1_PIN);
    engage_lock(LOCK2_PIN);

    // Close SPI
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    // Open log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Two-factor authentication system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Authenticate the tag
        if (authenticate_tag() == 0) {
            printf("Tag authentication successful\n");

            // Read the button press
            if (read_button() == 1) {
                printf("Button pressed\n");

                // Engage both locks
                engage_lock(LOCK1_PIN);
                engage_lock(LOCK2_PIN);

                // Log the access attempt
                log_access("Successful authentication");

                // Disengage both locks
                disengage_lock(LOCK1_PIN);
                disengage_lock(LOCK2_PIN);

                // Re-engage both locks
                engage_lock(LOCK1_PIN);
                engage_lock(LOCK2_PIN);
            } else {
                log_access("Button press without valid tag");
            }
        } else {
            log_access("Tag authentication failed");
        }

        gpioDelay(1000); // Delay for 1 second
    }

    return 0;
}

