#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define ENA 23
#define IN1 24
#define IN2 25

// Motor 2
#define ENB 12
#define IN3 16
#define IN4 20

// Encoder 1
#define ENCA 5
#define ENCB 6

// Encoder 2
#define ENCA2 26
#define ENCB2 19

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME 0.1 // 100ms

// Target RPM
#define TARGET_RPM1 60.0
#define TARGET_RPM2 60.0

// Global Variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
volatile int encoder1_direction = 1; // 1 for clockwise, -1 for counter-clockwise
volatile int encoder2_direction = 1;
double integral1 = 0, integral2 = 0;
double previous_error1 = 0, previous_error2 = 0;
double output1, output2;
FILE *log_file = NULL;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void encoder1_isr(int gpio, int level, uint32_t tick, void *user);
void encoder2_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int count, double direction);
double pid_control(double setpoint, double actual, double *integral, double *previous_error, double kp, double ki, double kd, double sample_time);
void set_motor_speed(int motor, double speed);
void stop_motor(int motor);
void signal_handler(int signal);
void log_data(double rpm1, double pid1, double pid2, double pid3, double output1, double output2);

// Function to calculate RPM
double calculate_rpm(int count, double direction) {
    double rpm = (count * 60.0) / (direction == 1 ? 600.0 : 600.0); // 600 pulses/rev
    return rpm;
}

// PID Control Function
double pid_control(double setpoint, double actual, double *integral, double *previous_error, double kp, double ki, double kd, double sample_time) {
    double error = setpoint - actual;
    *integral += error * sample_time;
    double derivative = (error - *previous_error) / sample_time;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set motor speed using software PWM
void set_motor_speed(int motor, double speed) {
    if (motor == 1) {
        gpioPWM(ENA, (int)(speed * 255.0)); // ENA controls motor 1
    } else if (motor == 2) {
        gpioPWM(ENB, (int)(speed * 255.0)); // ENB controls motor 2
    }
}

// Function to stop a motor
void stop_motor(int motor) {
    if (motor == 1) {
        gpioPWM(ENA, 0); // Stop motor 1
    } else if (motor == 2) {
        gpioPWM(ENB, 0); // Stop motor 2
    }
}

// Encoder Interrupt Service Routine
void encoder1_isr(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&encoder1_mutex);
    if (gpio == ENCA) {
        encoder1_count++;
    } else if (gpio == ENCB) {
        encoder1_count--;
    }
    pthread_mutex_unlock(&encoder1_mutex);
}

void encoder2_isr(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&encoder2_mutex);
    if (gpio == ENCA2) {
        encoder2_count++;
    } else if (gpio == ENCB2) {
        encoder2_count--;
    }
    pthread_mutex_unlock(&encoder2_mutex);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_motor(1);
    stop_motor(2);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Logging Function
void log_data(double rpm1, double pid1, double pid2, double pid3, double output1, double output2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, rpm1, pid1, pid2, pid3, output1, output2);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);
    gpioSetMode(ENCA, PI_INPUT);
    gpioSetMode(ENCB, PI_INPUT);
    gpioSetMode(ENCA2, PI_INPUT);
    gpioSetMode(ENCB2, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(ENA, 100); // 100 Hz
    gpioSetPWMfrequency(ENB, 100); // 100 Hz

    // Open log file
    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,RPM1,PID1,PID2,PID3,Output1,Output2\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupts for encoders
    gpioSetISRFuncEx(ENCA, EITHER_EDGE, 0, encoder1_isr, NULL);
    gpioSetISRFuncEx(ENCB, EITHER_EDGE, 0, encoder1_isr, NULL);
    gpioSetISRFuncEx(ENCA2, EITHER_EDGE, 0, encoder2_isr, NULL);
    gpioSetISRFuncEx(ENCB2, EITHER_EDGE, 0, encoder2_isr, NULL);

    // Main control loop
    while (1) {
        // Read encoder counts
        pthread_mutex_lock(&encoder1_mutex);
        int current_count1 = encoder1_count;
        encoder1_count = 0; // Reset count
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        int current_count2 = encoder2_count;
        encoder2_count = 0; // Reset count
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate RPM
        double rpm1 = calculate_rpm(current_count1, encoder1_direction);
        double rpm2 = calculate_rpm(current_count2, encoder2_direction);

        // Calculate PID outputs
        double pid1 = pid_control(TARGET_RPM1, rpm1, &integral1, &previous_error1, KP, KI, KD, SAMPLE_TIME);
        double pid2 = pid_control(TARGET_RPM2, rpm2, &integral2, &previous_error2, KP, KI, KD, SAMPLE_TIME);

        // Calculate PID components
        double pid3 = KP * (TARGET_RPM1 - rpm1);
        double pid4 = KI * (TARGET_RPM1 - rpm1) * SAMPLE_TIME;
        double pid5 = KD * (TARGET_RPM1 - rpm1 - previous_error1) / SAMPLE_TIME;

        // Calculate motor speeds
        double speed1 = pid1;
        double speed2 = pid2;

        // Set motor speeds
        set_motor_speed(1, speed1);
        set_motor_speed(2, speed2);

        // Log data
        log_data(rpm1, pid3, pid4, pid5, pid1, pid2);

        // Sleep for 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    fclose(log_file);
    gpioTerminate();
    return 0;
}

