#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// GPIO pin for relay control
#define RELAY_PIN 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int mpr121_read_touch_status(int i2c_handle);
void relay_control(int gpio_pin, int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Structure to hold MPR121 configuration
typedef struct {
    uint8_t soft_reset;
    uint8_t filter_config;
    uint8_t touch_thresholds[12];
    uint8_t release_thresholds[12];
    uint8_t run_mode;
} mpr121_config_t;

// Function to write a byte to an MPR121 register
int mpr121_write_register(int i2c_handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from an MPR121 register
int mpr121_read_register(int i2c_handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    mpr121_config_t config;

    // Soft reset
    config.soft_reset = 0x63; // Reset command
    if (mpr121_write_register(i2c_handle, 0x80, config.soft_reset) != 0) return -1;
    gpioDelay(100); // Wait for reset

    // Electrode configuration
    for (int i = 0; i < 12; i++) {
        config.touch_thresholds[i] = 0x30; // Touch threshold
        config.release_thresholds[i] = 0x10; // Release threshold
    }

    // Run mode configuration
    config.run_mode = 0x0C; // Enable all electrodes
    if (mpr121_write_register(i2c_handle, 0x5E, config.run_mode) != 0) return -1;

    // Set filter configuration
    config.filter_config = 0x10; // Set filter configuration
    if (mpr121_write_register(i2c_handle, 0x5B, config.filter_config) != 0) return -1;

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int i2c_handle) {
    uint8_t touch_status_low, touch_status_high;
    if (mpr121_read_register(i2c_handle, 0x00, &touch_status_low) != 0) return -1;
    if (mpr121_read_register(i2c_handle, 0x01, &touch_status_high) != 0) return -1;

    return (touch_status_high << 8) | touch_status_low;
}

// Function to control the relay
void relay_control(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log the relay state
void log_relay_state(int state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int last_relay_state = 0; // Track the last relay state
    while (!terminate) {
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status\n");
            gpioDelay(50); // Wait before retrying
            continue;
        }

        // Check if any electrode is touched
        if (touch_status > 0) {
            // Toggle relay state
            int new_relay_state = !last_relay_state;
            relay_control(RELAY_PIN, new_relay_state);
            last_relay_state = new_relay_state;

            // Log relay state change
            log_relay_state(new_relay_state);
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup
    relay_control(RELAY_PIN, 0); // Deactivate relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

