#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

// Define GPIO pins
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define schedule parameters
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define VALVE1_PAUSE_MS 5000
#define VALVE2_PAUSE_MS 10000

// Define log file path
#define LOG_FILE "valve_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int request_gpio_line(int gpio, struct gpiod_line **line);
int set_gpio_value(struct gpiod_line *line, int value);
int unexport_gpio_line(struct gpiod_line *line);
int log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        program_running = 0;
        printf("Received signal %d, shutting down...\n", sig);
    }
}

// Initialize GPIO
int initialize_gpio() {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines
    ret = request_gpio_line(&valve1_line, VALVE1_GPIO);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for valve 1: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = request_gpio_line(&valve2_line, VALVE2_GPIO);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for valve 2: %s\n", strerror(-ret));
        gpiod_line_release(valve1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Request a GPIO line
int request_gpio_line(int gpio, struct gpiod_line **line) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "valve_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        perror("Error getting GPIO line");
        return -1;
    }

    int ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Set GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Unexport a GPIO line
int unexport_gpio_line(struct gpiod_line *line) {
    int ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    return 0;
}

// Log an event to the log file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file not initialized.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (valve1_line) {
        unexport_gpio_line(valve1_line);
    }
    if (valve2_line) {
        unexport_gpio_line(valve2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Greenhouse water distribution system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate Valve 1
        if (set_gpio_value(valve1_line, 1) < 0) {
            log_event("Error activating Valve 1");
        } else {
            log_event("Valve 1 activated");
            usleep(VALVE1_DURATION_MS * 1000); // Convert ms to microseconds
            if (set_gpio_value(valve1_line, 0) < 0) {
                log_event("Error deactivating Valve 1");
            } else {
                log_event("Valve 1 deactivated");
            }
        }

        // Pause
        usleep(VALVE1_PAUSE_MS * 1000); // Convert ms to microseconds

        // Activate Valve 2
        if (set_gpio_value(valve2_line, 1) < 0) {
            log_event("Error activating Valve 2");
        } else {
            log_event("Valve 2 activated");
            usleep(VALVE2_DURATION_MS * 1000); // Convert ms to microseconds
            if (set_gpio_value(valve2_line, 0) < 0) {
                log_event("Error deactivating Valve 2");
            } else {
                log_event("Valve 2 deactivated");
            }
        }

        // Pause
        usleep(VALVE2_PAUSE_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Greenhouse water distribution system stopped.\n");
    return 0;
}

