#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_CONFIG 0x20
#define ELE_EN 0x20
#define RELAY_ON 1
#define RELAY_OFF 0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int mpr121_read_touch_status(int i2c_handle);
void relay_toggle(int relay_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init(int i2c_handle) {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode.\n");
        return -1;
    }

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), TOUCH_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), RELEASE_THRESHOLD) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Configure filter/charge time
    if (i2cWriteByteData(i2c_handle, 0x5E, FILTER_CONFIG) < 0) {
        fprintf(stderr, "Error: Failed to configure filter/charge time.\n");
        return -1;
    }

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5C, ELE_EN) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes.\n");
        return -1;
    }

    // Enter run mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to enter run mode.\n");
        return -1;
    }

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int i2c_handle) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }
    return ((int)buf[1] << 8) | (int)buf[0];
}

// Relay toggle function
void relay_toggle(int relay_pin) {
    int current_state = gpioRead(relay_pin);
    gpioWrite(relay_pin, !current_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, RELAY_OFF); // Initialize relay to OFF

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int touch_status = mpr121_read_touch_status(i2c_handle);
        if (touch_status > 0) {
            relay_toggle(RELAY_PIN);
            printf("Relay toggled, touch status: %d\n", touch_status);
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_PIN, RELAY_OFF); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

