#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define RELAY_PIN 18

// Define unlock duration (milliseconds)
#define UNLOCK_DURATION 500

// Define rate limit window (milliseconds)
#define RATE_LIMIT_WINDOW 2000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_unlock_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor(int gpio);
int activate_relay(int gpio, int duration_ms);
int log_event(const char *event);
void cleanup(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);

    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Function to read PIR sensor value
int read_pir_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to activate the relay
int activate_relay(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Activate relay
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio, 0); // Deactivate relay
    return 0;
}

// Function to log events to file
int log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write to file
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    running = 0;
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read PIR sensors
        int sensor1_value = read_pir_sensor(PIR_SENSOR_1);
        int sensor2_value = read_pir_sensor(PIR_SENSOR_2);

        // Check for motion detection
        if (sensor1_value == 1 || sensor2_value == 1) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Check if it's the first motion detected in the rate limit window
            if (last_unlock_time == 0 || (time(NULL) - last_unlock_time) * 1000 >= RATE_LIMIT_WINDOW) {
                // Activate relay
                if (activate_relay(RELAY_PIN, UNLOCK_DURATION) == 0) {
                    // Log event
                    log_event("Door unlocked");
                    last_unlock_time = time(NULL);
                } else {
                    log_event("Error activating relay");
                }
            } else {
                // Log rate-limited event
                log_event("Rate limited: Door unlock attempt");
            }
        }

        gpioDelay(50 * 1000); // Delay for 50ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

