#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define the range for PWM duty cycles (0-255)
#define PWM_RANGE 255

// Define the range for durations (milliseconds)
#define DURATION_RANGE 200

// Define the minimum and maximum number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Define the minimum and maximum duration for each step
#define MIN_DURATION 50
#define MAX_DURATION 200

// Global variables
volatile sig_atomic_t shutdown_flag = 0;

// Function prototypes
void signal_handler(int signal);
void generate_pattern(int *steps, int *durations, int num_steps);
void play_pattern(int *steps, int *durations, int num_steps);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    shutdown_flag = 1;
    printf("\nCaught signal %d, shutting down...\n", signal);
}

// Function to generate a random pattern
void generate_pattern(int *steps, int *durations, int num_steps) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate random steps and durations
    for (int i = 0; i < num_steps; i++) {
        steps[i] = rand() % PWM_RANGE;
        durations[i] = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;
    }
}

// Function to play a pattern
