#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define THRESHOLD 10.0 // kg
#define TIMEOUT_US 500000 // 0.5 seconds in microseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static float scale_factor = 1.0;
static float offset = 0.0;

// Function prototypes
int read_hx711();
float convert_to_weight(int raw_value, float scale, float offset);
void control_solenoid(int state);
void log_weight(float weight);
void calibrate_sensor();
void signal_handler(int signal);
int load_calibration_data();

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for HX711 data pin to go low\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Sign extend if negative
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw data to weight
float convert_to_weight(int raw_value, float scale, float offset) {
    return (raw_value - offset) / scale;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
}

// Function to log weight readings with timestamp
void log_weight(float weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %.2f kg\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to calibrate the sensor
void calibrate_sensor() {
    int i;
    long sum = 0;
    int raw_value;

    printf("Calibrating sensor... Please ensure no weight is applied.\n");
    gpioDelay(2000); // Wait 2 seconds

    for (i = 0; i < 100; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711 during calibration\n");
            return;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    offset = (float)sum / 100.0;
    printf("Calibration complete. Offset: %.2f\n", offset);

    // Save calibration data to file
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing\n");
        return;
    }
    fprintf(fp, "%.2f %.2f", offset, 1.0); // Save offset and scale (assuming scale is 1.0)
    fclose(fp);
    printf("Calibration data saved to %s\n", CALIBRATION_FILE);
}

// Function to load calibration data from file
int load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found. Using default values.\n");
        return 0; // Use default values
    }

    if (fscanf(fp, "%f %f", &offset, &scale_factor) != 2) {
        fprintf(stderr, "Error reading calibration data from file. Using default values.\n");
        fclose(fp);
        return 0; // Use default values
    }

    fclose(fp);
    printf("Calibration data loaded from %s: offset=%.2f, scale=%.2f\n", CALIBRATION_FILE, offset, scale_factor);
    return 1; // Calibration data loaded successfully
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_solenoid(0); // Release the lock
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    if (!load_calibration_data()) {
        offset = 0.0;
        scale_factor = 1.0;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711, skipping iteration\n");
            gpioDelay(500); // Wait before next iteration
            continue;
        }

        float weight = convert_to_weight(raw_value, scale_factor, offset);

        log_weight(weight);

        if (weight > THRESHOLD) {
            control_solenoid(1); // Engage the lock
        } else {
            control_solenoid(0); // Release the lock
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_solenoid(0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

