#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define MOTOR_RUN_TIME_S 5
#define CHECK_INTERVAL_S 60

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_rain_sensor();
int is_raining();
void close_window();
void stop_window();
void log_event(const char *event);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int readings[DEBOUNCE_READINGS];
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(RAIN_SENSOR_PIN);
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }
    return (readings[2] == 0) ? 0 : 1; // Return 0 if at least 3 readings are LOW (rain detected), else 1
}

// Function to determine if it is raining
int is_raining() {
    return read_rain_sensor();
}

// Function to close the window
void close_window() {
    log_event("Closing window");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioSetPWMfrequency(MOTOR_PWM_PIN, 1000); // Set PWM frequency to 1 kHz
    gpioPWM(MOTOR_PWM_PIN, 150); // Set duty cycle to 150/255
    gpioDelay(MOTOR_RUN_TIME_S * 1000000); // Run for MOTOR_RUN_TIME_S seconds
    stop_window();
}

// Function to stop the window
void stop_window() {
    log_event("Stopping window");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0); // Set PWM to 0
}

// Function to log events to syslog
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, event);
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure the log is written immediately
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    stop_window();
    cleanup_gpio();
    closelog();
    exit(0);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(MOTOR_PWM_PIN, 1000); // Set PWM frequency to 1 kHz

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
}

int main() {
    // Open syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen("/var/log/window_control.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        syslog(LOG_ERR, "Error opening log file!");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    log_event("System started");

    // Main loop
    while (running) {
        if (is_raining()) {
            close_window();
        }
        gpioDelay(CHECK_INTERVAL_S * 1000000); // Check every CHECK_INTERVAL_S seconds
    }

    // Cleanup and exit
    stop_window();
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    closelog();
    return 0;
}

