long read_hx711() {
    long count = 0;
    int i;

    gpioSetMode(DT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);

    // Wait for DT to go low
    int timeout = 0;
    while (gpioRead(DT_PIN) == 1 && timeout < 100) {
