#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Calibration file
#define CALIBRATION_FILE "calibration.txt"

// Log file
#define LOG_FILE "security.log"

// Threshold weight in kg
#define WEIGHT_THRESHOLD 5.0

// Solenoid activation time in seconds
#define SOLENOID_ACTIVATION_TIME 5

// HX711 timeout (microseconds)
#define HX711_TIMEOUT 100000 // 100ms

// Global variables
static volatile int running = 1;
static double calibration_factor = 1.0; // Default calibration factor
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double convert_to_kg(int raw_value);
void calibrate_load_cell();
void log_event(double weight);
void activate_solenoid();
void signal_handler(int signal);
int read_calibration_factor();

// Function to read a single bit from HX711
int read_hx711_bit() {
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    int bit = gpioRead(HX711_DATA_PIN);
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    return bit;
}

// Function to read a byte from HX711
int read_hx711_byte() {
    int byte = 0;
    for (int i = 0; i < 8; i++) {
        if (read_hx711_bit() == 1) {
            byte |= (1 << i);
        }
    }
    return byte;
}

// Function to read a 24-bit signed integer from HX711
int read_hx711() {
    int32_t raw_value = 0;
    int i;

    // Wait for the data line to go low
    int timeout_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > HX711_TIMEOUT) {
            fprintf(stderr, "HX711 timeout error\n");
            return 0; // Indicate error
        }
    }

    // Read 24 bits
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us delay
        raw_value = raw_value << 1;
        if (read_hx711_bit() == 1) {
            raw_value++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us delay
    }

    // Sign extend if negative
    if (raw_value & 0x800000) {
        raw_value |= 0xFF000000;
    }

    return raw_value;
}

// Function to convert raw value to kilograms
double convert_to_kg(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to calibrate the load cell
void calibrate_load_cell() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input. Please enter a number.\n");
        return;
    }

    printf("Reading raw value...\n");
    raw_value = read_hx711();
    if (raw_value == 0) {
        fprintf(stderr, "Error reading raw value during calibration.\n");
        return;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %lf\n", calibration_factor);

    // Save calibration factor to file
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing.\n");
        return;
    }
    fprintf(fp, "%lf", calibration_factor);
    fclose(fp);
    printf("Calibration factor saved to %s\n", CALIBRATION_FILE);
}

// Function to log an event to the log file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Set GPIO high
    printf("Solenoid activated for %d seconds\n", SOLENOID_ACTIVATION_TIME);
    gpioDelay(SOLENOID_ACTIVATION_TIME * 1000); // Delay for activation time
    gpioWrite(SOLENOID_PIN, 0); // Set GPIO low
    printf("Solenoid deactivated\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to read the calibration factor from file
int read_calibration_factor() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for reading. Using default calibration factor.\n");
        return 1.0; // Return default calibration factor
    }
    double cf;
    if (fscanf(fp, "%lf", &cf) != 1) {
        fprintf(stderr, "Error reading calibration factor from file. Using default calibration factor.\n");
        fclose(fp);
        return 1.0; // Return default calibration factor
    }
    fclose(fp);
    printf("Calibration factor read from file: %lf\n", cf);
    return cf;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Initialize solenoid to unlocked state
    gpioWrite(SOLENOID_PIN, 0);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Read calibration factor
    calibration_factor = read_calibration_factor();

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == 0) {
            fprintf(stderr, "Error reading HX711 value. Retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        double weight = convert_to_kg(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            log_event(weight);
            activate_solenoid();
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    fclose(log_file);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked on exit
    gpioTerminate();

    return 0;
}

