int initialize_gpio() {
    sensor_chip = gpiod_chip_open_by_name(SENSOR_CHIP);
    if (!sensor_chip) {
        fprintf(stderr, "Error opening sensor chip: %s\n", SENSOR_CHIP);
        return -1;
    }

    sensor_line = gpiod_chip_get_line(sensor_chip, SENSOR_LINE);
    if (!sensor_line) {
