    int sensor_value;

    printf("Monitoring obstacle avoidance sensor...\n");

    while (1) {
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        if (sensor_value == 0) { // Obstacle detected (active-low)
            relay_state = toggle_relay(relay_state);
            if (relay_state < 0) {
                fprintf(stderr, "Error toggling relay, retrying...\n");
                sleep(1); // Wait before retrying
                continue;
            }

            if (log_event(relay_state) != 0) {
                fprintf(stderr, "Error logging event, retrying...\n");
            }
        }

        usleep(100000); // 100ms delay
    }

    return 0;
}

