#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define CONFIG_FILE "watering.conf"
#define MAX_CONFIG_VALUE 3600

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int gpio_pin = GPIO_LINE;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the watering duration from the configuration file
int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        if (feof(fp)) {
            fprintf(stderr, "Config file is empty.\n");
            fclose(fp);
            return -1;
        } else {
            fprintf(stderr, "Error reading config file: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);

    char *key = strtok(line, "=");
    char *value = strtok(NULL, "=");

    if (key == NULL || value == NULL) {
        fprintf(stderr, "Invalid config file format.\n");
        return -1;
    }

    if (strcmp(key, "duration=") != 0) {
        fprintf(stderr, "Invalid key in config file.\n");
        return -1;
    }

    char *endptr;
    long duration = strtol(value, &endptr, 10);

    if (*endptr != '\0' || duration <= 0 || duration > MAX_CONFIG_VALUE) {
        fprintf(stderr, "Invalid duration value: %ld. Must be a positive integer between 1 and 3600.\n", duration);
        return -1;
    }

    return (int)duration;
}

// Function to set the GPIO line state
int set_gpio_state(int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to turn the valve on
int turn_valve_on() {
    return set_gpio_state(1);
}

// Function to turn the valve off
int turn_valve_off() {
    return set_gpio_state(0);
}

// Function to log the valve state
void log_valve_state(int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (state == 1) {
        printf("[%s] Valve ON\n", timestamp);
    } else {
        printf("[%s] Valve OFF\n", timestamp);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration
    int duration = read_config(CONFIG_FILE);
    if (duration < 0) {
        fprintf(stderr, "Failed to read configuration. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line as output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial state to off
    if (turn_valve_off() != 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        if (turn_valve_on() == 0) {
            sleep(duration);
            if (turn_valve_off() != 0) {
                program_running = 0; // Exit on error
                break;
            }
        } else {
            program_running = 0;
            break;
        }
    }

    // Cleanup
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

