#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

// Define servo pulse widths (microseconds)
#define LOCKED_PULSE_WIDTH 1000
#define UNLOCKED_PULSE_WIDTH 2000

// Define safe servo pulse width range (microseconds)
#define SAFE_PULSE_WIDTH_MIN 500
#define SAFE_PULSE_WIDTH_MAX 2500

// Global variable to track servo state
volatile int servo_state = 0; // 0 = unlocked, 1 = locked

// Function prototypes
int initialize_gpio();
void lock_door();
void unlock_door();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initializes the pigpio library and sets up GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-up resistors (active-low buttons)
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    return 0; // Indicate success
}

// Locks the door by setting the servo to the locked position
void lock_door() {
    if (servo_state != 1) {
        gpioServo(SERVO_PIN, LOCKED_PULSE_WIDTH);
        servo_state = 1;
        printf("Door locked\n");
    }
}

// Unlocks the door by setting the servo to the unlocked position
void unlock_door() {
    if (servo_state != 0) {
        gpioServo(SERVO_PIN, UNLOCKED_PULSE_WIDTH);
        servo_state = 0;
        printf("Door unlocked\n");
    }
}

// Cleans up the pigpio library and terminates the program
void cleanup_gpio() {
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Check for button presses with debouncing
        if (gpioRead(LOCK_BUTTON) == 0) {
            lock_door();
            gpioDelay(100); // Debounce delay (100 ms)
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            unlock_door();
            gpioDelay(100); // Debounce delay (100 ms)
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0; // This line will never be reached due to the infinite loop
}

