#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO lines for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define the number of lines to request
#define NUM_LINES 2

// Define the pulse durations in milliseconds
#define PULSE_DURATION1 200
#define PULSE_DURATION2 300

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_LINES];
int line_requests[NUM_LINES];

// Function prototypes
int request_gpio_line(struct gpiod_chip *chip, int gpio, int flags, struct gpiod_line **line);
int set_gpio_value(struct gpiod_line *line, int value);
int release_gpio_line(struct gpiod_line *line);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig)
{
    if (sig == SIGINT || sig == SIGTERM)
    {
        printf("Received signal %d, cleaning up...\n", sig);
        cleanup();
        exit(0);
    }
}

// Function to request a GPIO line
int request_gpio_line(struct gpiod_chip *chip, int gpio, int flags, struct gpiod_line **line)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "haptic_feedback";
    config.request_type = flags; // Request as output
    config.consumer_request = &line_requests[0]; // Use a global array to track requests

    int ret = gpiod_line_request(chip, gpio, &config, line);
    if (ret < 0)
    {
        fprintf(stderr, "Error requesting GPIO line %d: %d\n", gpio, ret);
        return -1;
    }
    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0)
    {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to release a GPIO line
int release_gpio_line(struct gpiod_line *line)
{
    int ret = gpiod_line_release(line);
    if (ret < 0)
    {
        fprintf(stderr, "Error releasing GPIO line: %d\n", ret);
        return -1;
    }
    return 0;
}

// Cleanup function to release GPIO lines and chip
void cleanup()
{
    // Release motor 1 line
    if (lines[0] != NULL) {
        release_gpio_line(lines[0]);
    }

    // Release motor 2 line
    if (lines[1] != NULL) {
        release_gpio_line(lines[1]);
    }

    // Close the chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        fprintf(stderr, "Error opening GPIO chip: %d\n", chip);
        return 1;
    }

    // Request GPIO lines
    if (request_gpio_line(chip, MOTOR1_GPIO, GPIOD_LINE_REQUEST_FLAG_REQUEST | GPIOD_LINE_REQUEST_FLAG_OUTPUT, &lines[0]) < 0) {
        cleanup();
        return 1;
    }
    if (request_gpio_line(chip, MOTOR2_GPIO, GPIOD_LINE_REQUEST_FLAG_REQUEST | GPIOD_LINE_REQUEST_FLAG_OUTPUT, &lines[1]) < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (1)
    {
        // Pulse motor 1
        if (set_gpio_value(lines[0], 1) < 0) {
            cleanup();
            return 1;
        }
        usleep(PULSE_DURATION1 * 1000); // Convert milliseconds to microseconds
        if (set_gpio_value(lines[0], 0) < 0) {
            cleanup();
            return 1;
        }

        // Pulse motor 2
        if (set_gpio_value(lines[1], 1) < 0) {
            cleanup();
            return 1;
        }
        usleep(PULSE_DURATION2 * 1000); // Convert milliseconds to microseconds
        if (set_gpio_value(lines[1], 0) < 0) {
            cleanup();
            return 1;
        }

        // Small delay to prevent busy-waiting
        usleep(10000); // 10ms
    }

    return 0;
}

