#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <zmq.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"

// Define sound threshold
#define SOUND_THRESHOLD 0 // Active-low, so 0 means sound detected

// Define alarm duration
#define ALARM_DURATION_MS 1000

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY_MS 50

// Global variables for cleanup
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sound_line = NULL;
static struct gpiod_line *alarm_line = NULL;
static void *zmq_context = NULL;
static void *zmq_pub_socket = NULL;
static void *zmq_sub_socket = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_gpio(void);
int init_zmq(void);
void cleanup(void);
void signal_handler(int sig);
int read_sound_sensor(void);
void publish_alert(void);
void handle_alarm(void);
int init_gpio_chip(int pin);
int init_gpio_line(int pin, int direction);
int set_gpio_value(int pin, int value);
int read_gpio_value(int pin);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        running = 0;
        printf("Received signal %d, shutting down...\n", sig);
    }
}

// Initialize GPIO
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("Error getting sound sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_line) {
        perror("Error getting alarm LED line");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(alarm_line, "alarm_node", 0) < 0) {
        perror("Error requesting alarm LED line for output");
        gpiod_line_release(sound_line);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(sound_line, "sound_sensor", 0) < 0) {
        perror("Error requesting sound sensor line for input");
        gpiod_line_release(alarm_line);
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Initialize ZeroMQ
int init_zmq(void) {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("Error creating ZeroMQ context");
        return -1;
    }

    zmq_pub_socket = zmq_socket(zmq_context, ZMQ_PUB);
    if (!zmq_pub_socket) {
        perror("Error creating ZeroMQ socket (pub)");
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    int bind_result = zmq_bind(zmq_pub_socket, ZMQ_ENDPOINT);
    if (bind_result < 0) {
        perror("Error binding ZeroMQ socket (pub)");
        zmq_close(zmq_pub_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    zmq_sub_socket = zmq_socket(zmq_context, ZMQ_SUB);
    if (!zmq_sub_socket) {
        perror("Error creating ZeroMQ socket (sub)");
        zmq_close(zmq_pub_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    int connect_result = zmq_connect(zmq_sub_socket, "tcp://localhost:5555");
    if (connect_result < 0) {
        perror("Error connecting ZeroMQ socket (sub)");
        zmq_close(zmq_sub_socket);
        zmq_close(zmq_pub_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    int subscribe_result = zmq_setsockopt(zmq_sub_socket, ZMQ_SUBSCRIBE, "SOUND_ALERTS", strlen("SOUND_ALERTS"));
    if (subscribe_result < 0) {
        perror("Error setting ZeroMQ socket (sub) options");
        zmq_close(zmq_sub_socket);
        zmq_close(zmq_pub_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    if (chip) {
        gpiod_line_release(sound_line);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
    }

    if (zmq_pub_socket) {
        zmq_close(zmq_pub_socket);
    }
    if (zmq_sub_socket) {
        zmq_close(zmq_sub_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }
}

// Read sound sensor value with debouncing
int read_sound_sensor(void) {
    int value = read_gpio_value(SOUND_SENSOR_PIN);
    struct timespec delay = {0, DEBOUNCE_DELAY_MS * 1000000L};
    nanosleep(&delay, NULL);
    return value;
}

// Publish alert message
void publish_alert(void) {
    char message[50];
    snprintf(message, sizeof(message), "SOUND_ALERT");
    zmq_msg_t topic_msg;
    zmq_msg_init_size(&topic_msg, strlen("SOUND_ALERTS"));
    memcpy(zmq_msg_data(&topic_msg), "SOUND_ALERTS", strlen("SOUND_ALERTS"));
    zmq_msg_send(&topic_msg, zmq_pub_socket, 0);
    zmq_msg_close(&topic_msg);
    zmq_msg_t message_msg;
    zmq_msg_init_size(&message_msg, strlen(message));
    memcpy(zmq_msg_data(&message_msg), message, strlen(message));
    zmq_msg_send(&message_msg, zmq_pub_socket, 0);
    zmq_msg_close(&message_msg);
}

// Handle alarm (turn on LED for 1 second)
void handle_alarm(void) {
    printf("Alarm triggered!\n");
    set_gpio_value(ALARM_LED_PIN, 1); // Turn on LED
    struct timespec delay = {0, ALARM_DURATION_MS * 1000000L};
    nanosleep(&delay, NULL);
    set_gpio_value(ALARM_LED_PIN, 0); // Turn off LED
}

// Initialize GPIO line
int init_gpio_chip(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }
    return chip;
}

// Initialize GPIO line for input or output
int init_gpio_line(int pin, int direction) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(line, "sound_sensor", 0) < 0) {
        perror("Error requesting GPIO line for input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }
    return line;
}

// Set GPIO value (0 or 1)
int set_gpio_value(int pin, int value) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }
    return gpiod_line_set_value(line, value);
}

// Read GPIO value (0 or 1)
int read_gpio_value(int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }
    return gpiod_line_get_value(line);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor or alarm_node\n");
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") != 0 && strcmp(argv[1], "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    if (init_zmq() < 0) {
        fprintf(stderr, "ZeroMQ initialization failed\n");
        cleanup();
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        printf("Entering sound sensor mode...\n");
        while (running) {
            int sound_detected = read_sound_sensor();
            if (sound_detected == SOUND_THRESHOLD) {
                publish_alert();
            }
            struct timespec delay = {0, 10 * 1000000L}; // 10 ms
            nanosleep(&delay, NULL);
        }
    } else {
        printf("Entering alarm node mode...\n");
        while (running) {
            zmq_msg_t message;
            zmq_msg_init(&message);
            int recv_result = zmq_msg_recv(&message, zmq_sub_socket, 0);
            if (recv_result < 0) {
                perror("Error receiving message");
                zmq_msg_close(&message);
                continue; // Continue listening for messages
            }

            char *message_data = zmq_msg_data(&message);
            char *endptr;
            long message_size = zmq_msg_size(&message);
            char *topic = (char *)message_data;
            long topic_len = strlen(topic);

            if (topic_len == strlen("SOUND_ALERTS")) {
                printf("Received message: %s\n", message_data);
                handle_alarm();
            } else {
                printf("Received invalid topic: %.*s\n", topic_len, topic);
            }
            zmq_msg_close(&message);
        }
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

