#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

// Configuration
#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder"
#define PULSE_BUFFER_SIZE 100
#define MARK_TIME 9
#define SPACE_TIME 4.5
#define MARK_TIME_US 9000
#define SPACE_TIME_US 1700
#define MAX_PULSES 100

// Global variables
static volatile int pulse_count = 0;
static volatile unsigned int pulse_times[PULSE_BUFFER_SIZE];
static volatile int pulse_index = 0;
static volatile unsigned int last_tick = 0;
static volatile unsigned int decoded_address = 0;
static volatile unsigned int decoded_command = 0;
static volatile int nec_valid = 0;
static struct mosquitto *mosq = NULL;
static struct mosquitto_username_pw Protect = {NULL, NULL};

// Function prototypes
void signal_handler(int signal);
void ir_callback(int gpio, int level, uint32_t tick);
int decode_nec(unsigned int *pulse_times, int pulse_count, unsigned int *address, unsigned int *command);
int validate_checksum(unsigned int address, unsigned int command);
int publish_mqtt(unsigned int address, unsigned int command);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    exit(0);
}

// IR callback function
void ir_callback(int gpio, int level, uint32_t tick) {
    unsigned int diff = tick - last_tick;
    last_tick = tick;

    if (diff > 5000) {
        pulse_index = 0;
        pulse_count = 0;
        nec_valid = 0;
    }

    if (pulse_index < PULSE_BUFFER_SIZE) {
        pulse_times[pulse_index++] = diff;
    }
}

// NEC decoding function
int decode_nec(unsigned int *pulse_times, int pulse_count, unsigned int *address, unsigned int *command) {
    if (pulse_count < 32) {
        syslog(LOG_WARNING, "Not enough pulses received (%d)", pulse_count);
        return -1;
    }

    unsigned int address_temp = 0;
    unsigned int command_temp = 0;

    // Extract address (bits 2-9)
    for (int i = 0; i < 8; i++) {
        address_temp <<= 1;
        if (pulse_times[2 * i + 1] > SPACE_TIME_US) {
            address_temp |= 1;
        }
    }

    // Extract command (bits 10-17)
    for (int i = 0; i < 8; i++) {
        command_temp <<= 1;
        if (pulse_times[2 * i + 1] > SPACE_TIME_US) {
            command_temp |= 1;
        }
    }

    *address = address_temp;
    *command = command_temp;

    return 0;
}

// Checksum validation function
int validate_checksum(unsigned int address, unsigned int command) {
    unsigned int inv_address = ~address + 1;
    unsigned int inv_command = ~command + 1;

    // NEC checksum is the inverse of the address and command
    if ((address ^ inv_address) != 0xFF || (command ^ inv_command) != 0xFF) {
        syslog(LOG_ERR, "Checksum validation failed: address=0x%08X, inv_address=0x%08X, command=0x%08X, inv_command=0x%08X",
               address, inv_address, command, inv_command);
        return -1;
    }

    return 0;
}

// MQTT publish function
int publish_mqtt(unsigned int address, unsigned int command) {
    json_t *root = json_object();
    json_object_set_new(root, "address", json_integer(address));
    json_object_set_new(root, "command", json_integer(command));

    char *json_str = json_dumps(root, JSON_REAL_PRECISION(5));
    if (!json_str) {
        syslog(LOG_ERR, "Failed to serialize JSON: %s", json_error_ptr(NULL));
        json_decref(root);
        return -1;
    }

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(json_str), json_str, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(ret));
        json_decref(root);
        free(json_str);
        return -1;
    }

    json_decref(root);
    free(json_str);
    return 0;
}

// MQTT connect callback
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0 && message->payload != NULL) {
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, (char *)message->payload);
    } else {
        syslog(LOG_INFO, "Received empty message on topic %s", message->topic);
    }
}

int main() {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO mode
    gpioSetMode(IR_GPIO, PI_INPUT);

    // Set alert function
    gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, &Protect);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_username_pw_set(mosq, NULL, NULL); // Disable username/password authentication

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "IR decoder started");

    // Main loop
    while (1) {
        if (pulse_count > 0 && nec_valid) {
            if (decode_nec(pulse_times, pulse_count, &decoded_address, &decoded_command) == 0) {
                if (validate_checksum(decoded_address, decoded_command) == 0) {
                    syslog(LOG_INFO, "Decoded address: 0x%08X, command: 0x%08X", decoded_address, decoded_command);
                    if (publish_mqtt(decoded_address, decoded_command) != 0) {
                        syslog(LOG_ERR, "Failed to publish MQTT message");
                    }
                } else {
                    syslog(LOG_ERR, "Checksum validation failed for address: 0x%08X, command: 0x%08X", decoded_address, decoded_command);
                }
            } else {
                syslog(LOG_ERR, "Failed to decode NEC frame");
            }
            pulse_count = 0;
        }
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup (never reached in normal operation due to the infinite loop)
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

