#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SLEEP_SECONDS 1

// Sensor addresses
const int sensor_addresses[] = {0x23, 0x24, 0x25, 0x26};
const int num_sensors = sizeof(sensor_addresses) / sizeof(sensor_addresses[0]);

// Global flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to read lux value from a single sensor
float read_sensor(int fd, int address) {
    unsigned char command = 0x20; // One-Time High-Resolution Mode
    unsigned char buffer[2];
    int bytes_read;
    int lux;

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", address, strerror(errno));
        return NAN;
    }

