#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define LOG_FILE "airflow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t *buf, int count);
int i2c_write_bytes(int fd, uint8_t *buf, int count);
int read_airflow(int i2c_fd, float *flow_rate);
void log_airflow(float flow_rate);
void signal_handler(int signal);

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t *buf, int count) {
    int retries = RETRY_COUNT;
    int bytes_read = 0;
    int result;

    while (retries > 0) {
        result = read(fd, buf, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %s (errno=%d)\n", strerror(errno), errno);
            retries--;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_bytes(int fd, uint8_t *buf, int count) {
    int retries = RETRY_COUNT;
    int bytes_written = 0;
    int result;

    while (retries > 0) {
        result = write(fd, buf, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error: %s (errno=%d)\n", strerror(errno), errno);
            retries--;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C write failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to read airflow data
int read_airflow(int i2c_fd, float *flow_rate) {
    uint8_t buf[4];
    int raw_flow;

    // Start reading sequence
    if (i2c_write_bytes(i2c_fd, NULL, 0) != 0) {
        fprintf(stderr, "Failed to start read sequence.\n");
        return -1;
    }

    // Read 4 bytes (2 for flow, 2 for status)
    if (i2c_read_bytes(i2c_fd, buf, 4) != 0) {
        fprintf(stderr, "Failed to read airflow data.\n");
        return -1;
    }

    // Extract raw flow value (first two bytes)
    raw_flow = ((uint16_t)buf[0] << 8) | buf[1];

    // Convert to SLPM
    *flow_rate = (raw_flow - 3277) * 0.1;

    return 0;
}

// Function to log airflow data
void log_airflow(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    float flow_rate;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s (errno=%d)\n", strerror(errno), errno);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s (errno=%d)\n", strerror(errno), errno);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (read_airflow(i2c_fd, &flow_rate) == 0) {
            log_airflow(flow_rate);
        } else {
            fprintf(stderr, "Failed to read airflow.\n");
        }

        sleep(1); // Sample every second
    }

    return 0; // This line will not be reached due to the infinite loop
}

