#include <linux/i2c-dev.h>
#include <errno.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Registers
#define WHO_AM_I 0x24
#define PON 0x80
#define CFG6 0xAF
#define SP_EN 0x02
#define F1_DATA 0x60
#define F2_DATA 0x61
#define F3_DATA 0x62
#define F4_DATA 0x63
#define F5_DATA 0x64
#define F6_DATA 0x65
#define F7_DATA 0x66
#define F8_DATA 0x67
#define CLEAR_DATA 0x68
#define NIR_DATA 0x69

// Configuration values
#define PON_VALUE 0x01
#define CFG6_VALUE 0x03 // Enable all channels

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_setup(const char *device);
int as7341_init(int fd);
int read_sensor_data(int fd, uint16_t *data);
float calculate_lux(const uint16_t *data);
int log_data(const uint16_t *data, float lux);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t f1;
    uint16_t f2;
    uint16_t f3;
    uint16_t f4;
    uint16_t f5;
    uint16_t f6;
    uint16_t f7;
    uint16_t f8;
    uint16_t clear;
    uint16_t nir;
} sensor_data_t;

// Function to initialize the I2C bus
int i2c_setup(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// Function to initialize the AS7341 sensor
int as7341_init(int fd) {
    uint8_t who_am_i;

    // Verify WHO_AM_I register
    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    who_am_i = i2c_smbus_read_byte_data(fd, WHO_AM_I);
    if (who_am_i != 0x19) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%x, expected 0x19\n", who_am_i);
        return -1;
    }

    // Power on the sensor
    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (i2c_smbus_write_byte_data(fd, PON, PON_VALUE) < 0) {
        perror("Error writing to PON register");
        return -1;
    }
    usleep(10000); // Wait for power-on

    // Configure SMUX (CFG6)
    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (i2c_smbus_write_byte_data(fd, CFG6, CFG6_VALUE) < 0) {
        perror("Error writing to CFG6 register");
        return -1;
    }

    // Enable spectral measurement
    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (i2c_smbus_write_byte_data(fd, SP_EN, SP_EN) < 0) {
        perror("Error writing to SP_EN register");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, uint16_t *data) {
    uint8_t buffer[10];

    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    for (int i = 0; i < 10; i++) {
        int result = i2c_smbus_read_word_data(fd, F1_DATA + i);
        if (result < 0) {
            perror("Error reading sensor data");
            return -1;
        }
        buffer[i] = (uint8_t)result;
    }

    memcpy(data, buffer, 10 * 2); // Copy the data
    return 0;
}

// Function to calculate lux approximation (simplified)
float calculate_lux(const uint16_t *data) {
    // This is a placeholder.  A real implementation would use
    // more sophisticated algorithms based on the AS7341's
    // spectral data and calibration parameters.
    // This example just returns a simple average.
    float sum = 0.0;
    for (int i = 0; i < 10; i++) {
        sum += data[i];
    }
    return sum / 10.0;
}

// Function to log data to a CSV file
int log_data(const uint16_t *data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
