#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define ERROR_LOG_FILE "seismic_error.log"
#define CSV_LOG_FILE "seismic_data.log"

// Data structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Global variables (to be minimized, used for signal handling)
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_close(int fd);
int read_sensor_data(int fd, sensor_data_t *data);
float convert_to_g(int16_t raw);
int log_data(FILE *fp, float x, float y, float z);
int log_error(const char *message);
void signal_handler(int sig);
int parse_arguments(int argc, char *argv[], int *i2c_address, int *interval, char *filename);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = i2c_smbus_write_byte(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (reg 0x%02X, value 0x%02X), retry %d: %s\n", reg, value, retries + 1, strerror(errno));
            log_error("I2C write failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        }
    }
    return -1; // Failure after retries
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = i2c_smbus_read_i2c_block_data(fd, reg, (char *)buf, len);
        if (result >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X, len %d), retry %d: %s\n", reg, len, retries + 1, strerror(errno));
            log_error("I2C read failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        }
    }
    return -1; // Failure after retries
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C bus");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buf[12];
    if (i2c_read_bytes(fd, 0x28, buf, 12) != 0) {
        log_error("Failed to read sensor data");
        return -1;
    }

    // Combine high and low bytes for each axis (little-endian)
    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Convert raw data to g
float convert_to_g(int16_t raw) {
    return (float)raw * 0.000244;
}

// Log data to CSV file
int log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        perror("Error writing to CSV file");
        log_error("Error writing to CSV file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Log error to file
int log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (error_file != NULL) {
        fprintf(error_file, "%s: %s\n", timestamp, message);
        fflush(error_file);
    } else {
        fprintf(stderr, "Error log file not opened!\n");
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Parse command-line arguments
int parse_arguments(int argc, char *argv[], int *i2c_address, int *interval, char *filename) {
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                *i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                *interval = atoi(optarg);
                if (*interval <= 0) {
                    fprintf(stderr, "Invalid interval value. Using default interval of 1 second.\n");
                    *interval = DEFAULT_INTERVAL;
                }
                break;
            case 'f':
                *filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                return -1;
        }
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    char *filename = DEFAULT_FILENAME;
    int opt;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &i2c_address, &interval, &filename) != 0) {
        return 1;
    }

    // Open error log file
    error_file = fopen(ERROR_LOG_FILE, "a");
    if (error_file == NULL) {
        perror("Error opening error log file");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        fclose(error_file);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(filename, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        log_error("Failed to open CSV file");
        i2c_close(i2c_fd);
        fclose(error_file);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");
        fflush(csv_file);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("Error setting I2C slave address");
        log_error("Error setting I2C slave address");
        i2c_close(i2c_fd);
        fclose(csv_file);
        fclose(error_file);
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    float x_g, y_g, z_g;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            x_g = convert_to_g(sensor_data.x);
            y_g = convert_to_g(sensor_data.y);
            z_g = convert_to_g(sensor_data.z);

            if (log_data(csv_file, x_g, y_g, z_g) != 0) {
                log_error("Failed to log data");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(interval);
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2c_close(i2c_fd);
    fclose(csv_file);
    fclose(error_file);

    return 0;
}

