    char *filename = DEFAULT_FILENAME;
    int opt;

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &i2c_address, &interval, &filename) != 0) {
        return 1;
    }

    // Open error log file
    error_file = fopen(ERROR_LOG_FILE, "a");
    if (error_file == NULL) {
        perror("Error opening error log file");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        fclose(error_file);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(filename, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        log_error("Failed to open CSV file");
        i2c_close(i2c_fd);
        fclose(error_file);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");
        fflush(csv_file);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("Error setting I2C slave address");
        log_error("Error setting I2C slave address");
        i2c_close(i2c_fd);
        fclose(csv_file);
        fclose(error_file);
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    float x_g, y_g, z_g;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            x_g = convert_to_g(sensor_data.x);
            y_g = convert_to_g(sensor_data.y);
            z_g = convert_to_g(sensor_data.z);

            if (log_data(csv_file, x_g, y_g, z_g) != 0) {
                log_error("Failed to log data");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(interval);
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2c_close(i2c_fd);
    fclose(csv_file);
    fclose(error_file);

    return 0;
}

