#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_POWER_ON 0x01

int i2c_fd = -1;
int socket_fd = -1;

// Function to initialize the BH1750 sensor
int init_bh1750() {
    char buf[2];
    int result;

    // Power on the sensor
    buf[0] = BH1750_POWER_ON;
    result = write(i2c_fd, buf, 1);
    if (result != 1) {
        perror("Failed to power on BH1750");
        return -1;
    }

    // Set continuous high-resolution mode
    buf[0] = BH1750_CONTINUOUS_HIGH_RES_MODE;
    result = write(i2c_fd, buf, 1);
    if (result != 1) {
        perror("Failed to set BH1750 mode");
        return -1;
    }

    return 0;
}

// Function to read the light level from the BH1750 sensor
int read_light_level(unsigned short *raw_value) {
    unsigned char buf[2];
    int result;

    result = read(i2c_fd, buf, 2);
    if (result != 2) {
        perror("Failed to read light level");
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send the lux value over UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    char buffer[32];
    int result;

    // Format the lux value as a string
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    // Configure the destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send the data
    result = sendto(socket_fd, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr));
    if (result < 0) {
        perror("Failed to send UDP multicast");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }
    exit(0);
}

int main() {
    unsigned short raw_value;
    float lux_value;
    struct timeval tv;
    int retry_count = 0;
    int max_retries = 3;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open UDP socket
    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        perror("Failed to create socket");
        close(i2c_fd);
        return 1;
    }

    // Set TTL for multicast
    int ttl = 1;
    if (setsockopt(socket_fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set TTL");
        close(i2c_fd);
        close(socket_fd);
        return 1;
    }

    // Initialize the BH1750 sensor
    if (init_bh1750() != 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor. Exiting.\n");
        close(i2c_fd);
        close(socket_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read light level
        if (read_light_level(&raw_value) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_value);

            // Send over UDP multicast
            if (send_udp_multicast(lux_value) != 0) {
                fprintf(stderr, "Failed to send lux value. Retrying...\n");
            } else {
                printf("Lux: %.2f\n", lux_value);
            }
        } else {
            fprintf(stderr, "Failed to read light level. Retrying...\n");
        }

        // Wait for 1 second
        sleep(1);

        // Retry mechanism
        retry_count++;
        if (retry_count > max_retries) {
            fprintf(stderr, "Max retries reached. Exiting.\n");
            break;
        }
        if (errno != 0) {
            retry_count = 0;
            errno = 0; // Reset errno for the next retry
        }
    }

    // Cleanup
    close(i2c_fd);
    close(socket_fd);

    return 0;
}

