#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_SIZE 4
#define MAGIC_WORD_LE 0x02040306
#define TLV_TYPE_RANGE 1
#define TLV_TYPE_VELOCITY 2
#define TLV_TYPE_OBJECT_DETECTED 3
#define TLV_TYPE_STATUS 4
#define TLV_TYPE_CONFIG 5
#define TLV_TYPE_DATA 6
#define TLV_TYPE_COMMAND 7
#define TLV_TYPE_RESPONSE 8
#define TLV_TYPE_ERROR 9
#define TLV_TYPE_NAMED_RANGE 10
#define TLV_TYPE_NAMED_VELOCITY 11
#define TLV_TYPE_NAMED_OBJECT_DETECTED 12
#define TLV_TYPE_NAMED_STATUS 13
#define TLV_TYPE_NAMED_CONFIG 14
#define TLV_TYPE_NAMED_DATA 15
#define TLV_TYPE_NAMED_COMMAND 16
#define TLV_TYPE_NAMED_RESPONSE 17
#define TLV_TYPE_NAMED_ERROR 18
#define TLV_TYPE_NAMED_NAMED_RANGE 19
#define TLV_TYPE_NAMED_NAMED_VELOCITY 20
#define TLV_TYPE_NAMED_NAMED_OBJECT_DETECTED 21
#define TLV_TYPE_NAMED_NAMED_STATUS 22
#define TLV_TYPE_NAMED_NAMED_CONFIG 23
#define TLV_TYPE_NAMED_NAMED_DATA 24
#define TLV_TYPE_NAMED_NAMED_COMMAND 25
#define TLV_TYPE_NAMED_NAMED_RESPONSE 26
#define TLV_TYPE_NAMED_NAMED_ERROR 27
#define TLV_TYPE_NAMED_NAMED_NAMED_RANGE 28
#define TLV_TYPE_NAMED_NAMED_NAMED_VELOCITY 29
#define TLV_TYPE_NAMED_NAMED_NAMED_OBJECT_DETECTED 30
#define TLV_TYPE_NAMED_NAMED_NAMED_STATUS 31
#define TLV_TYPE_NAMED_NAMED_NAMED_CONFIG 32
#define TLV_TYPE_NAMED_NAMED_NAMED_DATA 33
#define TLV_TYPE_NAMED_NAMED_NAMED_COMMAND 34
#define TLV_TYPE_NAMED_NAMED_NAMED_RESPONSE 35
#define TLV_TYPE_NAMED_NAMED_NAMED_ERROR 36

#define MAX_BUFFER_SIZE 4096

// Global variables
int uart_fd;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar data
typedef struct {
    long long timestamp;
    int object_index;
    float range_m;
    float velocity_mps;
} RadarData;

// Function prototypes
int initialize_uart();
void close_resources();
void signal_handler(int signal);
int read_uart_data(char *buffer, int buffer_size);
int parse_tlv(char *buffer, int buffer_size, RadarData *radar_data);
int validate_tlv_type(unsigned short tlv_type);
int extract_range(float *range, unsigned short tlv_type);
int extract_velocity(float *velocity, unsigned short tlv_type);
int extract_object_index(int *object_index, unsigned short tlv_type);
int write_to_csv(RadarData radar_data);
int write_error_log(const char *message);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize UART
int initialize_uart() {
    uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_fd < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_fd);
        return -1;
    }
    printf("UART initialized on %s at %d baud\n", UART_DEVICE, BAUD_RATE);
    return 0;
}

// Close resources
void close_resources() {
    if (uart_fd >= 0) {
        serClose(uart_fd);
        printf("UART closed\n");
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        printf("CSV file closed\n");
    }
    gpioTerminate();
    printf("pigpio terminated\n");
}

// Read data from UART
int read_uart_data(char *buffer, int buffer_size) {
    int bytes_read = serRead(uart_fd, buffer, buffer_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    } else if (bytes_read == 0) {
        // No data available, return 0
        return 0;
    }
    return bytes_read;
}

// Parse TLV data
int parse_tlv(char *buffer, int buffer_size, RadarData *radar_data) {
    int offset = 0;
    while (offset < buffer_size - 4) { // Ensure enough bytes for type and length
        unsigned short tlv_type = *((unsigned short *)(buffer + offset));
        unsigned short tlv_length = *((unsigned short *)(buffer + offset + 2));

        if (offset + 4 + tlv_length > buffer_size) {
            fprintf(stderr, "TLV length exceeds buffer size, skipping\n");
            return -1; // TLV too large
        }

        if (validate_tlv_type(tlv_type)) {
            if (tlv_type == TLV_TYPE_RANGE) {
                if (extract_range(&radar_data->range_m, tlv_type) != 0) {
                    fprintf(stderr, "Error extracting range\n");
                    return -1;
                }
            } else if (tlv_type == TLV_TYPE_VELOCITY) {
                if (extract_velocity(&radar_data->velocity_mps, tlv_type) != 0) {
                    fprintf(stderr, "Error extracting velocity\n");
                    return -1;
                }
            } else if (tlv_type == TLV_TYPE_OBJECT_DETECTED) {
                if (extract_object_index(&radar_data->object_index, tlv_type) != 0) {
                    fprintf(stderr, "Error extracting object index\n");
                    return -1;
                }
            } else if (tlv_type == TLV_TYPE_STATUS) {
                // Status TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_CONFIG) {
                // Configuration TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_DATA) {
                // Data TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_COMMAND) {
                // Command TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_RESPONSE) {
                // Response TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_ERROR) {
                // Error TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_RANGE) {
                // Named Range TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_VELOCITY) {
                // Named Velocity TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_OBJECT_DETECTED) {
                // Named Object Detected TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_STATUS) {
                // Named Status TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_CONFIG) {
                // Named Config TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_DATA) {
                // Named Data TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_COMMAND) {
                // Named Command TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_RESPONSE) {
                // Named Response TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_ERROR) {
                // Named Error TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_RANGE) {
                // Named Named Range TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_VELOCITY) {
                // Named Named Velocity TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_OBJECT_DETECTED) {
                // Named Named Object Detected TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_STATUS) {
                // Named Named Status TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_CONFIG) {
                // Named Named Config TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_DATA) {
                // Named Named Data TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_COMMAND) {
                // Named Named Command TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_RESPONSE) {
                // Named Named Response TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_ERROR) {
                // Named Named Error TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_NAMED_RANGE) {
                // Named Named Named Range TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_NAMED_VELOCITY) {
                // Named Named Named Velocity TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_NAMED_OBJECT_DETECTED) {
                // Named Named Named Object Detected TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_NAMED_STATUS) {
                // Named Named Named Status TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_NAMED_CONFIG) {
                // Named Named Named Config TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_NAMED_DATA) {
                // Named Named Named Data TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_NAMED_COMMAND) {
                // Named Named Named Command TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_NAMED_RESPONSE) {
                // Named Named Named Response TLV is not used in this example
            } else if (tlv_type == TLV_TYPE_NAMED_NAMED_NAMED_ERROR) {
                // Named Named Named Error TLV is not used in this example
            } else {
                fprintf(stderr, "Unknown TLV type: 0x%04X\n", tlv_type);
                return -1;
            }
        }
        offset += 4 + tlv_length;
    }
    return 0;
}

// Validate TLV type
int validate_tlv_type(unsigned short tlv_type) {
    return (tlv_type >= 1 && tlv_type <= 36); // Basic range check
}

// Extract range
int extract_range(float *range, unsigned short tlv_type) {
    if (tlv_type == TLV_TYPE_RANGE) {
        *range = *((float *)(buffer + offset));
        return 0;
    } else {
        return -1;
    }
}

// Extract velocity
int extract_velocity(float *velocity, unsigned short tlv_type) {
    if (tlv_type == TLV_TYPE_VELOCITY) {
        *velocity = *((float *)(buffer + offset));
        return 0;
    } else {
        return -1;
    }
}

// Extract object index
int extract_object_index(int *object_index, unsigned short tlv_type) {
    if (tlv_type == TLV_TYPE_OBJECT_DETECTED) {
        *object_index = *((int *)(buffer + offset));
        return 0;
    } else {
        return -1;
    }
}

// Write to CSV file
int write_to_csv(RadarData radar_data) {
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        return -1;
    }

    fprintf(csv_file, "%lld,%d,%.2f,%.2f\n", radar_data.timestamp, radar_data.object_index, radar_data.range_m, radar_data.velocity_mps);
    fclose(csv_file);
    return 0;
}

// Write error log
int write_error_log(const char *message) {
    FILE *error_file = fopen("error_log.txt", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file\n");
        return -1;
    }

