int main() {
    int uart_fd;
    char uart_buffer[MAX_BUFFER_SIZE];
    char range_buffer[MAX_BUFFER_SIZE];
    time_t timestamp;
    struct tm *timeinfo;
    char timestamp_str[20];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = uart_init(UART_PORT);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    printf("UART initialized successfully.\n");

    while (program_running) {
        ssize_t bytes_read = uart_read_data(uart_fd, uart_buffer, sizeof(uart_buffer));
        if (bytes_read > 0) {
            if (parse_data(uart_buffer, range_buffer, sizeof(range_buffer)) > 0) {
                timestamp = time(NULL);
                timeinfo = localtime(&timestamp);
                strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

                printf("Timestamp: %s, Range: %s meters\n", timestamp_str, range_buffer);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting.\n");
            break;
        }
    }

    close(uart_fd);
    printf("UART closed.\n");

    return EXIT_SUCCESS;
}

