#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 7
#define MIDDLE_SENSOR_PIN 11
#define RIGHT_SENSOR_PIN 13

// Define the serial port
#define SERIAL_PORT "/dev/ttyAMA0"

// Define the baud rate
#define BAUD_RATE 115200

// Define the emergency stop string
#define EMERGENCY_STOP_STRING "EMERGENCY STOP!\n"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int all_sensors_blocked(int left, int middle, int right);
void send_emergency_stop();
void signal_handler(int signal);

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to check if all sensors are blocked
int all_sensors_blocked(int left, int middle, int right) {
    return (left == 0 && middle == 0 && right == 0);
}

// Function to send the emergency stop string over the serial port
void send_emergency_stop() {
    FILE *serial_port = fopen(SERIAL_PORT, "w");
    if (serial_port == NULL) {
        fprintf(stderr, "Error opening serial port %s\n", SERIAL_PORT);
        return;
    }

    if (fprintf(serial_port, "%s", EMERGENCY_STOP_STRING) < 0) {
        fprintf(stderr, "Error writing to serial port %s\n", SERIAL_PORT);
    }

    if (fclose(serial_port) != 0) {
        fprintf(stderr, "Error closing serial port %s\n", SERIAL_PORT);
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            // Error reading sensor, continue to the next iteration
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Check if all sensors are blocked
        if (all_sensors_blocked(left_value, middle_value, right_value)) {
            send_emergency_stop();
        }

        // Print sensor states to the console
        printf("Left: %d, Middle: %d, Right: %d\n", left_value, middle_value, right_value);

        // Delay for 100ms (10 Hz)
        gpioDelay(100000);
    }

    // Close the serial port (not strictly necessary, but good practice)
    // No need to explicitly close serial_port here, as it is automatically closed on exit.

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

